def street_w(r):
    """Measured width of a street or path in metres (see measure_widths); 0.0 where the survey does not show it."""
    return r.get("w") or 0.0


def measure_widths(S):
    """Width of every street and path from the survey: across the centreline every 4 m, the distance between the
    surveyed road edges (YOL_SOSE / YOL_BORDUR / YOL_TOPRAK) on both sides; where the edges are missing, between
    the facing frontages (building outlines, walls, fences). The median of the cuts is kept when enough of them
    (30 % road edges, 50 % frontages) see both sides within 15 m; otherwise the width stays unknown (None).
    An OSM width tag, where mapped, is used as it is."""
    RM = 15.0

    def seg_grid(polys, closed):
        g = Grid(20.0)
        for P in polys:
            n = len(P)
            for k in range(n if closed else n - 1):
                a, b = P[k], P[(k + 1) % n]
                g.add((a, b), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))
        return g
    g_edge = seg_grid(S.road_edges, False)
    g_front = seg_grid([P for u in S.bld for P in u["parts"]], True)
    for P in S.walls + S.fences:
        for k in range(len(P) - 1):
            a, b = P[k], P[k + 1]
            g_front.add((a, b), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))

    def hit(g, px, py, dx, dy):
        ex, ey = px + dx * RM, py + dy * RM
        best = None
        for a, b in g.query((min(px, ex), min(py, ey), max(px, ex), max(py, ey))):
            r = seg_x((px, py), (dx * RM, dy * RM), a, (b[0] - a[0], b[1] - a[1]))
            if r is not None and r[0] * RM > 0.3 and (best is None or r[0] * RM < best):
                best = r[0] * RM
        return best
    for r in S.roads + S.paths:
        tw_ = num(r["tags"].get("width"))
        if tw_ is not None and 0.5 <= tw_ <= 40.0:
            r["w"], r["w_src"] = tw_, "OSM width"
            continue
        if r["tags"].get("footway") in ("sidewalk", "crossing") or r["tags"].get("path") == "sidewalk":
            r["w"], r["w_src"] = None, None              # part of a street: measuring across it gives the street
            continue
        pts = resample(r["P"], 4.0)
        cuts = []
        for i in range(1, len(pts) - 1):
            x, y = pts[i]
            tx, ty = pts[i + 1][0] - pts[i - 1][0], pts[i + 1][1] - pts[i - 1][1]
            L_ = math.hypot(tx, ty)
            if L_ >= 1e-6:
                cuts.append((x, y, -ty / L_, tx / L_))
        n = len(cuts)
        r["w"], r["w_src"] = None, None
        if not n:
            continue
        kw = []
        for x, y, nx, ny in cuts:
            a = hit(g_edge, x, y, nx, ny)
            b = hit(g_edge, x, y, -nx, -ny) if a is not None else None
            if a is not None and b is not None:
                kw.append(a + b)
        if len(kw) >= max(3, 0.3 * n):
            kw.sort()
            r["w"], r["w_src"] = kw[len(kw) // 2], "road edges"
            continue
        fw = []
        for x, y, nx, ny in cuts:
            a = hit(g_front, x, y, nx, ny)
            b = hit(g_front, x, y, -nx, -ny) if a is not None else None
            if a is not None and b is not None:
                fw.append(a + b)
        if len(fw) >= max(3, 0.5 * n):
            fw.sort()
            r["w"], r["w_src"] = fw[len(fw) // 2], "frontages"
    g_rd = Grid(30.0)
    for r in S.roads:
        g_rd.add(r, r["bb"])
    for r in S.paths:                                    # a path running inside a street is that street's pavement
        if not r.get("w") or r.get("w_src") == "OSM width":
            continue
        ds = []
        for x, y in resample(r["P"], 4.0):
            near = [pl_dist(x, y, q["P"], False) for q in g_rd.query((x - 20, y - 20, x + 20, y + 20))]
            ds.append(min(near) if near else 1e9)
        ds.sort()
        if ds and ds[len(ds) // 2] < r["w"] / 2.0:
            r["w"], r["w_src"] = None, None


# ============================================================ STREETS AS SURFACES (v16.2)
# Every street with a measured width becomes its surface between two edges. Across the centreline every 2 m each
# side is measured on its own to the surveyed road edge (YOL_SOSE / YOL_BORDUR / YOL_TOPRAK), so an OSM line that is
# off the middle of the street does not matter; a side without a surveyed edge within reach takes the street's
# measured width (measure_widths) less the other side. A street end reaches into the street it meets (half the
# narrower width) so junctions close; a dead end stops where the street does. The surfaces are merged into one outline
# per block of streets (raster union, as the river) and the outline is then laid back onto the measured edges, so the
# two edge lines are the measured ones, not the raster's steps. The open water is never a street: where a street's
# side reaches over the river it stops at the water, except on the bridges (OSM bridge ways, the surveyed decks) and
# where a street crosses the stream.
ROAD_CELL = 0.25           # m, raster of the union
ROAD_SNAP = 0.03           # m, simplification of an outline lying on a measured edge (the raster's steps: 0.75 cell)
ROAD_FILL = C("D3D4CC")    # street surface on the plan: a cool, light stone grey under the warm fabric
ROAD_EDGE = mix(INK, PAPER, 0.5)


def is_bridge(r):
    b = (r["tags"].get("bridge") or "").strip().lower()
    return b not in ("", "no", "0", "false")


def mask_at(F, M, x, y):
    """Is the point in a raster mask over the frame (dict rows / nx / ny / cell)?"""
    u, v = F.local(x, y)
    i, j = int(math.floor((u - F.u0) / M["cell"])), int(math.floor((v - F.v0) / M["cell"]))
    if 0 <= j < M["ny"] and 0 <= i < M["nx"]:
        return (M["rows"][j] >> i) & 1 == 1
    return False


def road_polys(S, wet=None):
    """The surface of every measured street and path as a polygon (world coordinates): [dict(P, bridge)]. With wet
    (a point test for open water), a stretch where a street crosses the stream comes out again as its own piece
    marked bridge, so the water never cuts a street where the street crosses it."""
    g_edge = Grid(20.0)
    for P in S.road_edges:
        for k in range(len(P) - 1):
            a, b = P[k], P[k + 1]
            g_edge.add((a, b), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))

    def hit(px, py, dx, dy, rm):
        ex, ey = px + dx * rm, py + dy * rm
        best = None
        for a, b in g_edge.query((min(px, ex), min(py, ey), max(px, ex), max(py, ey))):
            r = seg_x((px, py), (dx * rm, dy * rm), a, (b[0] - a[0], b[1] - a[1]))
            if r is not None and r[0] * rm > 0.3 and (best is None or r[0] * rm < best):
                best = r[0] * rm
        return best

    def smooth(vals, r):
        med = [sorted(vals[max(0, i - r):i + r + 1])[len(vals[max(0, i - r):i + r + 1]) // 2] for i in range(len(vals))]
        return [sum(med[max(0, i - 1):i + 2]) / float(len(med[max(0, i - 1):i + 2])) for i in range(len(med))]
    meas = [r for r in S.roads + S.paths if r.get("w") and r["w"] >= 0.8 and len(r["P"]) >= 2 and
            pl_length(r["P"]) >= 1.0]
    # every vertex of every measured way: an end on another way is a joint, an end on none a dead end
    g_v = Grid(2.0)
    for wi, r in enumerate(meas):
        for p in r["P"]:
            g_v.add((wi, p), (p[0], p[1], p[0], p[1]))

    def joint(wi, p):
        best = 0.0
        for wj, q in g_v.query((p[0] - 0.5, p[1] - 0.5, p[0] + 0.5, p[1] + 0.5)):
            if wj != wi and abs(q[0] - p[0]) <= 0.5 and abs(q[1] - p[1]) <= 0.5:
                best = max(best, meas[wj]["w"] / 2.0)
        return best
    # the stream's direction, to tell a street crossing it from one running along its bank
    g_riv = Grid(30.0)
    for P in getattr(S, "selinus", None) or []:
        for k in range(len(P) - 1):
            a, b = P[k], P[k + 1]
            g_riv.add((a, b), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))

    def across(x, y, tx, ty):
        best, d0 = None, 60.0
        for a, b in g_riv.query((x - 60, y - 60, x + 60, y + 60)):
            d = seg_dist(x, y, a[0], a[1], b[0], b[1])
            if d < d0:
                d0, best = d, (a, b)
        if best is None:
            return True                                  # other water: a way over it crosses it
        a, b = best
        L_ = math.hypot(b[0] - a[0], b[1] - a[1]) or 1.0
        return abs(tx * (b[0] - a[0]) / L_ + ty * (b[1] - a[1]) / L_) < 0.7     # more than 45 degrees off the stream

    out = []
    for wi, r in enumerate(meas):
        w = r["w"]
        P = r["P"]
        pts = resample(P, 2.0)
        if math.hypot(pts[-1][0] - P[-1][0], pts[-1][1] - P[-1][1]) > 0.2:
            pts.append(P[-1])
        n = len(pts)
        if n < 2:
            continue
        rm = min(15.0, 1.5 * w + 2.0)
        T, Ls, Rs = [], [], []
        for k in range(n):
            a_, b_ = pts[max(0, k - 1)], pts[min(n - 1, k + 1)]
            d_ = math.hypot(b_[0] - a_[0], b_[1] - a_[1]) or 1.0
            tx, ty = (b_[0] - a_[0]) / d_, (b_[1] - a_[1]) / d_
            T.append((tx, ty))
            nx, ny = -ty, tx
            a = hit(pts[k][0], pts[k][1], nx, ny, rm)
            b = hit(pts[k][0], pts[k][1], -nx, -ny, rm)
            if a is not None and b is not None and 0.6 * w <= a + b <= 1.5 * w:
                l_, r_ = a, b
            elif a is not None and a <= 1.2 * w and w - a >= 0.3:
                l_, r_ = a, w - a
            elif b is not None and b <= 1.2 * w and w - b >= 0.3:
                l_, r_ = w - b, b
            else:
                l_ = r_ = w / 2.0
            Ls.append(l_)
            Rs.append(r_)
        Ls, Rs = smooth(Ls, 2), smooth(Rs, 2)
        Ls = [max(0.3, min(1.5 * w, v)) for v in Ls]
        Rs = [max(0.3, min(1.5 * w, v)) for v in Rs]
        left = [(p[0] - t[1] * l_, p[1] + t[0] * l_) for p, t, l_ in zip(pts, T, Ls)]
        right = [(p[0] + t[1] * r_, p[1] - t[0] * r_) for p, t, r_ in zip(pts, T, Rs)]
        closed = math.hypot(P[0][0] - P[-1][0], P[0][1] - P[-1][1]) < 0.3
        e0 = 0.5 * (Ls[0] + Rs[0]) if closed else min(0.5 * (Ls[0] + Rs[0]), joint(wi, P[0]))
        e1 = 0.5 * (Ls[-1] + Rs[-1]) if closed else min(0.5 * (Ls[-1] + Rs[-1]), joint(wi, P[-1]))
        t0, t1 = T[0], T[-1]
        L2 = [(left[0][0] - t0[0] * e0, left[0][1] - t0[1] * e0)] + left + [(left[-1][0] + t1[0] * e1, left[-1][1] + t1[1] * e1)]
        R2 = [(right[0][0] - t0[0] * e0, right[0][1] - t0[1] * e0)] + right + [(right[-1][0] + t1[0] * e1, right[-1][1] + t1[1] * e1)]
        brg = is_bridge(r)
        out.append(dict(P=L2 + list(reversed(R2)), bridge=brg))
        if brg or wet is None:
            continue
        # a crossing: a run of stations over open water, the street across the stream there
        k = 0
        while k < n:
            if not wet(pts[k][0], pts[k][1]):
                k += 1
                continue
            k0 = k
            while k < n and wet(pts[k][0], pts[k][1]):
                k += 1
            k1 = k - 1
            tx = sum(T[q][0] for q in range(k0, k1 + 1))
            ty = sum(T[q][1] for q in range(k0, k1 + 1))
            tl = math.hypot(tx, ty) or 1.0
            mid = pts[(k0 + k1) // 2]
            if across(mid[0], mid[1], tx / tl, ty / tl):
                a0, a1 = max(0, k0 - 1), min(n - 1, k1 + 1)
                out.append(dict(P=left[a0:a1 + 1] + list(reversed(right[a0:a1 + 1])), bridge=True))
    return out


def dp_tols(P, tols):
    """Douglas-Peucker on an open chain where every point carries its own tolerance: indices kept."""
    n = len(P)
    if n < 3:
        return list(range(n))
    keep = [False] * n
    keep[0] = keep[-1] = True
    stack = [(0, n - 1)]
    while stack:
        a, b = stack.pop()
        if b <= a + 1:
            continue
        ax, ay = P[a]
        dx, dy = P[b][0] - ax, P[b][1] - ay
        L_ = math.hypot(dx, dy)
        best, bi = 1.0, -1
        for i in range(a + 1, b):
            px, py = P[i]
            d = abs(dy * (px - ax) - dx * (py - ay)) / L_ if L_ > 1e-12 else math.hypot(px - ax, py - ay)
            q = d / tols[i]
            if q > best:
                best, bi = q, i
        if bi >= 0:
            keep[bi] = True
            stack.append((a, bi))
            stack.append((bi, b))
    return [i for i in range(n) if keep[i]]


def mask_regions(F, rows, nx, ny, cell, min_body, min_hole, tol, snap=None, wet_snap=None):
    """Outlines of a raster mask over the frame: [(outer, holes)] in world coordinates, plus the edge polylines (every
    outline less its stretches on the frame edge). snap: polygons (world) whose edges the outline is laid onto where it
    runs within a cell of them, so the outline is the measured edge itself, not the raster's steps; wet_snap: the
    same for the water's outline, whose stretches are then left out of the edge lines (the water draws its own)."""
    u1, v1 = F.u0 + F.w, F.v0 + F.h
    edge = 0.75 * cell

    def local(i, j):
        u, v = F.u0 + i * cell, F.v0 + j * cell
        b = False
        if i <= 0:
            u, b = F.u0, True
        elif u >= u1 - edge:
            u, b = u1, True
        if j <= 0:
            v, b = F.v0, True
        elif v >= v1 - edge:
            v, b = v1, True
        return (u, v), b
    sg = None
    if snap or wet_snap:
        sg = Grid(2.0)
        for tag, polys in ((0, snap or []), (1, wet_snap or [])):
            for P in polys:
                Q = [F.local(x, y) for x, y in P]
                m = len(Q)
                for k in range(m):
                    a, b = Q[k], Q[(k + 1) % m]
                    if abs(a[0] - b[0]) + abs(a[1] - b[1]) < 1e-9:
                        continue
                    sg.add((a, b, tag), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))
    rs = cell

    def snap_pt(p):
        best, bq, bt = rs, None, None
        px, py = p
        for a, b, tag in sg.query((px - rs, py - rs, px + rs, py + rs)):
            dx, dy = b[0] - a[0], b[1] - a[1]
            t = ((px - a[0]) * dx + (py - a[1]) * dy) / (dx * dx + dy * dy)
            t = 0.0 if t < 0.0 else (1.0 if t > 1.0 else t)
            qx, qy = a[0] + t * dx, a[1] + t * dy
            d = math.hypot(px - qx, py - qy)
            if d < best:
                best, bq, bt = d, (qx, qy), tag
        return bq, bt
    outers, holes = [], []
    for lp in mask_loops(rows, nx):
        pts, brd = [], []
        for i, j in lp:
            p, b = local(i, j)
            pts.append(p)
            brd.append(b)
        a = signed_area(pts)
        if a >= min_body:
            outers.append([pts, brd, a, []])
        elif a <= -min_hole:
            holes.append([pts, brd, a])
    outers.sort(key=lambda o: o[2])
    for h in holes:
        (x0, y0), (x1, y1) = h[0][0], h[0][1]
        L_ = math.hypot(x1 - x0, y1 - y0) or 1.0
        px, py = (x0 + x1) / 2.0 - (y1 - y0) / L_ * 0.25 * cell, (y0 + y1) / 2.0 + (x1 - x0) / L_ * 0.25 * cell
        for o in outers:
            if pip(px, py, o[0]):
                o[3].append(h)
                break

    def snapped(pts, brd):
        """The ring laid onto the measured edges and simplified: (points, tags) with tag 0 road edge, 1 water edge,
        2 frame edge, None raster."""
        Q, tg = [], []
        for p, b in zip(pts, brd):
            if b:
                Q.append(p)
                tg.append(2)
                continue
            q, t = snap_pt(p)
            Q.append(q if q is not None else p)
            tg.append(t)
        n = len(Q)
        tol_of = [ROAD_SNAP if t in (0, 1) else (0.75 * cell if t is None else 1e-9) for t in tg]
        anchors = [k for k in range(n) if tg[k] == 2]
        if not anchors:
            far = max(range(n), key=lambda k: (Q[k][0] - Q[0][0]) ** 2 + (Q[k][1] - Q[0][1]) ** 2)
            if far == 0:
                return Q, tg
            anchors = [0, far]
        keep = []
        for q in range(len(anchors)):
            s, e = anchors[q], anchors[(q + 1) % len(anchors)]
            idx = list(range(s, e + 1)) if e > s else list(range(s, n)) + list(range(0, e + 1))
            ch = dp_tols([Q[k] for k in idx], [tol_of[k] for k in idx])
            keep += [idx[k] for k in ch[:-1]]
        out, ot = [], []
        for k in keep:
            if not out or abs(Q[k][0] - out[-1][0]) > 1e-6 or abs(Q[k][1] - out[-1][1]) > 1e-6:
                out.append(Q[k])
                ot.append(tg[k])
        while len(out) > 2 and abs(out[0][0] - out[-1][0]) <= 1e-6 and abs(out[0][1] - out[-1][1]) <= 1e-6:
            out.pop()
            ot.pop()
        return out, ot
    regions, lines = [], []
    for pts, brd, area, hl in outers:
        rings = [(pts, brd)] + [(h[0], h[1]) for h in hl]
        final = None
        if sg is not None:
            cand = [snapped(p, b) for p, b in rings]
            if all(len(c[0]) >= 3 for c in cand) and loops_simple([c[0] for c in cand]) and \
                    signed_area(cand[0][0]) > 0 and all(signed_area(c[0]) < 0 for c in cand[1:]):
                final = cand
        if final is None:
            for tl, it in ((tol, 2), (tol, 0), (0.0, 0)):
                cand = [dedupe_ring(smooth_loop(p, b, tl, it) if tl > 0 else p) for p, b in rings]
                if all(len(c) >= 3 for c in cand) and (tl == 0.0 or loops_simple(cand)):
                    final = [(c, [None] * len(c)) for c in cand]
                    break
        if final is None:
            continue
        regions.append(([F.world(u, v) for u, v in final[0][0]], [[F.world(u, v) for u, v in c] for c, t in final[1:]]))
        for c, tg in final:
            n = len(c)
            on = [abs(u - F.u0) < 1e-6 or abs(u - u1) < 1e-6 or abs(v - F.v0) < 1e-6 or abs(v - v1) < 1e-6 for u, v in c]
            cut = [k for k in range(n) if (on[k] and on[(k + 1) % n] and (
                (abs(c[k][0] - c[(k + 1) % n][0]) < 1e-6) or (abs(c[k][1] - c[(k + 1) % n][1]) < 1e-6))) or
                   (tg[k] == 1 and tg[(k + 1) % n] == 1)]
            if not cut:
                lines.append([F.world(u, v) for u, v in c + [c[0]]])
                continue
            cuts = set(cut)
            s0 = (cut[0] + 1) % n
            run = [c[s0]]
            for q in range(1, n + 1):
                k = (s0 + q - 1) % n
                if k in cuts:
                    if len(run) >= 2:
                        lines.append([F.world(u, v) for u, v in run])
                    run = [c[(k + 1) % n]]
                else:
                    run.append(c[(k + 1) % n])
            if len(run) >= 2:
                lines.append([F.world(u, v) for u, v in run])
    return regions, lines


def mask_of(F, polys, cell, nx, ny, holes=None):
    """Raster rows (one int per row) of polygons given in world coordinates (non-zero winding; holes cut out)."""
    rows = [0] * ny
    for P in polys:
        loops = [[F.local(x, y) for x, y in P]]
        for j, spans in poly_spans(loops, F.u0, F.v0, cell, nx, ny, nonzero=True):
            m = rows[j]
            for a, b in spans:
                m |= ((1 << (b - a)) - 1) << a
            rows[j] = m
    if holes:
        hr = mask_of(F, holes, cell, nx, ny)
        rows = [r & ~h for r, h in zip(rows, hr)]
    return rows


def build_road_net(S):
    """The street surfaces merged into one outline per block of streets (S.road_net), their edges (S.road_lines_net),
    the raster itself (S.road_mask, for the sections) and the polygons (S.road_polys). Runs after the river."""
    F = S.F
    S.road_net, S.road_lines_net, S.road_mask, S.road_polys = [], [], None, []
    cell = ROAD_CELL
    nx, ny = int(math.ceil(F.w / cell)), int(math.ceil(F.h / cell))
    wat = [w for w in (getattr(S, "water", None) or []) if len(w["P"]) >= 3]
    wrows = None
    if wat:                                           # the open water (the bridge decks left out: streets cross there)
        wrows = mask_of(F, [w["P"] for w in wat], cell, nx, ny, holes=[h for w in wat for h in (w.get("H") or [])])
        decks = [P for P in (getattr(S, "decks", None) or []) if len(P) >= 3]
        if decks:
            drows = mask_of(F, decks, cell, nx, ny)
            wrows = [a & ~b for a, b in zip(wrows, drows)]
    WM = dict(rows=wrows, nx=nx, ny=ny, cell=cell) if wrows else None
    polys = road_polys(S, (lambda x, y: mask_at(F, WM, x, y)) if WM else None)
    S.road_polys = [d["P"] for d in polys]
    if not polys:
        return
    rows = mask_of(F, [d["P"] for d in polys if not d["bridge"]], cell, nx, ny)
    if wrows:
        rows = [a & ~b for a, b in zip(rows, wrows)]
    br = [d["P"] for d in polys if d["bridge"]]
    if br:
        rows = [a | b for a, b in zip(rows, mask_of(F, br, cell, nx, ny))]
    rows = mask_unpinch(mask_close(rows, nx, 1), nx)
    S.road_mask = dict(rows=rows, nx=nx, ny=ny, cell=cell)
    wet = [w["P"] for w in wat] + [h for w in wat for h in (w.get("H") or [])]
    regions, lines = mask_regions(F, rows, nx, ny, cell, 4.0, 2.0, 0.12, snap=S.road_polys, wet_snap=wet)
    S.road_net = [dict(P=P, H=H) for P, H in regions]
    S.road_lines_net = lines


ROAD_HATCH_SP = 0.13     # v16.5: street hatch, page units (U) between its lines, at 45 degrees ...
ROAD_HATCH_W = 0.03      # ... and their print weight (mm)
ROAD_SOLID = True        # v16.7 (Nil): street surfaces in one solid colour, no hatch lines. False = the v16.6 hatch
ROAD_FILL = (207, 204, 197)       # v16.7: that colour on the plans and in the land-use sections (a warm light grey)
ROAD_FILL_OVER = (178, 178, 184)  # v16.7: the street surfaces over the sound maps (T1), a cool grey that reads on them


def road_lines(S, B, V, L, order, casing=None, surface=ROADC, min_w=0.06, paths=False, fill=None, hatch=True):
    """Streets at their surveyed width: the surface between its two edges (one outline per block of streets, so
    junctions are clean); a street whose width the survey does not show is a single thin line on its centre.
    Footpaths optional as thin dashes. v16.5: the street surfaces hatched (fine 45-degree lines, a shade darker than
    the edges' paper) in every plan that shows them."""
    casing = casing or mix(INK, PAPER, 0.5)
    net = getattr(S, "road_net", None)
    if net:
        col = fill if fill is not None else surface
        hc = mix(casing, col, 0.2)
        for rg_ in net:
            if hatch and ROAD_SOLID:                      # v16.7: one solid colour
                B.fill(V.Ps([rg_["P"]] + rg_["H"]), ROAD_FILL if fill is None else col, L, order)
                continue
            B.fill(V.Ps([rg_["P"]] + rg_["H"]), col, L, order)
            if hatch:
                B.hatch(V.Ps([rg_["P"]] + rg_["H"]), hc, L, order, ROAD_HATCH_SP * S.U, w=ROAD_HATCH_W)
        for P in getattr(S, "road_lines_net", []):
            B.line(V.P(P), casing, L, order + 1, 0.05)
        for r in S.roads:
            if not r.get("w"):
                B.line(V.P(r["P"]), casing, L, order + 1, 0.06)
    else:
        s = V.s
        rs = sorted(S.roads, key=lambda r: r["tags"].get("highway") in MAIN_ROADS)
        for r in rs:
            if r.get("w"):
                B.line(V.P(r["P"]), casing, L, order, max(min_w, r["w"] * s * MMU) + 0.07)
            else:
                B.line(V.P(r["P"]), casing, L, order, 0.07)
        for r in rs:
            if r.get("w"):
                B.line(V.P(r["P"]), surface, L, order + 1, max(min_w, r["w"] * s * MMU))
    if paths:
        for p in S.paths:
            for d in dashes(V.P(p["P"]), 0.3 * S.U, 0.2 * S.U):
                B.line(d, casing, L, order + 1, 0.05)


def road_overlay(S, B, V, L, order, col=(52, 52, 58)):
    """v16.6: the streets drawn OVER an analysis map without hiding it: each street surface hatched with fine lines
    (no fill, the analysis colours show between them), its edges, and the centre line of a street whose width the
    survey does not show. Used on the sound maps (T1), where the streets are the sources."""
    net = getattr(S, "road_net", None)
    if net:
        for rg_ in net:
            if ROAD_SOLID:                                # v16.7: a solid surface over the map (hides the colour there)
                B.fill(V.Ps([rg_["P"]] + rg_["H"]), ROAD_FILL_OVER, L, order)
            else:
                B.hatch(V.Ps([rg_["P"]] + rg_["H"]), col, L, order, ROAD_HATCH_SP * 1.4 * S.U, w=ROAD_HATCH_W)
        for P in getattr(S, "road_lines_net", []):
            B.line(V.P(P), col, L, order + 1, 0.05)
        for r in S.roads:
            if not r.get("w"):
                B.line(V.P(r["P"]), col, L, order + 1, 0.06)
    else:
        for r in S.roads:
            B.line(V.P(r["P"]), col, L, order + 1, 0.06)


def is_heritage(t):
    h = t.get("historic")
    return (h is not None and h not in ("memorial", "boundary_stone", "milestone", "wayside_cross", "yes")) \
        or t.get("tourism") in ("museum", "attraction")


def zone_class(t):
    lu, le, na, am = t.get("landuse"), t.get("leisure"), t.get("natural"), t.get("amenity")
    if lu in AGRI_TREES_LU:
        return ("agri", "orchard")
    if lu in AGRI_FIELD_LU:
        return ("agri", "field")
    if lu in GREEN_WOOD_LU or na in GREEN_WOOD_NAT:
        return ("green", "wood")
    if le in GREEN_PARK_LE or lu in GREEN_PARK_LU:
        return ("green", "park")
    if lu in GREEN_GRASS_LU or na in GREEN_GRASS_NAT or le in GREEN_GRASS_LE:
        return ("green", "grass")
    if am in ("parking", "bus_station") or lu == "garages":
        return ("transport", None)
    if lu in VACANT_LU:
        return ("vacant", None)
    return None


def poi_class(t):
    am = t.get("amenity")
    if am == "place_of_worship" or is_heritage(t):
        return "religious"
    if am in INST_AMEN:
        return "institutional"
    if "shop" in t or "office" in t or "craft" in t or am in COM_AMEN or \
            t.get("tourism") in ("hotel", "guest_house", "hostel", "motel"):
        return "commercial"
    if am in TRN_AMEN:
        return "transport"
    return None


def chain_segments(segs, tol=0.02):
    """Join 2-point segments that share endpoints into polylines (fewer objects to draw)."""
    key = lambda p: (round(p[0] / tol), round(p[1] / tol))
    ends = {}
    for i, s in enumerate(segs):
        ends.setdefault(key(s[0]), []).append(i)
        ends.setdefault(key(s[-1]), []).append(i)
    used = [False] * len(segs)
    out = []
    for i in range(len(segs)):
        if used[i]:
            continue
        used[i] = True
        line = list(segs[i])
        for direction in (0, 1):
            while True:
                tip = line[-1] if direction == 0 else line[0]
                nxt = None
                for j in ends.get(key(tip), ()):
                    if not used[j]:
                        nxt = j
                        break
                if nxt is None:
                    break
                used[nxt] = True
                s = segs[nxt]
                pts = list(s) if key(s[0]) == key(tip) else list(reversed(s))
                if direction == 0:
                    line += pts[1:]
                else:
                    line = list(reversed(pts[1:])) + line
        out.append(line)
    return out


class Site(object):
    pass


# ------------------------------------------------------------ floors and heights that the survey does not record
NB_K = 5            # unlabelled buildings take the floor count shared by most of the 5 nearest surveyed counts
# Monuments with a published height (OSM way id: metres, source). Used instead of floors x storey height.
DOC_HEIGHT = {
    "1087234401": (19.0, "Red Basilica hall: walls stand to 19 m (Koester 2007, p. 171; Wikipedia 'Red Basilica')"),
    "1222770549": (18.0, "Red Basilica south rotunda: 18 m high (Wikipedia 'Red Basilica')"),
    "1222770550": (18.0, "Red Basilica north rotunda, Kurtulus Camii: 18 m high (Wikipedia 'Red Basilica')"),
}


def nearest_samples(g, x, y, k, skip=None):
    """The k surveyed floor counts nearest to (x, y) as [(distance, sample)], ties in order of position; g is a
    40 m Grid of the samples. Rings of cells are added until no unvisited cell can hold a nearer sample."""
    c = g.c
    i0, j0 = int(math.floor(x / c)), int(math.floor(y / c))
    get = g.d.get
    found = []
    r = 0
    while r <= 60:
        for i in range(i0 - r, i0 + r + 1):
            edge = abs(i - i0) == r
            for j in ((range(j0 - r, j0 + r + 1)) if edge else (j0 - r, j0 + r)):
                for s in get((i, j), ()):
                    if s is not skip:
                        found.append((math.hypot(s[0] - x, s[1] - y), s[0], s[1], s))
        if len(found) >= k:
            found.sort(key=lambda t: t[:3])
            if found[k - 1][0] <= r * c:
                break
        r += 1
    found.sort(key=lambda t: t[:3])
    return [(t[0], t[3]) for t in found[:k]]


def floors_from(nb):
    """The floor count shared by most of the neighbours; a tie goes to the nearest of the tied counts."""
    cnt = {}
    for d, s in nb:
        cnt[s[2]] = cnt.get(s[2], 0) + 1
    top = max(cnt.values())
    for d, s in nb:
        if cnt[s[2]] == top:
            return s[2]


HOUSING = {"residential": "housing", "mixed": "housing", "commercial": "housing", "annex": "housing"}


def floors_loo(samples, g, by_use=None):
    """How well the rule works here: each surveyed count predicted from its NB_K nearest others (of the same use
    for non-housing buildings, as the rule is applied). Returns (tested, % the same, % within one floor)."""
    n = same = near = 0
    for s in samples:
        gg = (by_use or {}).get(s[3], g) if len(s) > 3 and s[3] != "housing" else g
        nb = nearest_samples(gg, s[0], s[1], NB_K, skip=s)
        if not nb:
            continue
        f = floors_from(nb)
        n += 1
        same += f == s[2]
        near += abs(f - s[2]) <= 1
    return (n, 100.0 * same / n, 100.0 * near / n) if n else (0, 0.0, 0.0)


# ============================================================ SITE ASSEMBLY
def build_site(R, osm, places, F):
    S = Site()
    S.F = F
    S.U = F.w / 100.0
    S.frame_area = F.area
    bbm = (F.bb[0] - 40, F.bb[1] - 40, F.bb[2] + 40, F.bb[3] + 40)
    S.bbm = bbm
    S.stats = {}

    def seg_in(s):
        return bb_hit((min(s[0], s[2]), min(s[1], s[3]), max(s[0], s[2]), max(s[1], s[3])), bbm)

    lines = R["lines"]

    # ------------------------------------------------ survey footprints
    segs = []
    for lay in DWG["bld"]:
        segs += [(s[0], s[1], s[2], s[3], lay) for s in lines.get(lay, []) if seg_in(s)]
    segs += drop_x([(s[0], s[1], s[2], s[3], DWG["shed"]) for s in lines.get(DWG["shed"], []) if seg_in(s)])
    segs += [(s[0], s[1], s[2], s[3], "KAPI") for s in lines.get(DWG["door"], []) if seg_in(s)]
    segs += [(s[0], s[1], s[2], s[3], "WALL") for s in lines.get(DWG["walls"][0], []) if seg_in(s)]
    faces = polygonize(segs, holes=True)
    gF = Grid(40.0)
    for i, f in enumerate(faces):
        f["bb"] = bb_pts(f["P"])
        gF.add(i, f["bb"])
    labels = [(t[1], t[2], t[0].strip()) for t in R["texts"].get(DWG["floors"], [])
              if bbm[0] <= t[1] <= bbm[2] and bbm[1] <= t[2] <= bbm[3]]
    BLD_TAGS = set(DWG["bld"]) | {DWG["shed"], "KAPI"}

    def is_yard(tags):
        """A face closed mostly by garden walls is a yard or plot, not a building (its walls outweigh its building
        lines)."""
        return tags.get("WALL", 0.0) > sum(l for t, l in tags.items() if t in BLD_TAGS)

    def in_face(x, y, f):
        return pip(x, y, f["P"]) and not any(pip(x, y, H) for H in f.get("H") or ())
    lab, miss = {}, []
    n_yard_lab = 0
    for (x, y, v) in labels:
        c = [i for i in gF.query((x, y, x, y)) if in_face(x, y, faces[i])]
        if c:
            fi = min(c, key=lambda i: faces[i]["A"])
            if is_yard(faces[fi]["tags"]):
                miss.append((x, y, v))                     # the survey did not close this building's own outline
                n_yard_lab += 1
            else:
                lab.setdefault(fi, []).append((x, y, v))
        else:
            miss.append((x, y, v))
    gT = Grid(10.0)
    for s in segs:
        if s[4] in DWG["bld"] and math.hypot(s[2] - s[0], s[3] - s[1]) <= 6.0:
            gT.add(s, (min(s[0], s[2]), min(s[1], s[3]), max(s[0], s[2]), max(s[1], s[3])))

    def dom_kind(tags):
        best, bl = None, 0.0
        for t, l in tags.items():
            if (t in DWG["bld"] or t == DWG["shed"]) and l > bl:
                best, bl = t, l
        return best

    units = []
    gU_ = Grid(40.0)                                      # every unit so far (for the overlap tests below)

    def add_unit(parts, label, layer, src, tags=None, osm_id=None, holes=None):
        cp = []
        for P in parts:
            cp += [q for q in [F.clip_poly(P)] if q]
        if not cp:
            return None
        hs = [q for q in (F.clip_poly(H) for H in (holes or [])) if q]
        A = sum(shoelace(P)[0] for P in cp) - sum(shoelace(H)[0] for H in hs)
        if A < 1.0:
            return None
        cx = (sum(shoelace(P)[0] * shoelace(P)[1] for P in cp) - sum(shoelace(H)[0] * shoelace(H)[1] for H in hs)) / A
        cy = (sum(shoelace(P)[0] * shoelace(P)[2] for P in cp) - sum(shoelace(H)[0] * shoelace(H)[2] for H in hs)) / A
        u = dict(parts=cp, holes=hs, A=A, cx=cx, cy=cy, bb=bb_union([bb_pts(P) for P in cp]), layer=layer,
                 label=label, src=src, tags=tags or {}, name=((tags or {}).get("name") or "").strip(), osm_id=osm_id)
        units.append(u)
        gU_.add(u, u["bb"])
        return u

    def holes_in(H, Ps):
        """The holes whose inside lies in one of the outlines Ps."""
        out = []
        for h in H:
            x, y = interior_point(h)
            if any(pip(x, y, Q) for Q in Ps):
                out.append(h)
        return out

    for fi, labs in lab.items():
        f = faces[fi]
        layer = dom_kind(f["tags"]) or "BINA_MESKEN"
        if len(labs) == 1:
            add_unit([f["P"]], labs[0][2], layer, "dwg", holes=f["H"])
            continue
        ticks = [s for s in gT.query(f["bb"]) if pip((s[0] + s[2]) / 2.0, (s[1] + s[3]) / 2.0, f["P"])]
        try:
            for parts, l in split_face(f["P"], labs, ticks):
                add_unit(parts, l[2] if l else None, layer, "dwg", holes=holes_in(f["H"], parts))
        except Exception:
            for P, l in zip(voronoi_split(f["P"], [(l[0], l[1]) for l in labs]), labs):
                if P:
                    add_unit([P], l[2], layer, "dwg", holes=holes_in(f["H"], [P]))
    n_shed = n_yard = 0
    for fi, f in enumerate(faces):
        if fi in lab:
            continue
        layer = dom_kind(f["tags"])
        if (layer == DWG["shed"] and f["A"] > 2.5) or (layer in DWG["bld"] and DWG["bld"][layer] != "mesken" and f["A"] > 8.0):
            if is_yard(f["tags"]):
                n_yard += 1
                continue
            if layer == DWG["shed"]:
                u = add_unit([f["P"]], None, layer, "shed", holes=f["H"])
                n_shed += 1 if u else 0
            else:
                add_unit([f["P"]], None, layer, "dwg", holes=f["H"])
    S.stats["survey_units"] = len([u for u in units if u["src"] == "dwg"])
    S.stats["floor_labels"] = len(labels)
    S.stats["labels_unmatched"] = len(miss)
    S.stats["yards"] = (n_yard, n_yard_lab)

    # ------------------------------------------------ OSM buildings: fill what the survey lacks
    osm_b = []
    if osm:
        Pj = osm["P"]
        for wid, (refs, tags) in osm["ways"].items():
            if "building" in tags and len(refs) >= 4 and refs[0] == refs[-1]:
                P = [Pj(r) for r in refs[:-1]]
                P = [p for p in P if p]
                if len(P) >= 3 and bb_hit(bb_pts(P), bbm):
                    osm_b.append(dict(P=P, A=shoelace(P)[0], cx=shoelace(P)[1], cy=shoelace(P)[2],
                                      bb=bb_pts(P), tags=tags, used=False, id=wid))
    gO = Grid(40.0)
    for b in osm_b:
        gO.add(b, b["bb"])

    def covered(P, A):
        """Share of the OSM outline P already covered by the outlines kept so far (sampled on a fine grid)."""
        bb = bb_pts(P)
        cand = gU_.query(bb)
        if not cand:
            return 0.0
        step = max(0.5, math.sqrt(max(A, 1.0) / 600.0))
        n = hit = 0
        y = bb[1] + step / 2.0
        while y < bb[3]:
            x = bb[0] + step / 2.0
            while x < bb[2]:
                if pip(x, y, P):
                    n += 1
                    if any(pip(x, y, Q) for u in cand for Q in u["parts"]):
                        hit += 1
                x += step
            y += step
        return hit / float(n) if n else 0.0

    def osm_layer(tags):
        kind = OSM_BKIND.get(tags.get("building"))
        return [k for k, v in DWG["bld"].items() if v == kind][0] if kind else "BINA_MESKEN"
    n_fb = n_skip = 0
    for (x, y, v) in miss:
        for b in gO.query((x, y, x, y)):
            if not b["used"] and pip(x, y, b["P"]):
                if covered(b["P"], b["A"]) > 0.2:
                    b["used"] = True                       # OSM's outline is mostly a surveyed building already
                    n_skip += 1
                elif add_unit([b["P"]], v, osm_layer(b["tags"]), "osm+label", b["tags"], b["id"]):
                    b["used"] = True
                    n_fb += 1
                break
    # ------------------------------------------------ floor labels whose building outline the survey never closed:
    # the footprint is unknown, so no building is drawn or analysed there; the count still informs its neighbours
    S.labels_open = [(x, y, v) for (x, y, v) in miss
                     if F.inside(x, y) and not any(pip(x, y, P) for u in gU_.query((x, y, x, y)) for P in u["parts"])]
    S.stats["labels_open"] = len(S.labels_open)
    n_inf = 0
    for b in osm_b:
        if b["used"] or b["A"] < 15.0:
            continue
        if covered(b["P"], b["A"]) > 0.2:
            n_skip += 1
            continue
        if add_unit([b["P"]], None, osm_layer(b["tags"]), "osm", b["tags"], b["id"]):
            n_inf += 1
    S.stats["osm_fallback"] = n_fb
    S.stats["osm_infill"] = n_inf
    S.stats["osm_overlapping"] = n_skip
    # monuments with a published height keep it when the survey draws them (the OSM outline is then not used)
    for b in osm_b:
        if b["id"] in DOC_HEIGHT and not any(u.get("osm_id") == b["id"] for u in units):
            for u in gU_.query(b["bb"]):
                ix, iy = interior_point(u["parts"][0])
                if pip(ix, iy, b["P"]) or any(pip(*interior_point(b["P"]), Q) for Q in u["parts"]):
                    u["doc_id"] = b["id"]
    S.stats["sheds"] = n_shed

    # ------------------------------------------------ uses: survey layer > survey names > places/POIs
    gU = Grid(40.0)
    for u in units:
        gU.add(u, u["bb"])
    for t in R["texts"].get(DWG["names"], []):
        for u in gU.query((t[1], t[2], t[1], t[2])):
            if any(pip(t[1], t[2], P) for P in u["parts"]):
                u["name"] = (u["name"] + " " + t[0].strip()).strip()
                break
    pois = []
    for p in places or []:
        if F.inside(p["x"], p["y"]):
            pois.append(dict(p, in_bld=False))
    if osm:
        for ll, tags in osm["pois"]:
            pc = poi_class(tags)
            if pc:
                x, y = to_dwg(*ll)
                if F.inside(x, y):
                    pois.append(dict(x=x, y=y, cat=pc, name=tags.get("name", ""), src="osm", in_bld=False,
                                     her=is_heritage(tags)))
    S.pois = pois
    gP = Grid(30.0)
    for p in pois:
        gP.add(p, (p["x"], p["y"], p["x"], p["y"]))
    # ---- v16.7: each building's own name, where a source gives one (drawn instead of its type word: "Ulu Camii", not
    #      "mosque"). Survey name text inside it, then a named OpenStreetMap outline over it, then a named place of
    #      worship, heritage or civic point inside it. A name that is only a type word (cami, trafo, depo ...) is
    #      not a name. Nothing is guessed: a building no source names keeps its type word.
    for u in units:
        cand = [(u.get("name") or "", "survey name" if u["src"] not in ("osm", "osm+label") else "OpenStreetMap")]
        ix_, iy_ = interior_point(u["parts"][0])
        for b in gO.query(u["bb"]):
            nm_ = (b["tags"].get("name") or "").strip()
            if nm_ and (pip(ix_, iy_, b["P"]) or any(pip(b["cx"], b["cy"], Q) for Q in u["parts"])):
                cand.append((nm_, "OpenStreetMap"))
        for p in gP.query(u["bb"]):
            if p.get("name") and p["cat"] in ("religious", "institutional") and \
                    any(pip(p["x"], p["y"], Q) for Q in u["parts"]):
                cand.append((p["name"], "OpenStreetMap point" if p.get("src") == "osm" else "places"))
        u["proper"], u["proper_src"] = next(((proper_name(c_), sr_) for c_, sr_ in cand if proper_name(c_)), ("", ""))
    S.stats["named_buildings"] = sum(1 for u in units if u["proper"])
    # ---- pass 1: use (survey layer > survey names > places), surveyed floor counts, OpenStreetMap levels
    for u in units:
        kind = DWG["bld"].get(u["layer"], "mesken")
        cat = KIND_CAT.get(kind, "residential")
        nm = u["name"].lower()
        for key, c in NAME_RULES:
            if key in nm:
                cat = c
                break
        lbl = (u["label"] or "").strip()
        floors, fsrc = None, None
        if lbl.isdigit():
            floors, fsrc = max(1, int(lbl)), "survey"
        elif lbl:
            ll = lbl.lower()
            if ll.startswith("mezar") or ll.startswith("çeş") or ll.startswith("ces"):
                cat, floors, fsrc = "religious", 1, "survey"     # a tomb or fountain, as the survey names it
            elif "fab" in ll:
                cat = "industrial"
            elif "havuz" in ll:
                cat, floors, fsrc = "water", 0, "survey"
        tg = u.get("tags") or {}
        if floors is None:
            lv = num(tg.get("building:levels"))
            if lv is not None and 1.0 <= lv <= 60.0:
                floors, fsrc = int(round(lv)), "osm"
        cnt = {}
        for p in gP.query((u["bb"][0] - 3, u["bb"][1] - 3, u["bb"][2] + 3, u["bb"][3] + 3)):
            inside = any(pip(p["x"], p["y"], P) for P in u["parts"])
            if inside or min(pl_dist(p["x"], p["y"], P, True) for P in u["parts"]) <= 3.0:
                cnt[p["cat"]] = cnt.get(p["cat"], 0) + (2 if inside else 1)
                p["in_bld"] = True
        shop = False
        if u["src"] == "shed":
            cat = "annex"
            floors, fsrc = 1, "shed"                         # a sundurma is one open, roofed level
        elif cat == "residential":
            if cnt.get("religious", 0) >= 2:
                cat = "religious"
            elif cnt.get("institutional", 0) >= 2:
                cat = "institutional"
            elif cnt.get("commercial", 0):
                cat, shop = "commercial", True               # commerce, or mixed use once the floors are known
            elif cnt.get("industrial", 0):
                cat = "industrial"
        u["cat"], u["_shop"] = cat, shop
        u["floors"], u["floors_src"] = floors, fsrc
    # ---- every surveyed floor count, inside a closed outline or not, with the use of the building it stands in
    # (a count whose outline the survey never closed stands for a house). These are the measurements the buildings
    # without a count take theirs from: the count shared by most of the NB_K nearest; civic, sacred, industrial
    # and other non-housing buildings look only at surveyed buildings of their own use, where there are any.
    gUc = Grid(40.0)
    for u in units:
        gUc.add(u, u["bb"])
    samples = []
    for (x, y, v) in labels:
        if not v.isdigit():
            continue
        c_ = "residential"
        for u in gUc.query((x, y, x, y)):
            if u["floors_src"] == "survey" and any(pip(x, y, P) for P in u["parts"]):
                c_ = u["cat"]
                break
        samples.append((x, y, max(1, int(v)), HOUSING.get(c_, c_)))
    gS = Grid(40.0)
    by_use = {}
    for s_ in samples:
        gS.add(s_, (s_[0], s_[1], s_[0], s_[1]))
        if s_[3] != "housing":
            by_use.setdefault(s_[3], Grid(40.0)).add(s_, (s_[0], s_[1], s_[0], s_[1]))
    S.floor_samples = samples
    S.floor_test = floors_loo(samples, gS, by_use)
    for u in units:
        if u["floors"] is None:
            use = HOUSING.get(u["cat"], u["cat"])
            nb = nearest_samples(by_use[use] if use in by_use else gS, u["cx"], u["cy"], NB_K)
            if nb:
                u["floors"], u["floors_src"] = floors_from(nb), "neighbours"
        if u["_shop"] and (u["floors"] or 1) > 1:
            u["cat"] = "mixed"                           # shop below, home above
        u["floors_src"] = u["floors_src"] or "none"
        u["floors"] = u["floors"] if u["floors"] is not None else 0
        del u["_shop"]
    for u in units:                                     # sheds take the use of their neighbour
        if u["cat"] != "annex":
            continue
        best, bd = None, 6.0
        for v in gU.query((u["cx"] - 6, u["cy"] - 6, u["cx"] + 6, u["cy"] + 6)):
            if v is u or v["src"] == "shed" or v["cat"] in ("annex", "water"):
                continue
            d = min(pl_dist(u["cx"], u["cy"], P, True) for P in v["parts"])
            if d < bd:
                bd, best = d, v
        u["cat"] = best["cat"] if best else "residential"
        u["annex"] = True
    units = [u for u in units if u["cat"] != "water"]
    for u in units:
        u.setdefault("annex", False)
        doc = DOC_HEIGHT.get(u.get("doc_id") or u.get("osm_id") or "")
        hh = num((u.get("tags") or {}).get("height"))
        if doc:                                          # a monument with a published height
            u["h"], u["h_src"] = doc
            u["floors"], u["floors_src"] = 1, "published"
        elif hh is not None and 2.0 <= hh <= 200.0 and u["floors_src"] in ("osm", "neighbours", "none"):
            u["h"], u["h_src"] = hh, "OSM height tag"
            if u["floors_src"] != "osm":                  # floors to match the mapped height, not the neighbours'
                u["floors"] = max(1, int(round(hh / STOREY.get(u["cat"], FLOOR_H))))
            u["floors_src"] = "osm"
        elif u["annex"]:
            u["h"] = FLOOR_H * u["floors"]               # one level at the typical storey height
        else:
            u["h"] = u["floors"] * STOREY.get(u["cat"], FLOOR_H)
    S.bld = units
    S.g_bld = Grid(40.0)
    for u in units:
        S.g_bld.add(u, u["bb"])
    for t in R["texts"].get("YAZI_UNSUR", []):           # the survey's own word for a shack
        if "barak" not in t[0].lower():
            continue
        best, bd = None, 8.0
        for u in S.g_bld.query((t[1] - 8, t[2] - 8, t[1] + 8, t[2] + 8)):
            d = 0.0 if any(pip(t[1], t[2], P) for P in u["parts"]) else min(pl_dist(t[1], t[2], P, True) for P in u["parts"])
            if d < bd:
                best, bd = u, d
        if best is not None:
            best["baraka"] = True
            best["name"] = (best["name"] + " " + t[0].strip()).strip()
    mpts = [((s[0] + s[2]) / 2.0, (s[1] + s[3]) / 2.0) for s in lines.get(DWG["minarets"], [])]
    mpts += [(p[0], p[1]) for p in R["points"].get(DWG["minarets"], [])]
    for (x, y) in mpts:                                  # a minaret symbol marks the mosque it belongs to
        best, bd = None, 8.0
        for u in S.g_bld.query((x - 8, y - 8, x + 8, y + 8)):
            d = 0.0 if any(pip(x, y, P) for P in u["parts"]) else min(pl_dist(x, y, P, True) for P in u["parts"])
            if d < bd:
                best, bd = u, d
        if best is not None:
            best["minaret"] = True
            best["minaret_xy"] = (x, y)                  # v16.4: its place, for the minaret in the sections

    # ------------------------------------------------ OSM zones, streets, paths
    S.zones, S.roads, S.paths = [], [], []
    S.roads_noise = []                                  # every street with motor traffic, uncut by the frame (v16.3)
    if osm:
        Pj = osm["P"]

        def make_zone(kind, sub, outers, inners, tags):
            Ps = [q for q in (F.clip_poly(P) for P in outers) if q]
            Hs = [q for q in (F.clip_poly(P) for P in inners) if q]
            if not Ps:
                return
            A = sum(shoelace(P)[0] for P in Ps) - sum(shoelace(H)[0] for H in Hs)
            if A > 1.0:
                S.zones.append(dict(kind=kind, sub=sub, Ps=Ps, Hs=Hs, A=A, bb=bb_union([bb_pts(P) for P in Ps]), tags=tags))
        for refs, tags in osm["ways"].values():
            if len(refs) < 2 or "building" in tags:
                continue
            hw = tags.get("highway")
            if hw and hw not in SKIP_HW and tags.get("area") != "yes":
                P = [p for p in (Pj(r) for r in refs) if p]
                for run in F.clip_line(P):
                    (S.paths if hw in PED else S.roads).append(dict(P=run, bb=bb_pts(run), tags=tags, L=pl_length(run)))
                if len(P) >= 2 and hw in GPG_CAT:
                    for P_, tags_ in kgm_split(P, tags):           # the ring road in its two KGM sections
                        S.roads_noise.append(dict(P=P_, tags=tags_))
                continue
            if refs[0] == refs[-1] and len(refs) >= 4:
                zc = zone_class(tags)
                if zc:
                    P = [p for p in (Pj(r) for r in refs[:-1]) if p]
                    if len(P) >= 3:
                        make_zone(zc[0], zc[1], [P], [], tags)
        for mem, tags in osm["rels"]:
            if tags.get("type") != "multipolygon" or "building" in tags:
                continue
            if tags.get("ref:whc"):                      # v21 (R06-30): OSM's WHS relation is fenced areas, not the
                continue                                 # inscribed boundary; never an area of this map
            zc = zone_class(tags)
            if not zc:
                continue
            outer, inner = [], []
            for ref, role in mem:
                if ref in osm["ways"]:
                    P = [p for p in (Pj(r) for r in osm["ways"][ref][0]) if p]
                    if len(P) >= 2:
                        (inner if role == "inner" else outer).append([(p[0], p[1]) for p in P])
            loops = [c for c in chain_segments(outer, 0.05) if len(c) >= 4]
            holes = [c for c in chain_segments(inner, 0.05) if len(c) >= 4]
            if loops:
                make_zone(zc[0], zc[1], loops, holes, tags)
    S.g_road, S.g_path = Grid(60.0), Grid(60.0)
    for r in S.roads:
        S.g_road.add(r, r["bb"])
    for r in S.paths:
        S.g_path.add(r, r["bb"])
    S.g_green, S.g_park, S.g_vac, S.g_agri = Grid(80.0), Grid(80.0), Grid(80.0), Grid(120.0)
    for z in S.zones:
        {"green": S.g_green, "transport": S.g_park, "vacant": S.g_vac, "agri": S.g_agri}[z["kind"]].add(z, z["bb"])

    # ------------------------------------------------ survey line work (drawn and analysed)
    def clipped(layers):
        segs_ = []
        for lay in layers:
            for s in lines.get(lay, []):
                if seg_in(s):
                    segs_ += F.clip_line([(s[0], s[1]), (s[2], s[3])])
        return chain_segments(segs_)
    S.walls = clipped(DWG["walls"])
    S.walls_hist = clipped(["SINIR_TARIHI_SUR"])
    S.fences = clipped(DWG["fences"])
    S.slopes = clipped(DWG["slopes"])
    S.slope_hatch = clipped([DWG["slope_hatch"]])
    S.stairs = clipped([DWG["stairs"]])
    S.bridges = clipped(DWG["bridges"])
    S.road_edges = clipped(DWG["roads"])
    S.park_lines = clipped([DWG["park"]])
    S.banks = clipped(DWG["banks"])
    S.pools = clipped(DWG["water_misc"])
    S.g_wall = Grid(30.0)                               # surveyed walls
    for P in S.walls:
        S.g_wall.add(P, bb_pts(P))
    S.g_slope = Grid(30.0)                              # surveyed slope (sev) lines: embankments
    for P in S.slopes:
        S.g_slope.add(P, bb_pts(P))
    S.g_redge = Grid(30.0)
    for P in S.road_edges:
        S.g_redge.add(P, bb_pts(P))
    S.g_stairs = Grid(30.0)
    for P in S.stairs:
        S.g_stairs.add(P, bb_pts(P))

    # ------------------------------------------------ the Selinus: OSM centreline widened to the surveyed banks
    build_stream(S, R, osm)

    S.decks = list(getattr(S, "decks", []))

    # ------------------------------------------------ trees (survey symbols, kept symbolic)
    S.trees = []
    for lay, kind in DWG["trees"].items():
        pts = [((s[0] + s[2]) / 2.0, (s[1] + s[3]) / 2.0) for s in lines.get(lay, []) if seg_in(s)]
        pts += [(p[0], p[1]) for p in R["points"].get(lay, [])]
        par = list(range(len(pts)))                    # pieces of one symbol: linked within 1.6 m, transitively

        def root(i):
            while par[i] != i:
                par[i] = par[par[i]]
                i = par[i]
            return i
        g = Grid(2.0)
        for i, p in enumerate(pts):
            g.add(i, (p[0], p[1], p[0], p[1]))
        for i, p in enumerate(pts):
            for j in g.query((p[0] - 1.6, p[1] - 1.6, p[0] + 1.6, p[1] + 1.6)):
                if j != i and math.hypot(p[0] - pts[j][0], p[1] - pts[j][1]) < 1.6:
                    a_, b_ = root(i), root(j)
                    if a_ != b_:
                        par[a_] = b_
        groups = {}
        for i in range(len(pts)):
            groups.setdefault(root(i), []).append(pts[i])
        for grp in groups.values():
            if len(grp) >= 2:
                mx = sum(q[0] for q in grp) / len(grp)
                my = sum(q[1] for q in grp) / len(grp)
                sxx = sum((q[0] - mx) ** 2 for q in grp)
                syy = sum((q[1] - my) ** 2 for q in grp)
                sxy = sum((q[0] - mx) * (q[1] - my) for q in grp)
                tr_, det = sxx + syy, sxx * syy - sxy * sxy
                lam_min = tr_ / 2.0 - math.sqrt(max(0.0, tr_ * tr_ / 4.0 - det))
                if lam_min / len(grp) < 0.01 and tr_ / len(grp) > 0.01:
                    continue                           # dashes on a straight line: the symbol's ground line
            x = sum(q[0] for q in grp) / len(grp)
            y = sum(q[1] for q in grp) / len(grp)
            if F.inside(x, y):
                S.trees.append((x, y, TREE_SYMBOL_R.get(kind, 2.4), kind))
    S.n_trees_surveyed = len(S.trees)                      # positions as surveyed; the radius is the map symbol
    S.g_tree = Grid(20.0)
    for t in S.trees:
        S.g_tree.add(t, (t[0], t[1], t[0], t[1]))

    # ------------------------------------------------ street widths measured on the survey, and the street surfaces
    #                                                  (after the river: a street's side stops at the open water)
    measure_widths(S)
    build_road_net(S)

    # ------------------------------------------------ terrain (survey points + contours + spot heights)
    build_terrain(S, R)
    channel_profile(S)

    # ------------------------------------------------ areas (ground coverage inside the frame)
    S.area = dict((k, 0.0) for k in CAT_ORDER)
    for u in S.bld:
        S.area[u["cat"]] = S.area.get(u["cat"], 0.0) + u["A"]
    for z in S.zones:
        S.area[z["kind"]] += z["A"]
    for r in S.roads + S.paths:                          # streets with a measured width only
        if r.get("w"):
            S.area["transport"] += r["L"] * r["w"]
    S.street_km = (sum(r["L"] for r in S.roads) / 1000.0, sum(r["L"] for r in S.roads if r.get("w")) / 1000.0)
    S.area["water"] += sum(w["A"] for w in S.water)
    S.total_area = sum(S.area.values()) or 1.0
    S.built_area = sum(u["A"] for u in S.bld)
    greens = [z for z in S.zones if z["kind"] == "green"]
    S.n_major_green = len([z for z in greens if z["A"] >= 2500.0])
    S.green_pct = 100.0 * sum(z["A"] for z in greens) / S.frame_area
    S.path_km = sum(p["L"] for p in S.paths) / 1000.0
    return S


def river_faces(S, R, seeds, cl):
    """The river as the survey draws it: faces closed by stream lines, walls, buildings, bridges and road edges,
    grown from the faces the stream runs through and across stream lines that lie inside the channel."""
    F = S.F
    out = dict(water=[], decks=[], outline=[], faces=[])
    bb = (F.bb[0] - 60, F.bb[1] - 60, F.bb[2] + 60, F.bb[3] + 60)
    bank_l = set(DWG["banks"])
    bridge_l = set(DWG["bridges"])
    layers = DWG["banks"] + DWG["walls"] + DWG["fences"] + list(DWG["bld"]) + DWG["bridges"] + DWG["roads"]
    segs = []
    for lay in layers:
        for s in R["lines"].get(lay, []):
            if bb_hit((min(s[0], s[2]), min(s[1], s[3]), max(s[0], s[2]), max(s[1], s[3])), bb):
                segs.append((s[0], s[1], s[2], s[3], lay))
    if not segs or not seeds:
        return out
    n = len(F.P)
    segs += [(F.P[i][0], F.P[i][1], F.P[(i + 1) % n][0], F.P[(i + 1) % n][1], "FRAME") for i in range(n)]
    faces = polygonize(segs, tol=0.05, gap=1.5)
    gF = Grid(40.0)
    for i, f in enumerate(faces):
        f["bb"] = bb_pts(f["P"])
        gF.add(i, f["bb"])
    gC = Grid(30.0)
    if cl:
        for k in range(len(cl) - 1):
            a, b = cl[k], cl[k + 1]
            gC.add((a, b), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))

    def far_from_stream(f, lim=80.0):
        if not cl:
            return False
        for (x, y) in f["P"][::max(1, len(f["P"]) // 40)]:
            near = gC.query((x - lim, y - lim, x + lim, y + lim))
            if not near or min(seg_dist(x, y, a[0], a[1], b[0], b[1]) for a, b in near) > lim:
                return True
        return False

    def is_building(f):
        a, cx, cy = shoelace(f["P"])
        return any(in_unit(cx, cy, u) for u in S.g_bld.query((cx, cy, cx, cy)))

    def acceptable(i):
        f = faces[i]
        if f["A"] < 2.0 or f["A"] > 600000.0:
            return False
        per = sum(math.hypot(f["P"][(k + 1) % len(f["P"])][0] - f["P"][k][0],
                             f["P"][(k + 1) % len(f["P"])][1] - f["P"][k][1]) for k in range(len(f["P"])))
        if 2.0 * f["A"] / max(per, 1e-9) > 70.0:
            return False
        return not is_building(f) and not far_from_stream(f)
    start = set()
    for (x, y) in seeds:
        c = [i for i in gF.query((x, y, x, y)) if pip(x, y, faces[i]["P"])]
        if c:
            start.add(min(c, key=lambda i: faces[i]["A"]))
    edge_faces = {}
    for i, f in enumerate(faces):
        for kk in f["E"]:
            edge_faces.setdefault(kk, []).append(i)
    ok = {}
    queue = [i for i in start if acceptable(i)]
    for i in queue:
        ok[i] = True
    while queue:
        i = queue.pop()
        for kk, tg in zip(faces[i]["E"], faces[i]["ET"]):
            if tg and tg <= bank_l:                      # stream lines inside the channel do not stop the river
                for j in edge_faces.get(kk, ()):
                    if j not in ok:
                        ok[j] = acceptable(j)
                        if ok[j]:
                            queue.append(j)
    for i, good in ok.items():
        if not good:
            continue
        f = faces[i]
        tot = sum(f["tags"].values()) or 1.0
        cp = F.clip_poly(f["P"])
        if not cp:
            continue
        if sum(v for t_, v in f["tags"].items() if t_ in bridge_l) / tot >= 0.3:
            out["decks"].append(cp)
            continue
        out["water"].append(dict(P=cp, A=shoelace(cp)[0], bb=bb_pts(cp)))
        out["faces"].append(f["P"])
        run = []                                         # river edges, without frame and bridge edges
        P = f["P"]
        for k in range(len(P)):
            tg = f["ET"][k]
            if tg and not (tg & bridge_l) and "FRAME" not in tg:
                if not run:
                    run = [P[k]]
                run.append(P[(k + 1) % len(P)])
            else:
                if len(run) >= 2:
                    out["outline"].append(run)
                run = []
        if len(run) >= 2:
            out["outline"].append(run)
    return out


def stream_from_banks(S, R):
    """No OSM centreline: seed the river from the survey's stream names and stream lines."""
    F = S.F
    seeds = [(t[1], t[2]) for t in R["texts"].get(DWG["stream_names"], []) if F.inside(t[1], t[2])]
    for P in S.banks:
        for (x, y) in resample(P, 25.0):
            seeds.append((x, y))
    rf = river_faces(S, R, seeds, None)
    S.water += rf["water"]
    S.decks = list(getattr(S, "decks", [])) + rf["decks"]
    S.water_outline = rf["outline"] or [P for P in S.banks]
    river_union(S)
    S.covered = []
    names = [t[0].strip() for t in R["texts"].get(DWG["stream_names"], []) if F.inside(t[1], t[2]) and t[0].strip()]
    if S.banks:
        main = max(S.banks, key=pl_length)
        p, t = pl_point_at(main, pl_length(main) * 0.5)
        nm = max(set(names), key=names.count) if names else "SELİNOS DERESİ"
        S.river_label = (p[0], p[1], t, tr_upper(nm))


def bank_pair_channel(S):
    """Where both stream lines (HIDRO) exist, the river is simply the ground between them."""
    F = S.F
    chains = [P for P in S.banks if len(P) >= 2 and pl_length(P) > 6.0]
    g = Grid(15.0)
    for ci, P in enumerate(chains):
        for k in range(len(P) - 1):
            a, b = P[k], P[k + 1]
            g.add((ci, a, b), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))

    def opposite(p, t, ci):
        best = None
        for cj, a, b in g.query((p[0] - 45, p[1] - 45, p[0] + 45, p[1] + 45)):
            if cj == ci:
                continue
            ex, ey = b[0] - a[0], b[1] - a[1]
            l2 = ex * ex + ey * ey
            if l2 < 1e-9:
                continue
            q = max(0.0, min(1.0, ((p[0] - a[0]) * ex + (p[1] - a[1]) * ey) / l2))
            qx, qy = a[0] + q * ex, a[1] + q * ey
            d = math.hypot(qx - p[0], qy - p[1])
            if not 3.0 <= d <= 45.0:
                continue
            if abs(((qx - p[0]) * t[0] + (qy - p[1]) * t[1]) / d) > 0.5:       # straight across, not along
                continue
            if abs((ex * t[0] + ey * t[1]) / math.sqrt(l2)) < 0.5:              # the other bank runs alongside
                continue
            if best is None or d < best[0]:
                best = (d, (qx, qy))
        return best

    def simple(P):
        n = len(P)
        for i in range(n):
            a, b = P[i], P[(i + 1) % n]
            for j in range(i + 2, n):
                if i == 0 and j == n - 1:
                    continue
                c, d = P[j], P[(j + 1) % n]
                r = seg_x(a, (b[0] - a[0], b[1] - a[1]), c, (d[0] - c[0], d[1] - c[1]))
                if r and 1e-6 < r[0] < 1 - 1e-6 and 1e-6 < r[1] < 1 - 1e-6:
                    return False
        return True
    # every stream line has one water side; a strip counts only when both lines see each other on that side
    samples = []
    for ci, P in enumerate(chains):
        pts = resample(P, 3.0)
        if math.hypot(pts[-1][0] - P[-1][0], pts[-1][1] - P[-1][1]) > 0.5:
            pts.append(P[-1])
        n = len(pts)
        tans, hits = [], []
        for k in range(n):
            a_, b_ = pts[max(0, k - 1)], pts[min(n - 1, k + 1)]
            d_ = math.hypot(b_[0] - a_[0], b_[1] - a_[1]) or 1.0
            t_ = ((b_[0] - a_[0]) / d_, (b_[1] - a_[1]) / d_)
            tans.append(t_)
            hits.append(opposite(pts[k], t_, ci))
        samples.append((pts, tans, hits))
    water_side = []
    S.bank_sides = []
    for pts, tans, hits in samples:
        sgn = [1 if (t_[0] * (h[1][1] - p[1]) - t_[1] * (h[1][0] - p[0])) > 0 else -1
               for p, t_, h in zip(pts, tans, hits) if h]
        water_side.append(1 if sgn.count(1) >= sgn.count(-1) else -1)
        n1, n2 = sgn.count(1), sgn.count(-1)
        if n1 + n2 >= 3 and max(n1, n2) >= 0.75 * (n1 + n2):   # the side is known: the other bank was seen there
            S.bank_sides.append((pts, tans, 1 if n1 >= n2 else -1))
    gS = Grid(15.0)
    for ci, (pts, tans, hits) in enumerate(samples):
        for p, t_ in zip(pts, tans):
            gS.add((ci, p, t_), (p[0], p[1], p[0], p[1]))

    def side_of(ci, q, p):
        near = [(math.hypot(x[1][0] - q[0], x[1][1] - q[1]), x) for x in gS.query((q[0] - 6, q[1] - 6, q[0] + 6, q[1] + 6))
                if x[0] == ci]
        if not near:
            return None
        _, (c_, qq, t_) = min(near, key=lambda z: z[0])
        return 1 if (t_[0] * (p[1] - qq[1]) - t_[1] * (p[0] - qq[0])) > 0 else -1
    pieces, centres = [], []
    for ci, (pts, tans, hits) in enumerate(samples):
        n = len(pts)
        opp = []
        for k in range(n):
            h = hits[k]
            ok = False
            if h:
                own = 1 if (tans[k][0] * (h[1][1] - pts[k][1]) - tans[k][1] * (h[1][0] - pts[k][0])) > 0 else -1
                cj = min(((math.hypot(x[1][0] - h[1][0], x[1][1] - h[1][1]), x[0])
                          for x in gS.query((h[1][0] - 6, h[1][1] - 6, h[1][0] + 6, h[1][1] + 6)) if x[0] != ci),
                         default=(None, None))[1]
                if own == water_side[ci] and cj is not None and side_of(cj, h[1], pts[k]) == water_side[cj]:
                    ok = True
            opp.append(h[1] if ok else None)
        k = 0                                             # bridge short breaks in the opposite line (<= 30 m)
        while k < n:
            if opp[k] is None:
                j = k
                while j < n and opp[j] is None:
                    j += 1
                if k > 0 and j < n and j - k <= 10:
                    for m in range(k, j):
                        f = (m - k + 1) / float(j - k + 1)
                        opp[m] = (opp[k - 1][0] + (opp[j][0] - opp[k - 1][0]) * f,
                                  opp[k - 1][1] + (opp[j][1] - opp[k - 1][1]) * f)
                k = j
            else:
                k += 1
        for k in range(n):
            if opp[k] is not None:
                centres.append(((pts[k][0] + opp[k][0]) / 2.0, (pts[k][1] + opp[k][1]) / 2.0))
        runs, cur = [], []
        for k in range(n):
            ok = opp[k] is not None
            if ok and cur:
                w0 = math.hypot(opp[cur[-1]][0] - pts[cur[-1]][0], opp[cur[-1]][1] - pts[cur[-1]][1])
                w1 = math.hypot(opp[k][0] - pts[k][0], opp[k][1] - pts[k][1])
                if abs(w1 - w0) > 6.0:                    # a sudden jump means another line was caught: split
                    if len(cur) >= 2:
                        runs.append(cur)
                    cur = []
            if ok:
                cur.append(k)
            else:
                if len(cur) >= 2:
                    runs.append(cur)
                cur = []
        if len(cur) >= 2:
            runs.append(cur)
        for run in runs:
            left = [pts[k] for k in run]
            right = [opp[k] for k in run]
            k = 0
            while k < len(run) - 1:
                m = min(12, len(run) - 1 - k)
                while m > 1:
                    Pp = left[k:k + m + 1] + list(reversed(right[k:k + m + 1]))
                    if simple(Pp):
                        break
                    m //= 2
                Pp = left[k:k + m + 1] + list(reversed(right[k:k + m + 1]))
                cp = F.clip_poly(Pp)                  # merged into one outline afterwards: no slice is dropped
                if cp:
                    pieces.append(cp)
                k += m
    return pieces, chains, centres


# ============================================================ THE RIVER AS ONE OUTLINE
# The channel is first assembled from many short slices (between the two stream lines, or measured out to the
# nearest wall, slope or building). Those slices are merged here into clean outlines: one closed polyline per
# stretch of open water, islands as holes, never crossing itself. Every drawing, hatch and analysis then uses
# these outlines, so Rhino always receives a single, valid boundary to hatch.
RIVER_CELL = 0.5           # m, raster used to merge the slices
RIVER_CLOSE = 1.0          # m, seams and pinholes narrower than twice this are closed
RIVER_TOL = 0.4            # m, outline simplification tolerance
RIVER_DRY = 20.0           # m: the dry side of a surveyed stream line that is never water
RIVER_PAIR_D = 30.0        # m (v16.7): a stream-line pair is the river when it lies within this of its centre line
RIVER_FAR = 80.0           # m (v16.7): how far a wide dry bed is followed to its slope toe or street edge


def poly_spans(loops, u0, v0, cell, nx, ny, nonzero=True):
    """Scanline fill of one or more loops on a grid (cell centres). Yields (row, [(a, b), ...]): cells a..b-1 inside.
    nonzero winding fills overlapping or self-crossing slices; even-odd treats inner loops as holes."""
    edges = []
    for L_ in loops:
        n = len(L_)
        for k in range(n):
            (x0, y0), (x1, y1) = L_[k], L_[(k + 1) % n]
            if y0 == y1:
                continue
            d = 1
            if y0 > y1:
                x0, y0, x1, y1 = x1, y1, x0, y0
                d = -1
            edges.append((y0, y1, x0, (x1 - x0) / (y1 - y0), d))
    if not edges:
        return
    edges.sort()
    vmax = max(e[1] for e in edges)
    j0 = max(0, int(math.ceil((edges[0][0] - v0) / cell - 0.5)))
    j1 = min(ny - 1, int(math.floor((vmax - v0) / cell - 0.5)))
    active = []
    k, ne = 0, len(edges)
    for j in range(j0, j1 + 1):
        yc = v0 + (j + 0.5) * cell
        while k < ne and edges[k][0] <= yc:
            active.append(edges[k])
            k += 1
        active = [e for e in active if e[1] > yc]
        if not active:
            continue
        xs = sorted((e[2] + (yc - e[0]) * e[3], e[4]) for e in active)
        spans = []
        wnd = 0
        start = 0.0
        for x, d in xs:
            was = wnd != 0
            wnd = (wnd + d) if nonzero else (1 - wnd)
            if wnd != 0 and not was:
                start = x
            elif was and wnd == 0:
                a = max(0, int(math.ceil((start - u0) / cell - 0.5)))
                b = min(nx, int(math.floor((x - u0) / cell - 0.5)) + 1)
                if b > a:
                    spans.append((a, b))
        if spans:
            yield j, spans


def bit_runs(x):
    """(start, length) of every run of set bits in an integer row."""
    while x:
        s = (x & -x).bit_length() - 1
        y = x >> s
        n = ((y + 1) & ~y).bit_length() - 1
        yield s, n
        x &= ~(((1 << n) - 1) << s)


def mask_close(rows, nx, r):
    """Morphological closing with a (2r+1) square: fills seams, slivers and pinholes, never removes water."""
    full = (1 << nx) - 1
    ny = len(rows)

    def dil(x):
        y = x
        for k in range(1, r + 1):
            y |= (x << k) | (x >> k)
        return y & full

    def ero(x):                                      # beyond the frame counts as water, so cuts stay at the edge
        y = x
        for k in range(1, r + 1):
            y &= ((x << k) | ((1 << k) - 1)) & full
            y &= (x >> k) | (full ^ (full >> k))
        return y
    hd = [dil(x) for x in rows]
    D = []
    for j in range(ny):
        y = 0
        for jj in range(max(0, j - r), min(ny, j + r + 1)):
            y |= hd[jj]
        D.append(y)
    he = [ero(x) for x in D]
    out = []
    for j in range(ny):
        y = full
        for jj in range(max(0, j - r), min(ny, j + r + 1)):
            y &= he[jj]
        out.append(y | rows[j])
    return out


def mask_unpinch(rows, nx):
    """Join water cells that touch only at a corner, so every traced outline is a simple loop."""
    full = (1 << nx) - 1
    lim = full >> 1
    for _ in range(6):
        changed = False
        for j in range(len(rows) - 1):
            a, b = rows[j], rows[j + 1]
            p1 = a & ~(a >> 1) & ~b & (b >> 1) & lim
            p2 = ~a & (a >> 1) & b & ~(b >> 1) & lim
            if p1 or p2:
                rows[j] = (a | (p1 << 1) | p2) & full
                changed = True
        if not changed:
            break
    return rows


def mask_loops(rows, nx):
    """Boundary loops of a raster mask in cell-corner coordinates, water on the left: outer loops anticlockwise,
    holes clockwise. Without corner-only contacts every loop is simple and the loops never touch."""
    ny = len(rows)
    nxt = {}
    for j in range(ny):
        m = rows[j]
        if not m:
            continue
        below = rows[j - 1] if j > 0 else 0
        above = rows[j + 1] if j < ny - 1 else 0
        for s, n in bit_runs(m & ~below):
            nxt[(s, j)] = (s + n, j)
        for s, n in bit_runs(m & ~above):
            nxt[(s + n, j + 1)] = (s, j + 1)
        for s, n in bit_runs(m & ~(m >> 1)):
            for i in range(s, s + n):
                nxt[(i + 1, j)] = (i + 1, j + 1)
        for s, n in bit_runs(m & ~(m << 1)):
            for i in range(s, s + n):
                nxt[(i, j + 1)] = (i, j)
    loops = []
    while nxt:
        start, cur = nxt.popitem()
        loop = [start]
        guard = 0
        while cur != start and guard < 10 ** 7:
            loop.append(cur)
            cur = nxt.pop(cur, start)
            guard += 1
        out = []
        n = len(loop)
        for k in range(n):                          # drop vertices in the middle of straight runs
            a, b, c = loop[k - 1], loop[k], loop[(k + 1) % n]
            if (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0]) != 0:
                out.append(b)
        if len(out) >= 4:
            loops.append(out)
    return loops


def dp_simplify(P, tol):
    """Douglas-Peucker on an open chain; the two ends are kept."""
    n = len(P)
    if n < 3:
        return list(P)
    keep = [False] * n
    keep[0] = keep[-1] = True
    stack = [(0, n - 1)]
    while stack:
        a, b = stack.pop()
        if b <= a + 1:
            continue
        ax, ay = P[a]
        dx, dy = P[b][0] - ax, P[b][1] - ay
        L_ = math.hypot(dx, dy)
        best, bi = -1.0, -1
        for i in range(a + 1, b):
            px, py = P[i]
            d = abs(dy * (px - ax) - dx * (py - ay)) / L_ if L_ > 1e-12 else math.hypot(px - ax, py - ay)
            if d > best:
                best, bi = d, i
        if best > tol:
            keep[bi] = True
            stack.append((a, bi))
            stack.append((bi, b))
    return [P[i] for i in range(n) if keep[i]]


def chaikin_open(P, it):
    """Corner cutting on an open chain; both ends stay where they are."""
    for _ in range(it):
        n = len(P)
        if n < 3:
            return P
        Q = [P[0]]
        for k in range(n - 1):
            (x0, y0), (x1, y1) = P[k], P[k + 1]
            if k > 0:
                Q.append((0.75 * x0 + 0.25 * x1, 0.75 * y0 + 0.25 * y1))
            if k < n - 2:
                Q.append((0.25 * x0 + 0.75 * x1, 0.25 * y0 + 0.75 * y1))
        Q.append(P[-1])
        P = Q
    return P


def chaikin_closed(P, it):
    for _ in range(it):
        n = len(P)
        Q = []
        for k in range(n):
            (x0, y0), (x1, y1) = P[k], P[(k + 1) % n]
            Q.append((0.75 * x0 + 0.25 * x1, 0.75 * y0 + 0.25 * y1))
            Q.append((0.25 * x0 + 0.75 * x1, 0.25 * y0 + 0.75 * y1))
        P = Q
    return P


def loops_simple(loops, cell=6.0):
    """True when no loop crosses or touches itself or another loop of the same set."""
    segs = []
    for li, L_ in enumerate(loops):
        n = len(L_)
        for k in range(n):
            segs.append((li, k, n, L_[k], L_[(k + 1) % n]))
    g = {}
    for idx, (li, k, n, a, b) in enumerate(segs):
        for gx in range(int(math.floor(min(a[0], b[0]) / cell)), int(math.floor(max(a[0], b[0]) / cell)) + 1):
            for gy in range(int(math.floor(min(a[1], b[1]) / cell)), int(math.floor(max(a[1], b[1]) / cell)) + 1):
                g.setdefault((gx, gy), []).append(idx)
    seen = set()
    for lst in g.values():
        for p in range(len(lst)):
            for q in range(p + 1, len(lst)):
                i1, i2 = lst[p], lst[q]
                key = (i1, i2) if i1 < i2 else (i2, i1)
                if key in seen:
                    continue
                seen.add(key)
                l1, k1, n1, a1, b1 = segs[i1]
                l2, k2, n2, a2, b2 = segs[i2]
                if l1 == l2 and (abs(k1 - k2) == 1 or abs(k1 - k2) == n1 - 1):
                    continue                        # neighbours share their common vertex
                r = seg_x(a1, (b1[0] - a1[0], b1[1] - a1[1]), a2, (b2[0] - a2[0], b2[1] - a2[1]))
                if r is not None:
                    return False
    return True


def smooth_loop(L_, border, tol, it):
    """Simplify and round a raster loop; vertices on the frame edge stay fixed so cuts stay straight."""
    n = len(L_)
    anchors = [k for k in range(n) if border[k]]
    if not anchors:
        far = max(range(n), key=lambda k: (L_[k][0] - L_[0][0]) ** 2 + (L_[k][1] - L_[0][1]) ** 2)
        if far == 0:
            return list(L_)
        a = dp_simplify(L_[:far + 1], tol)
        b = dp_simplify(L_[far:] + [L_[0]], tol)
        return chaikin_closed(a[:-1] + b[:-1], it) if it else a[:-1] + b[:-1]
    out = []
    for q in range(len(anchors)):
        s, e = anchors[q], anchors[(q + 1) % len(anchors)]
        chain = L_[s:e + 1] if e > s else L_[s:] + L_[:e + 1]
        if len(anchors) == 1:
            chain = L_[s:] + L_[:s + 1]
        ch = dp_simplify(chain, tol)
        if it and not (border[s] and border[e] and len(chain) == 2):
            ch = chaikin_open(ch, it)
        out += ch[:-1]
    return out


def dedupe_ring(P, eps=1e-6):
    out = []
    for p in P:
        if not out or abs(p[0] - out[-1][0]) > eps or abs(p[1] - out[-1][1]) > eps:
            out.append(p)
    while len(out) > 2 and abs(out[0][0] - out[-1][0]) <= eps and abs(out[0][1] - out[-1][1]) <= eps:
        out.pop()
    return out


def river_union(S, cell=RIVER_CELL, close_m=RIVER_CLOSE, min_body=25.0, min_hole=40.0):
    """Merge every water slice into clean outlines (see above). Replaces S.water and S.water_outline."""
    F = S.F
    pieces = [w["P"] for w in S.water if len(w["P"]) >= 3]
    if not pieces:
        return
    nx, ny = int(math.ceil(F.w / cell)), int(math.ceil(F.h / cell))
    rows = [0] * ny
    for P in pieces:
        for j, spans in poly_spans([[F.local(x, y) for x, y in P]], F.u0, F.v0, cell, nx, ny, nonzero=True):
            m = rows[j]
            for a, b in spans:
                m |= ((1 << (b - a)) - 1) << a
            rows[j] = m
    rows = mask_unpinch(mask_close(rows, nx, max(1, int(round(close_m / cell)))), nx)
    cut = getattr(S, "river_cut", None)
    if cut:                                         # never over a building or the dry side of a surveyed bank
        sub = mask_of(F, cut["bld"] + cut["dry"], cell, nx, ny)
        rows = mask_unpinch([w_ & ~s_ for w_, s_ in zip(rows, sub)], nx)
    S.water_mask = dict(rows=rows, nx=nx, ny=ny, cell=cell)
    u1, v1 = F.u0 + F.w, F.v0 + F.h
    edge = 0.75 * cell

    def local(i, j):                                 # snap to the frame edge where the water is cut by it
        u, v = F.u0 + i * cell, F.v0 + j * cell
        b = False
        if i <= 0:
            u, b = F.u0, True
        elif u >= u1 - edge:
            u, b = u1, True
        if j <= 0:
            v, b = F.v0, True
        elif v >= v1 - edge:
            v, b = v1, True
        return (u, v), b
    outers, holes = [], []
    for lp in mask_loops(rows, nx):
        pts, brd = [], []
        for i, j in lp:
            p, b = local(i, j)
            pts.append(p)
            brd.append(b)
        a = signed_area(pts)                             # outer loops anticlockwise (+), holes clockwise (-)
        if a >= min_body:
            outers.append([pts, brd, a, []])
        elif a <= -min_hole:
            holes.append([pts, brd, a])
    outers.sort(key=lambda o: o[2])
    for h in holes:                                  # a point just on the water side of the hole's first edge
        (x0, y0), (x1, y1) = h[0][0], h[0][1]
        L_ = math.hypot(x1 - x0, y1 - y0) or 1.0
        px, py = (x0 + x1) / 2.0 - (y1 - y0) / L_ * 0.25 * cell, (y0 + y1) / 2.0 + (x1 - x0) / L_ * 0.25 * cell
        for o in outers:
            if pip(px, py, o[0]):
                o[3].append(h)
                break
    water, outline, nv, fallback = [], [], 0, 0
    for pts, brd, area, hl in outers:
        rings = [(pts, brd)] + [(h[0], h[1]) for h in hl]
        final = None
        for tol, it in ((RIVER_TOL, 2), (RIVER_TOL, 0), (0.0, 0)):
            cand = [dedupe_ring(smooth_loop(p, b, tol, it) if tol > 0 else p) for p, b in rings]
            if all(len(c) >= 3 for c in cand) and (tol == 0.0 or loops_simple(cand)):
                final = cand
                break
        if final is not cand or tol != RIVER_TOL or it != 2:
            fallback += 1                            # this stretch kept a less smoothed (still valid) outline
        nv += sum(len(c) for c in final)
        Pw = [F.world(u, v) for u, v in final[0]]
        Hw = [[F.world(u, v) for u, v in c] for c in final[1:]]
        net = shoelace(final[0])[0] - sum(abs(shoelace(c)[0]) for c in final[1:])
        water.append(dict(P=Pw, H=Hw, A=net, bb=bb_pts(Pw), src="river"))
        for c in final:                              # river lines: every outline minus the cuts at the frame edge
            on = [abs(u - F.u0) < 1e-6 or abs(u - u1) < 1e-6 or abs(v - F.v0) < 1e-6 or abs(v - v1) < 1e-6 for u, v in c]
            n = len(c)
            cut = [k for k in range(n) if on[k] and on[(k + 1) % n] and (
                (abs(c[k][0] - c[(k + 1) % n][0]) < 1e-6) or (abs(c[k][1] - c[(k + 1) % n][1]) < 1e-6))]
            if not cut:
                outline.append([F.world(u, v) for u, v in c + [c[0]]])
                continue
            cuts = set(cut)
            s0 = (cut[0] + 1) % n
            run = [c[s0]]
            for q in range(1, n + 1):
                k = (s0 + q - 1) % n
                if k in cuts:
                    if len(run) >= 2:
                        outline.append([F.world(u, v) for u, v in run])
                    run = [c[(k + 1) % n]]
                else:
                    run.append(c[(k + 1) % n])
            if len(run) >= 2:
                outline.append([F.world(u, v) for u, v in run])
    S.water = water
    S.water_outline = outline
    S.stats["river_outlines"] = (len(water), sum(len(w["H"]) for w in water), nv, fallback)


def river_free_banks(S, step=2.0, near=1.5):
    """Pieces of the surveyed stream lines lying clear of the merged river."""
    M = getattr(S, "water_mask", None)
    if M is None:
        return []
    r = max(1, int(round(near / M["cell"])))
    out = []
    for P in S.banks:
        run = []
        for x, y in resample(P, step):
            u, v = S.F.local(x, y)
            i, j = int(math.floor((u - S.F.u0) / M["cell"])), int(math.floor((v - S.F.v0) / M["cell"]))
            hit = False
            for jj in range(j - r, j + r + 1):
                if 0 <= jj < M["ny"] and (M["rows"][jj] >> max(0, i - r)) & ((1 << (2 * r + 1)) - 1):
                    hit = True
                    break
            if hit:
                if len(run) >= 2:
                    out.append(run)
                run = []
            else:
                run.append((x, y))
        if len(run) >= 2:
            out.append(run)
    return out


def water_at(S, x, y):
    """Is the point in the river? (raster lookup: fast and consistent with the drawn outline)"""
    M = getattr(S, "water_mask", None)
    if M is None:
        return any(region_contains(x, y, [w["P"]], w.get("H", [])) for w in S.water)
    u, v = S.F.local(x, y)
    i, j = int(math.floor((u - S.F.u0) / M["cell"])), int(math.floor((v - S.F.v0) / M["cell"]))
    if 0 <= j < M["ny"] and 0 <= i < M["nx"]:
        return (M["rows"][j] >> i) & 1 == 1
    return False


def build_stream(S, R, osm):
    F = S.F
    S.water, S.selinus, S.stations, S.river_label, S.water_outline, S.covered = [], [], [], None, [], []
    S.decks = []
    chains = []
    if osm:
        Pj = osm["P"]
        by_name = {}
        for refs, tags in osm["ways"].values():
            if tags.get("waterway") in ("river", "stream", "canal"):
                P = [p for p in (Pj(r) for r in refs) if p]
                if len(P) >= 2:
                    by_name.setdefault(tags.get("name") or "", []).append(P)
        main_named = []                                  # v16.7: every Selinos/Bergama piece, to continue the line
        for nm, segs_ in by_name.items():
            for ch in chain_segments(segs_, 1.0):
                inside = sum(pl_length(r) for r in F.clip_line(ch))
                low = nm.lower().replace("i̇", "i")
                if "selin" in low or "bergama" in low:
                    main_named.append((nm, ch))
                if inside > 30.0:
                    pref = 1.6 if ("selin" in low or "bergama" in low) else (1.0 if nm else 0.5)
                    chains.append((inside * pref, nm, ch))
    if not chains:
        LOG.append("No stream centreline from OSM inside the frame; the river comes from the survey alone.")
        stream_from_banks(S, R)
        S.g_water = Grid(30.0)
        for w in S.water:
            S.g_water.add(w, w["bb"])
        return
    score, sname, cl = max(chains, key=lambda c: c[0])
    # v16.7: the river keeps its course where OSM changes its name. "Selinos Çayı" ends at the Ilıca junction bridge and
    # the same water goes on as "Bergama Deresi" (OSM way 1077764102) to the frame edge; v16.6 stopped at that name
    # change. Pieces named Selinos/Bergama whose end lies within 10 m of either end of the line are joined on (the
    # Ilıca Deresi, which also meets there, is a tributary and is not joined).
    cl = list(cl)
    joined = []
    rest = [(nm, ch) for nm, ch in main_named if ch is not cl and ch != cl]
    grew = True
    while grew and rest:
        grew = False
        for idx_, (nm, ch) in enumerate(rest):
            e0, e1 = cl[0], cl[-1]
            d_ = [(math.hypot(ch[0][0] - e1[0], ch[0][1] - e1[1]), "tail", ch),
                  (math.hypot(ch[-1][0] - e1[0], ch[-1][1] - e1[1]), "tail", list(reversed(ch))),
                  (math.hypot(ch[-1][0] - e0[0], ch[-1][1] - e0[1]), "head", ch),
                  (math.hypot(ch[0][0] - e0[0], ch[0][1] - e0[1]), "head", list(reversed(ch)))]
            dd, where, ch2 = min(d_, key=lambda z: z[0])
            if dd <= 10.0:
                cl = cl + ch2[1:] if where == "tail" else ch2[:-1] + cl
                joined.append(nm)
                rest.pop(idx_)
                grew = True
                break
    S.stats["river_osm_joined"] = joined
    S.river_cl = cl
    # stretches OSM maps as in a tunnel or culvert (used only where the survey shows no open channel)
    g_tun = Grid(20.0)
    n_tun = 0
    for refs, tags in osm["ways"].values():
        if tags.get("waterway") in ("river", "stream", "canal", "drain", "ditch") and (
                tags.get("tunnel") in ("yes", "culvert", "building_passage") or tags.get("covered") == "yes"):
            P = [p for p in (osm["P"](r) for r in refs) if p]
            for k in range(len(P) - 1):
                a_, b_ = P[k], P[k + 1]
                g_tun.add((a_, b_), (min(a_[0], b_[0]) - 6, min(a_[1], b_[1]) - 6, max(a_[0], b_[0]) + 6, max(a_[1], b_[1]) + 6))
                n_tun += 1

    def in_tunnel(q):
        for a_, b_ in g_tun.query((q[0], q[1], q[0], q[1])):
            if seg_dist(q[0], q[1], a_[0], a_[1], b_[0], b_[1]) <= 5.0:
                return True
        return False
    # ---- the channel, sorted by the survey itself: on each side, every 3 m, the edge is the stream line (HIDRO) when
    #      it exists; otherwise the slope toe, then a wall, then a building front - whichever layer is there first.
    #      Administrative lines, symbols, texts and contours never count as edges.
    bbx = (F.bb[0] - 120, F.bb[1] - 120, F.bb[2] + 120, F.bb[3] + 120)

    def seg_grid(layers):
        g = Grid(10.0)
        for lay in layers:
            for s in R["lines"].get(lay, []):
                sb = (min(s[0], s[2]), min(s[1], s[3]), max(s[0], s[2]), max(s[1], s[3]))
                if bb_hit(sb, bbx):
                    g.add(((s[0], s[1]), (s[2], s[3])), sb)
        return g
    PRIORITY = [("stream lines", seg_grid(DWG["banks"]), 30.0),
                ("slope toes", seg_grid(["SEV_ALT", "SEV_SEVALT"]), 25.0),
                ("walls", seg_grid(DWG["walls"]), 25.0),
                ("building fronts", seg_grid(list(DWG["bld"])), 25.0)]

    def hit(g, p, d, maxd):
        q = (p[0] + d[0] * maxd, p[1] + d[1] * maxd)
        best = None
        for s in g.query((min(p[0], q[0]), min(p[1], q[1]), max(p[0], q[0]), max(p[1], q[1]))):
            r = seg_x(p, (q[0] - p[0], q[1] - p[1]), s[0], (s[1][0] - s[0][0], s[1][1] - s[0][1]))
            if r and r[0] * maxd > 0.3 and (best is None or r[0] * maxd < best):
                best = r[0] * maxd
        return best

    def side(p, d):
        for name, g_, maxd in PRIORITY:
            h = hit(g_, p, d, maxd)
            if h is not None:
                return h, name
        return None, None

    def in_building(x, y):
        return any(in_unit(x, y, u) for u in S.g_bld.query((x, y, x, y)))
    # pass 1 - stations on the OSM line: both edges, then a corrected, smooth centre line between them
    L = pl_length(cl)
    stations = []
    s = 0.0
    while s <= L:
        p, t = pl_point_at(cl, s)
        u, v = F.local(p[0], p[1])
        if F.u0 - 60 <= u <= F.u1 + 60 and F.v0 - 60 <= v <= F.v1 + 60:
            stations.append((p, (-t[1], t[0])))
        s += 3.0
    N = len(stations)
    if N < 3:
        S.selinus = F.clip_line(cl)
        return
    off = []
    for p, n_ in stations:
        if in_building(p[0], p[1]):
            off.append(None)
            continue
        (a1, k1), (b1, k2) = side(p, n_), side(p, (-n_[0], -n_[1]))
        off.append((a1 - b1) / 2.0 if (a1 is not None and b1 is not None) else None)

    def fill_series(vals):
        known = [i for i, v_ in enumerate(vals) if v_ is not None]
        if not known:
            return [0.0] * len(vals)
        out_ = list(vals)
        for i in range(len(vals)):
            if out_[i] is None:
                lo = max([k for k in known if k < i], default=None)
                hi = min([k for k in known if k > i], default=None)
                if lo is None:
                    out_[i] = vals[hi]
                elif hi is None:
                    out_[i] = vals[lo]
                else:
                    out_[i] = vals[lo] + (vals[hi] - vals[lo]) * (i - lo) / float(hi - lo)
        return out_

    def median_filter(vals, r):
        return [sorted(vals[max(0, i - r):i + r + 1])[len(vals[max(0, i - r):i + r + 1]) // 2] for i in range(len(vals))]

    def mean_filter(vals, r):
        return [sum(vals[max(0, i - r):i + r + 1]) / float(len(vals[max(0, i - r):i + r + 1])) for i in range(len(vals))]
    off = mean_filter(median_filter(fill_series(off), 5), 3)
    Q = [(p[0] + n_[0] * o, p[1] + n_[1] * o) for (p, n_), o in zip(stations, off)]
    pair_pieces, pair_chains, pair_centres = bank_pair_channel(S)
    # v16.7: only the river's own stream-line pairs are river. Another pair of HIDRO lines (the strip labelled "Kestel
    # Deresi" north of the Ilıca junction, which Nil confirmed on site is not a river bed) is no longer filled; its
    # lines stay as thin surveyed stream lines. A pair counts when its middle lies within RIVER_PAIR_D of the river's
    # centre line (OSM, joined as above).
    g_cl = Grid(20.0)
    for k in range(len(cl) - 1):
        a_, b_ = cl[k], cl[k + 1]
        g_cl.add((a_, b_), (min(a_[0], b_[0]), min(a_[1], b_[1]), max(a_[0], b_[0]), max(a_[1], b_[1])))

    def d_cl(x, y, r=RIVER_PAIR_D):
        best = None
        for a_, b_ in g_cl.query((x - r, y - r, x + r, y + r)):
            d_ = seg_dist(x, y, a_[0], a_[1], b_[0], b_[1])
            if best is None or d_ < best:
                best = d_
        return best if best is not None else 1e9

    def on_main(pts):
        near_ = sum(1 for x, y in pts if d_cl(x, y) <= RIVER_PAIR_D)
        return near_ >= 0.5 * len(pts)
    keep_p = [P for P in pair_pieces if on_main(P)]
    S.stats["river_pairs_dropped"] = [(round(shoelace(P)[1]), round(shoelace(P)[2]), round(abs(shoelace(P)[0])))
                                      for P in pair_pieces if not on_main(P)]
    pair_pieces = keep_p
    pair_chains = [P for P in pair_chains if on_main(resample(P, 3.0))]
    pair_centres = [c_ for c_ in pair_centres if d_cl(c_[0], c_[1]) <= RIVER_PAIR_D]
    S.bank_sides = [b_ for b_ in getattr(S, "bank_sides", []) if on_main(b_[0])]
    gC = Grid(15.0)
    for c_ in pair_centres:
        gC.add(c_, (c_[0], c_[1], c_[0], c_[1]))
    for i in range(N):                                   # inside the paired channel the centre is its true middle
        q = Q[i]
        near = [(math.hypot(c_[0] - q[0], c_[1] - q[1]), c_) for c_ in gC.query((q[0] - 20, q[1] - 20, q[0] + 20, q[1] + 20))]
        if near:
            d_, c_ = min(near, key=lambda z: z[0])
            if d_ <= 20.0:
                Q[i] = c_
    T = []
    for i in range(N):                                   # direction from the nearest distinct centres around i
        lo_, hi_ = max(0, i - 2), min(N - 1, i + 2)
        while lo_ > 0 and math.hypot(Q[hi_][0] - Q[lo_][0], Q[hi_][1] - Q[lo_][1]) < 1.0:
            lo_ -= 1
        while hi_ < N - 1 and math.hypot(Q[hi_][0] - Q[lo_][0], Q[hi_][1] - Q[lo_][1]) < 1.0:
            hi_ += 1
        a_, b_ = Q[lo_], Q[hi_]
        d_ = math.hypot(b_[0] - a_[0], b_[1] - a_[1])
        if d_ < 1e-9:
            a_, b_ = stations[max(0, i - 1)][0], stations[min(N - 1, i + 1)][0]
            d_ = math.hypot(b_[0] - a_[0], b_[1] - a_[1]) or 1.0
        T.append(((b_[0] - a_[0]) / d_, (b_[1] - a_[1]) / d_))
    # a station the OSM line puts on the dry side of a surveyed bank (whose water side the other bank showed) is moved
    # across it, 3 m into the water: the OSM line is metres off in places, the survey is not
    gB_ = Grid(15.0)
    for pts_, tans_, side_ in getattr(S, "bank_sides", []):
        for p_, t_ in zip(pts_, tans_):
            gB_.add((p_, t_, side_), (p_[0], p_[1], p_[0], p_[1]))
    moved = 0
    for i in range(N):
        q = Q[i]
        near_ = [(math.hypot(p_[0] - q[0], p_[1] - q[1]), p_, t_, sd_) for p_, t_, sd_ in
                 gB_.query((q[0] - 20, q[1] - 20, q[0] + 20, q[1] + 20))]
        if not near_:
            continue
        d_, p_, t_, sd_ = min(near_, key=lambda z: z[0])
        own = 1 if (t_[0] * (q[1] - p_[1]) - t_[1] * (q[0] - p_[0])) > 0 else -1
        if own != sd_ and d_ <= 20.0 and not in_building(q[0], q[1]):
            Q[i] = (p_[0] - sd_ * t_[1] * 3.0, p_[1] + sd_ * t_[0] * 3.0)
            moved += 1
    S.stats["river_stations_moved"] = moved
    # the directions again, from the centres as moved and over 4 stations each way (12 m): a centre line that wanders
    # by a metre or two no longer fans the cuts across the channel (a fan leaves wedges of dry ground in the water)
    T = []
    for i in range(N):
        lo_, hi_ = max(0, i - 4), min(N - 1, i + 4)
        while lo_ > 0 and math.hypot(Q[hi_][0] - Q[lo_][0], Q[hi_][1] - Q[lo_][1]) < 1.0:
            lo_ -= 1
        while hi_ < N - 1 and math.hypot(Q[hi_][0] - Q[lo_][0], Q[hi_][1] - Q[lo_][1]) < 1.0:
            hi_ += 1
        a_, b_ = Q[lo_], Q[hi_]
        d_ = math.hypot(b_[0] - a_[0], b_[1] - a_[1])
        if d_ < 1e-9:
            a_, b_ = stations[max(0, i - 1)][0], stations[min(N - 1, i + 1)][0]
            d_ = math.hypot(b_[0] - a_[0], b_[1] - a_[1]) or 1.0
        T.append(((b_[0] - a_[0]) / d_, (b_[1] - a_[1]) / d_))
    # the surveyed bridges (pairs of YOL_KOPRU lines): the river runs on under them, they never cover it
    bsegs0 = [((s_[0], s_[1]), (s_[2], s_[3])) for lay in DWG["bridges"] for s_ in R["lines"].get(lay, [])
              if bb_hit((min(s_[0], s_[2]), min(s_[1], s_[3]), max(s_[0], s_[2]), max(s_[1], s_[3])), bbx)]
    bgroups = []
    for sgm in bsegs0:
        near_ = [gp for gp in bgroups if any(min(math.hypot(a[0] - c[0], a[1] - c[1]) for a in sgm for c in o) < 14.0
                                              for o in gp)]
        if near_:
            merged = [sgm]
            for gp in near_:
                merged += gp
                bgroups.remove(gp)
            bgroups.append(merged)
        else:
            bgroups.append([sgm])
    bridge_hulls = [H_ for H_ in (hull([pt for sgm in gp for pt in sgm]) for gp in bgroups if len(gp) >= 2) if len(H_) >= 3]

    def on_bridge(q):
        return any(pip(q[0], q[1], H_) for H_ in bridge_hulls)
    # pass 2 - measure from the smooth centre line. Each bank keeps one edge layer along a stretch (the most common
    #          one around it, priority breaking ties) and short breaks in that layer are bridged, not jumped.
    gPair = Grid(30.0)
    for P in pair_pieces:
        gPair.add(P, bb_pts(P))

    def in_pair(x, y):
        return any(pip(x, y, P) for P in gPair.query((x, y, x, y)))
    names_ = [nm for nm, _, _ in PRIORITY]
    D = {+1: [], -1: []}
    state = []
    for q, t in zip(Q, T):
        n_ = (-t[1], t[0])
        for sg in (+1, -1):
            D[sg].append([hit(g_, q, (n_[0] * sg, n_[1] * sg), maxd) for nm, g_, maxd in PRIORITY])
        if in_building(q[0], q[1]):
            state.append("covered")
        elif in_pair(q[0], q[1]):
            state.append("pair")
        elif in_tunnel(q) and not on_bridge(q):
            state.append("covered")
        else:
            state.append("open" if any(v_ is not None for v_ in D[+1][-1] + D[-1][-1]) else "unknown")

    def stable(sg):
        first = [next((li for li, v_ in enumerate(D[sg][k]) if v_ is not None), None) for k in range(N)]
        vals, kinds = [], []
        for k in range(N):
            win = [first[j] for j in range(max(0, k - 5), min(N, k + 6)) if first[j] is not None]
            if not win:
                vals.append(None)
                kinds.append(None)
                continue
            stream_near = [D[sg][j][0] for j in range(max(0, k - 5), min(N, k + 6)) if D[sg][j][0] is not None]
            li = 0 if stream_near else max(set(win), key=lambda x: (win.count(x), -x))   # stream lines always win
            v_ = D[sg][k][li]
            if v_ is None:
                nb = [D[sg][j][li] for j in range(max(0, k - 8), min(N, k + 9)) if D[sg][j][li] is not None]
                v_ = sorted(nb)[len(nb) // 2] if nb else (D[sg][k][first[k]] if first[k] is not None else None)
                lo_ = any(D[sg][j][li] is not None for j in range(max(0, k - 8), k))
                hi_ = any(D[sg][j][li] is not None for j in range(k + 1, min(N, k + 9)))
                if nb and not (lo_ and hi_) and first[k] is not None and D[sg][k][first[k]] <= v_ + 8.0:
                    v_ = D[sg][k][first[k]]
            vals.append(v_)
            kinds.append(names_[li])
        return vals, kinds
    A, KA = stable(+1)
    Bv, KB = stable(-1)
    found = sorted([v_ for v_ in A + Bv if v_ is not None])
    half = found[len(found) // 2] if found else 8.0

    def repair(vals, other):
        out_ = list(vals)
        for i in range(N):
            if state[i] == "covered" or out_[i] is not None:
                continue
            nb = [vals[k] for k in range(max(0, i - 8), min(N, i + 9)) if vals[k] is not None and state[k] != "covered"]
            if nb:
                out_[i] = sorted(nb)[len(nb) // 2]
            elif other[i] is not None:
                out_[i] = min(other[i], half)
        return out_
    A2, B2 = repair(A, Bv), repair(Bv, A)
    S.stats["river_states_before_bridging"] = dict((k_, state.count(k_)) for k_ in set(state))
    S.stats["open_missing_side"] = sum(1 for k_ in range(N) if state[k_] == "open" and (A2[k_] is None or B2[k_] is None))
    i = 0
    while i < N:                                         # bridge short stretches with no edge at all (<= 45 m)
        if state[i] == "unknown" or (state[i] == "open" and (A2[i] is None or B2[i] is None)):
            j = i
            while j < N and (state[j] == "unknown" or (state[j] == "open" and (A2[j] is None or B2[j] is None))):
                j += 1
            ok_lo = i > 0 and state[i - 1] == "open" and A2[i - 1] is not None and B2[i - 1] is not None
            ok_hi = j < N and state[j] == "open" and A2[j] is not None and B2[j] is not None
            for k in range(i, j):
                if ok_lo and ok_hi and (j - i) <= 15:
                    f = (k - i + 1) / float(j - i + 1)
                    A2[k] = A2[i - 1] + (A2[j] - A2[i - 1]) * f
                    B2[k] = B2[i - 1] + (B2[j] - B2[i - 1]) * f
                    state[k] = "open"
                    KA[k] = KB[k] = "bridged"
                else:
                    state[k] = "none"
            i = j
        else:
            i += 1

    def tidy(vals, kinds=None, sg=1):
        """Per stretch of consecutive open stations (stretches apart do not influence each other): isolated spikes
        through gaps go (median of 11), and the bank may only drift gradually (1.2 m per station) - except on a
        surveyed stream line, which keeps its measured distance unless that is a spike (3 m off the median). The
        filters work on where the bank is across the mean of 11 centres, so a centre that wanders by a metre or two
        does not make a straight wall look like a row of spikes."""
        out_ = list(vals)
        k = 0
        while k < N:
            if state[k] != "open":
                k += 1
                continue
            j = k
            while j < N and state[j] == "open":
                j += 1
            idx = list(range(k, j))
            sh = []
            for q in idx:
                win = idx[max(0, q - k - 5):q - k + 6]
                mx = sum(Q[w][0] for w in win) / float(len(win))
                my = sum(Q[w][1] for w in win) / float(len(win))
                sh.append((Q[q][0] - mx) * (-T[q][1] * sg) + (Q[q][1] - my) * (T[q][0] * sg))
            raw = [vals[q] + s_ for q, s_ in zip(idx, sh)]
            seq = median_filter(raw, 5)
            line = [kinds is not None and kinds[q] == "stream lines" for q in idx]
            for q in range(len(seq)):
                if line[q] and abs(raw[q] - seq[q]) <= 3.0:
                    seq[q] = raw[q]
            for q in range(1, len(seq)):
                if not line[q]:
                    seq[q] = min(seq[q], seq[q - 1] + 1.2)
            for q in range(len(seq) - 2, -1, -1):
                if not line[q]:
                    seq[q] = min(seq[q], seq[q + 1] + 1.2)
            seq = [v_ - s_ for v_, s_ in zip(seq, sh)]
            for q, v_ in zip(idx, seq):
                out_[q] = max(1.0, min(v_, RIVER_FAR if q in far_k else 30.0))
            k = j
        return out_
    # a surveyed kerb nearer than the bank found is the bank: the water never runs on over a street. Kerbs on a bridge
    # or within 3 m of one are left out (the river runs on under it, the street onto it is no bank), and only kerbs
    # running with the stream count (within 40 degrees of it): a street crossing the stream is not its bank.
    hull_bb = [(bb_pts(H_), H_) for H_ in bridge_hulls]

    def near_bridge(p, d):
        for bb_, H_ in hull_bb:
            if bb_[0] - d <= p[0] <= bb_[2] + d and bb_[1] - d <= p[1] <= bb_[3] + d and (
                    pip(p[0], p[1], H_) or pl_dist(p[0], p[1], H_, True) < d):
                return True
        return False
    g_kerb = Grid(10.0)
    for lay in DWG["roads"]:
        for s_ in R["lines"].get(lay, []):
            a_, b_ = (s_[0], s_[1]), (s_[2], s_[3])
            m_ = ((s_[0] + s_[2]) / 2.0, (s_[1] + s_[3]) / 2.0)
            sb = (min(s_[0], s_[2]), min(s_[1], s_[3]), max(s_[0], s_[2]), max(s_[1], s_[3]))
            if bb_hit(sb, bbx) and not (near_bridge(m_, 3.0) or near_bridge(a_, 3.0) or near_bridge(b_, 3.0)):
                g_kerb.add((a_, b_), sb)

    # v16.7: a wide dry bed. Where neither side has an edge within the usual 25-30 m for more than 45 m of river (east
    # of the Fabrika Caddesi bend up to and past the Ilıca junction bridge, where the bed is 40-70 m wide), v16.6
    # drew no water at all and the bed looked empty. Those stations now follow the bed out to RIVER_FAR: the nearest
    # slope toe, wall, building front or street edge on each side that runs with the stream (within 40 degrees of
    # it, so a street crossing the river is never its bank; streets on or within 3 m of a surveyed bridge are left
    # out). A side that already had a near edge keeps it. Stations upstream that had edges are not changed.
    far_grids = [g_ for nm, g_, md in PRIORITY[1:]] + [g_kerb]

    def far_hit(p, d, t, maxd=RIVER_FAR):
        q = (p[0] + d[0] * maxd, p[1] + d[1] * maxd)
        best = None
        for g_ in far_grids:
            for a_, b_ in g_.query((min(p[0], q[0]), min(p[1], q[1]), max(p[0], q[0]), max(p[1], q[1]))):
                sx, sy = b_[0] - a_[0], b_[1] - a_[1]
                sl = math.hypot(sx, sy)
                if sl < 1e-9 or abs(sx * t[0] + sy * t[1]) / sl < 0.766:
                    continue
                r = seg_x(p, (q[0] - p[0], q[1] - p[1]), a_, (sx, sy))
                if r and r[0] * maxd > 0.3 and (best is None or r[0] * maxd < best):
                    best = r[0] * maxd
        return best
    far_k = set()
    for k in range(N):
        if state[k] != "none" or in_building(Q[k][0], Q[k][1]):
            continue
        t = T[k]
        n_ = (-t[1], t[0])
        a_ = A[k] if A[k] is not None else far_hit(Q[k], n_, t)
        b_ = Bv[k] if Bv[k] is not None else far_hit(Q[k], (-n_[0], -n_[1]), t)
        if a_ is not None and b_ is not None:
            if A[k] is None:
                KA[k] = "far edge (wide bed)"
            if Bv[k] is None:
                KB[k] = "far edge (wide bed)"
            A2[k], B2[k], state[k] = a_, b_, "open"
            far_k.add(k)
    i = 0                                                # short breaks inside the wide bed (a street crossing it on
    while i < N:                                         # a bridge hides its edges): carried across, <= 45 m
        if state[i] == "none":
            j = i
            while j < N and state[j] == "none":
                j += 1
            if 0 < i and j < N and (i - 1 in far_k or j in far_k) and state[i - 1] == "open" and state[j] == "open" \
                    and j - i <= 15:
                for k in range(i, j):
                    f = (k - i + 1) / float(j - i + 1)
                    A2[k] = A2[i - 1] + (A2[j] - A2[i - 1]) * f
                    B2[k] = B2[i - 1] + (B2[j] - B2[i - 1]) * f
                    state[k] = "open"
                    KA[k] = KB[k] = "bridged"
                    far_k.add(k)
            i = j
        else:
            i += 1
    S.stats["river_far_stations"] = len(far_k)
    A2, B2 = tidy(A2, KA, 1), tidy(B2, KB, -1)

    def kerb_hit(p, d, maxd, t):
        q = (p[0] + d[0] * maxd, p[1] + d[1] * maxd)
        best = None
        for a_, b_ in g_kerb.query((min(p[0], q[0]), min(p[1], q[1]), max(p[0], q[0]), max(p[1], q[1]))):
            sx, sy = b_[0] - a_[0], b_[1] - a_[1]
            sl = math.hypot(sx, sy)
            if sl < 1e-9 or abs(sx * t[0] + sy * t[1]) / sl < 0.766:
                continue
            r = seg_x(p, (q[0] - p[0], q[1] - p[1]), a_, (sx, sy))
            if r and r[0] * maxd > 0.3 and (best is None or r[0] * maxd < best):
                best = r[0] * maxd
        return best
    kerbed = 0
    for k in range(N):
        if state[k] != "open":
            continue
        q, t = Q[k], T[k]
        n_ = (-t[1], t[0])
        for sg, arr in ((+1, A2), (-1, B2)):
            if arr[k] is None:
                continue
            h = kerb_hit(q, (n_[0] * sg, n_[1] * sg), arr[k], t)
            if h is not None and h >= 1.0 and h < arr[k] - 0.3:
                arr[k] = h
                kerbed += 1
    if kerbed:
        A2, B2 = tidy(A2, KA, 1), tidy(B2, KB, -1)
    S.stats["river_kerb_stops"] = kerbed
    S.stats["river_states"] = dict((k_, state.count(k_)) for k_ in set(state))
    S.stats["river_edges"] = {}
    for k in range(N):
        if state[k] == "open":
            for kname in (KA[k] or "neighbours", KB[k] or "neighbours"):
                S.stats["river_edges"][kname] = S.stats["river_edges"].get(kname, 0) + 1
    st = []
    for k in range(N):
        q, t = Q[k], T[k]
        if state[k] in ("open", "pair"):
            st.append([q[0], q[1], t[0], t[1], A2[k], B2[k], state[k]])
        else:
            st.append([q[0], q[1], t[0], t[1], None, None, state[k]])
    def capped(vals):
        out_ = list(vals)
        for k in range(N):
            if st[k][6] != "pair" or vals[k] is None:
                continue
            win = sorted(vals[j] for j in range(max(0, k - 5), min(N, k + 6))
                         if vals[j] is not None and st[j][6] in ("open", "pair"))
            out_[k] = min(vals[k], win[len(win) // 2] + 2.0)
        return out_
    ca_, cb_ = capped([r[4] for r in st]), capped([r[5] for r in st])
    for k in range(N):
        st[k][4], st[k][5] = ca_[k], cb_[k]
    S.river_st = st
    idx_runs, cur = [], []
    for k in range(N):
        if st[k][6] == "open" or (st[k][6] == "pair" and st[k][4] is not None and st[k][5] is not None):
            cur.append(k)
        else:
            if cur:
                idx_runs.append(cur)
            cur = []
    if cur:
        idx_runs.append(cur)
    runs = []
    def paired(k_):
        return st[k_][6] == "pair" and st[k_][4] is not None and st[k_][5] is not None
    for r_ in idx_runs:                                  # overlap into the paired channel (up to 8 stations): no seam
        pre, post = [], []
        while len(pre) < 8 and r_[0] - len(pre) - 1 >= 0 and paired(r_[0] - len(pre) - 1):
            pre.insert(0, r_[0] - len(pre) - 1)
        while len(post) < 8 and r_[-1] + len(post) + 1 < N and paired(r_[-1] + len(post) + 1):
            post.append(r_[-1] + len(post) + 1)
        r_ = pre + r_ + post
        if len(r_) >= 2:
            runs.append([st[k] for k in r_])
    cov, ccur = [], []
    for row in st + [None]:
        if row is not None and row[6] == "covered":
            ccur.append(row)
        else:
            if len(ccur) >= 2:
                cov.append(ccur)
            ccur = []
    for c_ in cov:
        S.covered += F.clip_line([(r[0], r[1]) for r in c_])
    for P in pair_pieces:                                # the channel between the two stream lines
        S.water.append(dict(P=P, A=0.5 * shoelace(P)[0], bb=bb_pts(P), src="pair"))
    S.water_outline += [P for P in pair_chains]
    S.stats["river_edges"]["stream lines (both banks)"] = 2 * sum(1 for x in state if x == "pair")
    def simple(P):
        n = len(P)
        for i in range(n):
            a, b = P[i], P[(i + 1) % n]
            for j in range(i + 2, n):
                if i == 0 and j == n - 1:
                    continue
                c, d = P[j], P[(j + 1) % n]
                r = seg_x(a, (b[0] - a[0], b[1] - a[1]), c, (d[0] - c[0], d[1] - c[1]))
                if r and 1e-6 < r[0] < 1 - 1e-6 and 1e-6 < r[1] < 1 - 1e-6:
                    return False
        return True
    for run in runs:
        left = [(r[0] - r[3] * r[4], r[1] + r[2] * r[4]) for r in run]
        right = [(r[0] + r[3] * r[5], r[1] - r[2] * r[5]) for r in run]
        k = 0
        while k < len(run) - 1:                          # merge slices into larger clean pieces (no seams)
            m = min(12, len(run) - 1 - k)
            while m > 1:
                P = left[k:k + m + 1] + list(reversed(right[k:k + m + 1]))
                if simple(P):
                    break
                m //= 2
            P = left[k:k + m + 1] + list(reversed(right[k:k + m + 1]))
            if m == 1 and not simple(P):
                H_ = hull(P)
                if len(H_) >= 3:
                    P = H_
            cp = F.clip_poly(P)
            if cp:
                S.water.append(dict(P=cp, A=shoelace(cp)[0], bb=bb_pts(cp), src="axis"))
            k += m
        S.water_outline += F.clip_line(left) + F.clip_line(right)
    dry = []
    for pts, tans, side in getattr(S, "bank_sides", []):
        if len(pts) < 2:
            continue
        inner = [(p[0] + side * t_[1] * 0.6, p[1] - side * t_[0] * 0.6) for p, t_ in zip(pts, tans)]
        outer = [(p[0] + side * t_[1] * RIVER_DRY, p[1] - side * t_[0] * RIVER_DRY) for p, t_ in zip(pts, tans)]
        dry.append(inner + list(reversed(outer)))
    S.river_cut = dict(bld=[P for u in S.bld for P in u["parts"]], dry=dry)
    S.stats["river_tunnel_ways"] = n_tun
    river_union(S)
    # ---- bridge decks: each pair of surveyed bridge lines, drawn over the water
    bsegs = [((s[0], s[1]), (s[2], s[3])) for lay in DWG["bridges"] for s in R["lines"].get(lay, [])
             if bb_hit((min(s[0], s[2]), min(s[1], s[3]), max(s[0], s[2]), max(s[1], s[3])), bbx)]
    groups = []
    for sgm in bsegs:
        near = [gp for gp in groups if any(min(math.hypot(a[0] - c[0], a[1] - c[1]) for a in sgm for c in o) < 14.0
                                               for o in gp)]
        if near:
            merged = [sgm]
            for gp in near:
                merged += gp
                groups.remove(gp)
            groups.append(merged)
        else:
            groups.append([sgm])
    for gp in groups:
        if len(gp) < 2:
            continue
        H = hull([pt for sgm in gp for pt in sgm])
        if len(H) >= 3:
            a_, cx_, cy_ = shoelace(H)
            probe = [(cx_, cy_)] + H + [((H[k][0] + H[(k + 1) % len(H)][0]) / 2.0, (H[k][1] + H[(k + 1) % len(H)][1]) / 2.0)
                                        for k in range(len(H))]
            if any(water_at(S, x_, y_) for x_, y_ in probe):  # a deck only where the bridge really spans water
                cp = F.clip_poly(H)
                if cp:
                    S.decks.append(cp)
    S.selinus = F.clip_line(cl)
    S.g_water = Grid(30.0)
    for w in S.water:
        S.g_water.add(w, w["bb"])
    if S.selinus:
        main = max(S.selinus, key=pl_length)
        p, t = pl_point_at(main, pl_length(main) * 0.5)
        S.river_label = (p[0], p[1], t, tr_upper(sname or "Selinos Çayı"))


def build_terrain(S, R):
    F = S.F
    bb = (F.bb[0] - 150, F.bb[1] - 150, F.bb[2] + 150, F.bb[3] + 150)

    def inb(x, y):
        return bb[0] <= x <= bb[2] and bb[1] <= y <= bb[3]
    smp = [p for p in R["points"].get(DWG["survey"], []) if inb(p[0], p[1]) and p[2] > 0.5]
    for lay in DWG["contours"]:
        for P in R["plines"].get(lay, []):
            last = None
            for p in P:
                if p[2] > 0.5 and inb(p[0], p[1]) and (last is None or math.hypot(p[0] - last[0], p[1] - last[1]) >= 4.0):
                    smp.append(p)
                    last = p
    for lay in DWG["spot_texts"]:
        for t in R["texts"].get(lay, []):
            v = num(t[0])
            if v is not None and 1.0 < v < 2000.0 and "." in t[0] and inb(t[1], t[2]):
                smp.append((t[1], t[2], v))
    n0 = len(smp)
    for lay in DWG["zlines"]:                            # v33: bank tops and toes, stream lines (heights > 1 m only)
        for P in R["plines"].get("Z::" + lay, []):
            last = None
            for p in P:
                if p[2] > 1.0 and inb(p[0], p[1]) and (last is None or math.hypot(p[0] - last[0], p[1] - last[1]) >= 4.0):
                    smp.append(p)
                    last = p
    S.terrain_banks = len(smp) - n0
    S.terrain_n = len(smp)
    S.terrain_ok = len(smp) > 50
    S.terrain_fp = fp(("idw8-nearest", smp))
    S.terrain_smp = smp
    S.z_at = terrain_z_at(S, smp)


def terrain_z_at(S, smp):
    """S.z_at for the terrain samples smp. v18: taken out of build_terrain unchanged, so the worker processes make
    the very same function from the same samples."""
    g = {}
    Cc = 25.0
    for p in smp:
        g.setdefault((int(math.floor(p[0] / Cc)), int(math.floor(p[1] / Cc))), []).append(p)

    gget = g.get

    def z_at(x, y, k=8):
        """Inverse-distance height from the 8 nearest samples. Square rings of 25 m cells are added (each ring
        column by column) until 8 samples are found and no cell outside the rings can hold a nearer one; the
        samples are ranked by distance (ties: the order they were found)."""
        if not S.terrain_ok:
            return 0.0
        i0, j0 = int(math.floor(x / Cc)), int(math.floor(y / Cc))
        found = list(gget((i0, j0), ()))
        r = 0
        while r < 60:
            r += 1
            jl, jh = j0 - r, j0 + r
            for j in range(jl, jh + 1):                      # first column of the ring: every cell
                found += gget((i0 - r, j), ())
            for i in range(i0 - r + 1, i0 + r):              # middle columns: bottom and top cells only
                found += gget((i, jl), ())
                found += gget((i, jh), ())
            for j in range(jl, jh + 1):                      # last column: every cell
                found += gget((i0 + r, j), ())
            if len(found) >= k:
                dk = sorted((p[0] - x) ** 2 + (p[1] - y) ** 2 for p in found)[k - 1]
                if dk <= (r * Cc) ** 2:
                    break
        if not found:
            return 0.0
        d = [(p[0] - x) ** 2 + (p[1] - y) ** 2 for p in found]
        ws = zs = 0.0
        for q in sorted(range(len(found)), key=d.__getitem__)[:k]:
            d2 = d[q]
            if d2 < 0.01:
                return found[q][2]
            w = 1.0 / d2
            ws += w
            zs += w * found[q][2]
        return zs / ws
    return z_at


def pl_chainage(P, x, y):
    """Distance along polyline P to the point of P nearest (x, y)."""
    best, bs, acc = None, 0.0, 0.0
    for i in range(len(P) - 1):
        ax, ay = P[i]
        bx, by = P[i + 1]
        ex, ey = bx - ax, by - ay
        l2 = ex * ex + ey * ey
        L_ = math.sqrt(l2)
        q = 0.0 if l2 < 1e-12 else max(0.0, min(1.0, ((x - ax) * ex + (y - ay) * ey) / l2))
        d = math.hypot(ax + q * ex - x, ay + q * ey - y)
        if best is None or d < best:
            best, bs = d, acc + q * L_
        acc += L_
    return bs


def water_runs(flags):
    """Index runs [k0, k1) where flags is True."""
    out, k = [], 0
    while k < len(flags):
        if not flags[k]:
            k += 1
            continue
        k0 = k
        while k < len(flags) and flags[k]:
            k += 1
        out.append((k0, k))
    return out


def channel_profile(S):
    """How deep the stream bed lies under its banks, from the survey alone. Every 10 m along the main stream a cut
    across the water (0.5 m steps, as the sections are cut): where the surveyed terrain dips at least 1 m below the
    lower bank, that depth is a measurement. Between measured cuts the depth is interpolated along the stream;
    beyond the first and last it is held. S.chan = dict(line, ch, d, n_cuts)."""
    S.chan = dict(line=None, ch=[], d=[], n_cuts=0)
    streams = [P for P in (getattr(S, "selinus", None) or []) if len(P) >= 2]
    if not streams or not getattr(S, "terrain_ok", False):
        return
    main = max(streams, key=pl_length)
    L = pl_length(main)
    ch, dd = [], []
    n_cuts = 0
    s = 5.0
    gB = S.g_bld
    while s < L - 5.0:
        p, t = pl_point_at(main, s)
        nx, ny = -t[1], t[0]
        pts, flags = [], []
        for k in range(-80, 81):
            qx, qy = p[0] + nx * k * 0.5, p[1] + ny * k * 0.5
            if not S.F.inside(qx, qy):
                pts.append(None)
                flags.append(False)
                continue
            pts.append((qx, qy))                         # water as classify_point has it: in the river, not in a building
            flags.append(water_at(S, qx, qy) and not any(in_unit(qx, qy, u) for u in gB.query((qx, qy, qx, qy))))
        runs = water_runs(flags)
        if runs:
            k0, k1 = min(runs, key=lambda rk: 0 if rk[0] <= 80 < rk[1] else min(abs(rk[0] - 80), abs(rk[1] - 1 - 80)))
            a, b = pts[max(0, k0 - 2)], pts[min(len(pts) - 1, k1)]       # the banks, as the sections take them
            if a is not None and b is not None:
                n_cuts += 1
                depth = min(S.z_at(*a), S.z_at(*b)) - min(S.z_at(*pts[i]) for i in range(k0, k1))
                if depth >= 1.0:
                    ch.append(s)
                    dd.append(depth)
        s += 10.0
    S.chan = dict(line=main, ch=ch, d=dd, n_cuts=n_cuts)


def bed_depth(S, x, y):
    """Depth of the bed under the banks at a point of the stream where the survey has no bed level there:
    the channel_depth input if given, else interpolated along the stream from the surveyed depths; None when the
    survey has no bed level anywhere (the bed is then left as surveyed)."""
    if CH_DEPTH is not None:
        return CH_DEPTH
    C = getattr(S, "chan", None)
    if not C or not C["ch"]:
        return None
    s = pl_chainage(C["line"], x, y)
    ch, dd = C["ch"], C["d"]
    if s <= ch[0]:
        return dd[0]
    if s >= ch[-1]:
        return dd[-1]
    for i in range(len(ch) - 1):
        if ch[i] <= s <= ch[i + 1]:
            t = (s - ch[i]) / (ch[i + 1] - ch[i]) if ch[i + 1] > ch[i] else 0.0
            return dd[i] + (dd[i + 1] - dd[i]) * t
    return dd[-1]


def water_level(S, x, y, bed, bank):
    """v16.5: (level of the water surface, source) where the stream crosses a section at (x, y), its bed at bed and its
    lower bank top at bank: the measured levels of the water_levels input interpolated along the stream (within their
    stretch only); else the bed + water_depth (the input, else the APPROXIMATE depth). Never above the lower bank."""
    pts = getattr(S, "water_pts", None)
    C = getattr(S, "chan", None)
    if pts and C and C.get("line"):
        s = pl_chainage(C["line"], x, y)
        q = sorted((pl_chainage(C["line"], px, py), pz) for px, py, pz in pts)
        if len(q) == 1 and abs(s - q[0][0]) <= 50.0:
            return min(bank, max(bed, q[0][1])), "measured"
        for (s0, z0), (s1, z1) in zip(q, q[1:]):
            if s0 <= s <= s1:
                z = z0 if s1 <= s0 else z0 + (z1 - z0) * (s - s0) / (s1 - s0)
                return min(bank, max(bed, z)), "measured"
    return min(bank, bed + WATER_DEPTH), WATER_SRC


def water_key(S):
    """What the water drawn in the sections depends on (cache keys)."""
    return (WATER_DEPTH, WATER_SRC, tuple(getattr(S, "water_pts", None) or ()))


# ============================================================ URBAN FABRIC (building types read from the survey)
# Every building gets one fabric type from what the survey and open data record about it and its surroundings:
# survey layer (historic, ruin, religious, civic...), names, OSM / Overture heritage tags, surveyed floors,
# footprint size and regularity, whether it shares walls, and the grain of the 40 m around it (coverage, how
# aligned the buildings are, sheds). The rules are listed in the legend; the same type is drawn in every section.
FABRIC_ORDER = ["monument", "sacred", "traditional", "block", "regular", "selfbuilt", "large", "construction"]
FABRIC = {
    "monument": ("Monuments & historic buildings", "survey historic / ruin layers, named monuments, heritage tags",
                 C("A8382A")),
    "sacred": ("Mosques & sacred buildings", "survey religious layer, mosque names, places of worship", C("D98A3D")),
    "traditional": ("Old town fabric", "low, attached, organic: dense grain, shared walls, irregular plots",
                    C("2E2C2A")),
    "block": ("Planned apartment blocks", "3+ surveyed floors on regular footprints", C("62605C")),
    "regular": ("Planned low-rise houses", "1-2 floors on regular, aligned plots", C("97948E")),
    "selfbuilt": ("Small irregular houses", "under 130 m2, irregular, loose grain or added sheds; "
                  "the survey's 'Baraka' (shack) labels", C("C9C5BC")),
    "large": ("Civic, school & industrial halls", "public layers, institutions, industry or 1000 m2+", C("FBFAF6")),
    "construction": ("Under construction", "survey 'in construction' layer", C("E9E5DA")),
}
FABRIC_SHORT = {"monument": "Monuments, historic", "sacred": "Mosques & sacred", "traditional": "Old town fabric",
                "block": "Apartment blocks", "regular": "Planned low-rise", "selfbuilt": "Small irregular",
                "large": "Civic & industrial", "construction": "Under construction"}     # legend labels (two columns)
HERITAGE_WORDS = ("tarihi", "harabe", "harap", "kalıntı", "kalinti", "hamam", " han ", "bedesten", "arasta", "türbe",
                  "turbe", "medrese", "kızıl avlu", "kizil avlu", "tapınağı", "tapinagi", "kilise", "sinagog", "çeşme",
                  "cesme", "sebil", "kervansaray", "müze", "muze")
SACRED_WORDS = ("cami", "mescit", "mescid", "cemevi", "tekke", "zaviye")


def fabric_types(S):
    """Fabric type of every survey unit (u["fabric"]) and the measures behind it (u["fm"])."""
    units = S.bld
    if not units:
        return
    # shared walls: an edge (to the centimetre) that belongs to two units
    owner = {}
    for k, u in enumerate(units):
        for P in u["parts"]:
            n = len(P)
            for i in range(n):
                a = (round(P[i][0], 2), round(P[i][1], 2))
                b = (round(P[(i + 1) % n][0], 2), round(P[(i + 1) % n][1], 2))
                key = (a, b) if a <= b else (b, a)
                s_ = owner.get(key)
                if s_ is None:
                    owner[key] = {k}
                else:
                    s_.add(k)
    att = [False] * len(units)
    for s_ in owner.values():
        if len(s_) > 1:
            for k in s_:
                att[k] = True
    for k, u in enumerate(units):
        pts = [p for P in u["parts"] for p in P]
        r = min_area_rect(pts)
        if r:
            area, ang, u0, u1, v0, v1 = r
            rect = u["A"] / max(area, 1e-6)
            ang = ang if (u1 - u0) >= (v1 - v0) else ang + math.pi / 2.0
        else:
            rect, ang = 1.0, 0.0
        u["fm"] = dict(rect=rect, ang=ang, att=att[k])
    grid = {}
    for k, u in enumerate(units):
        grid.setdefault((int(math.floor(u["cx"] / 20.0)), int(math.floor(u["cy"] / 20.0))), []).append(k)
    R = 40.0
    for k, u in enumerate(units):
        i0, j0 = int(math.floor(u["cx"] / 20.0)), int(math.floor(u["cy"] / 20.0))
        nb = [m for i in range(i0 - 2, i0 + 3) for j in range(j0 - 2, j0 + 3) for m in grid.get((i, j), ())
              if math.hypot(units[m]["cx"] - u["cx"], units[m]["cy"] - u["cy"]) <= R]
        mains = [units[m] for m in nb if not units[m]["annex"]]
        w = sum(v["A"] for v in mains) or 1.0
        zx = sum(math.cos(4.0 * v["fm"]["ang"]) * v["A"] for v in mains)
        zy = sum(math.sin(4.0 * v["fm"]["ang"]) * v["A"] for v in mains)
        fm = u["fm"]
        fm["cov"] = sum(units[m]["A"] for m in nb) / (math.pi * R * R)
        fm["coh"] = math.hypot(zx, zy) / w
        fm["attsh"] = sum(1 for v in mains if v["fm"]["att"]) / float(max(1, len(mains)))
        fm["shed"] = sum(1 for m in nb if units[m]["annex"]) / float(max(1, len(mains)))
    her_pois = [p for p in getattr(S, "pois", []) if p.get("her")]
    gH = Grid(30.0)
    for p in her_pois:
        gH.add(p, (p["x"], p["y"], p["x"], p["y"]))
    for u in units:
        if u["annex"]:
            continue
        kind = DWG["bld"].get(u["layer"], "mesken")
        nm = " " + (u.get("name") or "").lower() + " "
        tg = u.get("tags") or {}
        fm = u["fm"]
        her_poi = any(any(pip(p["x"], p["y"], P) for P in u["parts"])
                      for p in gH.query((u["bb"][0] - 1, u["bb"][1] - 1, u["bb"][2] + 1, u["bb"][3] + 1)))
        if (kind in ("tarihi", "harabe") or any(w_ in nm for w_ in HERITAGE_WORDS) or tg.get("historic") or
                tg.get("heritage") or tg.get("building") in ("ruins", "temple", "historic", "synagogue", "church") or her_poi):
            t = "monument"
        elif kind == "dini" or any(w_ in nm for w_ in SACRED_WORDS) or u["cat"] == "religious" or tg.get("building") == "mosque":
            t = "sacred"
        elif kind == "insaat" or u["cat"] == "vacant":
            t = "construction"
        elif (u["cat"] in ("institutional", "industrial", "transport") or
              kind in ("resmi", "okul", "spor", "fabrika", "sera", "akaryakit") or u["A"] >= 1000.0):
            t = "large"
        elif u["floors"] >= 4 or (u["floors"] >= 3 and fm["rect"] >= 0.75):
            t = "block"
        elif fm["cov"] >= 0.35 and fm["attsh"] >= 0.55 and (fm["coh"] < 0.8 or fm["rect"] < 0.85):
            t = "traditional"
        elif u["A"] < 130.0 and (fm["rect"] < 0.8 or fm["coh"] < 0.6) and (fm["shed"] >= 0.15 or fm["attsh"] < 0.5):
            t = "selfbuilt"
        elif fm["rect"] >= 0.8 and fm["coh"] >= 0.6:
            t = "regular"
        elif fm["cov"] >= 0.35:
            t = "traditional"
        else:
            t = "selfbuilt" if (fm["rect"] < 0.8 and u["A"] < 130.0) else "regular"     # small irregular: < 130 m2
        if u.get("baraka"):
            t = "selfbuilt"                              # the survey itself labels it a shack
        u["fabric"] = t
    mains = [u for u in units if not u["annex"]]
    gM = Grid(40.0)
    for u in mains:
        gM.add(u, u["bb"])
    for u in units:                                     # sheds and annexes belong to the house they stand by
        if not u["annex"]:
            continue
        best, bd = None, 1e18
        for v in gM.query((u["cx"] - 40, u["cy"] - 40, u["cx"] + 40, u["cy"] + 40)):
            d = min(pl_dist(u["cx"], u["cy"], P, True) for P in v["parts"])     # the house it stands by
            if d < bd:
                best, bd = v, d
        u["fabric"] = "selfbuilt" if u.get("baraka") else (best["fabric"] if best else "selfbuilt")
    S.fabric_area = dict((k, 0.0) for k in FABRIC_ORDER)
    for u in mains:
        S.fabric_area[u["fabric"]] += u["A"]


# ============================================================ ANALYSES
def run_analyses(S):
    S.int_cells, S.int_breaks, S.int_cell, S.int_peak, S.int_peak_name = [], (0, 0, 0), 50.0, 0.0, ""
    S.corr_primary, S.corr_secondary, S.clusters, S.n_inst = [], [], [], 0
    S.edge_runs, S.wall_runs, S.edge_samples = [], [], []
    S.edge_len = dict((k, 0.0) for k in EDGE_ORDER)
    S.walled_len = 0.0
    S.embanked_len = 0.0
    S.bank_runs = []
    S.sections, S.sec_lines, S.observations = [], [], []
    for fn in (build_intensity, build_corridors, build_clusters, build_edges, build_sections, build_observations):
        try:
            fn(S)
        except Exception:
            LOG.append("{} failed:\n{}".format(fn.__name__, traceback.format_exc()))


def build_intensity(S, cell=10.0):
    """Floor-area ratio on a 10 m grid: every footprint is split exactly across the cells it covers."""
    F = S.F
    if not S.bld:
        return
    acc = {}
    for u in S.bld:
        fl = u["floors"]
        for P in u["parts"]:
            Q = [F.local(x, y) for x, y in P]
            us, vs = [q[0] for q in Q], [q[1] for q in Q]
            for i in range(int(math.floor((min(us) - F.u0) / cell)), int(math.floor((max(us) - F.u0) / cell)) + 1):
                cu = F.u0 + i * cell
                Ci = clip_half(clip_half(Q, cu, 0.0, -1.0, 0.0), cu + cell, 0.0, 1.0, 0.0)
                if len(Ci) < 3:
                    continue
                for j in range(int(math.floor((min(vs) - F.v0) / cell)), int(math.floor((max(vs) - F.v0) / cell)) + 1):
                    cv = F.v0 + j * cell
                    Cj = clip_half(clip_half(Ci, 0.0, cv, 0.0, -1.0), 0.0, cv + cell, 0.0, 1.0)
                    if len(Cj) >= 3:
                        a_ = shoelace(Cj)[0]
                        if a_ > 0.01:
                            acc[(i, j)] = acc.get((i, j), 0.0) + a_ * fl
    far = dict((k, v / (cell * cell)) for k, v in acc.items() if v > 0.0)
    if not far:
        return
    vals = sorted(far.values())

    def q(p):
        return vals[min(len(vals) - 1, int(p * len(vals)))]
    br = (q(0.25), q(0.5), q(0.75))
    cls = lambda f: 0 if f < br[0] else (1 if f < br[1] else (2 if f < br[2] else 3))
    rows = {}
    for (i, j), f in far.items():
        rows.setdefault(j, []).append((i, cls(f)))
    for j, lst in rows.items():                         # merge equal neighbours in a row into one strip
        lst.sort()
        k = 0
        while k < len(lst):
            i0, c0 = lst[k]
            i1 = i0
            while k + 1 < len(lst) and lst[k + 1][0] == i1 + 1 and lst[k + 1][1] == c0:
                k += 1
                i1 = lst[k][0]
            u0, u1 = F.u0 + i0 * cell, F.u0 + (i1 + 1) * cell
            v0, v1 = F.v0 + j * cell, F.v0 + (j + 1) * cell
            S.int_cells.append(([F.world(u0, v0), F.world(u1, v0), F.world(u1, v1), F.world(u0, v1)], c0, j))
            k += 1
    S.int_breaks, S.int_cell = br, cell
    (pi, pj), pf = max(far.items(), key=lambda kv: kv[1])
    S.int_peak = pf
    px, py = F.world(F.u0 + (pi + 0.5) * cell, F.v0 + (pj + 0.5) * cell)
    named = [r for r in S.roads + S.paths if r["tags"].get("name")]
    if named:
        r = min(named, key=lambda r: pl_dist(px, py, r["P"], False))
        if pl_dist(px, py, r["P"], False) < 40.0:
            S.int_peak_name = r["tags"]["name"]


def build_corridors(S):
    skip = {"service", "track", "motorway", "motorway_link", "footway", "path", "steps", "cycleway",
            "bridleway", "corridor"}
    groups = {}
    grid = Grid(60.0)
    for r in S.roads + S.paths:
        if r["tags"].get("highway") in skip:
            continue
        name = r["tags"].get("name", "")
        key = name if name else "#{}".format(id(r))
        g = groups.setdefault(key, dict(label=name or "an unnamed street", Ps=[], n=0))
        g["Ps"].append(r["P"])
        r["grp"] = g
        grid.add(r, r["bb"])
    pts = [(u["cx"], u["cy"]) for u in S.bld if u["cat"] in ("commercial", "mixed") and not u["annex"]]
    pts += [(p["x"], p["y"]) for p in S.pois if p["cat"] == "commercial" and not p["in_bld"]]
    for x, y in pts:
        best, bd = None, 30.0
        for r in grid.query((x - 30, y - 30, x + 30, y + 30)):
            d = pl_dist(x, y, r["P"], False)
            if d < bd:
                bd, best = d, r.get("grp")
        if best is not None:
            best["n"] += 1
    ranked = sorted([g for g in groups.values() if g["n"] >= 3], key=lambda g: -g["n"])
    S.corr_primary = [g for g in ranked if g["n"] >= 6][:2]
    S.corr_secondary = [g for g in ranked if all(g is not p for p in S.corr_primary)][:4]


def build_clusters(S, D=100.0):
    pts = [(u["cx"], u["cy"]) for u in S.bld if u["cat"] in ("institutional", "religious") and not u["annex"]]
    pts += [(p["x"], p["y"]) for p in S.pois if p["cat"] in ("institutional", "religious") and not p["in_bld"]]
    n = len(pts)
    S.n_inst = n
    parent = list(range(n))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    g = Grid(D)
    for i, p in enumerate(pts):
        g.add(i, (p[0], p[1], p[0], p[1]))
    for i, p in enumerate(pts):
        for j in g.query((p[0] - D, p[1] - D, p[0] + D, p[1] + D)):
            if j > i and (pts[j][0] - p[0]) ** 2 + (pts[j][1] - p[1]) ** 2 <= D * D:
                parent[find(i)] = find(j)
    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(pts[i])
    for grp in groups.values():
        if len(grp) < 3:
            continue
        cx = sum(p[0] for p in grp) / len(grp)
        cy = sum(p[1] for p in grp) / len(grp)
        h = hull(grp)
        if len(h) < 3:
            r = max(math.hypot(p[0] - cx, p[1] - cy) for p in grp) + 25.0
            h = circle_pts(cx, cy, r, 28)
        else:
            infl = []
            for hx, hy in h:
                d = math.hypot(hx - cx, hy - cy) or 1.0
                infl.append((hx + (hx - cx) / d * 25.0, hy + (hy - cy) / d * 25.0))
            h = infl
        S.clusters.append(dict(P=h, n=len(grp)))


def zone_dist(x, y, z):
    if region_contains(x, y, z["Ps"], z["Hs"]):
        return 0.0
    return min(pl_dist(x, y, P, True) for P in z["Ps"] + z["Hs"])         # from inside a hole: to the hole's edge


def edge_type(S, x, y):
    best, bd = None, 1e9
    for u in S.g_bld.query((x - 8, y - 8, x + 8, y + 8)):
        d = min(pl_dist(x, y, P, True) for P in u["parts"])
        if d < 8.0 and d < bd:
            bd, best = d, "building"
    for r in S.g_path.query((x - 21, y - 21, x + 21, y + 21)):            # measured path widths reach 30 m
        d = pl_dist(x, y, r["P"], False) - street_w(r) / 2.0
        if d < 6.0 and d < bd:
            bd, best = d, "pedestrian"
    for P in S.g_stairs.query((x - 5, y - 5, x + 5, y + 5)):
        d = pl_dist(x, y, P, False)
        if d < 5.0 and d < bd:
            bd, best = d, "pedestrian"
    for r in S.g_road.query((x - 23, y - 23, x + 23, y + 23)):
        d = pl_dist(x, y, r["P"], False) - street_w(r) / 2.0
        if d < 8.0 and d < bd:
            bd, best = d, "street"
    for P in S.g_redge.query((x - 7, y - 7, x + 7, y + 7)):
        d = pl_dist(x, y, P, False) + 1.0
        if d < 7.0 and d < bd:
            bd, best = d, "street"
    for z in S.g_park.query((x - 8, y - 8, x + 8, y + 8)):
        d = zone_dist(x, y, z)
        if d < 8.0 and d < bd:
            bd, best = d, "parking"
    for z in S.g_green.query((x - 8, y - 8, x + 8, y + 8)) + S.g_agri.query((x - 8, y - 8, x + 8, y + 8)):
        d = zone_dist(x, y, z)
        if d < 8.0 and d < bd:
            bd, best = d, "green"
    if best is None:
        for t in S.g_tree.query((x - 6, y - 6, x + 6, y + 6)):
            if math.hypot(t[0] - x, t[1] - y) < 6.0:
                best = "green"
                break
    return best or "open"


def build_edges(S):
    SP = 4.0
    F = S.F
    for P in getattr(S, "water_outline", []):
        if len(P) < 2:
            continue
        seq = []
        for x, y in resample(P, SP):
            if pl_dist(x, y, F.P, True) < 3.0:
                seq.append(None)
                continue
            t = edge_type(S, x, y)
            # 1: a surveyed wall within 3 m, 2: only a surveyed slope line (an embankment), 0: neither
            wl = 1 if any(pl_dist(x, y, W, False) < 3.0 for W in S.g_wall.query((x - 3, y - 3, x + 3, y + 3))) else (
                2 if any(pl_dist(x, y, W, False) < 3.0 for W in S.g_slope.query((x - 3, y - 3, x + 3, y + 3))) else 0)
            seq.append((x, y, t, wl))
            S.edge_samples.append((x, y, t, wl))
            S.edge_len[t] += SP
            if wl == 1:
                S.walled_len += SP
            elif wl == 2:
                S.embanked_len += SP
        S.edge_runs.extend(make_runs(seq, 2))
        S.wall_runs.extend([pts for flag, pts in make_runs(seq, 3) if flag == 1])
        S.bank_runs.extend([pts for flag, pts in make_runs(seq, 3) if flag == 2])
    S.g_edge = Grid(20.0)
    for e in S.edge_samples:
        S.g_edge.add(e, (e[0], e[1], e[0], e[1]))


def in_unit(x, y, u):
    """Inside a building's outline and not in one of its courtyards."""
    return any(pip(x, y, P) for P in u["parts"]) and not any(pip(x, y, H) for H in u.get("holes") or ())


def classify_point(S, x, y):
    q = (x, y, x, y)
    for u in S.g_bld.query(q):
        if in_unit(x, y, u):
            return "bld", u
    if water_at(S, x, y):
        return "water", None
    M = getattr(S, "road_mask", None)
    if M is not None:                                  # the street surfaces as drawn on the plan
        if mask_at(S.F, M, x, y):
            return "road", None
    else:
        for r in S.g_road.query((x - 16, y - 16, x + 16, y + 16)):      # measured widths reach 30 m
            w = r.get("w")
            if w and pl_dist(x, y, r["P"], False) < w / 2.0:
                return "road", None
        for r in S.g_path.query((x - 16, y - 16, x + 16, y + 16)):
            w = r.get("w")
            if w and pl_dist(x, y, r["P"], False) < w / 2.0:
                return "road", None
    for z in S.g_green.query(q):
        if region_contains(x, y, z["Ps"], z["Hs"]):
            return "green", None
    for z in S.g_park.query(q):
        if region_contains(x, y, z["Ps"], z["Hs"]):
            return "parking", None
    for z in S.g_vac.query(q):
        if region_contains(x, y, z["Ps"], z["Hs"]):
            return "vacant", None
    for z in S.g_agri.query(q):
        if region_contains(x, y, z["Ps"], z["Hs"]):
            return "agri", None
    return "void", None


def sec_endpoints(ln):
    """Start and end of a section line (a curve, a Line, or two points); None if it has no length."""
    e = None
    for get in (lambda: (ln.PointAtStart, ln.PointAtEnd), lambda: (ln.From, ln.To)):
        try:
            a, b = get()
            e = ((a.X, a.Y), (b.X, b.Y))
            break
        except Exception:
            pass
    if e is None:
        try:
            e = ((float(ln[0][0]), float(ln[0][1])), (float(ln[1][0]), float(ln[1][1])))
        except Exception:
            return None
    if math.hypot(e[1][0] - e[0][0], e[1][1] - e[0][1]) < 1e-6:
        return None
    return e


def build_sections(S):
    lines_ = []
    for k, ln in enumerate(SEC_IN):
        e = sec_endpoints(ln)
        if e is None:
            continue
        runs = S.F.clip_line([e[0], e[1]])
        if not runs:
            LOG.append("Section line {} lies outside the frame and was skipped.".format(k + 1))
            continue
        a, b = runs[0][0], runs[0][-1]
        if math.hypot(a[0] - e[0][0], a[1] - e[0][1]) + math.hypot(b[0] - e[1][0], b[1] - e[1][1]) > 1.0:
            LOG.append("Section line {} was trimmed to the frame.".format(k + 1))
        lines_.append((a, b))
    if SEC_IN and not lines_:
        LOG.append("WARNING: none of the {} section lines cross the study area. If they were drawn before you rotated or "
                   "moved the drawing, redraw them across the stream (or rotate them with it).".format(len(SEC_IN)))
    S.sections_auto = False
    step = 0.5
    n_kept = 0
    for i, ((x0, y0), (x1, y1)) in enumerate(lines_):
        L = math.hypot(x1 - x0, y1 - y0)
        if L < 5.0:
            LOG.append("A section line shorter than 5 m inside the frame was skipped.")
            continue
        n_kept += 1
        name = "S{}".format(n_kept)
        S.sec_lines.append((x0, y0, x1, y1, name))
        S.sections.append(section_of_line(S, x0, y0, x1, y1, name, step))


def section_of_line(S, x0, y0, x1, y1, name, step=0.5):
    """v40: one straight section x0,y0 -> x1,y1 (was the body of build_sections): ground, water, buildings, trees,
    walls, levels, what lies beyond; the dict draw_section_strip draws."""
    L = math.hypot(x1 - x0, y1 - y0)
    ux, uy = (x1 - x0) / L, (y1 - y0) / L
    xs = [k * step for k in range(int(L / step) + 1)]
    smp = []
    for s in xs:
        px, py = x0 + ux * s, y0 + uy * s
        kind, ref = classify_point(S, px, py)
        smp.append([s, kind, ref, S.z_at(px, py)])
    # water intervals: the bed where the survey levels it; elsewhere the depth interpolated along the stream
    # from the surveyed depths (bed_depth). v16.5: the water surface from water_level (approximate unless measured).
    k = 0
    wat = []
    wsrcs = []
    while k < len(smp):
        if smp[k][1] != "water":
            k += 1
            continue
        k0 = k
        while k < len(smp) and smp[k][1] == "water":
            k += 1
        za = smp[max(0, k0 - 2)][3]
        zb = smp[min(len(smp) - 1, k)][3]
        bank = min(za, zb)
        bed = min(r[3] for r in smp[k0:k])
        src = "surveyed"
        if bank - bed < 1.0:
            sm = (smp[k0][0] + smp[k - 1][0]) / 2.0
            dd_ = bed_depth(S, x0 + ux * sm, y0 + uy * sm)
            if dd_ is None:
                src = "terrain"
            else:
                bed, src = bank - dd_, ("input" if CH_DEPTH is not None else "interpolated")
        for r in smp[k0:k]:
            r.append(bed)
        sm_ = (smp[k0][0] + smp[k - 1][0]) / 2.0
        lvl, wsrc = water_level(S, x0 + ux * sm_, y0 + uy * sm_, bed, bank)
        wat.append((smp[k0][0], smp[k - 1][0] + step, bed, lvl, bank, src))
        wsrcs.append(wsrc)
    for r in smp:
        if len(r) == 4:
            r.append(r[3])
    base = min(r[4] for r in smp) - 2.0
    ground = [(r[0], r[4] - base) for r in smp]
    runs, cur = [], None
    for r in smp:
        key = (r[1], id(r[2]) if r[2] is not None else 0)
        if cur is None or cur["key"] != key:
            if cur:
                runs.append(cur)
            cur = dict(key=key, kind=r[1], ref=r[2], s=[r])
        else:
            cur["s"].append(r)
    if cur:
        runs.append(cur)
    bl, strip, comp, trees = [], [], {}, []
    zmax = max(g[1] for g in ground)
    for r in runs:
        s0 = r["s"][0][0]
        s1 = min(L, r["s"][-1][0] + step)
        if r["kind"] == "bld":
            u = r["ref"]
            zb = min(q[3] for q in r["s"]) - base
            ms_ = minaret_s(u, x0, y0, ux, uy, s0, s1) if u.get("fabric") == "sacred" else None
            bl.append((s0, s1, zb, zb + u["h"], u["cat"], u["annex"], u.get("fabric", "regular"),
                       unit_flags(u) + (ms_, label_name(u)), u["floors"], u["floors_src"]))  # + minaret, name
            zmax = max(zmax, zb + u["h"] + typo_rise(u.get("fabric", "regular"), u["cat"], s1 - s0, u["h"],
                                                     ms_ is not None) + 1.0)
            cat = u["cat"]
        elif r["kind"] == "water":
            cat = "water"
        elif r["kind"] == "green":
            cat = "green"
        elif r["kind"] in ("road", "parking"):
            cat = "transport"
        elif r["kind"] == "vacant":
            cat = "vacant"
        elif r["kind"] == "agri":
            cat = "agri"
        else:
            cat = "void"
        strip.append((s0, s1, cat))
        comp[cat] = comp.get(cat, 0.0) + (s1 - s0)

    def g_at(s):
        return ground[max(0, min(len(ground) - 1, int(round(s / step))))][1]
    # ---- tree crowns as measured on the canopy height map: cut by the line, and those seen beyond it
    nx, ny = -uy, ux
    btrees = []
    for (tx, ty, tr, th) in crowns_near(S, (min(x0, x1) - 80, min(y0, y1) - 80, max(x0, x1) + 80, max(y0, y1) + 80)):
        d = (tx - x0) * nx + (ty - y0) * ny
        s = (tx - x0) * ux + (ty - y0) * uy
        if not (-tr < s < L + tr):
            continue
        lo, hi = crown_lo(th), th
        if abs(d) < tr:
            hw = math.sqrt(tr * tr - d * d)
            trees.append((s, S.z_at(tx, ty) - base, hw, lo, hi))
            zmax = max(zmax, S.z_at(tx, ty) - base + hi)
        elif tr <= d < 60.0:
            btrees.append((s, S.z_at(tx, ty) - base, tr, lo, hi, d))
    btrees.sort(key=lambda t: -t[5])
    # ---- surveyed walls crossing the line: their place only (the survey gives no wall heights)
    walls, chwalls = [], []
    sbb = (min(x0, x1) - 5, min(y0, y1) - 5, max(x0, x1) + 5, max(y0, y1) + 5)
    for P in S.g_wall.query(sbb):
        for k in range(len(P) - 1):
            res = seg_x((x0, y0), (x1 - x0, y1 - y0), P[k], (P[k + 1][0] - P[k][0], P[k + 1][1] - P[k][1]))
            if res:
                s = res[0] * L
                walls.append((s, g_at(s)))
    labels, levels = [], []
    for (s0, s1, bed, lvl, bank, src) in wat:
        for s in (s0, s1):
            px, py = x0 + ux * s, y0 + uy * s
            best, bd = None, 12.0
            for e in S.g_edge.query((px - 12, py - 12, px + 12, py + 12)):
                d = math.hypot(e[0] - px, e[1] - py)
                if d < bd:
                    bd, best = d, e
            if best:
                labels.append((s, best[2], best[3], bank - base))
                if best[3] == 1:
                    chwalls.append((s, bed - base, bank - base))     # the channel wall, bed to bank
        levels.append(((s0 + s1) / 2.0, bed - base, bed, "bed"))
        levels.append((s0, bank - base, bank, "bank"))
    levels.append((0.0, ground[0][1], ground[0][1] + base, "end"))
    levels.append((L, ground[-1][1], ground[-1][1] + base, "end"))
    # ---- what lies beyond the cut, looking to the left of S -> S'
    zcut = zmax
    band = (min(x0, x1) - 80, min(y0, y1) - 80, max(x0, x1) + 80, max(y0, y1) + 80)
    beyond = []
    for u in S.g_bld.query(band):
        d = (u["cx"] - x0) * nx + (u["cy"] - y0) * ny
        if not 1.5 < d < 75.0:
            continue
        sv = [(px - x0) * ux + (py - y0) * uy for P in u["parts"] for (px, py) in P]
        a, b = max(0.0, min(sv)), min(L, max(sv))
        if b - a < 1.5:
            continue
        zb = S.z_at(u["cx"], u["cy"]) - base
        beyond.append((a, b, zb, min(zb + u["h"], zcut + 5.0), u["cat"], d, u["floors"], u["annex"],
                       u.get("fabric", "regular"), unit_flags(u), u["floors_src"]))
    beyond.sort(key=lambda t: -t[5])
    for b_ in beyond:
        zmax = max(zmax, min(b_[3] + 1.6, zcut + 6.0))
    for t in btrees:
        zmax = max(zmax, min(t[1] + t[4], zcut + 6.0))
    bridges = []
    for P in S.bridges:
        if len(P) < 2:
            continue
        mx, my = sum(p[0] for p in P) / len(P), sum(p[1] for p in P) / len(P)
        d = (mx - x0) * nx + (my - y0) * ny
        if not 2.0 < d < 120.0:
            continue
        sv = [(px - x0) * ux + (py - y0) * uy for (px, py) in P]
        a, b = max(0.0, min(sv)), min(L, max(sv))
        if b - a > 2.0:
            bridges.append((a, b, S.z_at(mx, my) - base, d))
    # v16.7: named parks and places the line crosses (OpenStreetMap areas with their own name), called out by name
    places = []
    lbb = (min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1))
    for z in S.zones:
        nm_ = proper_name((z.get("tags") or {}).get("name") or "")
        if not nm_ or not bb_hit(z["bb"], lbb):
            continue
        ins = [s for s in xs if region_contains(x0 + ux * s, y0 + uy * s, z["Ps"], z.get("Hs") or [])]
        if len(ins) >= 4:
            places.append((ins[0], ins[-1] + step, nm_))
    return dict(name=name, line=(x0, y0, x1, y1, name), L=L, ground=ground, bld=bl, trees=trees, walls=walls,
                chwalls=chwalls, water=[(a, b, bed - base, lvl - base) for (a, b, bed, lvl, bank, src) in wat],
                bed_src=[src for (a, b, bed, lvl, bank, src) in wat], water_src=wsrcs,
                labels=labels, levels=levels, strip=strip, comp=comp, zmax=zmax, base=base,
                beyond=beyond, btrees=btrees, bridges=bridges, places=places)


def crown_lo(h):
    """Height where a crown starts above the ground: the analyses' convention (35 % of the measured top, at least
    1.5 m), the canopy map gives the top height and the crown radius, not the crown base."""
    return max(1.5, 0.35 * h)


def crowns_near(S, bb):
    """Tree crowns measured on the 1 m canopy height map (Meta / WRI) as (x, y, radius, top height), from env_path;
    crowns standing on a roof are misreadings and left out, as in the analyses. Empty without the environment file."""
    g = getattr(S, "g_crown", None)
    if g is None:
        E = (getattr(S, "env", None) or {}).get("E")
        if E is None and ENV_PATH:
            E, _ = load_env(ENV_PATH)
        fb = S.F.bb
        g = Grid(20.0)
        for row in (E or {}).get("trees", []):
            x, y, r, h = row[:4]
            if h < 3.0 or not (fb[0] - 80 <= x <= fb[2] + 80 and fb[1] - 80 <= y <= fb[3] + 80):
                continue
            if any(in_unit(x, y, u) for u in S.g_bld.query((x, y, x, y))):
                continue
            g.add((x, y, r, h), (x, y, x, y))
        S.g_crown = g
    return g.query(bb)


NAME_GENERIC = {"cami", "camii", "mescit", "mescid", "trafo", "w.c", "wc", "w.c.", "depo", "baraka", "okul", "park",
                "bahçe", "bahce", "havuz", "türbe", "turbe", "çeşme", "cesme", "mezar", "mezarlık", "mezarlik", "kilise",
                "hamam", "harabe", "kalıntı", "kalinti", "sundurma", "ahır", "ahir", "garaj", "dükkan", "dukkan", "yapı",
                "yapi", "bina", "inş", "ins", "inşaat", "insaat", "halinde", "fabrika", "fab", "atölye", "atolye",
                "kulübe", "kulube", "ambar", "samanlık", "tuvalet", "büfe", "bufe", "kahve", "kahvehane", "lojman",
                "monument", "mosque", "ruin", "place", "of", "worship", "sanayi", "sanayii", "sitesi", "harap", "kule",
                "tarihi", "salonu", "düğün", "dugun", "sahne"}


def proper_name(nm):
    """v16.7: the name itself when it names this one place (Ulu Camii, Kızıl Avlu), '' when it is only a type word
    (Cami, Trafo, Depo) or a number. Never invents or translates: the name is returned as the source spells it."""
    nm = " ".join((nm or "").split())
    if any(c_ in nm for c_ in "§�") or nm.lower().endswith(("mahallesi", "mahalle")):
        return ""                                        # a garbled spelling, or a neighbourhood's name
    h_ = nm.split()
    if len(h_) % 2 == 0 and h_[:len(h_) // 2] == h_[len(h_) // 2:]:
        nm = " ".join(h_[:len(h_) // 2])                 # the same name entered twice
    words = [w.strip(".,;:()-/").lower() for w in nm.split()]
    rest = [w for w in words if w and w not in NAME_GENERIC and not w.replace(".", "").isdigit()]
    return nm if any(len(w) >= 3 for w in rest) else ""


def label_name(u):
    """v16.7: the name drawn on a cut building in place of its type word: only for monuments, sacred buildings, civic
    halls and other civic or religious buildings that a source names (shops, hotels and houses keep their type)."""
    if not u or not u.get("proper"):
        return ""
    if u.get("fabric") in ("monument", "sacred", "large") or u.get("cat") in ("religious", "institutional"):
        return u["proper"]
    return ""


def live_unit(S, u):
    """v16.7: this run's building for a cached copy of it (cached solids keep the unit as it was when they were made,
    without the names added in v16.7). Matched by its centre."""
    if not u or "proper" in u:
        return u
    lk = getattr(S, "_live_units", None)
    if lk is None:
        lk = S._live_units = dict(((round(v["cx"], 2), round(v["cy"], 2)), v) for v in S.bld if "cx" in v)
    return lk.get((round(u.get("cx", 0.0), 2), round(u.get("cy", 0.0), 2)), u)


def unit_flags(u):
    """(mosque, minaret, ruin) as the survey records them: names, the minaret symbol, the ruin layer."""
    nm = " " + (u.get("name") or "").lower() + " "
    kind = DWG["bld"].get(u.get("layer"), "mesken")
    mosque = any(w in nm for w in ("cami", "mescit", "mescid")) or (kind == "dini" and bool(u.get("minaret")))
    ruin = kind == "harabe" or any(w in nm for w in ("harabe", "harap", "kalıntı", "kalinti"))
    return (mosque or bool(u.get("minaret")), bool(u.get("minaret")), ruin)


def build_observations(S):
    obs = []
    tot = S.total_area
    land = [(k, S.area[k]) for k in CAT_ORDER if S.area.get(k, 0) > 0 and k != "water"]
    if land:
        k, a = max(land, key=lambda t: t[1])
        obs.append((CAT[k][1], "{} carries the ground: {:.1f}% of all mapped cover, {:.2f} ha.".format(
            CAT[k][0], 100.0 * a / tot, a / 1e4)))
    bc = 100.0 * S.built_area / S.frame_area
    obs.append((INK, "Solid {:.0f}%, void {:.0f}%: a {} grain whose voids are streets, courtyards and the stream bed.".format(
        bc, 100.0 - bc, "tight" if bc > 40 else ("loose" if bc < 22 else "measured"))))
    surv = [u for u in S.bld if u["floors_src"] == "survey" and not u["annex"]]
    if surv:
        one = 100.0 * len([u for u in surv if u["floors"] == 1]) / len(surv)
        avg = sum(u["floors"] for u in surv) / float(len(surv))
        obs.append((CAT["residential"][1], "A low skyline: {:.0f}% of surveyed buildings stand a single storey; "
                                           "the mean is {:.1f} floors.".format(one, avg)))
    if S.corr_primary:
        names = [g["label"] for g in (S.corr_primary + S.corr_secondary)[:3]]
        obs.append((CAT["commercial"][1], "Commerce gathers along {}, where ground floors open to the street.".format(
            join_names(names))))
    obs.append((CAT["green"][1], "Green holds {:.1f}% of the frame; {} larger ground{} anchor{} a thin, broken weave.".format(
        S.green_pct, S.n_major_green, "" if S.n_major_green == 1 else "s", "s" if S.n_major_green == 1 else "") +
        green_sat_note(S)))
    if S.clusters:
        obs.append((CAT["institutional"][1], "{} civic constellation{} gather the town's public life.".format(
            len(S.clusters), "" if len(S.clusters) == 1 else "s")))
    te = sum(S.edge_len.values())
    if te > 0:
        k = max(S.edge_len, key=S.edge_len.get)
        obs.append((CAT["water"][1], "Along the Selinus, {} dominate ({:.0f}% of {:.0f} m of bank); {:.0f}% of the banks "
                                     "are walled and {:.0f}% embanked, a seam the town mostly turns its back on.".format(
            EDGE[k][2], 100.0 * S.edge_len[k] / te, te, 100.0 * S.walled_len / te, 100.0 * S.embanked_len / te)))
    S.observations = obs


# ============================================================ TEXT METRICS
# Rhino's text height is the CAPITAL height. Courier New advances ~1.05 x height per character,
# Arial/Josefin capitals ~0.92 x height. All wrapping and column fitting uses these widths.
ADV = {"mono": 1.05, "sans": 0.92}


def kind_of(font):
    return "mono" if font == FONT_BODY else "sans"


def tw(txt, h, kind="mono"):
    return len(txt) * h * ADV[kind]


def wrap(txt, width, h, kind="mono"):
    return textwrap.wrap(txt, max(6, int(width / (h * ADV[kind]))))


def short(label):
    return label.split(" · ")[0]


# ============================================================ BOARD MODEL (pure geometry, baked at the end)
class Board(object):
    """Pure-geometry drawing list. Every item remembers its drawing (group) and layer root."""

    def __init__(self):
        self.items = []
        self.group = None
        self.root = "LU_BOARD"

    def begin(self, group, root):
        self.group, self.root = group, root

    def _lay(self, layer):
        return self.root + layer[len("LU_BOARD"):] if layer.startswith("LU_BOARD") else layer

    def fill(self, polys, color, layer, order):
        polys = [P for P in polys if P and len(P) >= 3]
        if polys:
            self.items.append(("fill", polys, color, self._lay(layer), order, self.group))

    def line(self, P, color, layer, order, w=0.13):
        if P and len(P) >= 2:
            self.items.append(("line", P, color, self._lay(layer), order, w, self.group))

    def hatch(self, polys, color, layer, order, spacing, ang=math.radians(45.0), w=0.03):
        """v16.5: parallel hatch lines over the area of polys (outer rings and holes, even-odd), spacing apart in page
        units at angle ang. Baked as a Rhino hatch (pattern "SELINUS lines"); as plain lines where that fails."""
        polys = [P for P in polys if P and len(P) >= 3]
        if polys and spacing > 0:
            self.items.append(("hatch", polys, color, self._lay(layer), order, spacing, ang, w, self.group))

    def image(self, path, x0, y0, x1, y1, layer, order=5):
        self.items.append(("image", path, (x0, y0, x1, y1), self._lay(layer), order, self.group))

    def text(self, txt, x, y, h, color, layer, order=40, font=None, bold=False, align="L", angle=0.0, italic=False):
        self.items.append(("text", txt, (x, y), h, color, self._lay(layer), order, font or FONT_BODY, bold, align,
                           angle, italic, self.group))

    def para(self, txt, x, y, width, h, color, layer, lead=1.8, font=None, order=40):
        """Wrapped paragraph; returns the y below it."""
        k = kind_of(font or FONT_BODY)
        for ln in wrap(txt, width, h, k):
            self.text(ln, x, y, h, color, layer, order, font)
            y -= h * lead
        return y

    def para_fit(self, txt, x, y, width, h, ymin, color, layer, lead=1.8, font=None, order=40):
        """Wrapped paragraph kept above ymin: the text is made smaller, step by step, until its last line fits."""
        k = kind_of(font or FONT_BODY)
        for _ in range(16):
            if y - (len(wrap(txt, width, h, k)) - 1) * h * lead >= ymin:
                break
            h *= 0.94
        return self.para(txt, x, y, width, h, color, layer, lead=lead, font=font, order=order)

    def fit(self, txt, x, y, h, width, color, layer, **kw):
        """Single line, shrunk to fit the width if needed."""
        k = kind_of(kw.get("font") or FONT_BODY)
        need = tw(txt, h, k)
        if need > width > 0:
            h *= width / need
        self.text(txt, x, y, h, color, layer, **kw)
        return h


class View(object):
    def __init__(self, F, s, X0, Ytop):
        self.F, self.s, self.X0, self.Yt = F, s, X0, Ytop

    def p(self, x, y):
        u, v = self.F.local(x, y)
        return (self.X0 + self.s * (u - self.F.u0), self.Yt + self.s * (v - self.F.v1))

    def P(self, pts):
        return [self.p(x, y) for x, y in pts]

    def Ps(self, lst):
        return [self.P(P) for P in lst if P]

    def angle(self, tx, ty):
        a0 = self.F.local(0.0, 0.0)
        a1 = self.F.local(tx, ty)
        a = math.atan2(a1[1] - a0[1], a1[0] - a0[0])
        while a > math.pi / 2:
            a -= math.pi
        while a <= -math.pi / 2:
            a += math.pi
        return a


def view_fit(F, x, ytop, bw, bh):
    s = min(bw / F.w, bh / F.h)
    return View(F, s, x + (bw - F.w * s) / 2.0, ytop), F.w * s, F.h * s


def hatch_lines(Ps, Hs, bb, spacing, ang):
    d = (math.cos(ang), math.sin(ang))
    nrm = (-d[1], d[0])
    cx, cy = 0.5 * (bb[0] + bb[2]), 0.5 * (bb[1] + bb[3])
    R = 0.5 * math.hypot(bb[2] - bb[0], bb[3] - bb[1]) + spacing
    out = []
    k = -R
    while k <= R and len(out) < 600:
        ox, oy = cx + nrm[0] * k, cy + nrm[1] * k
        a = (ox - d[0] * R, oy - d[1] * R)
        r = (2 * d[0] * R, 2 * d[1] * R)
        ts = []
        for P in Ps + Hs:
            for i in range(len(P)):
                q, q2 = P[i], P[(i + 1) % len(P)]
                res = seg_x(a, r, q, (q2[0] - q[0], q2[1] - q[1]))
                if res:
                    ts.append(res[0])
        ts.sort()
        for i in range(0, len(ts) - 1, 2):
            out.append([(a[0] + r[0] * ts[i], a[1] + r[1] * ts[i]), (a[0] + r[0] * ts[i + 1], a[1] + r[1] * ts[i + 1])])
        k += spacing
    return out


def hatch_segments(polys, spacing, ang):
    """v16.5: the hatch lines of an area (rings: outer and holes alike, even-odd) as segments [(p, q)]: lines at angle
    ang, spacing apart, on one grid for every area (neighbouring areas line up). numpy; the old scanner without it."""
    if not HAVE_NP:
        bb = bb_pts([p for P in polys for p in P])
        return hatch_lines(polys, [], bb, spacing, ang)
    ca, sa = math.cos(ang), math.sin(ang)
    ua, va, ub, vb = [], [], [], []
    for P in polys:
        a = np.asarray(P, float)
        if len(a) < 3:
            continue
        b = np.roll(a, -1, axis=0)
        ua.append(ca * a[:, 0] + sa * a[:, 1])
        va.append(-sa * a[:, 0] + ca * a[:, 1])
        ub.append(ca * b[:, 0] + sa * b[:, 1])
        vb.append(-sa * b[:, 0] + ca * b[:, 1])
    if not ua:
        return []
    ua, va, ub, vb = (np.concatenate(q) for q in (ua, va, ub, vb))
    lo, hi = np.minimum(va, vb), np.maximum(va, vb)
    k0 = np.ceil(lo / spacing).astype(np.int64)
    k1 = np.ceil(hi / spacing).astype(np.int64) - 1          # half-open [lo, hi): every closed ring crosses a line evenly
    n = np.maximum(0, k1 - k0 + 1)
    n[va == vb] = 0
    tot = int(n.sum())
    if tot == 0:
        return []
    idx = np.repeat(np.arange(len(n)), n)
    off = np.repeat(np.cumsum(n) - n, n)
    kk = k0[idx] + (np.arange(tot) - off)
    v = kk * spacing
    u = ua[idx] + (v - va[idx]) * (ub[idx] - ua[idx]) / (vb[idx] - va[idx])
    o = np.lexsort((u, kk))
    kk, u, v = kk[o], u[o], v[o]
    out = []
    if len(kk) % 2 == 0 and np.all(kk[0::2] == kk[1::2]):
        pairs = zip(u[0::2], u[1::2], v[0::2])
    else:                                                   # an open ring: pair within each line only
        pairs = []
        for k in np.unique(kk):
            m = kk == k
            uu, vv = u[m], v[m][0]
            pairs += [(uu[i], uu[i + 1], vv) for i in range(0, len(uu) - 1, 2)]
    tiny = 0.15 * spacing
    for u0, u1, vv in pairs:
        if u1 - u0 > tiny:
            out.append([(ca * u0 - sa * vv, sa * u0 + ca * vv), (ca * u1 - sa * vv, sa * u1 + ca * vv)])
    return out


def draw_scalebar(B, x, y, scale, Lm, U, L, h=0.42):
    seg = Lm / 4.0
    bh = 0.38 * U
    for i in range(4):
        x0 = x + i * seg * scale
        B.fill([rect(x0, y, x0 + seg * scale, y + bh)], INK if i % 2 == 0 else KHAKI, L, 20)
    B.line(rect(x, y, x + Lm * scale, y + bh) + [(x, y)], INK, L, 21, 0.08)
    labs = [(v, "{:g}".format(v)) for v in (0.0, 2 * seg, Lm)]
    wd = [tw(t, h * U) for _, t in labs]
    gap = 0.3 * U                                     # a label is left out rather than run into its neighbour
    keep = [Lm * scale >= 0.5 * (wd[0] + wd[2]) + gap,
            2 * seg * scale >= 0.5 * (wd[0] + wd[1]) + gap and 2 * seg * scale >= 0.5 * (wd[1] + wd[2]) + gap, True]
    for (v, t), k in zip(labs, keep):
        if k:
            B.text(t, x + v * scale, y + bh + 0.35 * U, h * U, INK, L, align="C")
    B.text("m", x + Lm * scale + 0.9 * U, y, h * U, INK, L)


def draw_north_small(B, V, mw, mh, U, L, size=0.55):
    """Small north arrow kept fully inside the top-right corner of a map, in the foreground."""
    k = size * U
    x = V.X0 + mw - 1.2 * k - 0.35 * U
    y = V.Yt - 1.75 * k - 0.35 * U
    a = math.atan2(math.cos(V.F.ang), math.sin(V.F.ang))
    c, s = math.cos(a - math.pi / 2), math.sin(a - math.pi / 2)

    def R(px, py):
        return (x + c * px - s * py, y + s * px + c * py)
    tip, l, m, r = R(0, 0.75 * k), R(-0.38 * k, -0.5 * k), R(0, -0.22 * k), R(0.38 * k, -0.5 * k)
    B.fill([[tip, l, m]], INK, L, 60)
    B.fill([[tip, m, r]], KHAKI, L, 60)
    B.line([tip, l, m, r, tip], INK, L, 61, 0.05)
    nx, ny = R(0, 1.12 * k)
    B.text("N", nx, ny, 0.42 * k, INK, L, order=61, font=FONT_TITLE, bold=True, align="MC")


def draw_symbol(B, kind, col, x, y, U, L, sw=1.1, sh=0.62):
    y0, y1 = y - 0.05 * U, y + sh * U
    ym = 0.5 * (y0 + y1)
    seg = [(x, ym), (x + sw * U, ym)]
    if kind == "box":
        B.fill([rect(x, y0, x + sw * U, y1)], col, L, 20)
        B.line(rect(x, y0, x + sw * U, y1) + [(x, y0)], INK2, L, 21, 0.05)
    elif kind == "line":
        B.line(seg, col, L, 21, 0.5)
    elif kind == "thick":
        B.line(seg, col, L, 21, EDGE_W)
    elif kind == "dash":
        for d in dashes(seg, 0.32 * U, 0.2 * U):
            B.line(d, col, L, 21, 0.3)
    elif kind == "walled":
        B.line(seg, col, L, 21, EDGE_W)
        for d in dashes(seg, 0.22 * U, 0.18 * U):
            B.line(d, PAPER, L, 22, EDGE_MARK_W)
    elif kind == "embanked":
        B.line(seg, col, L, 21, EDGE_W)
        for d in dashes(seg, 0.06 * U, 0.22 * U):
            B.line(d, PAPER, L, 22, EDGE_MARK_W)
    elif kind == "dot":
        B.fill([circle_pts(x + 0.5 * sw * U, ym, 0.28 * U, 12)], col, L, 21)
    elif kind == "thin":                              # v33: stream thresholds on the plan
        B.line(seg, col, L, 21, THRESH_W)
    elif kind == "dense":
        B.line(seg, col, L, 21, 0.22)
    elif kind == "kmark":
        roundel(B, x + 0.5 * sw * U, ym, 0.3 * U, "K", (255, 255, 255), INK, L, order=21)
    elif kind == "cmark":
        roundel(B, x + 0.5 * sw * U, ym, 0.3 * U, "C", MARK_C, MARK_C, L, order=21)
    elif kind == "pmark":
        B.fill([rect(x + 0.5 * sw * U - 0.26 * U, ym - 0.26 * U, x + 0.5 * sw * U + 0.26 * U, ym + 0.26 * U)], INK, L, 21)
    elif kind == "street":
        B.line(seg, col, L, 21, 0.42)
        B.line(seg, ROAD_FILL if ROAD_SOLID else (255, 255, 255), L, 22, 0.3)     # v16.7: the solid street colour


def draw_legend_items(B, items, x, y, width, U, L, h=0.5):
    """Legend rows; two columns only when every label fits. Returns the y below."""
    sw = 1.1
    lw2 = width / 2.0
    if any(k_ == "hdr" for k_, _c, _l in items):            # v33: titled groups, each in as many columns as fit
        groups, cur = [], None
        for it in items:
            if it[0] == "hdr":
                cur = [it[2], []]
                groups.append(cur)
            elif cur is None:
                cur = ["", [it]]
                groups.append(cur)
            else:
                cur[1].append(it)
        ncol = max(1, int(width // (16.0 * U)))
        colw = width / ncol
        for title, its in groups:
            if title:
                B.text(title, x, y, h * U, INK2, L, font=FONT_TITLE, bold=True)
                y -= 1.6 * h * U + 0.15 * U
            for j, (kind, col, label) in enumerate(its):
                cx = x + (j % ncol) * colw
                draw_symbol(B, kind, col, cx, y, U, L, sw=sw)
                B.fit(label, cx + (sw + 0.5) * U, y, h * U, colw - (sw + 0.8) * U, INK, L)
                if j % ncol == ncol - 1 or j == len(its) - 1:
                    y -= 1.6 * h * U + 0.15 * U
            y -= 0.35 * U
        return y
    two = all(tw(lbl, h * U) + (sw + 0.6) * U <= lw2 - 0.6 * U for _, _, lbl in items)
    cols = 2 if two and len(items) > 2 else 1
    colw = width / cols
    for j, (kind, col, label) in enumerate(items):
        cx = x + (j % cols) * colw
        draw_symbol(B, kind, col, cx, y, U, L, sw=sw)
        B.fit(label, cx + (sw + 0.5) * U, y, h * U, colw - (sw + 0.8) * U, INK, L)
        if j % cols == cols - 1 or j == len(items) - 1:
            y -= 1.6 * h * U + 0.15 * U
    return y


# ============================================================ THE LAND-USE MAP
def draw_landuse_map(S, B, V, bcol=None):
    """bcol (v33): the colour of each building (default: its land-use colour)."""
    L = "LU_BOARD::Map"
    s = V.s
    U = S.U
    B.fill([V.P(S.F.P)], PAPER, L + "::paper", 2)
    draw_landcover(S, B, V, L + "::landcover", 3)       # v31: under the surveyed / OSM ground (4)
    for z in S.zones:
        if z["kind"] == "green":
            col = GREEN_SUB.get(z["sub"], CAT["green"][1])
        elif z["kind"] == "transport":
            col = mix(CAT["transport"][1], PAPER, 0.3)
        else:
            col = CAT[z["kind"]][1]
        B.fill(V.Ps(z["Ps"] + z["Hs"]), col, L + "::" + z["kind"], 4)
        if z["kind"] == "vacant" and TEXTURE:
            for ln in hatch_lines(z["Ps"], z["Hs"], z["bb"], 5.0, math.radians(45)):
                B.line(V.P(ln), mix(INK, PAPER, 0.55), L + "::texture", 5, 0.06)
        if z["kind"] == "agri" and z["sub"] == "field" and TEXTURE:
            ang = (_zlib_crc(repr([round(v_, 2) for v_ in z["bb"]]).encode("utf-8")) % 180) * math.pi / 180.0
            for ln in hatch_lines(z["Ps"], z["Hs"], z["bb"], 7.0, ang):
                B.line(V.P(ln), mix(CAT["agri"][1], INK, 0.22), L + "::texture", 5, 0.04)
    for w in S.water:
        B.fill(V.Ps([w["P"]] + w.get("H", [])), CAT["water"][1], L + "::water", 6)
    for q in getattr(S, "decks", []):
        B.fill([V.P(q)], ROADC, L + "::streets", 7)
    for P in getattr(S, "covered", []):              # the covered course: a hidden line over the streets and roofs
        for d in dashes(V.P(P), 0.35 * U, 0.25 * U):
            B.line(d, BLUE_D, L + "::water", 19, 0.12)
    for P in S.water_outline:                         # the river edge: one continuous line per stretch (under decks)
        B.line(V.P(P), BLUE_D, L + "::water", 6, 0.13)
    for P in river_free_banks(S):                     # other surveyed streams and ditches, thinner
        B.line(V.P(P), BLUE_D, L + "::water", 7, 0.07)
    for P in S.pools:
        B.line(V.P(P), BLUE_D, L + "::water", 7, 0.08)
    road_lines(S, B, V, L + "::streets", 8, casing=ROAD_EDGE, surface=ROADC, min_w=0.04, fill=ROAD_FILL)
    for p in S.paths:                                 # paths whose width the survey does not show: a thin line
        if not p.get("w"):
            B.line(V.P(p["P"]), ROADC, L + "::streets", 9, 0.04)
    if TEXTURE:
        for x, y, r, kind in S.trees:
            bx, by = V.p(x, y)
            B.fill([circle_pts(bx + 0.35 * r * s, by - 0.35 * r * s, r * s, 14)], TREE_SHADOW, L + "::trees", 10)
            B.fill([circle_pts(bx, by, r * s, 14)], TREE_COLS.get(kind, TREE_COLS["tree"]), L + "::trees", 11)
            if kind == "pine":
                B.fill([circle_pts(bx - 0.25 * r * s, by + 0.25 * r * s, 0.45 * r * s, 10)],
                       mix(TREE_COLS["pine"], PAPER, 0.35), L + "::trees", 12)
        sh = mix(INK, PAPER, 0.6)
        for u in S.bld:
            off = min(3.0, 0.11 * u["h"]) * s
            B.fill([[(x + off, y - off) for x, y in V.P(P)] for P in u["parts"] + (u.get("holes") or [])], sh,
                   L + "::texture", 13)
    for u in S.bld:
        col = CAT[u["cat"]][1]
        if u["annex"]:
            col = mix(col, PAPER, 0.35)
        if bcol is not None:
            col = bcol(u)
        B.fill(V.Ps(u["parts"] + (u.get("holes") or [])), col, L + "::" + u["cat"], 14)
        if TEXTURE:
            for P in u["parts"] + (u.get("holes") or []):
                B.line(V.P(P + [P[0]]), PAPER, L + "::texture", 15, 0.04)
    for P in S.slope_hatch:
        B.line(V.P(P), mix(INK2, PAPER, 0.4), L + "::ground", 16, 0.04)
    for P in S.slopes:
        B.line(V.P(P), INK2, L + "::ground", 16, 0.08)
    for P in S.stairs:
        B.line(V.P(P), INK2, L + "::ground", 16, 0.05)
    for P in S.fences:
        B.line(V.P(P), mix(INK2, PAPER, 0.3), L + "::ground", 16, 0.04)
    for P in S.park_lines:
        for d in dashes(V.P(P), 0.4 * U, 0.28 * U):
            B.line(d, mix(CAT["green"][1], INK, 0.3), L + "::ground", 16, 0.08)
    for P in S.walls:
        B.line(V.P(P), INK, L + "::walls", 17, 0.16)
    for P in S.bridges:
        B.line(V.P(P), INK, L + "::walls", 18, 0.24)


def study_areas_from(R, I):
    """v19: the closed curves on STUDY_LAYERS in survey coordinates: [dict(name, layer, P, area)]. Read only."""
    out = []
    for lay in STUDY_LAYERS:
        nm = (lay[:-5] if lay.lower().endswith("_alan") else lay).upper()
        for P in (R.get("plines") or {}).get(lay, []):
            pts = [T_apply(I, p[0], p[1]) for p in P]
            closed = len(pts) > 3 and math.hypot(pts[0][0] - pts[-1][0], pts[0][1] - pts[-1][1]) < 1e-6
            if not closed:
                LOG.append("WARNING: a curve on the layer '{}' is not closed, so it is not drawn as a study area."
                           .format(lay))
                continue
            pts = pts[:-1]
            out.append(dict(name=nm, layer=lay, P=pts, area=shoelace(pts)[0]))
    if out:
        LOG.append("Group study areas (read only, never drawn): " + "; ".join(
            "{} {:,.0f} m2".format(a["name"], a["area"]) for a in out) + ".")
    return out


def sec_road_spans(S, x0, y0, ux, uy, L, step=0.25):
    """v25: the streets a section line crosses: [(s0, s1, name, src)], s along the line. The stretch is where the line
    runs on a surveyed street surface (S.road_net); the name is the OSM street (S.roads, footpaths excluded) whose
    centreline crosses inside that stretch (the nearest one), else "". A named OSM centreline crossed off every surface
    gives (s, s, name, "osm") (position only, no surveyed width). Read only."""
    net = getattr(S, "road_net", None) or []
    n = int(L / step) + 1
    ss_ = [min(L, k * step) for k in range(n)]
    xs = [x0 + ux * s_ for s_ in ss_]
    ys = [y0 + uy * s_ for s_ in ss_]
    lb = (min(xs), min(ys), max(xs), max(ys))
    on = [False] * n
    for rg_ in net:
        P = rg_["P"]
        bx0, by0 = min(p[0] for p in P), min(p[1] for p in P)
        bx1, by1 = max(p[0] for p in P), max(p[1] for p in P)
        if bx1 < lb[0] or bx0 > lb[2] or by1 < lb[1] or by0 > lb[3]:
            continue
        for k in range(n):
            if not on[k] and bx0 <= xs[k] <= bx1 and by0 <= ys[k] <= by1 and pip(xs[k], ys[k], P) and \
                    not any(pip(xs[k], ys[k], H) for H in rg_.get("H") or []):
                on[k] = True
    spans = []
    k = 0
    while k < n:
        if on[k]:
            j = k
            while j + 1 < n and on[j + 1]:
                j += 1
            spans.append([max(0.0, ss_[k] - 0.5 * step), min(L, ss_[j] + 0.5 * step), "", "survey"])
            k = j + 1
        else:
            k += 1
    hits = []                                            # (s, name) where an OSM street centreline crosses the line
    for r in getattr(S, "roads", None) or []:
        hw = (r.get("tags") or {}).get("highway")
        if hw in PED:
            continue
        nm = proper_name((r.get("tags") or {}).get("name") or "")
        P = r["P"]
        for i in range(len(P) - 1):
            (ax, ay), (bx, by) = P[i][:2], P[i + 1][:2]
            ex, ey = bx - ax, by - ay
            den = ux * ey - uy * ex
            if abs(den) < 1e-12:
                continue
            wx, wy = ax - x0, ay - y0
            s = (wx * ey - wy * ex) / den
            t = (wx * uy - wy * ux) / den
            if 0.0 <= t <= 1.0 and 0.0 <= s <= L:
                hits.append((s, nm))
    for s, nm in sorted(hits):
        sp = next((q for q in spans if q[0] - 1.0 <= s <= q[1] + 1.0), None)
        if sp is not None:
            if nm and not sp[2]:
                sp[2] = nm
        elif nm and not any(abs(q[0] - s) < 3.0 and q[2] == nm for q in spans):
            spans.append([s, s, nm, "osm"])
    return sorted(tuple(q) for q in spans)


def road_label(s0, s1, nm, src):
    """v25: the text of a street in a section."""
    nm_ = tr_upper(nm) if nm else "STREET"
    if src == "osm":
        return nm_ + " · OSM line, no surveyed surface"
    return "{} · {:.1f} m on the cut".format(nm_, s1 - s0)


def draw_sec_roads(S, B, L, P, g_at, line, Lm, U, off=0.0, order=36, w=0.5):
    """v25: the streets in a section: a bold ink line on the ground over each street's surface, its ends ticked.
    Returns [(s_mid, z, label)] for the section's callouts (s within this part)."""
    x0, y0, x1, y1 = line[:4]
    Ll = math.hypot(x1 - x0, y1 - y0)
    if Ll < 1e-6:
        return []
    ux, uy = (x1 - x0) / Ll, (y1 - y0) / Ll
    out = []
    for s0, s1, nm, src in sec_road_spans(S, x0, y0, ux, uy, Ll):
        a0, a1 = s0 - off, s1 - off
        if a1 < -1e-6 or a0 > Lm + 1e-6:
            continue
        a0, a1 = max(0.0, a0), min(Lm, a1)
        if src == "osm":
            q = P(a0, g_at(a0))
            B.line([(q[0], q[1] - 0.25 * U), (q[0], q[1] + 0.45 * U)], INK, L, order, w)
        else:
            nn = max(2, int((a1 - a0) / 0.5) + 1)
            pts = [P(a0 + (a1 - a0) * k / (nn - 1.0), g_at(a0 + (a1 - a0) * k / (nn - 1.0))) for k in range(nn)]
            B.line(pts, INK, L, order, w)
            for q in (pts[0], pts[-1]):
                B.line([(q[0], q[1] - 0.2 * U), (q[0], q[1] + 0.2 * U)], INK, L, order, 0.5 * w)
        sm = 0.5 * (a0 + a1)
        out.append((sm, g_at(sm), road_label(s0, s1, nm, src)))
    return out


def draw_map_annotations(S, B, V, U):
    L = "LU_BOARD::Map::annotation"
    s = V.s
    if S.river_label and S.selinus:                     # river name on the stretch farthest from the section marks
        main = max(S.selinus, key=pl_length)
        Lm = pl_length(main)
        best = None
        for k in range(3, 18):
            p, t = pl_point_at(main, Lm * k / 20.0)
            d = min([seg_dist(p[0], p[1], x0, y0, x1, y1) for x0, y0, x1, y1, nm in S.sec_lines] + [1e9])
            d = min(d, pl_dist(p[0], p[1], S.F.P, True) * 1.5)
            if best is None or d > best[0]:
                best = (d, p, t)
        _, p, t = best
        ang = V.angle(t[0], t[1])
        bx, by = V.p(p[0], p[1])
        off = 1.4 * U
        B.text(S.river_label[3], bx - math.sin(ang) * off, by + math.cos(ang) * off, 0.5 * U, BLUE_D, L,
               align="MC", angle=ang, italic=True)
    for x0, y0, x1, y1, nm in S.sec_lines:              # light section marks, labels inside the map
        a, b = V.p(x0, y0), V.p(x1, y1)
        Lb = math.hypot(b[0] - a[0], b[1] - a[1]) or 1.0
        d = ((b[0] - a[0]) / Lb, (b[1] - a[1]) / Lb)
        nrm = (-d[1], d[0])
        for seg in dashes([a, b], 0.55 * U, 0.3 * U):
            B.line(seg, INK2, L, 20, 0.08)
        for p, inward, lab in ((a, d, nm), (b, (-d[0], -d[1]), nm + "'")):
            base = (p[0] + inward[0] * 0.35 * U, p[1] + inward[1] * 0.35 * U)
            tri = [(base[0] + nrm[0] * 0.45 * U, base[1] + nrm[1] * 0.45 * U),
                   (base[0] - d[0] * 0.18 * U, base[1] - d[1] * 0.18 * U),
                   (base[0] + d[0] * 0.18 * U, base[1] + d[1] * 0.18 * U)]
            B.fill([tri], INK, L, 21)
            lp = (p[0] + inward[0] * 1.1 * U - nrm[0] * 0.35 * U, p[1] + inward[1] * 1.1 * U - nrm[1] * 0.35 * U)
            B.text(lab, lp[0], lp[1], 0.36 * U, INK, L, font=FONT_TITLE, bold=True, align="MC")
    B.line(V.P(S.F.P + [S.F.P[0]]), INK, L, 21, 0.25)


# ============================================================ LEGEND / DISTRIBUTION / READINGS (page 1)
def draw_legend(S, B, x, y, w, U):
    L = "LU_BOARD::Legend"
    B.text("LAND USE", x, y, 1.05 * U, INK, L, font=FONT_TITLE, bold=True)
    hy = y - 1.7 * U
    h = 0.5
    B.text("ha", x + w - 6.0 * U, hy, 0.42 * U, INK2, L, align="R")
    B.text("%", x + w, hy, 0.42 * U, INK2, L, align="R")
    B.line([(x, hy - 0.45 * U), (x + w, hy - 0.45 * U)], INK, L, 20, 0.15)
    ry = hy - 1.4 * U
    tot = frame_total(S)                                 # v35: every % is a % of the site frame
    namew = w - 1.6 * U - 13.0 * U
    for k in CAT_ORDER:
        a = S.area.get(k, 0.0)
        if a <= 0.0:
            continue
        B.fill([rect(x, ry - 0.05 * U, x + 1.1 * U, ry + 0.62 * U)], CAT[k][1], L, 20)
        B.line(rect(x, ry - 0.05 * U, x + 1.1 * U, ry + 0.62 * U) + [(x, ry - 0.05 * U)], INK2, L, 21, 0.05)
        parts = CAT[k][0].split(" · ")
        B.fit(parts[0], x + 1.6 * U, ry, h * U, namew, INK, L)
        B.text("{:.2f}".format(a / 1e4), x + w - 6.0 * U, ry, h * U, INK, L, align="R")
        B.text("{:.1f}".format(100.0 * a / tot), x + w, ry, h * U, INK, L, align="R")
        if len(parts) > 1:
            ry -= 0.72 * U
            B.fit(parts[1], x + 1.6 * U, ry, 0.38 * U, namew, INK2, L)
        ry -= 1.12 * U
    B.line([(x, ry + 0.55 * U), (x + w, ry + 0.55 * U)], INK, L, 20, 0.15)
    ry -= 0.25 * U
    rest = getattr(S, "rest", None) or []
    if rest:                                             # v35: the mapped part, then the rest of the frame by satellite
        B.text("MAPPED ON THE SURVEY AND OSM", x + 1.6 * U, ry, h * U, INK, L, bold=True)
        B.text("{:.2f}".format(S.total_area / 1e4), x + w - 6.0 * U, ry, h * U, INK, L, bold=True, align="R")
        B.text("{:.1f}".format(100.0 * S.total_area / tot), x + w, ry, h * U, INK, L, bold=True, align="R")
        ry -= 1.12 * U
        for k_, lab, col, a in rest:
            B.fill([rect(x, ry - 0.05 * U, x + 1.1 * U, ry + 0.62 * U)], col, L, 20)
            B.line(rect(x, ry - 0.05 * U, x + 1.1 * U, ry + 0.62 * U) + [(x, ry - 0.05 * U)], INK2, L, 21, 0.05)
            parts = lab.split(" · ") if k_ == "rest" else [lab]
            B.fit(parts[0], x + 1.6 * U, ry, h * U, namew, INK, L)
            B.text("{:.2f}".format(a / 1e4), x + w - 6.0 * U, ry, h * U, INK, L, align="R")
            B.text("{:.1f}".format(100.0 * a / tot), x + w, ry, h * U, INK, L, align="R")
            if len(parts) > 1:
                ry -= 0.72 * U
                B.fit(parts[1], x + 1.6 * U, ry, 0.38 * U, namew, INK2, L)
            ry -= 1.12 * U
        B.line([(x, ry + 0.55 * U), (x + w, ry + 0.55 * U)], INK, L, 20, 0.15)
        ry -= 0.25 * U
    B.text("TOTAL · SITE FRAME" if rest else "TOTAL", x + 1.6 * U, ry, h * U, INK, L, bold=True)
    B.text("{:.2f}".format(tot / 1e4), x + w - 6.0 * U, ry, h * U, INK, L, bold=True, align="R")
    B.text("100.0", x + w, ry, h * U, INK, L, bold=True, align="R")
    ry -= 1.2 * U
    km, km_w = getattr(S, "street_km", (0.0, 0.0))
    # v38: keywords and [n] (was a paragraph); the sentences are entries of the Sources key
    r1 = bcite("Land use: ground cover inside the frame: surveyed footprints by use, open ground, street surfaces and "
               "the stream bed. Pale tones are sheds and annexes. Street surface only where its width is measured on "
               "the survey.")
    B.fit("ground cover in the frame · pale = sheds, annexes " + r1, x, ry, 0.38 * U, w, INK2, L)
    ry -= 0.7 * U
    B.fit("street width measured · {:.1f} of {:.1f} km {}".format(km_w, km, r1), x, ry, 0.38 * U, w, INK2, L)
    ry -= 0.7 * U
    if rest:
        r2 = bcite("Unmapped ground: the ground the survey and OSM leave unmapped is split by ESA WorldCover 2021 (10 m "
                   "satellite classes, CC BY 4.0) on a {:g} m raster; orchards inferred from the survey's olive and "
                   "fruit-tree symbols. Satellite rows: approximate.".format(REST_CELL))
        B.fit("satellite rows · approximate " + r2, x, ry, 0.38 * U, w, INK2, L)
        ry -= 0.7 * U
    return ry


def page1_readings(S):
    """v38: the page-one readings as figures for drawing (were five generated sentences): the largest use, solid and
    void, the surveyed floors, green and fields. Every value is computed here, as before."""
    R = {}
    tot = S.total_area
    land = [(k, S.area[k]) for k in CAT_ORDER if S.area.get(k, 0) > 0 and k != "water"]
    if land:
        k, a = max(land, key=lambda t: t[1])
        R["use"] = (CAT[k][1], short(CAT[k][0]), 100.0 * a / tot)
    bc = 100.0 * S.built_area / S.frame_area
    R["solid"] = (bc, "tight" if bc > 40 else ("loose" if bc < 22 else "measured"))
    surv = [u for u in S.bld if u["floors_src"] == "survey" and not u["annex"]]
    if surv:
        cnt = {}
        for u in surv:
            cnt[u["floors"]] = cnt.get(u["floors"], 0) + 1
        R["floors"] = (dict((f, 100.0 * n / len(surv)) for f, n in cnt.items()),
                       sum(u["floors"] for u in surv) / float(len(surv)), S.int_peak_name or "")
    g = rest_of(S, "trees", "grass", "shrub")            # as green_sat_note: the satellite's green on the unmapped ground
    R["green"] = (S.green_pct, S.n_major_green,
                  100.0 * (sum(z["A"] for z in S.zones if z["kind"] == "green") + g) / S.frame_area if g > 0.0 else None)
    agri = 100.0 * (S.area.get("agri", 0.0) + rest_of(S, "farmland", "orchard")) / S.frame_area   # v35: + satellite
    if agri >= 5.0:
        R["agri"] = agri
    return R


def draw_distribution(S, B, x, y, U):
    """Donut of ground cover; about 13 page units wide. Returns the y below."""
    L = "LU_BOARD::Distribution"
    B.text("DISTRIBUTION", x, y, 1.05 * U, INK, L, font=FONT_TITLE, bold=True)
    r1, r0 = 4.4 * U, 2.6 * U
    cx, cy = x + r1 + 1.4 * U, y - 2.4 * U - r1 - 1.0 * U
    tot = frame_total(S)                                 # v35: the site frame, the unmapped ground by satellite class
    a0 = math.pi / 2.0
    slices = [(S.area.get(k, 0.0), CAT[k][1]) for k in CAT_ORDER] + [
        (a, col) for _k, _l, col, a in (getattr(S, "rest", None) or [])]
    for a, col in slices:
        if a <= 0.0:
            continue
        fr = a / tot
        a1 = a0 - 2.0 * math.pi * fr
        B.fill([annulus(cx, cy, r0, r1, a0, a1)], col, L, 20)
        B.line([(cx + r0 * math.cos(a0), cy + r0 * math.sin(a0)), (cx + r1 * math.cos(a0), cy + r1 * math.sin(a0))],
               BG, L, 21, 0.2)
        if fr >= 0.04:
            am = 0.5 * (a0 + a1)
            B.text("{:.0f}%".format(100.0 * fr), cx + (r1 + 0.9 * U) * math.cos(am), cy + (r1 + 0.9 * U) * math.sin(am),
                   0.4 * U, INK, L, align="MC")
        a0 = a1
    B.text("{:.1f}".format(tot / 1e4), cx, cy + 0.1 * U, 0.95 * U, INK, L, font=FONT_TITLE, align="C")
    B.text("ha site frame" if getattr(S, "rest", None) else "ha mapped", cx, cy - 0.8 * U, 0.36 * U, INK2, L, align="C")
    return cy - r1 - 1.6 * U


def draw_readings(S, B, x, y, w, bottom, U):
    """Page-one readings as pictures (v38, visual first; were five sentences): the largest use as a tile, solid and
    void as a bar, the surveyed floors as a histogram, green and fields as rings. `bottom` is kept for the callers."""
    O = "LU_BOARD::Readings"
    B.text("READINGS", x, y, 1.05 * U, INK, O, font=FONT_TITLE, bold=True)
    R = page1_readings(S)
    oy = y - 1.6 * U
    tfill = mix(PAPER, (255, 255, 255), 0.5)
    if R.get("use"):
        col, nm, pct = R["use"]
        oy = vis_tiles(B, x, oy, w, [("build", nm.upper() + " · LARGEST", "{:.0f}% of mapped".format(pct),
                                      bcite("Readings: shares of the mapped cover (largest use) and of the site frame "
                                            "(solid / void, green, fields)."))],
                       U, O, h=1.3, ink=INK, grey=INK2, fill=tfill, rule=FAINT) - 1.0 * U
    bc, grain = R["solid"]                                # solid / void bar
    B.text("SOLID / VOID · {} GRAIN {}".format(grain.upper(), bcite("Solid / void: the voids are streets, courtyards "
                                                                     "and the stream bed.")), x, oy, 0.4 * U, INK, O,
           font=FONT_TITLE, bold=True)
    by = oy - 0.55 * U
    B.fill([rect(x, by - 0.8 * U, x + w, by)], PAPER, O, 20)
    B.fill([rect(x, by - 0.8 * U, x + w * min(1.0, bc / 100.0), by)], INK, O, 21)
    B.line(rect(x, by - 0.8 * U, x + w, by) + [(x, by - 0.8 * U)], INK2, O, 22, 0.05)
    B.text("solid {:.0f}%".format(bc), x + 0.2 * U, by - 0.6 * U, 0.4 * U, PAPER if bc > 25 else INK, O, order=23)
    B.text("void {:.0f}%".format(100.0 - bc), x + w - 0.2 * U, by - 0.6 * U, 0.4 * U, INK, O, order=23, align="R")
    oy = by - 0.8 * U - 1.2 * U
    if R.get("floors"):                                   # floors histogram of the surveyed buildings
        share, avg, peak = R["floors"]
        B.text("FLOORS · SURVEYED · MEAN {:.1f} {}".format(avg, bcite("Skyline: surveyed buildings by floors; density "
                                                                       "gathers where it rises.")), x, oy, 0.4 * U,
               INK, O, font=FONT_TITLE, bold=True)
        fl = sorted(share)
        hb = 2.6 * U
        cw = w / float(max(1, len(fl)))
        top_ = max(share.values()) or 1.0
        base = oy - 0.7 * U - hb
        for i, f in enumerate(fl):
            hh = hb * share[f] / top_
            B.fill([rect(x + i * cw + 0.08 * cw, base, x + (i + 0.92) * cw, base + hh)],
                   INTENSITY[2] if f == 1 else mix(INTENSITY[2], PAPER, 0.35), O, 20)
            B.fit("{:.0f}%".format(share[f]), x + (i + 0.5) * cw, base + hh + 0.12 * U, 0.3 * U, cw * 0.98, INK, O,
                  align="C")
            B.fit("{}".format(f), x + (i + 0.5) * cw, base - 0.45 * U, 0.3 * U, cw * 0.98, INK2, O, align="C")
        B.line([(x, base), (x + w, base)], INK2, O, 21, 0.05)
        oy = base - 0.9 * U
        B.text("floors" + (" · densest near " + peak if peak else ""), x, oy, 0.3 * U, INK2, O)
        oy -= 1.2 * U
    r = min(2.4 * U, w / 5.0)                             # green and fields as rings of the frame
    rings = [("GREEN", R["green"][0], CAT["green"][1], "{} larger ground{}".format(
        R["green"][1], "" if R["green"][1] == 1 else "s"), "{:.1f}%",
        bcite("Green: the mapped green of the frame, a thin weave anchored by its larger grounds."))]
    if R["green"][2] is not None:
        rings.append(("+ SATELLITE GREEN", R["green"][2], mix(CAT["green"][1], PAPER, 0.3), "unmapped ground too",
                      "{:.0f}%", bcite("With the satellite's tree cover, grass and shrubs on the unmapped ground.")))
    if R.get("agri") is not None:
        rings.append(("FIELDS & ORCHARDS", R["agri"], CAT["agri"][1], "town loosens into its plain", "{:.0f}%",
                      bcite("Fields and orchards (survey, OSM and satellite) of the frame: here the town loosens into "
                            "its plain.")))
    cw = w / float(len(rings))
    for i, (head, pct, col, sub, fmt_, ref) in enumerate(rings):
        cx, cy = x + (i + 0.5) * cw, oy - 0.4 * U - r
        vis_ring(B, cx, cy, r, pct, col, FAINT, O)
        B.text(fmt_.format(pct), cx, cy - 0.2 * U, 0.5 * U, INK, O, font=FONT_TITLE, bold=True, align="C")
        B.fit(head + " " + ref, cx, cy - r - 0.65 * U, 0.3 * U, cw * 0.96, INK, O, font=FONT_TITLE, bold=True, align="C")
        B.fit(sub, cx, cy - r - 1.15 * U, 0.26 * U, cw * 0.96, INK2, O, align="C")
    return oy - 0.4 * U - 2.0 * r - 1.6 * U


# ============================================================ DIAGRAM PANELS
def mini_base(S, B, V, L, water_col=BLUE_L):
    B.fill([V.P(S.F.P)], PAPER, L, 2)
    for w in S.water:
        B.fill(V.Ps([w["P"]] + w.get("H", [])), water_col, L, 8)


def fill_units(B, V, groups, col, L, order):
    """Fill the outlines of many buildings in one colour, a building's courtyards (holes) always in the same hatch."""
    chunk = []
    for loops in groups:
        chunk.extend(loops)
        if len(chunk) >= 400:
            B.fill(V.Ps(chunk), col, L, order)
            chunk = []
    if chunk:
        B.fill(V.Ps(chunk), col, L, order)


def mini_buildings(S, B, V, L, colfn, order=12):
    by_col = {}
    for u in S.bld:
        col = colfn(u)
        if col is not None:
            by_col.setdefault(col, []).append(u["parts"] + (u.get("holes") or []))
    for col, groups in by_col.items():
        fill_units(B, V, groups, col, L, order)


MAIN_ROADS = ("motorway", "trunk", "primary", "secondary", "tertiary")


# ============================================================ PAGE-ONE BLOCKS THAT FILL A GIVEN BAND


# ============================================================ ENVIRONMENT · sun and shade, solar radiation, sound, surface heat
# Methods (all standard and published; checked against pvlib, the reference solar library, during development):
#   sun position   NOAA / Meeus solar position algorithm, refraction included (agrees with pvlib to ~0.01 deg)
#   weather        PVGIS-SARAH2 typical meteorological year 2005-2020 for these coordinates (EU JRC), every hour
#   terrain        PVGIS DEM horizon profiles every 100 m over the frame (bilinear between nodes), as seen from the
#                  ground; in a section plane lowered with height by the fall of the terrain's own horizon (v16.3:
#                  survey terrain inside the frame, PVGIS DEM node heights to the grid's edge, terrain beyond as far)
#   trees          Meta / WRI 1 m canopy height crowns (modelled heights); leaf type per crown (CLC+ Backbone 2021 /
#                  Sentinel-2) and the deciduous leaf-out and leaf-fall days (Sentinel-2 2019-2025); 3 % / 46 %
#                  transmission, olive (evergreen broadleaf) 15 % (v24)
#   shade          exact obstruction by every building and crown and the terrain for every degree of sun azimuth,
#                  every minute of the four key days and of all 365 days (the mean day)
#   radiation      every hour of the typical year: direct + Perez 1990 diffuse (isotropic, horizon band) + ground
#                  reflection on the ground and every roof; mean kWh/m2 per day of each season
#   sound          RLS-90 road emission and segment method (distance, air, ground); building screening RLS-90-type
#                  D_z with ISO 9613-2 limits and sign (v21, R01-26: not VBUS's screening; no D_met, no reflections);
#                  Lden from day / evening / night traffic; optional calibration with your own measurements
#   surface heat   Landsat 8/9 Collection 2 Level-2 surface temperature (USGS), the mean of the clear scenes of
#                  each season
ENV_PATH = clean_path(inp("env_path", None), "env_path") or data_file("bergama_environment.json") or ""
# v33 24 Oct: all files under Downloads/Bergama/ (Aras rule): cache in cached/selinus_cache, the rest in output/selinus_board
BERGAMA_DIR = os.path.join(os.path.expanduser("~"), "Downloads", "Bergama")
SELINUS_CACHE_DIR = os.path.join(BERGAMA_DIR, "cached", "selinus_cache")
SELINUS_OUT_DIR = os.path.join(BERGAMA_DIR, "output", "selinus_board")
ENVIRONMENT = bool(inp("environment", False))
NOISE_PALETTE = str(inp("noise_palette", "") or "").strip().lower()     # "" = the graded bands (v16.4)
NOISE_PTS_IN = inp("noise_points", [])
NOISE_DB_IN = inp("noise_db", [])
FOCUS_IN = inp("focus", None)

SEASONS = [dict(key="spring", name="SPRING", day=(3, 20), months=(3, 4, 5), event="spring equinox, 20 March"),
           dict(key="summer", name="SUMMER", day=(6, 21), months=(6, 7, 8), event="summer solstice, 21 June"),
           dict(key="autumn", name="AUTUMN", day=(9, 22), months=(9, 10, 11), event="autumn equinox, 22 September"),
           dict(key="winter", name="WINTER", day=(12, 21), months=(12, 1, 2), event="winter solstice, 21 December")]
# Deciduous crowns are in leaf from leaf-out (inclusive) to leaf-fall (exclusive), days of the year measured over this
# site: Sentinel-2 L2A NDVI 2019-2025 of the Copernicus CLC+ Backbone 2021 broadleaved deciduous pixels, unmixed from
# their canopy-free surroundings, double-logistic fit over the day of the year, 50 % of the seasonal amplitude:
# leaf-out day 106 (16 April; 95 % interval 102-110), leaf-fall day 318 (14 November; 311-324). Environment data v2
# carries the same values ("phenology") and they are taken from there.
LEAF_DOY = [106, 318]
EVERGREEN = ("pine", "olive")             # needle-leaved and broadleaved evergreen crowns
LEAF_KIND = {0: "tree", 1: "olive", 2: "pine"}     # environment data v2 leaf code: deciduous, evergreen broadleaf, needle


def leaf_on_doy(doy):
    """Deciduous crowns in leaf on these days of the year (1-365)."""
    d = np.asarray(doy)
    return (d >= LEAF_DOY[0]) & (d < LEAF_DOY[1])


def doy_of(mo, d):
    return sum((31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)[:mo - 1]) + d


def leaf_key(season):
    """Deciduous crowns in leaf on a season's key day (None or any other key: in leaf)."""
    for s_ in SEASONS:
        if s_["key"] == season:
            return LEAF_DOY[0] <= doy_of(*s_["day"]) < LEAF_DOY[1]
    return True


def leaf_dates():
    """The leaf-out day and the last day in leaf, as text ("16 April", "13 November")."""
    import datetime as _dt

    def f(k):
        d = _dt.date(2025, 1, 1) + _dt.timedelta(days=k - 1)
        return "{} {}".format(d.day, MONTHS_EN[d.month - 1])
    return f(LEAF_DOY[0]), f(LEAF_DOY[1] - 1)


MONTHS_EN = ("January", "February", "March", "April", "May", "June", "July", "August", "September", "October",
             "November", "December")
ALBEDO = 0.20


def load_env(path):
    """The environment data and a fingerprint of the file's bytes (the cache key of everything computed from it)."""
    if not path:
        return None, None
    try:
        with open(path, "rb") as f:
            raw = f.read()
        return json.loads(raw.decode("utf-8")), _hashlib.sha1(raw).hexdigest()
    except Exception as ex:
        LOG.append("WARNING: environment data could not be read ({}).".format(ex))
        return None, None


# ------------------------------------------------------------ results kept between runs
import hashlib as _hashlib
import pickle as _pickle
import zlib as _zlib_store
# Version of each computation. A change to a method gets a new number, so results computed the old way are never reused.
MV = dict(solids=4, sky=2, shade=4, faces=1, ground=4, noise=6, comfort=5, shelter=3, season=3, core=2, relief=2,
          render=2, blocks=1, sec_geom=6, sec_field=8)     # v24: shade, ground, comfort, sec_field +1 (olive 15 %);
#                                                            v33: comfort +1 (the year's comfortable hours, T8)
_MEMSTORE = {}


def fp(*parts):
    """Fingerprint of everything a result depends on (exact: the full repr of the values)."""
    h = _hashlib.sha1()
    for p in parts:
        h.update(repr(p).encode("utf-8"))
        h.update(b"\x1f")
    return h.hexdigest()


class Store(object):
    """Results this script computed before, kept between bakes: in Rhino's memory for this session, and as files in
    Downloads/Bergama/cached/selinus_cache for later sessions (v33 24 Oct; an old "selinus_cache" next to env_path is still read). An entry is found only by the fingerprint of everything it
    was computed from (drawing, frame, data files, settings, method version), so a change anywhere can never pick up
    an old result. Only plain data is stored (lists, numbers, arrays), never live objects."""

    KEEP_IN_MEMORY = 6                                       # recent entries per kind; older ones stay on disk

    def __init__(self):
        mem = _MEMSTORE
        if HAVE_RHINO:
            mem = sc.sticky.get("selinus_store")
            if mem is None:
                mem = sc.sticky["selinus_store"] = {}
        self.mem = mem
        self.order = mem.setdefault("__order__", {})
        base = os.path.dirname(ENV_PATH) if ENV_PATH else ""
        self.dir = SELINUS_CACHE_DIR                         # v33 24 Oct (Aras rule); was beside env_path
        self.old_dir = os.path.join(base, "selinus_cache") if base else None   # old place: read only, as a fallback
        self.hits_mem, self.hits_disk, self.made = [], [], []
        self._made_keys = set()
        self._pruned = False

    def _path(self, kind, key):
        return os.path.join(self.dir, "%s_%s.bin" % (kind, key[:40]))

    def _remember(self, kind, k, val):
        self.mem[k] = val
        lst = self.order.setdefault(kind, [])
        if k in lst:
            lst.remove(k)
        lst.append(k)
        while len(lst) > self.KEEP_IN_MEMORY:
            self.mem.pop(lst.pop(0), None)

    def get(self, kind, key):
        k = kind + ":" + key
        v = self.mem.get(k)
        if v is not None:
            self.hits_mem.append(kind)
            return v
        if self.dir:
            p = self._path(kind, key)
            if not os.path.exists(p) and self.old_dir:
                p = os.path.join(self.old_dir, os.path.basename(p))
            try:
                if os.path.exists(p):
                    with open(p, "rb") as f:
                        stored_key, v = _pickle.loads(_zlib_store.decompress(f.read()))
                    if stored_key == key:
                        try:
                            os.utime(p, None)
                        except Exception:
                            pass
                        self._remember(kind, k, v)
                        (self.hits_mem if k in self._made_keys else self.hits_disk).append(kind)
                        return v
            except Exception:
                pass
        return None

    def has(self, kind, key):
        """v18: whether get would find it (without loading it or counting it as reused)."""
        k = kind + ":" + key
        if self.mem.get(k) is not None:
            return True
        return bool(self.dir) and (os.path.exists(self._path(kind, key)) or bool(self.old_dir) and
                                   os.path.exists(os.path.join(self.old_dir, os.path.basename(self._path(kind, key)))))

    def put(self, kind, key, val, disk=True):
        self._remember(kind, kind + ":" + key, val)
        self._made_keys.add(kind + ":" + key)
        self.made.append(kind)
        if disk and self.dir:
            try:
                if not os.path.isdir(self.dir):
                    os.makedirs(self.dir)
                self.prune()
                p = self._path(kind, key)
                tmp = p + ".part"
                with open(tmp, "wb") as f:
                    f.write(_zlib_store.compress(_pickle.dumps((key, val), protocol=4), 1))
                os.replace(tmp, p)
            except Exception:
                pass
        return val

    def prune(self, max_age_days=45.0, max_bytes=3e9):
        """Keep the cache folder bounded: files unused for 45 days go, then the oldest beyond 3 GB."""
        if self._pruned or not self.dir or not os.path.isdir(self.dir):
            return
        self._pruned = True
        try:
            import time as _t
            now = _t.time()
            files = []
            for nm in os.listdir(self.dir):
                if not (nm.endswith(".bin") or nm.endswith(".part")):
                    continue
                p = os.path.join(self.dir, nm)
                st = os.stat(p)
                files.append((st.st_mtime, st.st_size, p))
            files.sort()
            total = sum(f[1] for f in files)
            for mt, size, p in files:
                if now - mt > max_age_days * 86400.0 or total > max_bytes:
                    os.remove(p)
                    total -= size
        except Exception:
            pass

    def summary(self):
        def cnt(lst):
            d = {}
            for k in lst:
                d[k] = d.get(k, 0) + 1
            return ", ".join("%s %d" % kv if kv[1] > 1 else kv[0] for kv in sorted(d.items()))
        parts = []
        if self.hits_mem:
            parts.append("reused from this session: " + cnt(self.hits_mem))
        if self.hits_disk:
            parts.append("reused from earlier sessions: " + cnt(self.hits_disk))
        if self.made:
            parts.append("computed now: " + cnt(self.made))
        return "; ".join(parts)


def site_prints(S):
    """Fingerprints of what the analyses read from the site; computed once per bake."""
    p = getattr(S, "prints", None)
    if p:
        return p
    p = dict(
        bld=fp([(u["parts"], u["floors"], u["cat"], u["annex"], u["h"]) for u in S.bld]),
        terrain=getattr(S, "terrain_fp", None),
        zones=fp([(z["kind"], z["sub"], z["Ps"], z["Hs"]) for z in S.zones]),
        trees=fp(S.trees[:getattr(S, "n_trees_surveyed", len(S.trees))]),
        frame=fp(S.F.P),
        roads=fp([(r["P"], sorted(r["tags"].items()), r.get("w")) for r in S.roads]),
        water=fp([(w["P"], w.get("H", [])) for w in S.water]),
        stream=fp(getattr(S, "selinus", [])))
    S.prints = p
    return p


def solids_portable(solids, S):
    """Buildings and crowns as plain data (the link to the survey unit kept as its index)."""
    bl, gB, trees = solids
    uidx = dict((id(u), i) for i, u in enumerate(S.bld))
    pb = []
    for b in bl:
        d = dict((k, v) for k, v in b.items() if k != "u")
        d["ui"] = uidx.get(id(b.get("u")), -1)
        pb.append(d)
    return (pb, [dict(t) for t in trees])


def solids_live(port, S):
    pb, trees = port
    bl = []
    for d in pb:
        b = dict(d)
        ui = b.get("ui", -1)
        b["u"] = S.bld[ui] if 0 <= ui < len(S.bld) else None
        bl.append(b)
    g = Grid(25.0)
    for b in bl:
        g.add(b, b["bb"])
    return bl, g, [dict(t) for t in trees]


def lst_seasons(E):
    """Surface temperature per season: the multi-scene means of environment data v2, else v1's single scenes."""
    return E.get("lst_seasons") or E.get("lst", {})


def grid_geom(r):
    """The geometry of an analysis grid, kept with its results (cells, frame, open cells, cell centres)."""
    nx, ny, cell = r["nx"], r["ny"], r["cell"]
    F = Frame(r["frame"])
    u = F.u0 + (np.arange(nx) + 0.5) * cell
    v = F.v0 + (np.arange(ny) + 0.5) * cell
    UU, VV = np.meshgrid(u, v)
    xx, yy = f_world(F, UU.ravel(), VV.ravel())
    return dict(nx=nx, ny=ny, cell=cell, frame=r["frame"], open=r["open"], z=r["z"], xx=xx, yy=yy)


def run_environment(S):
    """The environment analyses, each taken from the store when its inputs are unchanged, otherwise computed and
    stored: buildings and crowns; shade, wind and temperature on the frame (one pass over the sun's positions);
    solar radiation on the focus area; sound."""
    import time as _t
    E, E_fp = load_env(ENV_PATH)
    if E is None:
        LOG.append("WARNING: environment analyses need the data file bergama_environment.json in env_path.")
        S.env = None
        return
    ph = E.get("phenology") or {}
    if ph.get("leaf_on_doy") and ph.get("leaf_off_doy"):
        LEAF_DOY[:] = [int(ph["leaf_on_doy"]), int(ph["leaf_off_doy"])]
    ST = Store()
    S.store = ST
    pr = site_prints(S)
    t0 = _t.time()
    keys = {}
    keys["solids"] = fp("solids", MV["solids"], pr["bld"], pr["terrain"], pr["zones"], pr["trees"], pr["frame"], E_fp)
    port = ST.get("solids", keys["solids"])
    if port is None:
        port = ST.put("solids", keys["solids"], solids_portable(env_solids(S, E), S))
    solids = solids_live(port, S)
    env = dict(E=E, E_fp=E_fp, solids=solids, lst=lst_seasons(E), keys=keys, memo={},
               bindex=dict((id(b), i) for i, b in enumerate(solids[0])), shade=None, comfort=None, rad=None)
    S.env = env
    log = []
    if not HAVE_NP:
        LOG.append("WARNING: the technical analyses need numpy. The line '# r: numpy' at the top of the script makes "
                   "Rhino 8 install it on the first run (internet needed once); then press the button again.")
        S.env = None
        return
    TT = tmy_table(E)
    env["TT"] = TT
    keys["shade"] = fp("shade16", MV["shade"], keys["solids"], SHADE_CELL, SUN_BINS)
    keys["comfort"] = fp("comfort16", MV["comfort"], MV["shelter"], keys["solids"], COMFORT_CELL, SUN_BINS, SKY_BINS,
                         WIND_BINS, hours_window())
    # v17: the sound map starts first, on the worker processes, and runs while Rhino computes shade, comfort and
    # solar radiation on its own threads (the analyses do not depend on each other); it is collected below.
    t_s0 = _t.time()
    keys["noise_raw"] = fp("noise", MV["noise"], keys["solids"], pr["roads"], pr["terrain"], pr["frame"], 10.0,
                           traffic_key(S))
    raw_nm = ST.get("noise", keys["noise_raw"])
    nm_job = noise_map_start(S, solids, cell=10.0, model=noise_model(S)) if raw_nm is None else None
    t_s = _t.time() - t_s0
    sh = ST.get("shade", keys["shade"])
    cf = ST.get("comfort", keys["comfort"]) if TT["full"] else None
    # v16.6: the shade (1 m) and the comfort analyses (2 m) on grids of their own (v16.5: both on one 3 m grid)
    for cell_, want_sh, want_cf in ((SHADE_CELL, sh is None, False), (COMFORT_CELL, False, TT["full"] and cf is None)):
        if want_sh or want_cf:
            r = env16_frame(S, E, solids, S.F, cell_, want_sh, want_cf, log)
            geo = dict(nx=r["nx"], ny=r["ny"], cell=r["cell"], frame=r["frame"], open=r["open"], z=r["z"])
            if want_sh:
                sh = ST.put("shade", keys["shade"], dict(r["shade"], geo=geo))
            if want_cf:
                cf = ST.put("comfort", keys["comfort"], dict(r["comfort"], geo=geo))
            r = None
    env["shade"] = dict(sh, grid=grid_geom(sh["geo"]))
    if cf is not None:
        env["comfort"] = dict(cf, grid=grid_geom(cf["geo"]))
    else:
        LOG.append("WARNING: wind, air and felt temperature need the hourly weather of the typical year (humidity, wind, "
                   "long-wave radiation): environment data version 2. This file has only sun and air temperature, so "
                   "T5-T7 and their sections are skipped.")
    focus = getattr(S, "focus_frame", None) or S.F       # v16.5: the whole frame (v16.4: the densest 420 x 210 m stretch)
    env["focus"] = focus
    keys["focus"] = fp(focus.P)
    keys["rad"] = fp("rad16", MV["ground"], keys["solids"], keys["focus"], 1.5, SUN_BINS, SKY_BINS)
    rd = ST.get("rad", keys["rad"])
    if rd is None:
        rd = ST.put("rad", keys["rad"], env16_focus(S, E, solids, focus, 1.5, log))
    env["rad"] = rd
    t1 = _t.time() - t_s
    if raw_nm is None:
        raw_nm = ST.put("noise", keys["noise_raw"], noise_map_collect(nm_job))
    nm = dict(raw_nm, grid=[[(dict(c) if c else c) for c in row] for row in raw_nm["grid"]])
    dbs = NOISE_DB_PAIRED[:len(NOISE_PTS_SURVEY)]
    off, n = calibrate_noise(S, nm, NOISE_PTS_SURVEY, dbs)
    nm["offset"], nm["n_meas"] = off, n
    keys["noise"] = fp(keys["noise_raw"], NOISE_PTS_SURVEY, dbs)
    env["noise"] = nm
    t2 = _t.time()
    parts = ["{} {:.0f} s".format(nm_, sec) for nm_, n_, sec in log if nm_ in ("sky", "shelter", "sun pass", "dark hours",
                                                                                "focus sky", "focus total", "frame total")]
    try:
        n_all_ = max(1, int(os.cpu_count() or 1))
    except Exception:
        n_all_ = 1
    LOG.append("Cores used: {} of {} (Rhino's threads for shade, comfort and solar; the sound model on worker "
               "processes{}).".format(n_cores(), n_all_, "" if _NOISE_PY.get("py", 1) else ": not available, " +
                                      _NOISE_PY.get("why", "")))
    LOG.append("Environment analyses: {}; {} tree crowns.".format(                 # v27: no step timings
        "computed" if parts else "all reused from the cache", len(solids[2])))


def noise_model(S):
    """The sound model of this bake (road pieces, building grid), shared by the map and every sound section."""
    m = S.env.get("noise_model")
    if m is None:
        m = S.env["noise_model"] = NoiseModel(S, S.env["solids"])
    return m


# ------------------------------------------------------------ sun
def sun_position(y, mo, d, hour_utc, lat, lon):
    """NOAA solar position (Meeus). Returns azimuth (deg from true north, clockwise), apparent elevation (deg)."""
    yy, mm = (y - 1, mo + 12) if mo <= 2 else (y, mo)
    A_ = yy // 100
    jd = int(365.25 * (yy + 4716)) + int(30.6001 * (mm + 1)) + d + (2 - A_ + A_ // 4) - 1524.5 + hour_utc / 24.0
    T = (jd - 2451545.0) / 36525.0
    L0 = (280.46646 + T * (36000.76983 + 0.0003032 * T)) % 360.0
    M = math.radians(357.52911 + T * (35999.05029 - 0.0001537 * T))
    e = 0.016708634 - T * (0.000042037 + 0.0000001267 * T)
    Cc = (math.sin(M) * (1.914602 - T * (0.004817 + 0.000014 * T)) + math.sin(2 * M) * (0.019993 - 0.000101 * T)
          + math.sin(3 * M) * 0.000289)
    om = math.radians(125.04 - 1934.136 * T)
    lam = math.radians(L0 + Cc - 0.00569 - 0.00478 * math.sin(om))
    eps = math.radians(23.0 + (26.0 + (21.448 - T * (46.815 + T * (0.00059 - T * 0.001813))) / 60.0) / 60.0
                       + 0.00256 * math.cos(om))
    dec = math.asin(math.sin(eps) * math.sin(lam))
    yv = math.tan(eps / 2.0) ** 2
    L0r = math.radians(L0)
    eqt = 4.0 * math.degrees(yv * math.sin(2 * L0r) - 2 * e * math.sin(M) + 4 * e * yv * math.sin(M) * math.cos(2 * L0r)
                             - 0.5 * yv * yv * math.sin(4 * L0r) - 1.25 * e * e * math.sin(2 * M))
    ha = math.radians(((hour_utc * 60.0 + eqt + 4.0 * lon) % 1440.0) / 4.0 - 180.0)
    lr = math.radians(lat)
    cz = math.sin(lr) * math.sin(dec) + math.cos(lr) * math.cos(dec) * math.cos(ha)
    zen = math.acos(max(-1.0, min(1.0, cz)))
    el = 90.0 - math.degrees(zen)
    if el > 85.0:
        r = 0.0
    elif el > 5.0:
        te = math.tan(math.radians(el))
        r = 58.1 / te - 0.07 / te ** 3 + 0.000086 / te ** 5
    elif el > -0.575:
        r = 1735.0 + el * (-518.2 + el * (103.4 + el * (-12.79 + el * 0.711)))
    else:
        r = -20.774 / math.tan(math.radians(el))     # v21: NOAA (R04-02)
    sz = math.sin(zen)
    if sz < 1e-9:
        az = 180.0
    else:
        a = math.degrees(math.acos(max(-1.0, min(1.0, (math.sin(lr) * cz - math.sin(dec)) / (math.cos(lr) * sz)))))
        az = (a + 180.0) % 360.0 if ha > 0 else (540.0 - a) % 360.0
    return az, el + r / 3600.0


def dni_extra(doy):
    b = 2.0 * math.pi * (doy - 1) / 365.0                   # v21: Spencer, day 0 = 1 January (R04-16)
    return 1366.1 * (1.00011 + 0.034221 * math.cos(b) + 0.00128 * math.sin(b) + 0.000719 * math.cos(2 * b)
                     + 0.000077 * math.sin(2 * b))


def airmass_ky(zen_deg):
    if zen_deg >= 90.0:
        return None
    return 1.0 / (math.cos(math.radians(zen_deg)) + 0.50572 * (96.07995 - zen_deg) ** -1.6364)


PEREZ_F1 = [(-0.008, 0.588, -0.062), (0.13, 0.683, -0.151), (0.33, 0.487, -0.221), (0.568, 0.187, -0.295),
            (0.873, -0.392, -0.362), (1.132, -1.237, -0.412), (1.06, -1.6, -0.359), (0.678, -0.327, -0.25)]
PEREZ_F2 = [(-0.06, 0.072, -0.022), (-0.019, 0.066, -0.029), (0.055, -0.064, -0.026), (0.109, -0.152, -0.014),
            (0.226, -0.462, 0.001), (0.288, -0.823, 0.056), (0.264, -1.127, 0.131), (0.156, -1.377, 0.251)]
PEREZ_EPS = (1.065, 1.23, 1.5, 1.95, 2.8, 4.5, 6.2)


def perez_f(dhi, dni, zen_deg, doy):
    """Perez et al. 1990 circumsolar (F1) and horizon (F2) brightness coefficients."""
    am = airmass_ky(zen_deg)
    if dhi <= 0.0 or am is None:
        return 0.0, 0.0
    z = math.radians(zen_deg)
    k = 1.041 * z ** 3
    eps = ((dhi + dni) / dhi + k) / (1.0 + k)
    delta = dhi * am / dni_extra(doy)
    b = sum(1 for t in PEREZ_EPS if eps >= t)
    c1, c2 = PEREZ_F1[b], PEREZ_F2[b]
    return max(0.0, c1[0] + c1[1] * delta + c1[2] * z), c2[0] + c2[1] * delta + c2[2] * z


class Compass(object):
    """True north and east as unit vectors in survey coordinates (meridian convergence and survey rotation)."""

    def __init__(self, lon, lat):
        a, b = to_dwg(lon, lat), to_dwg(lon, lat + 0.002)
        L_ = math.hypot(b[0] - a[0], b[1] - a[1])
        self.N = ((b[0] - a[0]) / L_, (b[1] - a[1]) / L_)
        self.E = (self.N[1], -self.N[0])

    def vec(self, az):
        r = math.radians(az)
        return (math.sin(r) * self.E[0] + math.cos(r) * self.N[0], math.sin(r) * self.E[1] + math.cos(r) * self.N[1])

    def az(self, dx, dy):
        return math.degrees(math.atan2(dx * self.E[0] + dy * self.E[1], dx * self.N[0] + dy * self.N[1])) % 360.0


class Horizons(object):
    """Terrain horizon (DEM) profiles; each point of the site uses the nearest profile."""

    def __init__(self, hz):
        self.P = [(h["x"], h["y"]) for h in hz]
        self.H = [h["h"] for h in hz]
        self.step = hz[0]["step"] if hz else 7.5

    def nearest(self, x, y):
        if not self.P:
            return None
        d = [(p[0] - x) ** 2 + (p[1] - y) ** 2 for p in self.P]    # same distances, first minimum as before
        return min(range(len(d)), key=d.__getitem__)

    def h(self, i, az):
        if i is None:
            return 0.0
        prof = self.H[i]
        f = (az % 360.0) / self.step
        k = int(f) % len(prof)
        t = f - int(f)
        return prof[k] * (1 - t) + prof[(k + 1) % len(prof)] * t


def env_solids(S, E=None):
    """Surveyed buildings as prisms (their height u["h"] on terrain: floors x storey height, or a published height)
    and trees as 3D crowns measured on the 1 m canopy height map (a surveyed tree symbol carries no size, so it
    is not modelled). Leaf type: measured per crown in environment data v2 (CLC+ Backbone 2021 / Sentinel-2),
    else from the survey's land-use zones (wood: needle-leaved, orchard: evergreen broadleaf, else deciduous)."""
    bl = []
    for u in S.bld:
        H = u["h"]
        if H <= 0.0:
            continue
        holes = u.get("holes") or []
        for P in u["parts"]:
            a, cx, cy = shoelace(P)
            if abs(a) < 2.0:
                continue
            Q = ccw(P)                                                # counter-clockwise
            hs = [list(reversed(ccw(h))) for h in holes if pip(interior_point(h)[0], interior_point(h)[1], Q)]
            base = S.z_at(cx, cy)
            bl.append(dict(P=Q, H=H, base=base, top=base + H, bb=bb_pts(Q), cx=cx, cy=cy, u=u, holes=hs))
    g = Grid(25.0)
    for b in bl:
        g.add(b, b["bb"])
    woods = [z for z in S.zones if (z["kind"] == "green" and z["sub"] in ("wood", "forest")) or z["sub"] == "forest"]
    orch = [z for z in S.zones if z["kind"] == "agri" and z["sub"] == "orchard"]

    def leaf_kind(x, y):
        for zs, kind in ((woods, "pine"), (orch, "olive")):
            for z in zs:
                if bb_hit(z["bb"], (x, y, x, y)) and any(pip(x, y, P) for P in z["Ps"]):
                    return kind
        return "tree"
    fb = S.F.bb
    fbx = (fb[0] - 80, fb[1] - 80, fb[2] + 80, fb[3] + 80)
    trees = []
    gT = Grid(10.0)
    for row in (E or {}).get("trees", []):
        x, y, r, h = row[:4]
        if not (fbx[0] <= x <= fbx[2] and fbx[1] <= y <= fbx[3]) or h < 3.0:
            continue
        uu, vv = S.F.local(x, y)
        if not (S.F.u0 - 60 <= uu <= S.F.u1 + 60 and S.F.v0 - 60 <= vv <= S.F.v1 + 60):
            continue
        if any(pip(x, y, b["P"]) for b in g.query((x, y, x, y))):
            continue                                                  # a crown on a roof is a misreading
        if len(row) > 5:
            kind, lsrc = LEAF_KIND.get(int(row[4]), "tree"), int(row[5])
        else:
            kind, lsrc = leaf_kind(x, y), 0
        t = dict(x=x, y=y, r=r, lo=max(1.5, 0.35 * h), hi=h, kind=kind, leaf_src=lsrc, base=S.z_at(x, y), src="canopy map")
        trees.append(t)
        gT.add(t, (x, y, x, y))
    return bl, g, trees


def convex_parts(P):
    """Split a footprint into convex pieces (ear clipping, merged greedily) so shadows stay exact."""
    a, _, _ = shoelace(P)
    if abs(convex_hull(P) and shoelace(convex_hull(P))[0]) <= abs(a) * 1.03:
        return [P]
    V = list(P)
    tris = []
    guard = 0
    while len(V) > 3 and guard < 500:
        guard += 1
        n = len(V)
        for i in range(n):
            p0, p1, p2 = V[i - 1], V[i], V[(i + 1) % n]
            if (p1[0] - p0[0]) * (p2[1] - p0[1]) - (p1[1] - p0[1]) * (p2[0] - p0[0]) <= 0:
                continue
            if any(pip(q[0], q[1], [p0, p1, p2]) for q in V if q not in (p0, p1, p2)):
                continue
            tris.append([p0, p1, p2])
            del V[i]
            break
        else:
            break
    if len(V) == 3:
        tris.append(V)
    return tris or [P]


# ------------------------------------------------------------ shade: hours in shade on the season's key day
def raster_rows(L_, F, cell, nx, ny):
    """Scanline a convex polygon given in frame-local coordinates: [(row, first cell, end cell)]."""
    n = len(L_)
    if n < 3:
        return []
    u0, v0 = F.u0, F.v0
    ys = [p[1] for p in L_]
    ymin, ymax = min(ys), max(ys)
    j0 = max(0, int(math.ceil((ymin - v0) / cell - 0.5)))
    j1 = min(ny - 1, int(math.floor((ymax - v0) / cell - 0.5)))
    if j1 < j0:
        return []
    edges = []
    for k in range(n):
        (x0, y0), (x1, y1) = L_[k], L_[(k + 1) % n]
        if y0 != y1:
            if y0 > y1:
                x0, y0, x1, y1 = x1, y1, x0, y0
            edges.append((y0, y1, x0, (x1 - x0) / (y1 - y0)))
    out = []
    ceil, floor = math.ceil, math.floor
    for j in range(j0, j1 + 1):
        yc = v0 + (j + 0.5) * cell
        lo = hi = None
        for y0, y1, x0, sl in edges:
            if y0 <= yc < y1:
                x = x0 + (yc - y0) * sl
                if lo is None or x < lo:
                    lo = x
                if hi is None or x > hi:
                    hi = x
        if lo is not None:
            a0 = max(0, int(ceil((lo - u0) / cell - 0.5)))
            a1 = min(nx, int(floor((hi - u0) / cell - 0.5)) + 1)
            if a1 > a0:
                out.append((j, a0, a1))
    return out


# ------------------------------------------------------------ sound: RLS-90 emission and segment method, VBUS period shares, Lden
# v16.3: EVERY street carries traffic. Where KGM (General Directorate of Highways) counted a road, its count is used as
# before; every other street takes a correlated estimate, labelled as such on every sheet:
#   1. the default flow of its street type from the European Commission's noise-mapping guidance: WG-AEN "Good Practice
#      Guide for Strategic Noise Mapping and the Production of Associated Data on Noise Exposure", version 2 (13 January
#      2006), Toolkit 2, Tool 2.5 (default flows by road type), with the OSM street types mapped to its road categories as
#      the open-source NoiseModelling software (Universite Gustave Eiffel / Cerema; Import_OSM.groovy, class Road,
#      release 4.0.5) does it: GPG_FLOWS below;
#   2. the correlation the KGM counts give for that street type here: factor k = counted AADT / GPG default daily flow
#      of the counted road's own type, taken from the nearest counted road of the SAME street type (a street type
#      with no count in reach keeps k = 1, the plain GPG default, and says so);
#   3. flow = k x the GPG default in each period (day 12 h, evening 4 h, night 8 h); the heavy share is the counted
#      road's KGM printed truck share (p_kgm, daily) where a count of the same type exists, else the GPG default share
#      of each period. (v22: the counted roads themselves use p over 3.5 t; the correlated streets keep p_kgm, so the
#      group's estimate for the streets without a count is unchanged.)
# A one-way OSM way (a dual carriageway is mapped as two of them) carries half the two-way flow, as NoiseModelling does.
# k in dB: 10 lg k (k = 1.54 is +1.9 dB on the GPG default). Nothing here is measured on the street itself: the sheets
# list every street type with its k, its source count and its km in the frame.
# The counts (two-way AADT, vehicles/day). p = the RLS-90 / VBUS heavy share (VBUS Table 1: Lkw over 3.5 t
# permissible gross weight) from KGM's class columns of the same row: OYTT + bus + truck + articulated over the total
# (v22, Aras's choice; R01-02; OYTT, about 3.5-10 t trucks and 14-25-seat buses, counted as heavy is an assumption).
# p_kgm = KGM's own printed heavy share, trucks and articulated trucks only (KGM 2022, pp. 3 and 9), kept for the
# correlated streets. Class counts car / OYTT / bus / truck / articulated:
#   35-04 section 1  KGM 2023 provincial roads, "KINIK (240-01) D.Y.AYR. (BERGAMA) - KOZAK", 21 km, OTSS1: 3,087,
#                    2,548 / 273 / 8 / 149 / 109 -> p 17.46 %, p_kgm 8 %  (project copy il23.txt line 2666)
#   35-05 section 3  KGM 2023 provincial roads, "GOCBEYLI (35-07) IL Y.AYR. - (BERGAMA-KINIK)(240-01) D.Y.AYR.", 5 km,
#                    OTSS1: 4,069, 3,445 / 363 / 1 / 217 / 43 -> p 15.34 %, p_kgm 6 %  (il23.txt line 2674)
#   240-01 section 1 KGM 2024 state roads (2. Bolge, Izmir), 8 km, OTSS1: 22,053,
#                    17,462 / 1,914 / 283 / 1,053 / 1,341 -> p 20.82 %, p_kgm 11 %  (KGM 2024 Bolge2.pdf map box)
#   240-01 section 2 KGM 2024 state roads (2. Bolge, Izmir), 2 km, OTSS1: 14,490,
#                    11,363 / 1,168 / 50 / 638 / 1,271 -> p 21.58 %, p_kgm 13 %  (same map)
#   240-01 section 3 KGM 2024 state roads (2. Bolge, Izmir), 16 km, OTSS3: 13,683,
#                    10,756 / 816 / 59 / 628 / 1,424 -> p 21.39 %, p_kgm 15 %  (same map)
# Which OSM way is which 240-01 section (KGM's report text gives no section ends; worked out from its own figures):
#   * KGM's section map shows section 1 as 3 + 5 km from the D550 (550-08) junction west of Bergama, section 2 (2 km)
#     ending where 35-05 joins ("(BERGAMA-KINIK)(240-01) D.Y.AYR.", KGM 2023), section 3 (16 km) on to Kinik.
#   * OSM: 35-05 starts at the roundabout where "Bergama Cevre Yolu" (the ring road, 6.85 km from the west end of the
#     extract) ends and "Akhisar - Bergama Yolu" begins, so Akhisar - Bergama Yolu is SECTION 3. On the ring road an
#     interchange (links to the town) lies 2.1-2.6 km before that roundabout and 4.2-4.8 km from the extract's west end,
#     about 3 km short of the D550 junction: the 3 + 5 / 2 km split; the ring road is cut there (KGM_SPLIT) into
#     section 1 (west) and section 2 (east).
#   * KGM's own speeds rule out the parallel route through the town (Ataturk and Adnan Menderes Bulvari, OSM primary,
#     50-70 km/h): cars on sections 1 and 2 average 67 km/h, 85th percentile 82 and 80 km/h, with 1 % and 4 % over the
#     limit; the OSM ring road is signed 110 km/h.
COUNTED = {
    "35-04": [dict(aadt=3087.0, p=100.0 * 539 / 3087, p_kgm=8.0,
                   src="KGM 2023, 35-04 section 1: 3,087 veh/day, 17.5 % over 3.5 t (KGM trucks + articulated 8 %) (OTSS1)")],
    "35-05": [dict(aadt=4069.0, p=100.0 * 624 / 4069, p_kgm=6.0,
                   src="KGM 2023, 35-05 section 3: 4,069 veh/day, 15.3 % over 3.5 t (KGM trucks + articulated 6 %) (OTSS1)")],
    "D240": [dict(aadt=22053.0, p=100.0 * 4591 / 22053, p_kgm=11.0, name="Bergama Çevre Yolu", section="1",
                  src="KGM 2024, 240-01 section 1: 22,053 veh/day, 20.8 % over 3.5 t (KGM trucks + articulated 11 %) (OTSS1)"),
             dict(aadt=14490.0, p=100.0 * 3127 / 14490, p_kgm=13.0, name="Bergama Çevre Yolu", section="2",
                  src="KGM 2024, 240-01 section 2: 14,490 veh/day, 21.6 % over 3.5 t (KGM trucks + articulated 13 %) (OTSS1)"),
             dict(aadt=13683.0, p=100.0 * 2927 / 13683, p_kgm=15.0, name="Akhisar - Bergama Yolu",
                  src="KGM 2024, 240-01 section 3: 13,683 veh/day, 21.4 % over 3.5 t (KGM trucks + articulated 15 %) (OTSS3)")],
}
# The ring road's cut between 240-01 sections 1 and 2: the interchange's two ramp nodes on the eastbound carriageway
# (OSM nodes at 27.1956573 E 39.0986022 N and 27.2004928 E 39.1020103 N; the cut is the line through their midpoint,
# square to the road between them). Section 1 lies on the west side of it, section 2 on the east.
KGM_SPLIT = {"Bergama Çevre Yolu": ((27.1956573, 39.0986022), (27.2004928, 39.1020103), "1", "2")}


def kgm_split(P, tags):
    """A road of KGM_SPLIT cut at its section boundary: [(points, tags with "_kgm_section")]; other roads unchanged."""
    sp = KGM_SPLIT.get(tags.get("name") or "")
    if not sp or len(P) < 2:
        return [(P, tags)]
    a, b = to_dwg(*sp[0]), to_dwg(*sp[1])
    if not a or not b:
        return [(P, tags)]
    mx, my = (a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0
    tx, ty = b[0] - a[0], b[1] - a[1]
    side = [(p[0] - mx) * tx + (p[1] - my) * ty >= 0.0 for p in P]
    out, run = [], [P[0]]
    for i in range(1, len(P)):
        if side[i] != side[i - 1]:
            p0, p1 = P[i - 1], P[i]
            d0 = (p0[0] - mx) * tx + (p0[1] - my) * ty
            d1 = (p1[0] - mx) * tx + (p1[1] - my) * ty
            f = d0 / (d0 - d1)
            q = (p0[0] + (p1[0] - p0[0]) * f, p0[1] + (p1[1] - p0[1]) * f)
            out.append((run + [q], side[i - 1]))
            run = [q]
        run.append(P[i])
    out.append((run, side[-1]))
    return [(r, dict(tags, _kgm_section=sp[3] if east else sp[2])) for r, east in out if len(r) >= 2]
# GPG v2 Tool 2.5 default flows by road category, as NoiseModelling 4.0.5 sets them (vehicles in the period, two-way):
#   category        0 motorway  1 trunk  2 primary  3 secondary  4 tertiary/unclassified  5 residential  6 service/living
GPG_D = (26103.0, 17936.0, 7124.0, 1400.0, 700.0, 350.0, 175.0)       # day, 12 h
