GPG_N = (3729.0, 2152.0, 712.0, 200.0, 100.0, 50.0, 25.0)              # night, 8 h
GPG_HV = ((0.25, 0.35, 0.45), (0.2, 0.2, 0.2), (0.2, 0.15, 0.1), (0.15, 0.10, 0.05), (0.10, 0.06, 0.03),
          (0.05, 0.02, 0.01), (0.02, 0.01, 0.0))                        # heavy share day, evening, night
GPG_CAT = {"motorway": 0, "motorway_link": 0, "trunk": 1, "trunk_link": 1, "primary": 2, "primary_link": 2,
           "secondary": 3, "secondary_link": 3, "tertiary": 4, "tertiary_link": 4, "unclassified": 4,
           "residential": 5, "service": 6, "living_street": 6}
GPG_NAMES = ("motorway", "trunk road", "primary road", "secondary road", "tertiary / unclassified street",
             "residential street", "service road / living street")
GPG_SRC = ("WG-AEN Good Practice Guide v2 (2006), Toolkit 2 Tool 2.5 default flows, OSM types mapped as NoiseModelling "
           "4.0.5 (Import_OSM.groovy)")
URBAN_LIMIT = 50.0      # km/h: legal limit inside settlements (Karayollari Trafik Yonetmeligi art. 100) unless signed
# Hourly share of the daily traffic per period for a COUNTED road: VBUS Table 2, row 3 (provincial roads): day 0.062,
# evening 0.042, night 0.008 x AADT; KGM publishes no hourly counts. Heavy share: the counted daily share in every period.
PERIODS = (("day", 12.0, 0.062, 1.0, 0.0), ("evening", 4.0, 0.042, 1.0, 5.0), ("night", 8.0, 0.008, 1.0, 10.0))


def road_count(tags):
    """The official count of a road from its OSM ref (and name where KGM counts one ref in sections), or None."""
    for k_ in (tags.get("ref") or "").replace(" ", "").split(";"):
        lst = COUNTED.get(k_)
        if not lst:
            continue
        if len(lst) == 1:
            return lst[0]
        nm = tags.get("name") or ""
        sec = tags.get("_kgm_section")
        for c_ in lst:
            if c_.get("name") == nm and c_.get("section") in (None, sec):
                return c_
        return lst[0]
    return None


def is_oneway(tags):
    return (tags.get("oneway") or "").lower() in ("yes", "1", "true", "-1")


def traffic_plan(S):
    """Traffic of every street that carries any (v16.3), once per bake: per road of S.roads_noise its hourly flows
    (day, evening, night), heavy shares, how they were found ("counted", "correlated" or "default"), k and source."""
    tp = getattr(S, "_traffic", None)
    if tp is not None:
        return tp
    roads = getattr(S, "roads_noise", [])
    counted = []                                          # (category, k, p, src, points) of every counted road
    for r in roads:
        c_ = road_count(r["tags"])
        cat = GPG_CAT.get(r["tags"].get("highway"))
        if c_ is not None and cat is not None:
            k = c_["aadt"] / (GPG_D[cat] + GPG_E[cat] + GPG_N[cat])
            counted.append((cat, k, c_["p_kgm"], c_["src"], r["P"][::max(1, len(r["P"]) // 40)]))   # v22: p_kgm
    plan = []
    for r in roads:
        tags = r["tags"]
        cat = GPG_CAT.get(tags.get("highway"))
        if cat is None:
            plan.append(None)
            continue
        half = 0.5 if is_oneway(tags) else 1.0
        c_ = road_count(tags)
        if c_ is not None:
            M = tuple(c_["aadt"] * share * half for name, hrs, share, pf, pen in PERIODS)
            plan.append(dict(kind="counted", M=M, p=(c_["p"],) * 3, k=None, cat=cat, src=c_["src"]))
            continue
        mx, my = r["P"][len(r["P"]) // 2]
        best = None
        for (cc, k, p, src, pts) in counted:
            if cc != cat:
                continue
            d = min(math.hypot(px - mx, py - my) for px, py in pts)
            if best is None or d < best[0]:
                best = (d, k, p, src)
        if best is not None:
            k, p = best[1], (best[2],) * 3
            kind, src = "correlated", best[3] + "; heavy share kept at KGM's {:.0f} %".format(best[2])
        else:
            k, p = 1.0, tuple(100.0 * v for v in GPG_HV[cat])
            kind, src = "default", None
        M = (k * GPG_D[cat] / 12.0 * half, k * GPG_E[cat] / 4.0 * half, k * GPG_N[cat] / 8.0 * half)
        plan.append(dict(kind=kind, M=M, p=p, k=k, cat=cat, src=src))
    for r, t in zip(roads, plan):
        r["traffic"] = t
    S._traffic = plan
    return plan


def traffic_key(S):
    """Fingerprint of the traffic model (for the result store)."""
    return fp(sorted((k_, [sorted(c_.items()) for c_ in v_]) for k_, v_ in COUNTED.items()), GPG_D, GPG_E, GPG_N, GPG_HV,
              sorted(GPG_CAT.items()), URBAN_LIMIT, PERIODS, sorted(KGM_SPLIT.items()), "v16.3")


def rls90_emission(M, p, v):
    """RLS-90 emission level L_m,E (dB(A) at 25 m) of M vehicles/h with p % heavy, cars at v km/h (30-130) and
    heavy vehicles at v but at most 80 km/h (30-80)."""
    if M <= 0:
        return None
    v = float(v)
    vp = max(30.0, min(v, 130.0))
    vl = max(30.0, min(v, 80.0))
    Lpkw = 27.7 + 10.0 * math.log10(1.0 + (0.02 * vp) ** 3)
    D = 23.1 + 12.5 * math.log10(vl) - Lpkw
    Dv = Lpkw - 37.3 + 10.0 * math.log10((100.0 + (10.0 ** (0.1 * D) - 1.0) * p) / (100.0 + 8.23 * p))
    return 37.3 + 10.0 * math.log10(M * (1.0 + 0.082 * p)) + Dv


def surface_corr(tags, v):
    """RLS-90 Table 4 road surface correction D_StrO for the speed limit v: columns 30, 40 and >= 50 km/h."""
    s = (tags.get("surface") or "").lower()
    col = 0 if v < 35.0 else (1 if v < 45.0 else 2)
    if s in ("sett", "cobblestone", "unhewn_cobblestone", "cobblestone:flattened"):
        return (3.0, 4.5, 6.0)[col]                     # other paving
    if s in ("paving_stones", "paving_stones:30", "paving_stones:lanes"):
        return (2.0, 2.5, 3.0)[col]                     # paving with an even surface
    if s in ("concrete", "concrete:plates", "concrete:lanes"):
        return (1.0, 1.5, 2.0)[col]                     # concrete
    return 0.0


def noise_sources(S, R=300.0):
    """Centrelines of the counted roads within R of the frame (not cut at it: receivers near the edge hear the road
    beyond it) in pieces of at most 10 m, with RLS-90 emission per period. Road gradient for D_Stg: over 50 m
    along the road (at most 12 %). v18: the pieces are listed first, their terrain heights found together (on the
    worker processes), then the sources made from them, in the same order with the same arithmetic."""
    pieces = []
    fb = S.F.bb
    box = (fb[0] - R, fb[1] - R, fb[2] + R, fb[3] + R)
    plan = traffic_plan(S)
    for r, tr in zip(getattr(S, "roads_noise", []), plan):
        if tr is None:
            continue
        v = URBAN_LIMIT
        try:
            v = float(str(r["tags"].get("maxspeed")).split()[0])          # the signed limit, where mapped
        except Exception:
            pass
        sc = surface_corr(r["tags"], v)
        P = r["P"]
        for k in range(len(P) - 1):
            a, b = P[k], P[k + 1]
            L_ = math.hypot(b[0] - a[0], b[1] - a[1])
            if L_ < 0.5 or not bb_hit((min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])), box):
                continue
            ux_, uy_ = (b[0] - a[0]) / L_, (b[1] - a[1]) / L_
            n = max(1, int(math.ceil(L_ / 10.0)))
            for q in range(n):
                t0, t1 = q / float(n), (q + 1) / float(n)
                x0, y0 = a[0] + (b[0] - a[0]) * t0, a[1] + (b[1] - a[1]) * t0
                x1, y1 = a[0] + (b[0] - a[0]) * t1, a[1] + (b[1] - a[1]) * t1
                mx_, my_ = (x0 + x1) / 2.0, (y0 + y1) / 2.0
                pieces.append((tr, v, sc, x0, y0, x1, y1, L_ / n, (mx_ + ux_ * 25.0, my_ + uy_ * 25.0),
                               (mx_ - ux_ * 25.0, my_ - uy_ * 25.0), (mx_, my_)))
    zs = z_at_many(S, [p_[k_] for p_ in pieces for k_ in (8, 9, 10)], "road gradients")
    src = []
    for j, (tr, v, sc, x0, y0, x1, y1, Ln, pa, pb, pm) in enumerate(pieces):
        za, zb, zm = zs[3 * j], zs[3 * j + 1], zs[3 * j + 2]
        g_ = abs(za - zb) / 50.0 * 100.0
        g_ = min(g_, 12.0)
        dstg = 0.6 * g_ - 3.0 if g_ > 5.0 else 0.0
        em = []
        for q_ in range(3):
            e_ = rls90_emission(tr["M"][q_], tr["p"][q_], v)
            em.append(e_ + sc + dstg if e_ is not None else None)
        src.append(dict(a=(x0, y0), b=(x1, y1), L=Ln, em=em, z=zm))
    return src


NOISE_MEAS_H = 1.5        # m above ground: the height of a hand-held sound level meter


def calibrate_noise(S, nm, pts, dbs):
    """Shift the whole map so it agrees, on median, with LAeq (day) measured at your points: the model is
    evaluated at each point itself, 1.5 m above the ground (where a hand-held meter measures)."""
    if not pts or not dbs:
        return 0.0, 0
    NM = noise_model(S)
    diffs = []
    for (x, y), m in zip(pts, dbs):
        if NM.inside(x, y):
            LOG.append("WARNING: a noise point lies inside a building and was not used for the calibration.")
            continue
        r = NM.column(x, y, S.z_at(x, y), (NOISE_MEAS_H,))[0]
        if r is not None and r[0] is not None:
            diffs.append(float(m) - r[0])
    if not diffs:
        return 0.0, 0
    diffs.sort()
    n_ = len(diffs)
    off = diffs[n_ // 2] if n_ % 2 else 0.5 * (diffs[n_ // 2 - 1] + diffs[n_ // 2])
    off = max(-12.0, min(12.0, off))
    for row in nm["grid"]:
        for c in row:
            if c and c["lden"] is not None:
                for k in ("day", "evening", "night", "lden"):
                    c[k] += off
    return off, len(diffs)


# ------------------------------------------------------------ surface heat: Landsat grids on the survey
def lst_sample(L_, x, y):
    i = (x - L_["x0"]) / L_["dx"] - 0.5
    j = (y - L_["y0"]) / L_["dx"] - 0.5
    i0, j0 = int(math.floor(i)), int(math.floor(j))
    vals, wts = [], []
    for di in (0, 1):
        for dj in (0, 1):
            ii, jj = i0 + di, j0 + dj
            if 0 <= jj < L_["ny"] and 0 <= ii < L_["nx"]:
                v_ = L_["values"][jj][ii]
                if v_ is not None:
                    vals.append(v_)
                    wts.append((1 - abs(i - ii)) * (1 - abs(j - jj)))
    if not vals or sum(wts) <= 0:
        return None
    return sum(v_ * w_ for v_, w_ in zip(vals, wts)) / sum(wts)


NOISE_PTS_SURVEY = []
NOISE_PTS_USER = []
NOISE_DB_PAIRED = []                      # the measured dB of each noise point kept (same order)
FOCUS_PTS_USER = []

# ------------------------------------------------------------ tree canopies: measured transmissivity of direct sun
# Konarska et al. 2014 (Theor. Appl. Climatol. 117:363-376), one coniferous and four deciduous urban trees measured:
# crowns in leaf pass 1.3-5.3 % of the direct beam, leafless crowns 40.2-51.9 %. Every needle-leaved crown (all year)
# and deciduous crown in leaf passes 3 % (SOLWEIG's default, inside the measured range; no needle-leaved measurement of
# its own: unverified), a leafless deciduous crown 46 % (the middle of the measured range).
# v24 (R03-04): olive crowns (evergreen broadleaf) pass 15 % all year. Castillo-Ruiz et al. 2016, Sensors 16(5):723,
# doi:10.3390/s16050723, Table 3: olive crown porosity along the sun beam (PAR transmittance) 13.3-24.6 % (nine variety
# x date x pruning means, mean 18.5 %); Konarska et al. measured no olive.
TAU_LEAFY, TAU_BARE, TAU_OLIVE = 0.03, 0.46, 0.15


def canopy_tau(kind, leaf_on):
    if kind == "olive":
        return TAU_OLIVE
    return TAU_LEAFY if (kind in EVERGREEN or leaf_on) else TAU_BARE


# ============================================================ ENVIRONMENT v16 · period averages (numpy engine)
# Every map and section of the technical sheets is an average over a period:
#   shade      hours in shade over the whole day (sunrise to sunset, every minute) on the four key days, and the mean
#              day of the year (every minute of all 365 days)
#   radiation  mean kWh/m2 per day of each season, from every hour of the typical year
#   wind, air temperature, felt temperature   means over every hour of each season's window (default: daylight)
# The sun and sky are cast through the surveyed buildings (exact footprints, roof heights over the surveyed terrain),
# the 3D tree crowns and the terrain horizon. For each degree of sun azimuth the obstruction of every receiver is found
# exactly (the steepest roof edge between it and the sun, and the elevation bands where crowns stand in the way); the
# time integrals over the sun's positions in that degree are then exact in elevation. The sky is integrated
# analytically in elevation over 5-degree sectors.
try:
    import numpy as np
    HAVE_NP = True
except Exception:
    np = None
    HAVE_NP = False

SUN_BINS = 360                    # 1 degree of azimuth
SKY_BINS = 72                     # 5 degrees of azimuth for the sky
ENV_REACH = 250.0                 # m: obstacles further away are not searched (as v15)
KIND_CLASS = {"pine": 0, "olive": 1, "tree": 2}
_h_in = inp("hours", "daylight")
if isinstance(_h_in, (list, tuple)):
    _h_in = _h_in[0] if _h_in else "daylight"
HOURS_IN = str(_h_in if _h_in is not None else "daylight").strip().lower()
if inp("hour", None) is not None:
    LOG.append("The input hour is no longer used: every wind, air and felt temperature map is a mean over the season's "
               "hours (input hours: daylight, all, or a local range such as 10-17).")


def hours_window():
    """The comfort averaging window: ("daylight", None), ("all", None) or ("range", (h0, h1)) in local hours."""
    h = HOURS_IN.replace(" ", "")
    if h in ("", "daylight", "day", "sun", "daytime"):
        return ("daylight", None)
    if h in ("all", "24", "24h", "allday", "0-24"):
        return ("all", None)
    try:
        a, b = h.replace("–", "-").split("-")
        a, b = int(round(float(a))) % 24, int(round(float(b)))
        if b <= a:
            b += 24
        return ("range", (a, b))
    except Exception:
        LOG.append("hours input '{}' not understood: daylight hours used.".format(HOURS_IN))
        return ("daylight", None)


def window_label(short=False):
    kind, rng = hours_window()
    if kind == "daylight":
        return "daylight hours" if short else "every daylight hour (sun above the horizon)"
    if kind == "all":
        return "all hours" if short else "every hour of the day and night"
    return "{:02d}:00-{:02d}:00".format(rng[0], rng[1] % 24) if short else "every hour from {:02d}:00 to {:02d}:00 local".format(rng[0], rng[1] % 24)


def tau_mask_table(leaf_on):
    """Transmission for each set of crown classes standing in the way (bit 0 needle-leaved, 1 evergreen broadleaf,
    2 deciduous): the most opaque one counts, as on the v15 plan."""
    tc = (canopy_tau("pine", leaf_on), canopy_tau("olive", leaf_on), canopy_tau("tree", leaf_on))
    t = np.ones(8)
    for m in range(1, 8):
        t[m] = min(tc[q] for q in range(3) if m >> q & 1)
    return t


# ------------------------------------------------------------ sun, vectorised (the formulas of sun_position)
def sun_np(y, mo, d, hour_utc, lat, lon):
    mo = np.asarray(mo, np.int64)
    d = np.asarray(d, np.int64)
    h = np.asarray(hour_utc, float)
    yy = np.where(mo <= 2, y - 1, y)
    mm = np.where(mo <= 2, mo + 12, mo)
    A_ = yy // 100
    jd = (np.floor(365.25 * (yy + 4716)) + np.floor(30.6001 * (mm + 1)) + d + (2 - A_ + A_ // 4) - 1524.5
          + h / 24.0)
    T = (jd - 2451545.0) / 36525.0
    L0 = (280.46646 + T * (36000.76983 + 0.0003032 * T)) % 360.0
    M = np.radians(357.52911 + T * (35999.05029 - 0.0001537 * T))
    e = 0.016708634 - T * (0.000042037 + 0.0000001267 * T)
    Cc = (np.sin(M) * (1.914602 - T * (0.004817 + 0.000014 * T)) + np.sin(2 * M) * (0.019993 - 0.000101 * T)
          + np.sin(3 * M) * 0.000289)
    om = np.radians(125.04 - 1934.136 * T)
    lam = np.radians(L0 + Cc - 0.00569 - 0.00478 * np.sin(om))
    eps = np.radians(23.0 + (26.0 + (21.448 - T * (46.815 + T * (0.00059 - T * 0.001813))) / 60.0) / 60.0
                     + 0.00256 * np.cos(om))
    dec = np.arcsin(np.sin(eps) * np.sin(lam))
    yv = np.tan(eps / 2.0) ** 2
    L0r = np.radians(L0)
    eqt = 4.0 * np.degrees(yv * np.sin(2 * L0r) - 2 * e * np.sin(M) + 4 * e * yv * np.sin(M) * np.cos(2 * L0r)
                           - 0.5 * yv * yv * np.sin(4 * L0r) - 1.25 * e * e * np.sin(2 * M))
    ha = np.radians(((h * 60.0 + eqt + 4.0 * lon) % 1440.0) / 4.0 - 180.0)
    lr = math.radians(lat)
    cz = math.sin(lr) * np.sin(dec) + math.cos(lr) * np.cos(dec) * np.cos(ha)
    zen = np.arccos(np.clip(cz, -1.0, 1.0))
    el = 90.0 - np.degrees(zen)
    with np.errstate(divide="ignore", invalid="ignore", over="ignore"):
        te = np.tan(np.radians(el))
        r = np.where(el > 85.0, 0.0,
                     np.where(el > 5.0, 58.1 / te - 0.07 / te ** 3 + 0.000086 / te ** 5,
                              np.where(el > -0.575, 1735.0 + el * (-518.2 + el * (103.4 + el * (-12.79 + el * 0.711))),
                                       -20.774 / te)))     # v21: NOAA (R04-02)
        sz = np.sin(zen)
        a = np.degrees(np.arccos(np.clip((math.sin(lr) * cz - np.sin(dec)) / (math.cos(lr) * sz), -1.0, 1.0)))
    az = np.where(ha > 0, (a + 180.0) % 360.0, (540.0 - a) % 360.0)
    az = np.where(sz < 1e-9, 180.0, az)
    return az, el + r / 3600.0


def perez_np(dhi, dni, zen_deg, doy):
    """perez_f vectorised: circumsolar F1 and horizon F2."""
    z = np.radians(zen_deg)
    with np.errstate(divide="ignore", invalid="ignore", over="ignore"):
        am = 1.0 / (np.cos(z) + 0.50572 * (96.07995 - zen_deg) ** -1.6364)
        k = 1.041 * z ** 3
        eps = ((dhi + dni) / dhi + k) / (1.0 + k)
        b_ = 2.0 * np.pi * (doy - 1) / 365.0               # v21: Spencer, day 0 = 1 January (R04-16)
        ext = 1366.1 * (1.00011 + 0.034221 * np.cos(b_) + 0.00128 * np.sin(b_) + 0.000719 * np.cos(2 * b_)
                        + 0.000077 * np.sin(2 * b_))
        delta = dhi * am / ext
    b = np.zeros(np.shape(eps), np.int64)
    for t in PEREZ_EPS:
        b += (eps >= t)
    F1c, F2c = np.array(PEREZ_F1), np.array(PEREZ_F2)
    f1 = np.maximum(0.0, F1c[b, 0] + F1c[b, 1] * delta + F1c[b, 2] * z)
    f2 = F2c[b, 0] + F2c[b, 1] * delta + F2c[b, 2] * z
    ok = (dhi > 0.0) & (zen_deg < 90.0)
    return np.where(ok, f1, 0.0), np.where(ok, f2, 0.0)


# ------------------------------------------------------------ terrain heights, vectorised (the rule of S.z_at)
def _ring_offsets(r):
    """The cells z_at visits up to ring r, in its order."""
    offs = [(0, 0)]
    for rr in range(1, int(r) + 1):
        offs += [(-rr, j) for j in range(-rr, rr + 1)]
        for i in range(-rr + 1, rr):
            offs += [(i, -rr), (i, rr)]
        offs += [(rr, j) for j in range(-rr, rr + 1)]
    return offs


_RING_CACHE = {}


def _ring_np(r):
    o = _RING_CACHE.get(r)
    if o is None:
        offs = _ring_offsets(r)
        o = _RING_CACHE[r] = (np.array([q[0] for q in offs], np.int64), np.array([q[1] for q in offs], np.int64))
    return o


def z_np(S, X, Y, k=8):
    """S.z_at for many points at once: the same samples (the 8 nearest, rings of 25 m cells until no nearer one can
    lie outside), the same ranking (distance, ties in the order found) and the same weights. Points are taken
    bucket by bucket, each bucket's candidates once for all its points."""
    X = np.asarray(X, float).ravel()
    Y = np.asarray(Y, float).ravel()
    out = np.zeros(X.size)
    if not getattr(S, "terrain_ok", False) or X.size == 0:
        return out
    if X.size >= POOL_MIN_PTS and k == 8 and not getattr(S, "_no_pool", False) and pool_live():
        # v18: on the worker processes, in contiguous pieces (each point's height depends on that point alone)
        res = pool_map("_pool_z_np", [(X[a:b], Y[a:b]) for a, b in _pool_chunks(X.size, 5000)], pool_terrain(S),
                       "terrain heights")
        return np.concatenate(res)
    T = getattr(S, "_tnp", None)
    Cc = 25.0
    if T is None:
        smp = S.terrain_smp
        SX = np.array([p[0] for p in smp], float)
        SY = np.array([p[1] for p in smp], float)
        SZ = np.array([p[2] for p in smp], float)
        bi = np.floor(SX / Cc).astype(np.int64)
        bj = np.floor(SY / Cc).astype(np.int64)
        i_lo, j_lo = int(bi.min()) - 61, int(bj.min()) - 61
        W = int(bi.max()) - i_lo + 62
        H = int(bj.max()) - j_lo + 62
        key = (bj - j_lo) * W + (bi - i_lo)
        order = np.argsort(key, kind="stable")              # within a bucket: the order the samples were added
        cnt = np.bincount(key, minlength=W * H)
        start = np.concatenate([[0], np.cumsum(cnt)])
        T = S._tnp = dict(SX=SX[order], SY=SY[order], SZ=SZ[order], i_lo=i_lo, j_lo=j_lo, W=W, H=H, start=start)
    SX, SY, SZ, i_lo, j_lo, W, H, start = (T[q] for q in ("SX", "SY", "SZ", "i_lo", "j_lo", "W", "H", "start"))
    i0 = np.floor(X / Cc).astype(np.int64) - i_lo
    j0 = np.floor(Y / Cc).astype(np.int64) - j_lo
    qk = (j0 + 4096) * (W + 8192) + (i0 + 4096)
    order = np.argsort(qk, kind="stable")
    qs_ = qk[order]
    cut = np.flatnonzero(np.r_[True, qs_[1:] != qs_[:-1], True])
    for u in range(cut.size - 1):
        pend = order[cut[u]:cut[u + 1]]
        ci, cj = int(i0[pend[0]]), int(j0[pend[0]])
        r = 1
        while pend.size:
            oi, oj = _ring_np(r)
            ii, jj = ci + oi, cj + oj
            ok_c = (ii >= 0) & (ii < W) & (jj >= 0) & (jj < H)          # cells beyond the samples' area are empty
            cells = np.where(ok_c, jj * W + ii, 0)
            s0 = np.where(ok_c, start[cells], 0)
            n_ = np.where(ok_c, start[cells + 1] - start[cells], 0)
            tot = int(n_.sum())
            if tot >= k or r >= 60:
                cand = np.repeat(s0, n_) + (np.arange(tot) - np.repeat(np.cumsum(n_) - n_, n_))
                if tot == 0:
                    out[pend] = 0.0
                    break
                D = (SX[cand][None, :] - X[pend][:, None]) ** 2 + (SY[cand][None, :] - Y[pend][:, None]) ** 2
                kk = min(k, tot)
                o = np.argsort(D, axis=1, kind="stable")[:, :kk]
                Dk = np.take_along_axis(D, o, 1)
                ok = (Dk[:, kk - 1] <= (r * Cc) ** 2) if (tot >= k and r < 60) else np.ones(pend.size, bool)
                if ok.any():
                    Do, oo = Dk[ok], o[ok]
                    zc = SZ[cand][oo]
                    ws = np.zeros(Do.shape[0])
                    zs = np.zeros(Do.shape[0])
                    for j in range(kk):                       # summed in rank order, as z_at
                        w = 1.0 / np.where(Do[:, j] > 0.0, Do[:, j], 1.0)
                        ws += w
                        zs += w * zc[:, j]
                    out[pend[ok]] = np.where(Do[:, 0] < 0.01, zc[:, 0], zs / ws)
                pend = pend[~ok]
            r += 1
    return out


# ------------------------------------------------------------ frames, footprints, crowns
def f_world(F, u, v):
    c, s = F._wc, F._ws
    return F.cx + c * u - s * v, F.cy + s * u + c * v


def f_local(F, x, y):
    c, s = F._lc, F._ls
    dx, dy = x - F.cx, y - F.cy
    return c * dx - s * dy, s * dx + c * dy


class Casters16(object):
    """What stands between a receiver and the sun or sky, in one frame's local coordinates: every wall of every
    surveyed footprint (counter-clockwise, with the building's roof height above sea level), the tree crowns (circles
    of their measured radius between their lowest and highest leaves) and the terrain horizon profiles."""

    def __init__(self, S, E, solids, F, reach=ENV_REACH):
        bl, gB, trees = solids
        fb = F.bb
        fbx = (fb[0] - reach, fb[1] - reach, fb[2] + reach, fb[3] + reach)
        AX, AY, BX, BY, TOP, OWN, HB = [], [], [], [], [], [], []
        self.rings, self.tops, self.blds = [], [], []        # per building: outline (anticlockwise) + courtyards
        for bi, b in enumerate(bl):
            if not bb_hit(b["bb"], fbx):
                continue
            P = [F.local(x, y) for x, y in dict.fromkeys(b["P"])]
            if len(P) < 3:
                continue
            if signed_area(P) < 0:
                P = P[::-1]
            rings = [P]
            for h in b.get("holes") or ():
                Hl = [F.local(x, y) for x, y in dict.fromkeys(h)]
                if len(Hl) >= 3:
                    rings.append(Hl if signed_area(Hl) < 0 else Hl[::-1])      # courtyards clockwise
            self.rings.append(rings)
            self.tops.append(b["top"])
            self.blds.append(bi)
            for R_ in rings:                                 # outward normals point away from the solid for both
                n = len(R_)
                for q in range(n):
                    (ax, ay), (bx, by) = R_[q], R_[(q + 1) % n]
                    if ax == bx and ay == by:
                        continue
                    AX.append(ax); AY.append(ay); BX.append(bx); BY.append(by); TOP.append(b["top"]); OWN.append(bi)
                    HB.append(b["H"])
        self.AX, self.AY, self.BX, self.BY = (np.array(v, float) for v in (AX, AY, BX, BY))
        self.top = np.array(TOP, float)
        self.own = np.array(OWN, np.int64)
        self.HB = np.array(HB, float)                         # the building's height above its own ground
        ex, ey = self.BX - self.AX, self.BY - self.AY
        le = np.hypot(ex, ey)
        self.NX, self.NY = ey / le, -ex / le
        tr = [t for t in trees if fbx[0] <= t["x"] <= fbx[2] and fbx[1] <= t["y"] <= fbx[3]]
        loc = [F.local(t["x"], t["y"]) for t in tr]
        self.CU = np.array([p[0] for p in loc], float)
        self.CV = np.array([p[1] for p in loc], float)
        self.CR = np.array([t["r"] for t in tr], float)
        self.CLO = np.array([t["base"] + t["lo"] for t in tr], float)
        self.CHI = np.array([t["base"] + t["hi"] for t in tr], float)
        self.CK = np.array([KIND_CLASS.get(t["kind"], 2) for t in tr], np.int64)
        self.CHR = np.array([t["hi"] for t in tr], float)     # crown tops above their own ground
        HG = E.get("horizon_grid")
        HZ = Horizons(E.get("horizons", []))
        self.HG = HG
        if HG:                                                 # profiles on a grid: interpolated between its nodes
            self.HN = np.array(HG["h"], float).reshape(HG["nu"] * HG["nv"], -1)
            self.step = float(HG["step"])
        else:                                                  # a few profiles: the nearest one
            self.HN = np.array(HZ.H, float) if HZ.H else np.zeros((0, 48))
            self.step = HZ.step
        self.HPX = np.array([p[0] for p in HZ.P], float)
        self.HPY = np.array([p[1] for p in HZ.P], float)
        lat, lon = E["location"]["lat"], E["location"]["lon"]
        self.CP = Compass(lon, lat)
        o = F.local(0.0, 0.0)
        ex_, ey_ = F.local(1.0, 0.0), F.local(0.0, 1.0)
        self.M = (ex_[0] - o[0], ey_[0] - o[0], ex_[1] - o[1], ey_[1] - o[1])
        self.F = F
        self.reach = reach

    def dir_local(self, az):
        """Unit vector toward azimuth az, in the frame's coordinates."""
        sv = self.CP.vec(az)
        m = self.M
        dx, dy = m[0] * sv[0] + m[1] * sv[1], m[2] * sv[0] + m[3] * sv[1]
        dl = math.hypot(dx, dy)
        return dx / dl, dy / dl

    def hz_nodes(self, az):
        """Terrain horizon (deg) of every profile or grid node at azimuth az, linear between its 7.5-degree steps."""
        if self.HN.shape[0] == 0:
            return np.zeros(0)
        nh = self.HN.shape[1]
        f = (az % 360.0) / self.step
        k = int(f) % nh
        t = f - int(f)
        return self.HN[:, k] * (1 - t) + self.HN[:, (k + 1) % nh] * t

    def tau_min(self, az):
        """tan of the lowest terrain horizon anywhere at azimuth az (a bound below every receiver's)."""
        a = self.hz_nodes(az)
        return math.tan(math.radians(float(a.min()))) if a.size else 0.0

    def tau_at(self, az, hw):
        """tan of the terrain horizon at azimuth az of points with horizon weights hw (hz_weights)."""
        a = self.hz_nodes(az)
        idx, w = hw
        if a.size == 0:
            return np.zeros(idx.shape[0])
        return np.tan(np.radians((a[idx] * w).sum(1)))

    def hz_weights(self, X, Y):
        """How each point takes its horizon: bilinear between the four grid nodes around it (points beyond the grid
        take its edge), or the nearest of the profiles. (node indices, weights), each (n, k)."""
        X = np.asarray(X, float).ravel()
        Y = np.asarray(Y, float).ravel()
        HG = self.HG
        if HG:
            c, s = math.cos(HG["ang"]), math.sin(HG["ang"])
            dx, dy = X - HG["cx"], Y - HG["cy"]
            fi = np.clip((c * dx + s * dy - HG["u0"]) / HG["du"], 0.0, HG["nu"] - 1.0)
            fj = np.clip((-s * dx + c * dy - HG["v0"]) / HG["du"], 0.0, HG["nv"] - 1.0)
            i0 = np.minimum(fi.astype(np.int64), HG["nu"] - 2)
            j0 = np.minimum(fj.astype(np.int64), HG["nv"] - 2)
            ti, tj = fi - i0, fj - j0
            n0 = j0 * HG["nu"] + i0
            idx = np.stack([n0, n0 + 1, n0 + HG["nu"], n0 + HG["nu"] + 1], 1)
            w = np.stack([(1 - ti) * (1 - tj), ti * (1 - tj), (1 - ti) * tj, ti * tj], 1)
            return idx, w
        if self.HPX.size == 0:
            return np.zeros((X.size, 1), np.int64), np.zeros((X.size, 1))
        d2 = (X[:, None] - self.HPX[None, :]) ** 2 + (Y[:, None] - self.HPY[None, :]) ** 2
        return np.argmin(d2, axis=1)[:, None], np.ones((X.size, 1))


# ------------------------------------------------------------ v16.3: the terrain horizon above the ground
# PVGIS gives the terrain horizon of a point ON THE GROUND. v16.2 used that ground horizon unchanged at every height of a
# section, so a point 20 m up kept the horizon of the ground under it: the whole sky of a section took the ground's
# horizon hours, in full-height bands whose edges fall where those hours cross a whole hour (the colour classes).
# v16.3 lowers the horizon with height by what the terrain itself shows: for each point and each of the PVGIS azimuths
# the terrain is marched from HZ_D0 out to the edge of the horizon grid (the survey's own terrain inside the frame, the
# PVGIS DEM heights of the 100 m grid nodes around it), and the terrain beyond the grid is the PVGIS horizon of the
# grid's edge point in that direction, taken as far away (so it does not fall with height). The point's horizon at
# height h is then its PVGIS ground horizon minus how much that terrain model's horizon falls between the ground and h.
# At the ground nothing changes (the plan, T3, and the section's ground row stay as they were).
HZ_D0 = 50.0                    # m: the march starts at half the PVGIS grid spacing (nearer ground: the slope's own plane)
HZ_GROW = 1.04                  # each march step 4 % longer than the last (50 m, 52 m, 54 m ... to the grid's edge)
HZ_HTS = (0.0, 1.0, 2.5, 5.0, 10.0, 20.0, 40.0, 80.0, 160.0)    # m above the ground where the fall is computed
HZ_CELL = 10.0                  # m: the terrain raster the march reads (bilinear)


def hz_terrain(S, HG):
    """Terrain heights on a HZ_CELL raster over the horizon grid, in the grid's own axes: the survey's terrain inside
    the frame (+40 m, as the section drawings use it), the grid nodes' PVGIS DEM heights (bilinear) elsewhere."""
    memo = env_memo(S)
    r = memo.get("hz_terrain")
    if r is not None:
        return r
    nu, nv, du = HG["nu"], HG["nv"], float(HG["du"])
    u0, v0 = float(HG["u0"]), float(HG["v0"])
    Lu, Lv = (nu - 1) * du, (nv - 1) * du
    ni, nj = int(math.ceil(Lu / HZ_CELL)) + 1, int(math.ceil(Lv / HZ_CELL)) + 1
    uu = u0 + np.arange(ni) * HZ_CELL
    vv = v0 + np.arange(nj) * HZ_CELL
    UU, VV = np.meshgrid(uu, vv)
    el = np.array(HG["elev"], float)                          # [j][i], like the profiles
    fi = np.clip((UU - u0) / du, 0.0, nu - 1.0)
    fj = np.clip((VV - v0) / du, 0.0, nv - 1.0)
    i0 = np.minimum(fi.astype(np.int64), nu - 2)
    j0 = np.minimum(fj.astype(np.int64), nv - 2)
    ti, tj = fi - i0, fj - j0
    Z = ((el[j0, i0] * (1 - ti) + el[j0, i0 + 1] * ti) * (1 - tj) + (el[j0 + 1, i0] * (1 - ti) + el[j0 + 1, i0 + 1] * ti) * tj)
    c, s = math.cos(HG["ang"]), math.sin(HG["ang"])
    X = HG["cx"] + c * UU - s * VV
    Y = HG["cy"] + s * UU + c * VV
    F = S.F
    lu, lv = f_local(F, X.ravel(), Y.ravel())
    ins = (lu >= F.u0 - 40.0) & (lu <= F.u1 + 40.0) & (lv >= F.v0 - 40.0) & (lv <= F.v1 + 40.0)
    Zr = Z.ravel()
    if getattr(S, "terrain_ok", False) and ins.any():
        Zr[ins] = z_np(S, X.ravel()[ins], Y.ravel()[ins])
    r = memo["hz_terrain"] = dict(Z=Zr.reshape(Z.shape), u0=u0, v0=v0, ni=ni, nj=nj, Lu=Lu, Lv=Lv, c=c, s=s,
                                  n_survey=int(ins.sum()), n_all=int(ins.size))
    return r


def _hz_z(T, U, V):
    fi = np.clip((U - T["u0"]) / HZ_CELL, 0.0, T["ni"] - 1.0)
    fj = np.clip((V - T["v0"]) / HZ_CELL, 0.0, T["nj"] - 1.0)
    i0 = np.minimum(fi.astype(np.int64), T["ni"] - 2)
    j0 = np.minimum(fj.astype(np.int64), T["nj"] - 2)
    ti, tj = fi - i0, fj - j0
    Z = T["Z"]
    return (Z[j0, i0] * (1 - ti) + Z[j0, i0 + 1] * ti) * (1 - tj) + (Z[j0 + 1, i0] * (1 - ti) + Z[j0 + 1, i0 + 1] * ti) * tj


def hz_fall_table(S, C, X, Y, Zg):
    """How far (in tan) the terrain horizon of each point falls between its ground (Zg) and each height of HZ_HTS, at
    each PVGIS azimuth: array (points, azimuths, heights), 0 at the ground. None without a horizon grid."""
    HG = C.HG
    if not HG or C.HN.shape[0] == 0:
        return None
    T = hz_terrain(S, HG)
    X = np.asarray(X, float)
    Y = np.asarray(Y, float)
    Zg = np.asarray(Zg, float)
    c, s = T["c"], T["s"]
    U = c * (X - HG["cx"]) + s * (Y - HG["cy"])
    V = -s * (X - HG["cx"]) + c * (Y - HG["cy"])
    nh = C.HN.shape[1]
    step = C.step
    dmax = math.hypot(T["Lu"], T["Lv"]) + 10.0
    d = [HZ_D0]
    while d[-1] < dmax:
        d.append(d[-1] * HZ_GROW)
    d = np.array(d)
    hts = np.array(HZ_HTS)
    out = np.zeros((X.size, nh, hts.size))
    u_lo, u_hi, v_lo, v_hi = T["u0"], T["u0"] + T["Lu"], T["v0"], T["v0"] + T["Lv"]
    for k in range(nh):
        az = k * step
        wx, wy = C.CP.vec(az)                                    # survey axes
        du_, dv_ = c * wx + s * wy, -s * wx + c * wy               # the grid's axes
        for a in range(0, X.size, 256):
            b = min(X.size, a + 256)
            Us = U[a:b, None] + du_ * d[None, :]
            Vs = V[a:b, None] + dv_ * d[None, :]
            ins = (Us >= u_lo) & (Us <= u_hi) & (Vs >= v_lo) & (Vs <= v_hi)
            zt = _hz_z(T, Us, Vs)
            # the edge point: the last march step still on the grid (the point itself when the first step leaves it)
            last = np.where(ins.any(1), ins.shape[1] - 1 - np.argmax(ins[:, ::-1], axis=1), -1)
            dl = np.where(last >= 0, d[np.maximum(last, 0)], 0.0)
            Ue, Ve = U[a:b] + du_ * dl, V[a:b] + dv_ * dl
            Xe = HG["cx"] + c * Ue - s * Ve
            Ye = HG["cy"] + s * Ue + c * Ve
            hw = C.hz_weights(Xe, Ye)
            tanE = np.tan(np.radians((C.HN[hw[0], k] * hw[1]).sum(1)))
            prev = None
            for q, h in enumerate(hts):
                tn = np.where(ins, (zt - (Zg[a:b, None] + h)) / d[None, :], -np.inf).max(1)
                tm = np.maximum(tn, tanE)
                if prev is None:
                    prev = tm
                out[a:b, k, q] = np.maximum(0.0, prev - tm)
    return out


class HzFall(object):
    """The horizon's fall with height for receivers of one Points16: per receiver its point's row of the table and its
    height above the ground, read linearly between the azimuths and the heights of the table."""

    def __init__(self, table, step, pid, hg):
        self.T = table
        self.step = step
        self.pid = np.asarray(pid, np.int64)
        hts = np.array(HZ_HTS)
        hg = np.clip(np.asarray(hg, float), 0.0, hts[-1])
        q = np.clip(np.searchsorted(hts, hg, side="right") - 1, 0, hts.size - 2)
        self.q = q
        self.wq = (hg - hts[q]) / (hts[q + 1] - hts[q])
        self._az = None

    def _slice(self, az):
        last = self._az                                   # v16.6: read once (the sun pass runs on several threads)
        if last is not None and last[0] == az:
            return last[1]
        nh = self.T.shape[1]
        f = (az % 360.0) / self.step
        k = int(f) % nh
        t = f - int(f)
        A = self.T[:, k, :] * (1 - t) + self.T[:, (k + 1) % nh, :] * t
        self._az = (az, A)
        return A

    def at(self, az):
        A = self._slice(az)
        r = A[self.pid]
        q = self.q
        idx = np.arange(q.size)
        return r[idx, q] * (1.0 - self.wq) + r[idx, q + 1] * self.wq

    def most(self, az):
        A = self._slice(az)
        return float(A.max()) if A.size else 0.0


def tau_floor(G, C, az):
    """The lowest terrain horizon any receiver of G can have at azimuth az (a bound for the sweeps): the frame's lowest
    ground horizon, lowered by the largest fall with height among G's receivers (v16.3)."""
    hz = getattr(G, "hzf", None)
    return C.tau_min(az) - (hz.most(az) if hz is not None else 0.0)


def footprint_values(groups, vals, u0, v0, cell, nx, ny):
    """Per cell whose centre lies inside a footprint (groups of rings: outline and courtyards, even-odd per group)
    the largest value of the groups covering it; -inf elsewhere."""
    EA, EB, PID = [], [], []
    for k, rings in enumerate(groups):
        for P in rings:
            n = len(P)
            for q in range(n):
                EA.append(P[q]); EB.append(P[(q + 1) % n]); PID.append(k)
    out = np.full(nx * ny, -np.inf)
    if not EA:
        return out
    ax = np.array([p[0] for p in EA]); ay = np.array([p[1] for p in EA])
    bx = np.array([p[0] for p in EB]); by = np.array([p[1] for p in EB])
    pid = np.array(PID, np.int64)
    ylo, yhi = np.minimum(ay, by), np.maximum(ay, by)
    j0 = np.clip(np.ceil((ylo - v0) / cell - 0.5).astype(np.int64), 0, ny)        # rows with ylo <= yc < yhi
    j1 = np.clip(np.ceil((yhi - v0) / cell - 0.5).astype(np.int64), 0, ny)
    cnt = np.maximum(j1 - j0, 0)
    tot = int(cnt.sum())
    if tot == 0:
        return out
    e = np.repeat(np.arange(ax.size), cnt)
    row = j0[e] + (np.arange(tot) - np.repeat(np.cumsum(cnt) - cnt, cnt))
    yc = v0 + (row + 0.5) * cell
    keep = (ay[e] <= yc) != (by[e] <= yc)
    e, row, yc = e[keep], row[keep], yc[keep]
    xc = ax[e] + (yc - ay[e]) * (bx[e] - ax[e]) / (by[e] - ay[e])
    o = np.lexsort((xc, row, pid[e]))
    e, row, xc = e[o], row[o], xc[o]
    key = pid[e] * (ny + 1) + row
    first = np.flatnonzero(np.r_[True, key[1:] != key[:-1]])
    pos = np.arange(key.size) - np.repeat(first, np.diff(np.r_[first, key.size]))
    a_i = np.flatnonzero(pos % 2 == 0)
    a_i = a_i[(a_i + 1 < key.size)]
    a_i = a_i[key[a_i + 1] == key[a_i]]
    lo, hi, rr, gg = xc[a_i], xc[a_i + 1], row[a_i], pid[e[a_i]]
    a0 = np.clip(np.ceil((lo - u0) / cell - 0.5).astype(np.int64), 0, nx)
    a1 = np.clip(np.floor((hi - u0) / cell - 0.5).astype(np.int64) + 1, 0, nx)
    ok = a1 > a0
    a0, a1, rr, gg = a0[ok], a1[ok], rr[ok], gg[ok]
    c = a1 - a0
    t2 = int(c.sum())
    rep = np.repeat(np.arange(c.size), c)
    idx = (rr * nx + a0)[rep] + (np.arange(t2) - np.repeat(np.cumsum(c) - c, c))
    np.maximum.at(out, idx, np.asarray(vals, float)[gg][rep])
    return out


def disc_values(cu, cv, r, vals, u0, v0, cell, nx, ny):
    """Per cell whose centre lies within a disc (crown) the largest value of the discs covering it; -inf elsewhere."""
    out = np.full(nx * ny, -np.inf)
    if np.size(cu) == 0:
        return out
    cu, cv, r, vals = (np.asarray(x, float) for x in (cu, cv, r, vals))
    j0 = np.clip(np.ceil((cv - r - v0) / cell - 0.5).astype(np.int64), 0, ny)
    j1 = np.clip(np.floor((cv + r - v0) / cell - 0.5).astype(np.int64) + 1, 0, ny)
    cnt = np.maximum(j1 - j0, 0)
    tot = int(cnt.sum())
    if tot == 0:
        return out
    q = np.repeat(np.arange(cu.size), cnt)
    row = j0[q] + (np.arange(tot) - np.repeat(np.cumsum(cnt) - cnt, cnt))
    dv = v0 + (row + 0.5) * cell - cv[q]
    hw = np.sqrt(np.maximum(r[q] ** 2 - dv ** 2, 0.0))
    inn = r[q] ** 2 - dv ** 2 > 0.0
    a0 = np.clip(np.ceil((cu[q] - hw - u0) / cell - 0.5).astype(np.int64), 0, nx)
    a1 = np.clip(np.floor((cu[q] + hw - u0) / cell - 0.5).astype(np.int64) + 1, 0, nx)
    ok = inn & (a1 > a0)
    q, row, a0, a1 = q[ok], row[ok], a0[ok], a1[ok]
    c = a1 - a0
    t2 = int(c.sum())
    rep = np.repeat(np.arange(c.size), c)
    idx = (row * nx + a0)[rep] + (np.arange(t2) - np.repeat(np.cumsum(c) - c, c))
    ux = u0 + (idx % nx + 0.5) * cell
    keep = (ux - cu[q][rep]) ** 2 + (v0 + (idx // nx + 0.5) * cell - cv[q][rep]) ** 2 < r[q][rep] ** 2
    np.maximum.at(out, idx[keep], vals[q][rep][keep])
    return out


# ------------------------------------------------------------ the obstruction kernel
class Coarse16(object):
    """Lowest receiver height per 30 m block (blocks without receivers: no height), each block also covering its 8
    neighbours: a lower bound of the height of every receiver near a point, used to stop sweeps early."""

    def __init__(self, zr_eff, u0, v0, cell, nx, ny, C=30.0):
        self.C, self.u0, self.v0 = C, u0, v0
        bx = int(math.ceil(nx * cell / C))
        by = int(math.ceil(ny * cell / C))
        idx = np.arange(nx * ny)
        ii = ((idx % nx) * cell // C).astype(np.int64)
        jj = ((idx // nx) * cell // C).astype(np.int64)
        Z = np.full(bx * by, np.inf)
        ok = np.isfinite(zr_eff)
        np.minimum.at(Z, (jj * bx + ii)[ok], zr_eff[ok])
        Z = Z.reshape(by, bx)
        Pd = np.pad(Z, 1, constant_values=np.inf)
        D = np.full_like(Z, np.inf)
        for dj in (0, 1, 2):
            for di in (0, 1, 2):
                D = np.minimum(D, Pd[dj:dj + by, di:di + bx])
        self.D = np.pad(D, 1, constant_values=np.inf)
        self.bx, self.by = bx, by

    def zlow(self, u, v):
        i = np.clip(np.floor((u - self.u0) / self.C).astype(np.int64) + 1, 0, self.bx + 1)
        j = np.clip(np.floor((v - self.v0) / self.C).astype(np.int64) + 1, 0, self.by + 1)
        return self.D[j, i]


def k_sweep_len(Co, AU, AV, BU, BV, top, d, tau_min, reach, slack=None):
    """Longest useful sweep away from the sun for segments A-B whose top is `top`: no receiver further than this along
    the sweep can see the segment above tan(elevation) = tau_min (exact bound from the coarse lowest heights)."""
    dx, dy = d
    C = Co.C
    n = AU.size
    if n == 0:
        return np.zeros(0)
    sl = np.zeros(n) if slack is None else slack
    ns = int(math.ceil((reach + float(sl.max())) / (0.5 * C))) + 2
    wid = np.hypot(BU - AU, BV - AV)
    nl = np.maximum(2, np.ceil(wid / C).astype(np.int64) + 1)
    obj = np.repeat(np.arange(n), nl)
    kk = np.arange(obj.size) - np.repeat(np.cumsum(nl) - nl, nl)
    s = kk / (nl[obj] - 1).astype(float)
    pu = AU[obj] + s * (BU - AU)[obj]
    pv = AV[obj] + s * (BV - AV)[obj]
    t = np.arange(ns) * (0.5 * C)
    z = Co.zlow(pu[:, None] - t[None, :] * dx, pv[:, None] - t[None, :] * dy)
    t_lo = np.maximum(np.maximum(t - 0.5 * C, 0.0)[None, :] - sl[obj][:, None], 0.0)
    useful = (top[obj][:, None] - z) >= tau_min * t_lo
    tt = np.where(useful, np.minimum(reach + sl[obj][:, None], t[None, :] + 0.5 * C), 0.0)
    out = np.zeros(n)
    np.maximum.at(out, obj, tt.max(1))
    return out


def k_strip_rows(v_lo, v_hi, b_lo, b_hi, p0, pu, pv, t_lo, t_hi, d, u0, v0, cell, nx, ny, eps=1e-7):
    """Rows and column intervals of the cells whose centres satisfy b_lo <= -u dy + v dx <= b_hi and
    t_lo <= p0 + pu u + pv v <= t_hi (one parallelogram per object). Returns (object, row, a0, a1)."""
    dx, dy = d
    j0 = np.clip(np.ceil((v_lo - eps - v0) / cell - 0.5).astype(np.int64), 0, ny)
    j1 = np.clip(np.floor((v_hi + eps - v0) / cell - 0.5).astype(np.int64) + 1, 0, ny)
    cnt = np.maximum(j1 - j0, 0)
    tot = int(cnt.sum())
    if tot == 0:
        e = np.zeros(0, np.int64)
        return e, e, e, e
    q = np.repeat(np.arange(cnt.size), cnt)
    row = j0[q] + (np.arange(tot) - np.repeat(np.cumsum(cnt) - cnt, cnt))
    v = v0 + (row + 0.5) * cell
    lo = np.full(tot, -np.inf)
    hi = np.full(tot, np.inf)
    if abs(dy) > 1e-12:
        x1 = (v * dx - b_hi[q]) / dy
        x2 = (v * dx - b_lo[q]) / dy
        lo = np.maximum(lo, np.minimum(x1, x2))
        hi = np.minimum(hi, np.maximum(x1, x2))
    else:
        bv = v * dx
        hi = np.where((bv < b_lo[q] - eps) | (bv > b_hi[q] + eps), -np.inf, hi)
    c = p0[q] + pv[q] * v
    s = pu[q]
    nzs = np.abs(s) > 1e-12
    ss = np.where(nzs, s, 1.0)
    y1 = (t_lo[q] - c) / ss
    y2 = (t_hi[q] - c) / ss
    lo = np.where(nzs, np.maximum(lo, np.minimum(y1, y2)), lo)
    hi = np.where(nzs, np.minimum(hi, np.maximum(y1, y2)), hi)
    hi = np.where(~nzs & ((c < t_lo[q] - eps) | (c > t_hi[q] + eps)), -np.inf, hi)
    a0 = np.clip(np.ceil((lo - eps - u0) / cell - 0.5).astype(np.int64), 0, nx)
    a1 = np.clip(np.floor((hi + eps - u0) / cell - 0.5).astype(np.int64) + 1, 0, nx)
    m = a1 > a0
    return q[m], row[m], a0[m], a1[m]


def k_expand(q, r, a0, a1, nx):
    cnt = a1 - a0
    tot = int(cnt.sum())
    rep = np.repeat(np.arange(q.size), cnt)
    a = np.arange(tot) - np.repeat(np.cumsum(cnt) - cnt, cnt) + a0[rep]
    return rep, a


def k_buildings(C, G, d, tau_min, crit):
    """crit = max(crit, (roof - receiver height) / distance to the first wall met toward the sun) on a grid."""
    dx, dy = d
    face = (C.NX * dx + C.NY * dy) < 0.0                     # walls facing away from the sun: where a ray enters
    AU, AV, BU, BV, top = C.AX[face], C.AY[face], C.BX[face], C.BY[face], C.top[face]
    aA, bA = AU * dx + AV * dy, -AU * dy + AV * dx
    aB, bB = BU * dx + BV * dy, -BU * dy + BV * dx
    ok = bA != bB
    AU, AV, BU, BV, top, aA, bA, aB, bB = (x[ok] for x in (AU, AV, BU, BV, top, aA, bA, aB, bB))
    T = k_sweep_len(G.Co, AU, AV, BU, BV, top, d, tau_min, C.reach)
    ok = T > 0
    AU, AV, BU, BV, top, aA, bA, aB, bB, T = (x[ok] for x in (AU, AV, BU, BV, top, aA, bA, aB, bB, T))
    if T.size == 0:
        return 0
    ke = (aB - aA) / (bB - bA)
    p0 = aA - bA * ke                                        # distance to the wall: t = p0 + pu u + pv v
    pu = -dy * ke - dx
    pv = dx * ke - dy
    vs = np.stack([AV, BV, AV - T * dy, BV - T * dy], 1)
    q, r, a0, a1 = k_strip_rows(vs.min(1), vs.max(1), np.minimum(bA, bB), np.maximum(bA, bB), p0, pu, pv,
                                np.zeros(T.size), T, d, G.u0, G.v0, G.cell, G.nx, G.ny)
    if q.size == 0:
        return 0
    t_row = p0[q] + pv[q] * (G.v0 + (r + 0.5) * G.cell) + pu[q] * (G.u0 + 0.5 * G.cell)
    rep, a = k_expand(q, r, a0, a1, G.nx)
    t = t_row[rep] + (pu[q] * G.cell)[rep] * a
    c = r[rep] * G.nx + a
    with np.errstate(divide="ignore", invalid="ignore"):
        val = np.where(t > 0.0, (top[q][rep] - G.zr_eff[c]) / t, np.inf)
    np.maximum.at(crit, c, val)
    return c.size


def k_crowns(C, G, d, tau_min):
    """Elevation bands (in tan) where a crown stands between each receiver and the sun: (receiver, lo, hi, class)."""
    dx, dy = d
    n = C.CU.size
    e = np.zeros(0)
    ei = np.zeros(0, np.int64)
    if n == 0:
        return ei, e, e, ei, 0
    px, py = -dy, dx
    r = C.CR
    AU, AV = C.CU - r * px + r * dx, C.CV - r * py + r * dy     # the crown's side toward the sun
    BU, BV = C.CU + r * px + r * dx, C.CV + r * py + r * dy
    T = k_sweep_len(G.Co, AU, AV, BU, BV, C.CHI, d, tau_min, C.reach, slack=2.0 * r)
    ok = T > 0
    cu, cv, r, zlo, zhi, cls, T = C.CU[ok], C.CV[ok], r[ok], C.CLO[ok], C.CHI[ok], C.CK[ok], T[ok]
    if T.size == 0:
        return ei, e, e, ei, 0
    ac, bc = cu * dx + cv * dy, -cu * dy + cv * dx
    # receivers with |b - bc| < r and ac + r - T <= a <= ac + r  (a = u dx + v dy)
    p0 = -(ac + r) + T * 0.0
    q, rr, a0, a1 = k_strip_rows(np.minimum(cv - r - T * np.maximum(dy, 0) - r, cv - r) - 2 * r,
                                 np.maximum(cv + r - T * np.minimum(dy, 0) + r, cv + r) + 2 * r,
                                 bc - r, bc + r, -(ac + r), np.full(T.size, dx), np.full(T.size, dy),
                                 -T, np.zeros(T.size), d, G.u0, G.v0, G.cell, G.nx, G.ny)
    if q.size == 0:
        return ei, e, e, ei, 0
    rep, a = k_expand(q, rr, a0, a1, G.nx)
    k = q[rep]
    row = rr[rep]
    c = row * G.nx + a
    uu = G.u0 + (a + 0.5) * G.cell
    vv = G.v0 + (row + 0.5) * G.cell
    perp = (-uu * dy + vv * dx) - bc[k]
    m = (np.abs(perp) < r[k]) & np.isfinite(G.zr_eff[c])
    k, c, perp, uu, vv = k[m], c[m], perp[m], uu[m], vv[m]
    hw = np.sqrt(r[k] * r[k] - perp * perp)
    along = ac[k] - (uu * dx + vv * dy)
    ta, tb = along - hw, along + hw
    m = (tb > 0.0) & (ta <= np.minimum(T[k], C.reach))
    k, c, ta, tb = k[m], c[m], ta[m], tb[m]
    ta = np.maximum(ta, 0.0)
    z = G.zr_eff[c]
    with np.errstate(divide="ignore", invalid="ignore"):
        lo = np.maximum((zlo[k] - z) / tb, 0.0)
        hi = np.where(ta > 0.0, (zhi[k] - z) / np.where(ta > 0.0, ta, 1.0), np.where(zhi[k] > z, np.inf, -1.0))
    m = (hi > lo) & (hi >= tau_min)
    return c[m], lo[m], hi[m], cls[k[m]], k.size


def k_segments(c, lo, hi, cls, crit, ncls=3):
    """The crown bands above crit merged per receiver: elementary segments (receiver, lo, hi, class bit mask)."""
    lo = np.maximum(lo, crit[c])
    m = hi > lo
    c, lo, hi, cls = c[m], lo[m], hi[m], cls[m]
    e = np.zeros(0)
    if c.size == 0:
        return np.zeros(0, np.int64), e, e, np.zeros(0, np.int64)
    n_per = np.bincount(c)
    single = n_per[c] == 1
    oc, olo, ohi, om = [c[single]], [lo[single]], [hi[single]], [(np.int64(1) << cls[single]).astype(np.int64)]
    mul = ~single
    if mul.any():
        c2, lo2, hi2, k2 = c[mul], lo[mul], hi[mul], cls[mul]
        n = c2.size
        ev_c = np.concatenate([c2, c2])
        ev_t = np.concatenate([lo2, hi2])
        ev_d = np.concatenate([np.ones(n, np.int64), -np.ones(n, np.int64)])
        ev_k = np.concatenate([k2, k2])
        o = np.lexsort((ev_t, ev_c))
        ev_c, ev_t, ev_d, ev_k = ev_c[o], ev_t[o], ev_d[o], ev_k[o]
        mask = np.zeros(ev_c.size, np.int64)
        for q in range(ncls):
            mask |= (np.cumsum(np.where(ev_k == q, ev_d, 0)) > 0).astype(np.int64) << q
        same = ev_c[1:] == ev_c[:-1]
        s_c, s_lo, s_hi, s_m = ev_c[:-1][same], ev_t[:-1][same], ev_t[1:][same], mask[:-1][same]
        keep = (s_m > 0) & (s_hi > s_lo)
        oc.append(s_c[keep]); olo.append(s_lo[keep]); ohi.append(s_hi[keep]); om.append(s_m[keep])
    return np.concatenate(oc), np.concatenate(olo), np.concatenate(ohi), np.concatenate(om)


class Grid16(object):
    """Receivers on a frame-aligned grid of `cell` metres: cell centres on the surveyed terrain, the terrain slope over
    6 m (capped at 35 degrees, as v15) and the nearest horizon profile. Cells inside a footprint are no receivers, or
    with roofs=True receivers on the roof (5 cm above it, facing up)."""

    def __init__(self, S, F, cell, C, height=0.0, roofs=False):
        self.F, self.cell = F, cell
        self.nx, self.ny = int(math.ceil(F.w / cell)), int(math.ceil(F.h / cell))
        self.u0, self.v0 = F.u0, F.v0
        u = F.u0 + (np.arange(self.nx) + 0.5) * cell
        v = F.v0 + (np.arange(self.ny) + 0.5) * cell
        UU, VV = np.meshgrid(u, v)
        self.uu, self.vv = UU.ravel(), VV.ravel()
        self.xx, self.yy = f_world(F, self.uu, self.vv)
        self.z = z_np(S, self.xx, self.yy)
        self.top = footprint_values(C.rings, C.tops, F.u0, F.v0, cell, self.nx, self.ny)
        self.inside = self.top > -np.inf
        self.roofs = roofs
        if roofs:
            self.zr_eff = np.where(self.inside, self.top + 0.05, self.z + height)
        else:
            self.zr_eff = np.where(self.inside, np.inf, self.z + height)
        h = 6.0
        zx = (z_np(S, self.xx + h, self.yy) - z_np(S, self.xx - h, self.yy)) / (2.0 * h)
        zy = (z_np(S, self.xx, self.yy + h) - z_np(S, self.xx, self.yy - h)) / (2.0 * h)
        sl = np.hypot(zx, zy)
        f = np.where(sl > 0.7, 0.7 / np.where(sl > 0, sl, 1.0), 1.0)
        zx, zy = zx * f, zy * f
        if roofs:
            zx, zy = np.where(self.inside, 0.0, zx), np.where(self.inside, 0.0, zy)     # roofs are flat
        n_ = np.sqrt(zx * zx + zy * zy + 1.0)
        self.nwx, self.nwy, self.nz = -zx / n_, -zy / n_, 1.0 / n_      # normal: world x, y and up
        m = C.M
        self.nlu = m[0] * self.nwx + m[1] * self.nwy                   # the same normal in frame coordinates
        self.nlv = m[2] * self.nwx + m[3] * self.nwy
        self.hw = C.hz_weights(self.xx, self.yy)
        self.Co = Coarse16(self.zr_eff, F.u0, F.v0, cell, self.nx, self.ny)
        self.open = ~self.inside
        self.recv = self.open | self.inside if roofs else self.open
        self.n = self.nx * self.ny
        self.zair = self.z                                     # air temperature at 2 m above this ground
        self.wf = None                                         # wind at head height (the plan's shelter as it is)

    def self_tau(self, d):
        """tan of the elevation of the receiver's own ground plane toward d (0 where the ground falls away)."""
        nd = self.nlu * d[0] + self.nlv * d[1]
        return np.where(nd < 0.0, -nd / self.nz, 0.0)

    def obstruction(self, C, az, tau_min, self_shade=False, cheap=False):
        """crit (tan of the elevation up to which the receiver is shut off: terrain, buildings, its own slope when
        self_shade) and the crown segments above it, for the sun at azimuth az (sun positions above tau_min).
        cheap=True: terrain and own slope only (every sun position of the degree is below every horizon)."""
        d = C.dir_local(az)
        crit = np.zeros(self.nx * self.ny)
        if not cheap:
            k_buildings(C, self, d, tau_min, crit)
        crit = np.maximum(crit, C.tau_at(az, self.hw))
        if self_shade:
            crit = np.maximum(crit, self.self_tau(d))
        if cheap:
            e = np.zeros(0)
            ei = np.zeros(0, np.int64)
            return crit, (ei, e, e, ei), d
        c, lo, hi, cls, _ = k_crowns(C, self, d, tau_min)
        segs = k_segments(c, lo, hi, cls, crit)
        return crit, segs, d


class Points16(object):
    """Receivers standing at points of the plan, each point with one or more heights: the columns of a section plane,
    points on cut roofs and facades. Receivers are given sorted by point, then height. For a direction the ray of
    every point is cast through the walls and crowns of the casters (exactly, as on the grid): crit per receiver is the
    steepest roof edge above it, crowns give their elevation bands. Normals (world x, y, up) make the receiver's own
    plane block the sky behind it: a facade sees nothing behind its wall; ground receivers hg metres above a slope see
    past the slope's plane once they stand above it (the slope taken over 6 m, as on the plan)."""

    BIG = 1.0e5

    def __init__(self, C, X, Y, pid, Z, nrm=None, hg=None, zair=None, wf=None):
        F = C.F
        X = np.asarray(X, float)
        Y = np.asarray(Y, float)
        self.np_ = X.size
        self.pu, self.pv = f_local(F, X, Y)
        self.pid = np.asarray(pid, np.int64)
        self.z = np.asarray(Z, float)
        self.n = self.pid.size
        key = self.pid * self.BIG + self.z
        assert self.n == 0 or np.all(np.diff(key) >= 0), "receivers must be sorted by point and height"
        self.zkey = key
        self.r0 = np.searchsorted(self.pid, np.arange(self.np_), side="left")
        self.r1 = np.searchsorted(self.pid, np.arange(self.np_), side="right")
        zmin = np.full(self.np_, np.inf)
        if self.n:
            np.minimum.at(zmin, self.pid, self.z)
        self.zmin = zmin
        self.hw = C.hz_weights(X, Y)
        if nrm is None:
            nrm = (np.zeros(self.n), np.zeros(self.n), np.ones(self.n))
        self.nwx, self.nwy, self.nz = (np.asarray(q, float) for q in nrm)
        m = C.M
        self.nlu = m[0] * self.nwx + m[1] * self.nwy
        self.nlv = m[2] * self.nwx + m[3] * self.nwy
        self.hg = np.zeros(self.n) if hg is None else np.asarray(hg, float)
        self.open = np.ones(self.n, bool)
        self.zair = self.z - 2.0 if zair is None else np.asarray(zair, float)
        self.wf = wf
        # the walls and crowns that can matter for these points at all
        if self.np_:
            lo_u, hi_u = self.pu.min() - C.reach, self.pu.max() + C.reach
            lo_v, hi_v = self.pv.min() - C.reach, self.pv.max() + C.reach
            ke = ((np.maximum(C.AX, C.BX) >= lo_u) & (np.minimum(C.AX, C.BX) <= hi_u) &
                  (np.maximum(C.AY, C.BY) >= lo_v) & (np.minimum(C.AY, C.BY) <= hi_v))
            kc = (C.CU + C.CR >= lo_u) & (C.CU - C.CR <= hi_u) & (C.CV + C.CR >= lo_v) & (C.CV - C.CR <= hi_v)
        else:
            ke = np.zeros(C.AX.size, bool)
            kc = np.zeros(C.CU.size, bool)
        self.E = dict(AX=C.AX[ke], AY=C.AY[ke], BX=C.BX[ke], BY=C.BY[ke], top=C.top[ke], NX=C.NX[ke], NY=C.NY[ke])
        self.Cw = dict(CU=C.CU[kc], CV=C.CV[kc], CR=C.CR[kc], CLO=C.CLO[kc], CHI=C.CHI[kc], CK=C.CK[kc])
        self.reach = C.reach

    def self_tau(self, d):
        nd = self.nlu * d[0] + self.nlv * d[1]
        with np.errstate(divide="ignore", invalid="ignore"):
            t = np.where(self.nz > 1e-9, -nd / np.where(self.nz > 1e-9, self.nz, 1.0) - self.hg / 6.0,
                         np.where(nd < 0.0, np.inf, 0.0))
        return np.maximum(t, 0.0)

    def _pairs(self, d, blo, bhi):
        """(object, point) pairs whose ray (toward d) meets the across-range [blo, bhi] of each object."""
        dx, dy = d
        bp = -self.pu * dy + self.pv * dx
        ob = np.argsort(bp, kind="stable")
        bs = bp[ob]
        i0 = np.searchsorted(bs, blo - 1e-9, side="left")
        i1 = np.searchsorted(bs, bhi + 1e-9, side="right")
        cnt = np.maximum(i1 - i0, 0)
        tot = int(cnt.sum())
        e = np.repeat(np.arange(cnt.size), cnt)
        p = ob[np.repeat(i0, cnt) + (np.arange(tot) - np.repeat(np.cumsum(cnt) - cnt, cnt))]
        return e, p, bp

    def _below(self, p, zz):
        """For each pair: the receivers of its point up to height zz (first index, count)."""
        k1 = np.searchsorted(self.zkey, p * self.BIG + zz, side="right")
        k0 = self.r0[p]
        return k0, np.maximum(k1 - k0, 0)

    def obstruction(self, C, az, tau_min, self_shade=False, cheap=False):
        d = C.dir_local(az)
        dx, dy = d
        n = self.n
        crit = np.zeros(n)
        e0 = np.zeros(0)
        i0_ = np.zeros(0, np.int64)
        segs = (i0_, e0, e0, i0_)
        if n and not cheap:
            E = self.E
            face = (E["NX"] * dx + E["NY"] * dy) < 0.0
            AU, AV, BU, BV, top = E["AX"][face], E["AY"][face], E["BX"][face], E["BY"][face], E["top"][face]
            aA, bA = AU * dx + AV * dy, -AU * dy + AV * dx
            aB, bB = BU * dx + BV * dy, -BU * dy + BV * dx
            ok = bA != bB
            aA, bA, aB, bB, top = aA[ok], bA[ok], aB[ok], bB[ok], top[ok]
            e, p, bp = self._pairs(d, np.minimum(bA, bB), np.maximum(bA, bB))
            if e.size:
                ap = self.pu[p] * dx + self.pv[p] * dy
                t = aA[e] + (bp[p] - bA[e]) * (aB[e] - aA[e]) / (bB[e] - bA[e]) - ap
                tp = top[e]
                k = (t > 0.0) & (t <= self.reach) & (tp - self.zmin[p] >= tau_min * t)
                p, t, tp = p[k], t[k], tp[k]
                k0, cnt = self._below(p, tp - tau_min * t)
                tot = int(cnt.sum())
                if tot:
                    q = np.repeat(np.arange(p.size), cnt)
                    r = np.repeat(k0, cnt) + (np.arange(tot) - np.repeat(np.cumsum(cnt) - cnt, cnt))
                    np.maximum.at(crit, r, (tp[q] - self.z[r]) / t[q])
        if n:
            th = C.tau_at(az, self.hw)[self.pid]
            if getattr(self, "hzf", None) is not None:
                th = th - self.hzf.at(az)                 # v16.3: the terrain horizon falls with height
            crit = np.maximum(crit, th)
            if self_shade:
                crit = np.maximum(crit, self.self_tau(d))
        if n and not cheap and self.Cw["CU"].size:
            W = self.Cw
            ac, bc = W["CU"] * dx + W["CV"] * dy, -W["CU"] * dy + W["CV"] * dx
            e, p, bp = self._pairs(d, bc - W["CR"], bc + W["CR"])
            if e.size:
                perp = bp[p] - bc[e]
                rr = W["CR"][e]
                k = np.abs(perp) < rr
                e, p, perp, rr = e[k], p[k], perp[k], rr[k]
                hw = np.sqrt(rr * rr - perp * perp)
                along = ac[e] - (self.pu[p] * dx + self.pv[p] * dy)
                ta, tb = along - hw, along + hw
                k = (tb > 0.0) & (ta <= self.reach)
                e, p, ta, tb = e[k], p[k], np.maximum(ta[k], 0.0), tb[k]
                zhi = W["CHI"][e]
                k0, cnt = self._below(p, zhi - tau_min * ta)
                tot = int(cnt.sum())
                if tot:
                    q = np.repeat(np.arange(p.size), cnt)
                    r = np.repeat(k0, cnt) + (np.arange(tot) - np.repeat(np.cumsum(cnt) - cnt, cnt))
                    z = self.z[r]
                    ta_, tb_ = ta[q], tb[q]
                    lo = np.maximum((W["CLO"][e][q] - z) / tb_, 0.0)
                    with np.errstate(divide="ignore", invalid="ignore"):
                        hi = np.where(ta_ > 0.0, (zhi[q] - z) / np.where(ta_ > 0.0, ta_, 1.0),
                                      np.where(zhi[q] > z, np.inf, -1.0))
                    k = (hi > lo) & (hi >= tau_min)
                    segs = k_segments(r[k], lo[k], hi[k], W["CK"][e][q][k], crit)
        return crit, segs, d


# ------------------------------------------------------------ sun positions of the analyses
SEASON_OF_MONTH = dict((m, sd["key"]) for sd in SEASONS for m in sd["months"])
SEASON_INDEX = dict((sd["key"], k) for k, sd in enumerate(SEASONS))
MONTH_DAYS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def by_month(f, dtype=None):
    """f(month) as an array indexed by month 1-12 (index 0 repeats January)."""
    return np.array([f(1)] + [f(m) for m in range(1, 13)], dtype)


def sun_bin(az):
    """The degree of azimuth each sun position falls in."""
    return np.minimum(SUN_BINS - 1, ((np.asarray(az, float) % 360.0) / (360.0 / SUN_BINS)).astype(np.int64))


def minute_sun(E):
    """The sun every minute of every day of 2025 (UTC+3, each minute at its middle), while above the horizon:
    azimuth, elevation, tan(elevation), day of the year (0-364), month, day, local time (h), leaf state."""
    import datetime as _dt
    lat, lon = E["location"]["lat"], E["location"]["lon"]
    days = [_dt.date(2025, 1, 1) + _dt.timedelta(days=k) for k in range(365)]
    MO = np.repeat(np.array([d.month for d in days]), 1440)
    DD = np.repeat(np.array([d.day for d in days]), 1440)
    DAY = np.repeat(np.arange(365), 1440)
    TL = np.tile((np.arange(1440) + 0.5) / 60.0, 365)
    az, el = sun_np(2025, MO, DD, TL - 3.0, lat, lon)
    up = el > 0.0
    mo = MO[up]
    return dict(az=az[up], el=el[up], tau=np.tan(np.radians(el[up])), day=DAY[up], mo=mo, dd=DD[up], tl=TL[up],
                leaf=leaf_on_doy(DAY[up] + 1))


def tmy_offset_h(E):
    """Hours after the time stamp at which the typical year's irradiance applies (PVGIS: the satellite's time, about
    hh:10 UTC); the weather columns apply at the time stamp."""
    if E.get("tmy_offset_h") is not None:
        return float(E["tmy_offset_h"])
    return float(E.get("tmy_minute", 0)) / 60.0


def tmy_table(E):
    """Every hour of the typical year as columns (numpy), with the sun position at the irradiance time and the
    Perez split of the sky: beam (direct + circumsolar, W/m2 normal to the sun), isotropic and horizon-band diffuse."""
    if E.get("tmy_full"):
        cols, A = E["tmy_full_cols"], np.array(E["tmy_full"], float)
    else:
        cols = E.get("tmy_cols") or ["month", "day", "hour_utc", "minute_utc", "ghi", "dni", "dhi", "t2m"]
        A = np.array(E["tmy"], float)
    T = dict((c, A[:, k]) for k, c in enumerate(cols))
    lat, lon = E["location"]["lat"], E["location"]["lon"]
    mo = T["month"].astype(np.int64)
    dd = T["day"].astype(np.int64)
    hu = T["hour_utc"] + T.get("minute_utc", np.zeros(len(A))) / 60.0 + tmy_offset_h(E)
    az, el = sun_np(2021, mo, dd, hu, lat, lon)
    cum = np.concatenate([[0], np.cumsum(MONTH_DAYS)])
    doy = (cum[mo - 1] + dd).astype(float)
    zen = 90.0 - el
    dni, dhi, ghi = T["dni"], T["dhi"], T["ghi"]
    F1, F2 = perez_np(dhi, dni, zen, doy)
    Bv = np.maximum(math.cos(math.radians(85.0)), np.cos(np.radians(zen)))
    up = (el > 0.0) & (ghi > 0.0)
    T.update(mo=mo, dd=dd, az=az, el=el, tau=np.tan(np.radians(np.maximum(el, 0.0))), up=up,
             beam=np.where(up, dni + F1 * dhi / Bv, 0.0), iso=np.where(up, (1.0 - F1) * dhi, 0.0),
             hor=np.where(up, F2 * dhi, 0.0), local=np.round(T["hour_utc"] + 3.0).astype(np.int64) % 24,
             si=by_month(lambda m: SEASON_INDEX[SEASON_OF_MONTH[m]], np.int64)[mo],
             leaf=leaf_on_doy(doy))
    T["full"] = all(c in T for c in ("rh", "ws10", "wd10", "ir"))
    return T


def window_mask(T):
    """The hours of the comfort averaging window (input hours)."""
    kind, rng = hours_window()
    if kind == "daylight":
        return T["el"] > 0.0
    if kind == "all":
        return np.ones(T["el"].size, bool)
    h0, h1 = rng
    return ((T["local"] - h0) % 24) < (h1 - h0)


def days_in_season(key):
    return sum(MONTH_DAYS[m - 1] for m in [sd for sd in SEASONS if sd["key"] == key][0]["months"])


# ------------------------------------------------------------ integrals over the obstruction of one direction
def count_le(ts, x):
    """Number of sorted values ts <= x (x an array)."""
    return np.searchsorted(ts, x, side="right")


def _H(e):
    """int_0^e cos^2 x dx"""
    return e / 2.0 + np.sin(2.0 * e) / 4.0


def _Z(e):
    """int_0^e sin x cos x dx"""
    return np.sin(e) ** 2 / 2.0


def sky_terms(crit, segs, tom, eb=None):
    """For one sector: the blocked part of int cos e de (its solid angle), of int cos^2 e de (horizontal cosine
    weight) and of int sin e cos e de (vertical), terrain, buildings and crowns (by what they block, 1 - tau)
    together; with eb also the last two below elevation eb (the horizon band)."""
    ec = np.arctan(crit)
    out = [np.sin(ec), _H(ec), _Z(ec)]
    if eb is not None:
        ecb = np.minimum(ec, eb)
        out += [_H(ecb), _Z(ecb)]
    sc, slo, shi, sm = segs
    if sc.size:
        n = crit.size
        el_, eh_ = np.arctan(slo), np.arctan(shi)
        f = 1.0 - tom[sm]
        out[0] += np.bincount(sc, f * (np.sin(eh_) - np.sin(el_)), minlength=n)
        out[1] += np.bincount(sc, f * (_H(eh_) - _H(el_)), minlength=n)
        out[2] += np.bincount(sc, f * (_Z(eh_) - _Z(el_)), minlength=n)
        if eb is not None:
            elb, ehb = np.minimum(el_, eb), np.minimum(eh_, eb)
            out[3] += np.bincount(sc, f * (_H(ehb) - _H(elb)), minlength=n)
            out[4] += np.bincount(sc, f * (_Z(ehb) - _Z(elb)), minlength=n)
    return out


HOR_BAND = 12.0                   # deg: the horizon band of the Perez model (sky below 12 deg, as v15)


def sky_pass(G, C, want_k=False):
    """The sky each receiver sees, over 72 sectors of 5 degrees, integrated exactly in elevation: the sky view
    (share of the vault's solid angle) with crowns in and out of leaf, and with want_k the cosine-weighted sky vectors
    (isotropic diffuse on any tilt: n . K) and those of the horizon band. The ground's own slope hides the sky below
    its plane."""
    n = G.n
    ns = SKY_BINS
    dphi = 2.0 * math.pi / ns
    s2 = 2.0 * math.sin(dphi / 2.0)
    eb = math.radians(HOR_BAND) if want_k else None
    states = (True, False)
    toms = dict((lf, tau_mask_table(lf)) for lf in states)
    sa = dict((lf, np.zeros(n)) for lf in states)
    K = dict((lf, np.zeros((3, n))) for lf in states)
    KB = dict((lf, np.zeros((3, n))) for lf in states)
    KB0 = np.zeros((3, n))
    Hb = float(_H(eb)) if want_k else 0.0
    Zb = float(_Z(eb)) if want_k else 0.0
    def obstr(s):
        az = (s + 0.5) * 360.0 / ns
        return G.obstruction(C, az, tau_floor(G, C, az), self_shade=True)

    def use(s, r):                                        # v16.6: the sectors' obstructions found on parallel threads
        crit, segs, d = r
        az = (s + 0.5) * 360.0 / ns
        vx, vy = C.CP.vec(az)
        for lf in states:
            r = sky_terms(crit, segs, toms[lf], eb)
            sa[lf] += r[0]
            if want_k:
                h_ = math.pi / 4.0 - r[1]
                K[lf][0] += (s2 * vx) * h_
                K[lf][1] += (s2 * vy) * h_
                K[lf][2] += dphi * (0.5 - r[2])
                hb = Hb - r[3]
                KB[lf][0] += (s2 * vx) * hb
                KB[lf][1] += (s2 * vy) * hb
                KB[lf][2] += dphi * (Zb - r[4])
        if want_k:
            es = np.minimum(np.arctan(G.self_tau(d)), eb)
            hb = Hb - _H(es)
            KB0[0] += (s2 * vx) * hb
            KB0[1] += (s2 * vy) * hb
            KB0[2] += dphi * (Zb - _Z(es))
    par_ordered(obstr, range(ns), use)
    out = dict(svf=dict((lf, 1.0 - sa[lf] / ns) for lf in states))
    if want_k:
        out.update(K=dict((lf, K[lf] / math.pi) for lf in states), KB=dict((lf, KB[lf] / math.pi) for lf in states),
                   KB0=KB0 / math.pi)
    return out


class Binned(object):
    """Sun positions sorted by degree of azimuth, then group, then tan(elevation), with running sums of weights."""

    def __init__(self, b, g, tau, ng, wts=None):
        o = np.lexsort((tau, g, b))
        self.tau = np.asarray(tau, float)[o]
        self.ng = ng
        self.st = np.searchsorted(np.asarray(b)[o] * ng + np.asarray(g)[o], np.arange(SUN_BINS * ng + 1))
        self.cum = dict((k, np.concatenate([[0.0], np.cumsum(np.asarray(v, float)[o])])) for k, v in (wts or {}).items())

    def span(self, b, g):
        return int(self.st[b * self.ng + g]), int(self.st[b * self.ng + g + 1])

    def trange(self, b):
        a, z = int(self.st[b * self.ng]), int(self.st[(b + 1) * self.ng])
        if z <= a:
            return None
        t = self.tau[a:z]
        return float(t.min()), float(t.max())


class ShadeJob(object):
    """Minutes in shade, every minute the sun is up: of every day of the year (deciduous crowns in leaf between the
    measured leaf-out and leaf-fall days) and of the four key days; crowns count by what they block (1 - tau)."""

    def __init__(self, G, MS):
        n = G.n
        b = sun_bin(MS["az"])
        parts = [(b, np.where(MS["leaf"], 0, 1), MS["tau"])]
        self.days = []
        for k, sd in enumerate(SEASONS):
            mo, dd = sd["day"]
            m = (MS["mo"] == mo) & (MS["dd"] == dd)
            parts.append((b[m], np.full(int(m.sum()), 2 + k), MS["tau"][m]))
            tl = MS["tl"][m]
            self.days.append(dict(daylight=float(m.sum()) / 60.0,
                                  sunrise=(float(tl.min()) - 1.0 / 120.0) if tl.size else None,
                                  sunset=(float(tl.max()) + 1.0 / 120.0) if tl.size else None))
        self.bs = Binned(np.concatenate([p[0] for p in parts]), np.concatenate([p[1] for p in parts]),
                         np.concatenate([p[2] for p in parts]), 6)
        self.acc = np.zeros((6, n))
        self.toms = [tau_mask_table(True), tau_mask_table(False)] + [tau_mask_table(leaf_key(sd["key"])) for sd in SEASONS]
        self.year_daylight = MS["tau"].size / 60.0 / 365.0

    def trange(self, b):
        return self.bs.trange(b)

    def run(self, b, crit, segs):
        par_all([(lambda g_=g: self._run_g(b, g_, crit, segs)) for g in range(6)])   # v17: each g its own sum

    def _run_g(self, b, g, crit, segs):
        sc, slo, shi, sm = segs
        n = crit.size
        if True:
            a, z = self.bs.span(b, g)
            if z <= a:
                return
            ts = self.bs.tau[a:z]
            acc = self.acc[g]
            m = np.flatnonzero(crit >= ts[0])
            if m.size:
                acc[m] += count_le(ts, crit[m])
            if sc.size:
                k = count_le(ts, shi) - count_le(ts, slo)
                q = k > 0
                if q.any():
                    acc += np.bincount(sc[q], (1.0 - self.toms[g][sm[q]]) * k[q], minlength=n)


class RadJob(object):
    """Beam (direct + circumsolar) energy of every hour of the typical year, per season: running sums of beam x sun
    vector over the hours in each degree of azimuth, sorted by elevation; a receiver collects those its obstruction
    lets through (crowns by their transmission)."""

    def __init__(self, G, TT, CP):
        n = G.n
        idx = np.flatnonzero(TT["up"])
        az, el = TT["az"][idx], TT["el"][idx]
        r = np.radians(az)
        ce, se = np.cos(np.radians(el)), np.sin(np.radians(el))
        vx = np.sin(r) * CP.E[0] + np.cos(r) * CP.N[0]
        vy = np.sin(r) * CP.E[1] + np.cos(r) * CP.N[1]
        w = TT["beam"][idx]
        g = TT["si"][idx] * 2 + np.where(TT["leaf"][idx], 0, 1)
        self.bs = Binned(sun_bin(az), g, TT["tau"][idx], 8, dict(x=w * ce * vx, y=w * ce * vy, z=w * se))
        self.V = np.zeros((4, 3, n))
        self.toms = (tau_mask_table(True), tau_mask_table(False))

    def trange(self, b):
        return self.bs.trange(b)

    def run(self, b, crit, segs):
        par_all([(lambda si_=si: self._run_si(b, si_, crit, segs)) for si in range(4)])  # v17: each season its sum

    def _run_si(self, b, si_, crit, segs):
        sc, slo, shi, sm = segs
        n = crit.size
        for g in (2 * si_, 2 * si_ + 1):                 # the season's two groups, in their v16 order
            a, z = self.bs.span(b, g)
            if z <= a:
                continue
            si, tom = g // 2, self.toms[g % 2]
            ts = self.bs.tau[a:z]
            k = count_le(ts, crit)
            if sc.size:
                klo, khi = count_le(ts, slo), count_le(ts, shi)
                q = khi > klo
                f = 1.0 - tom[sm[q]]
            for ci, c in enumerate("xyz"):
                C_ = self.bs.cum[c]
                V = self.V[si, ci]
                V += C_[z] - C_[a + k]
                if sc.size and q.any():
                    V -= np.bincount(sc[q], f * (C_[a + khi[q]] - C_[a + klo[q]]), minlength=n)


PAR_THREADS = 0          # threads for the obstructions and sums (0: one per logical core, v17: all of them; 1: none)
PAR_MAX = 0              # v17 (Nil): every logical core the computer reports (0 = no cap; v16.6: at most 8)


def n_cores():
    """v17: the logical cores to use: all that the operating system reports (PAR_MAX caps it when set)."""
    try:
        n = max(1, int(os.cpu_count() or 1))
    except Exception:
        n = 1
    return min(n, PAR_MAX) if PAR_MAX and PAR_MAX > 0 else n


def _ram_gb():
    """v17: the computer's memory in GB (Windows, macOS, Linux), or None when it cannot be read."""
    try:
        if os.name == "nt":
            import ctypes

            class _MS(ctypes.Structure):
                _fields_ = [("dwLength", ctypes.c_ulong), ("dwMemoryLoad", ctypes.c_ulong),
                            ("ullTotalPhys", ctypes.c_ulonglong), ("ullAvailPhys", ctypes.c_ulonglong),
                            ("ullTotalPageFile", ctypes.c_ulonglong), ("ullAvailPageFile", ctypes.c_ulonglong),
                            ("ullTotalVirtual", ctypes.c_ulonglong), ("ullAvailVirtual", ctypes.c_ulonglong),
                            ("sullAvailExtendedVirtual", ctypes.c_ulonglong)]
            m = _MS()
            m.dwLength = ctypes.sizeof(_MS)
            ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(m))
            return m.ullTotalPhys / 1e9
        if hasattr(os, "sysconf") and "SC_PHYS_PAGES" in os.sysconf_names:
            return os.sysconf("SC_PHYS_PAGES") * os.sysconf("SC_PAGE_SIZE") / 1e9
        import subprocess
        return int(subprocess.check_output(["sysctl", "-n", "hw.memsize"]).strip()) / 1e9
    except Exception:
        return None


def big_grid_cap():
    """v17: threads for a big grid's sun pass (about 0.7 GB per obstruction in flight): as many as half the memory
    holds (v16.6: always 4)."""
    r = _ram_gb()
    return 4 if r is None else max(2, int(0.5 * r / 0.75))


def par_ordered(fn, items, use, cap=None):
    """v16.6: fn(item) for every item on several threads at once (numpy works outside Python's lock, so the
    obstructions of different sun azimuths run side by side), use(item, result) on this thread in the items' order,
    so every sum is added in the same order as before and the results are identical. At most threads + 1 results are
    held at a time (memory). Falls back to one thread if threads are not available."""
    import os as _os
    n = PAR_THREADS or n_cores()
    if cap:
        n = min(n, cap)
    items = list(items)
    if n > 1 and len(items) > 1:
        try:
            from concurrent.futures import ThreadPoolExecutor
            ex = ThreadPoolExecutor(n)
        except Exception:
            ex = None
        if ex is not None:
            try:
                pend = []
                k = 0
                while k < len(items) and len(pend) < n + 1:
                    pend.append((items[k], ex.submit(fn, items[k])))
                    k += 1
                while pend:
                    it, f = pend.pop(0)
                    r = f.result()
                    if k < len(items):
                        pend.append((items[k], ex.submit(fn, items[k])))
                        k += 1
                    use(it, r)
                    r = None
            finally:
                ex.shutdown(wait=True)
            return
    for it in items:
        use(it, fn(it))


PAR_JOBS = True          # v17: the sums of each sun degree on several threads too (False: on one thread, as v16.7)
_JOB_POOL = []
_JOB_TLS = _threading.local()


def par_all(fns):
    """v17: run independent pieces of work (each writing only its own sums) at once and wait for all of them; one
    after the other when threads are off. Each piece does exactly what it did before, in the same order, so the
    results are identical; only pieces that share no sum ever run side by side. v18: a piece that itself runs pieces
    (a job's own groups) uses a second set of threads, so no thread ever waits for a piece queued behind it (v17 could
    stall that way on a computer with 2 cores)."""
    fns = list(fns)
    if not PAR_JOBS or len(fns) < 2:
        for f in fns:
            f()
        return
    lev = getattr(_JOB_TLS, "level", 0)
    while len(_JOB_POOL) <= lev and lev < 2:
        try:
            from concurrent.futures import ThreadPoolExecutor
            _JOB_POOL.append(ThreadPoolExecutor(PAR_THREADS or n_cores()))
        except Exception:
            _JOB_POOL.append(None)
    ex = _JOB_POOL[lev] if lev < 2 else None
    if ex is None:
        for f in fns:
            f()
        return

    def run(f):
        _JOB_TLS.level = lev + 1
        try:
            f()
        finally:
            _JOB_TLS.level = lev
    futs = [ex.submit(run, f) for f in fns]
    for f in futs:
        f.result()


def sun_pass(G, C, jobs, log=None):
    """One obstruction per degree of sun azimuth, shared by every job (each integrates its own sun positions in that
    degree). Degrees whose every sun position lies below every terrain horizon need only the horizon. v16.6: the
    obstructions of several degrees are found at once on parallel threads (par_ordered); identical results, about
    3.3 times faster on 4 cores."""
    import time as _t
    t0 = _t.time()
    todo = []
    for b in range(SUN_BINS):
        rr = [r for r in (j.trange(b) for j in jobs) if r is not None]
        if not rr:
            continue
        todo.append((b, min(r[0] for r in rr), max(r[1] for r in rr)))

    def obstr(t):
        b, tmin, tmax = t
        az = (b + 0.5) * 360.0 / SUN_BINS
        hmin = tau_floor(G, C, az)
        return G.obstruction(C, az, max(tmin, hmin), self_shade=True, cheap=tmax <= hmin)

    def use(t, r):                                       # v17: the jobs (shade, comfort ...) side by side
        par_all([(lambda j_=j: j_.run(t[0], r[0], r[1])) for j in jobs])
    par_ordered(obstr, todo, use, cap=big_grid_cap() if G.n > 1000000 else None)    # big grids: ~0.7 GB each
    nb = len(todo)
    if log is not None:
        log.append(("sun pass", nb, _t.time() - t0))


# ------------------------------------------------------------ wind shelter (numpy)
WIND_BINS = 36                    # 10-degree sectors of the wind direction, centred on N, 10, 20 ... degrees


def wind_bin(wd):
    return np.round(np.asarray(wd, float) / (360.0 / WIND_BINS)).astype(np.int64) % WIND_BINS


def wind_rasters(solids, F, cell, pad):
    """Obstacle heights above their own ground on the frame's grid widened by pad cells on every side: buildings
    (footprints with their courtyards), evergreen crowns and deciduous crowns (discs of their measured radius)."""
    bl, gB, trees = solids
    nx, ny = int(math.ceil(F.w / cell)), int(math.ceil(F.h / cell))
    nxp, nyp = nx + 2 * pad, ny + 2 * pad
    u0, v0 = F.u0 - pad * cell, F.v0 - pad * cell
    R = pad * cell + 10.0
    fb = F.bb
    box = (fb[0] - R, fb[1] - R, fb[2] + R, fb[3] + R)
    groups, vals = [], []
    for b in bl:
        if not bb_hit(b["bb"], box):
            continue
        rings = [[F.local(x, y) for x, y in b["P"]]] + [[F.local(x, y) for x, y in h] for h in (b.get("holes") or ())]
        groups.append(rings)
        vals.append(b["H"])
    HB = footprint_values(groups, vals, u0, v0, cell, nxp, nyp)
    out = [np.maximum(HB, 0.0)]
    for ever in (True, False):
        tr = [t for t in trees if (t["kind"] in EVERGREEN) == ever and box[0] <= t["x"] <= box[2] and box[1] <= t["y"] <= box[3]]
        loc = [F.local(t["x"], t["y"]) for t in tr]
        H_ = disc_values([p[0] for p in loc], [p[1] for p in loc], [t["r"] for t in tr], [t["hi"] for t in tr],
                         u0, v0, cell, nxp, nyp)
        out.append(np.maximum(H_, 0.0))
    return np.stack(out).reshape(3, nyp, nxp).astype(np.float32)


def wake_np(curve, xh):
    xs = np.array([c[0] for c in curve])
    fs = np.array([c[1] for c in curve])
    return np.interp(xh, xs, fs, left=fs[0], right=1.0)


def shelter_all(solids, F, cell, C, idx, fetch=300.0):
    """Share of the open-ground wind left at the receivers idx for every wind sector, crowns in and out of leaf: the
    strongest wake of any building or crown upwind within the fetch (also beyond the frame), from the windbreak wake
    curves (Heisler & DeWalle 1988), at the obstacle's distance in its own heights."""
    nx, ny = int(math.ceil(F.w / cell)), int(math.ceil(F.h / cell))
    K = int(fetch / cell)
    pad = K + 1
    R3 = wind_rasters(solids, F, cell, pad)
    have = [bool(R3[q].any()) for q in range(3)]
    out = np.ones((WIND_BINS, 2, idx.size), np.float32)
    for k in range(WIND_BINS):
        ux, uy = C.dir_local(k * 360.0 / WIND_BINS)        # unit vector toward where the wind comes from
        Sm = np.zeros((3, ny, nx), np.float32)
        tmp = np.empty((3, ny, nx), np.float32)
        for st in range(1, K + 1):
            di, dj = int(round(st * ux)), int(round(st * uy))
            src = R3[:, pad + dj:pad + dj + ny, pad + di:pad + di + nx]
            np.multiply(src, np.float32(1.0 / (st * cell)), out=tmp)
            np.maximum(Sm, tmp, out=Sm)
        Sm = Sm.reshape(3, -1)[:, idx].astype(float)
        with np.errstate(divide="ignore"):
            xh = np.where(Sm > 0.0, 1.0 / np.where(Sm > 0.0, Sm, 1.0), np.inf)
        fB = wake_np(WAKE_SOLID, xh[0]) if have[0] else 1.0
        fE = wake_np(WAKE_LEAFY, xh[1]) if have[1] else 1.0
        fD_on = wake_np(WAKE_LEAFY, xh[2]) if have[2] else 1.0
        fD_off = wake_np(WAKE_BARE, xh[2]) if have[2] else 1.0
        base = np.minimum(fB, fE)
        out[k, 0] = np.minimum(base, fD_on)
        out[k, 1] = np.minimum(base, fD_off)
    return out


# ------------------------------------------------------------ felt temperature, hour by hour (numpy)
F_EFF = 0.725                     # SolarCal: fraction of the body's surface exchanging radiation (standing)
MRT_K = (0.7 / 0.95) / (F_EFF * 6.012)   # SolarCal: absorbed short-wave flux (W/m2) -> mean radiant temperature (K)
MRT_ALBEDO = 0.25
UTCI_EDGES = np.array([-40.0, -27.0, -13.0, 0.0, 9.0, 26.0, 32.0, 38.0, 46.0]) if HAVE_NP else None
UTCI_NAMES = ("extreme cold", "very strong cold", "strong cold", "moderate cold", "slight cold", "no thermal stress",
              "moderate heat", "strong heat", "very strong heat", "extreme heat")
_P7 = np.arange(7) if HAVE_NP else None


def es_hpa_np(t):
    """es_hpa for arrays (the same formula)."""
    g = (-2836.5744, -6028.076559, 19.54263612, -0.02737830188, 0.000016261698, 7.0229056e-10, -1.8680009e-13)
    tk = np.asarray(t, float) + 273.15
    es = 2.7150305 * np.log(tk)
    for k, c in enumerate(g):
        es = es + c * tk ** (k - 2)
    return np.exp(es) * 0.01


def utci_K(ta, pa):
    """For each hour: the UTCI polynomial (Broede et al. 2012) at that hour's air temperature and vapour pressure as a
    polynomial in wind (b) and mrt - ta (e), with its first and second derivatives in air temperature (the second
    halved): K[h, 0..2, b, e]. Exact rearrangements of the published coefficients."""
    ta = np.asarray(ta, float)
    pa = np.asarray(pa, float)
    H = ta.size
    TA = np.ones((H, 7))
    PA = np.ones((H, 7))
    for k in range(1, 7):
        TA[:, k] = TA[:, k - 1] * ta
        PA[:, k] = PA[:, k - 1] * pa
    K = np.zeros((H, 3, 7, 7))
    for c, a, b, e, f in UTCI_COEF:
        K[:, 0, b, e] += c * TA[:, a] * PA[:, f]
        if a > 0:
            K[:, 1, b, e] += (c * a) * TA[:, a - 1] * PA[:, f]
        if a > 1:
            K[:, 2, b, e] += (c * a * (a - 1) / 2.0) * TA[:, a - 2] * PA[:, f]
    return K


def utci_eval(Kh, va, D, dl, dv=0.1, dd=0.25):
    """UTCI of many points of one hour: the hour's polynomial tabulated over the wind (0.1 m/s) and mrt - ta (0.25 K)
    present in that hour and read bilinearly, corrected to each point's own air temperature (dl: its difference from
    the hour's, a fraction of a kelvin) to second order. Within 0.01 K of the polynomial."""
    v0 = 0.5
    nv = int((float(va.max()) - v0) / dv) + 2
    d0 = math.floor(float(D.min()))
    nd = int((float(D.max()) - d0) / dd) + 2
    Vp = (v0 + np.arange(nv) * dv)[:, None] ** _P7
    Dp = (d0 + np.arange(nd) * dd)[:, None] ** _P7
    T0, T1, T2 = [(Vp @ Kh[q] @ Dp.T).ravel() for q in range(3)]
    fp_ = (va - v0) * (1.0 / dv)
    p = np.minimum(nv - 2, fp_.astype(np.int64))
    a = fp_ - p
    fq = (D - d0) * (1.0 / dd)
    q = np.minimum(nd - 2, fq.astype(np.int64))
    b = fq - q
    i = p * nd + q
    out = None
    for j, w in ((i, (1.0 - a) * (1.0 - b)), (i + nd, a * (1.0 - b)), (i + 1, (1.0 - a) * b), (i + nd + 1, a * b)):
        V = T2[j]
        V *= dl
        V += T1[j]
        V *= dl
        V += T0[j]
        V *= w
        out = V if out is None else out + V
    return out


def proj_np(alt):
    return np.interp(np.clip(alt, 0.0, 90.0), np.arange(19) * 5.0, np.array(FP_STAND))


class ComfortJob(object):
    """Felt temperature (UTCI) every hour of the averaging window on every open receiver: air temperature at the
    receiver's height, wind of that hour's sector through the shelter of the buildings and crowns upwind, mean radiant
    temperature from SolarCal with the receiver's sun (from the obstruction of that hour's sun azimuth) and sky view.
    Summed per season: mean UTCI, hours in sun, the stress categories, the mean by hour of the day."""

    def __init__(self, G, TT, win, svf, shel):
        self.idx = np.flatnonzero(G.open)
        no = self.idx.size
        self.no = no
        self.svf = dict((lf, svf[lf][self.idx]) for lf in (True, False))
        self.shel = shel
        self.dl = LAPSE * (G.zair[self.idx] - CLIMATE["elevation"])
        self.wf = None if G.wf is None else G.wf[self.idx]
        hrs = np.flatnonzero(win)
        self.hrs = hrs
        ta, rh, ir = TT["t2m"], TT["rh"], TT["ir"]
        el = TT["el"]
        self.ta, self.u10 = ta, TT["ws10"]
        self.wb = wind_bin(TT["wd10"])
        self.leaf, self.si, self.local = TT["leaf"], TT["si"], TT["local"]
        self.tau = TT["tau"]
        self.pa = es_hpa_np(ta) * rh / 1000.0
        sun = el >= 2.0
        self.c1 = np.where(sun, MRT_K * proj_np(el) * TT["dni"], 0.0)
        self.c2 = np.where(sun, MRT_K * 0.5 * F_EFF * (TT["dhi"] + TT["ghi"] * MRT_ALBEDO), 0.0)
        tsky = (np.maximum(1.0, ir) / (0.95 * 5.6697e-8)) ** 0.25 - 273.15
        self.B = self.c2 + 0.5 * (tsky - ta)
        self.K = utci_K(ta, self.pa)
        sh = hrs[sun[hrs] & (TT["dni"][hrs] > 0.0)]
        self.dark = np.setdiff1d(hrs, sh)
        bb = sun_bin(TT["az"][sh])
        o = np.lexsort((self.tau[sh], bb))
        self.sh, self.sh_b = sh[o], bb[o]
        self.st = np.searchsorted(self.sh_b, np.arange(SUN_BINS + 1))
        self.pos = np.full(G.n, -1, np.int64)
        self.pos[self.idx] = np.arange(no)
        self.toms = {True: tau_mask_table(True), False: tau_mask_table(False)}
        self.su = np.zeros((4, no))
        self.sT = np.zeros((4, no))
        self.nh = np.zeros(4, np.int64)
        self.hist = np.zeros((4, 10))
        self.split = np.zeros((4, 4))                         # sum and count in sun, sum and count in shade
        self.lh = np.zeros((4, 24, 2))                        # by local hour: sum of the site means, hours
        self.nc = np.zeros((4, no))                           # v33: hours with no thermal stress, UTCI 9 to 26 °C
        self.nz = np.zeros((4, no))                           # v33: hours in the 18 to 26 °C part of that band

    def trange(self, b):
        a, z = int(self.st[b]), int(self.st[b + 1])
        if z <= a:
            return None
        return float(self.tau[self.sh[a]]), float(self.tau[self.sh[z - 1]])

    def run(self, b, crit, segs):
        a, z = int(self.st[b]), int(self.st[b + 1])
        if z <= a:
            return
        co = crit[self.idx]
        sc, slo, shi, sm = segs
        ps = self.pos[sc] if sc.size else sc
        k = ps >= 0
        ps, slo, shi, sm = ps[k], slo[k], shi[k], sm[k]
        def one(h):
            tau = self.tau[h]
            T = (tau > co).astype(float)
            if ps.size:
                m = (slo < tau) & (shi >= tau)
                if m.any():
                    T[ps[m]] = self.toms[bool(self.leaf[h])][sm[m]]
            return T, self.felt(h, T)
        # v17: the hours' felt temperatures on several threads, their sums added here in the hours' order
        self._hours(list(self.sh[a:z]), one)

    def finish(self):
        self._hours(list(self.dark), lambda h: (None, self.felt(h, None)))

    def _hours(self, hs, one):
        if PAR_JOBS:
            par_ordered(one, hs, lambda h, r: self.hour(h, r[0], r[1]))
        else:
            for h in hs:
                T, U = one(h)
                self.hour(h, T, U)

    def felt(self, h, T):
        """UTCI of every open receiver in hour h (T: its sun, 0..1; None: no direct sun)."""
        lf = bool(self.leaf[h])
        sv = self.svf[lf]
        sh = self.shel[self.wb[h], 0 if lf else 1]
        va = np.clip(self.u10[h] * (sh if self.wf is None else sh * self.wf), 0.5, 17.0)
        D = sv * (self.B[h] - 0.5 * self.dl)
        if T is not None:
            D = D + self.c1[h] * T
        return utci_eval(self.K[h], va, D, self.dl)

    def hour(self, h, T, U=None):
        if U is None:
            U = self.felt(h, T)
        si = self.si[h]
        self.su[si] += U
        self.nh[si] += 1
        ge = [U.size] + [np.count_nonzero(U >= e) for e in UTCI_EDGES] + [0]
        self.hist[si] += [ge[k] - ge[k + 1] for k in range(10)]
        self.nc[si] += (U >= 9.0) & (U < 26.0)                # the histogram's own band edges (UTCI_EDGES)
        self.nz[si] += (U >= 18.0) & (U < 26.0)
        if T is not None:                                     # an hour with direct sun: in sun or in shade
            self.sT[si] += T
            ins = T > 0.5
            ns_ = int(ins.sum())
            us = float(U[ins].sum()) if ns_ else 0.0
            self.split[si] += (us, ns_, float(U.sum()) - us, U.size - ns_)
        self.lh[si, self.local[h]] += (float(U.mean()), 1)


# ------------------------------------------------------------ the analyses of one frame
def env16_frame(S, E, solids, F, cell=3.0, want_shade=True, want_comfort=True, log=None):
    """Shade (key days and the mean day of the year) and the felt-temperature, wind and air-temperature means of
    every season over the averaging window, on one grid of the frame: one obstruction per degree of sun azimuth
    serves both."""
    import time as _t
    log = log if log is not None else []
    t0 = _t.time()
    C = Casters16(S, E, solids, F)
    G = Grid16(S, F, cell, C)
    log.append(("grid", G.nx * G.ny, _t.time() - t0))
    TT = tmy_table(E)
    jobs = []
    SJ = CJ = None
    if want_shade:
        SJ = ShadeJob(G, minute_sun(E))
        jobs.append(SJ)
    if want_comfort:
        t1 = _t.time()
        sky = sky_pass(G, C)
        log.append(("sky", SKY_BINS, _t.time() - t1))
        t1 = _t.time()
        idx = np.flatnonzero(G.open)
        shel = shelter_all(solids, F, cell, C, idx)
        log.append(("shelter", WIND_BINS, _t.time() - t1))
        win = window_mask(TT)
        CJ = ComfortJob(G, TT, win, sky["svf"], shel)
        jobs.append(CJ)
    sun_pass(G, C, jobs, log)
    out = dict(cell=cell, nx=G.nx, ny=G.ny, frame=list(F.P), open=G.open.copy(), z=G.z.astype(np.float32))
    if SJ is not None:
        days = {}
        for k, sd in enumerate(SEASONS):
            h = (SJ.acc[2 + k] / 60.0).astype(np.float32)
            h[~G.open] = np.nan
            days[sd["key"]] = dict(SJ.days[k], hours=h)
        yr = ((SJ.acc[0] + SJ.acc[1]) / 60.0 / 365.0).astype(np.float32)
        yr[~G.open] = np.nan
        out["shade"] = dict(days=days, year=dict(hours=yr, daylight=SJ.year_daylight))
    if CJ is not None:
        t1 = _t.time()
        CJ.finish()
        log.append(("dark hours", CJ.dark.size, _t.time() - t1))
        out["comfort"] = comfort_results(G, TT, win, CJ, sky["svf"], shel)
    log.append(("frame total", 0, _t.time() - t0))
    return out


def comfort_results(G, TT, win, CJ, svf, shel):
    """Per season over the window hours: mean UTCI, air temperature, wind at head height and share of the hours in
    direct sun on every open receiver; the stress categories over all open receiver-hours; the climate of those hours
    (rose, typical day)."""
    n = G.nx * G.ny
    idx = CJ.idx
    res = dict(window=hours_window(), label=window_label(), label_short=window_label(True), seasons={})
    ta, u10, wd = TT["t2m"], TT["ws10"], TT["wd10"]
    for si, sd in enumerate(SEASONS):
        hs = np.flatnonzero(win & (TT["si"] == si))
        N = max(1, hs.size)

        def grid(v):
            g = np.full(n, np.nan, np.float32)
            g[idx] = v
            return g
        W = np.zeros((WIND_BINS, 2))
        np.add.at(W, (wind_bin(wd[hs]), np.where(TT["leaf"][hs], 0, 1)), u10[hs])
        uped = np.zeros(idx.size)
        for k, l in zip(*np.nonzero(W)):
            uped += W[k, l] * shel[k, l]
        uped *= PED_WIND / N
        sun_h = int(((TT["el"][hs] >= 2.0) & (TT["dni"][hs] > 0.0)).sum())
        sp = CJ.split[si]
        # the climate of the window hours: wind rose (16 sectors x the classes of CLIMATE), typical day
        cls = CLIMATE["classes"]
        rose = np.zeros((16, len(cls)))
        calm = 0
        for h in hs:
            if u10[h] < cls[0]:
                calm += 1
                continue
            k = int(round(wd[h] / 22.5)) % 16
            c = max(q for q in range(len(cls)) if u10[h] >= cls[q])
            rose[k, c] += 1
        allh = np.flatnonzero(TT["si"] == si)
        day = []
        for lh in range(24):
            q = allh[TT["local"][allh] == lh]
            v = np.sort(ta[q])
            day.append((float(v.mean()), float(v[int(0.1 * (v.size - 1))]), float(v[int(0.9 * (v.size - 1))])) if v.size else (None, None, None))
        res["seasons"][sd["key"]] = dict(
            hours=int(hs.size), sun_hours=sun_h,
            utci=grid(CJ.su[si] / N), sun=grid(CJ.sT[si] / max(1, sun_h)), ta=grid(float(ta[hs].mean()) + CJ.dl),
            uped=grid(uped), hist=CJ.hist[si].tolist(),
            utci_sun=(sp[0] / sp[1]) if sp[1] else None, utci_shade=(sp[2] / sp[3]) if sp[3] else None,
            by_hour=[((CJ.lh[si, k, 0] / CJ.lh[si, k, 1]) if CJ.lh[si, k, 1] else None) for k in range(24)],
            ta_mean=float(ta[hs].mean()) if hs.size else None, rh_mean=float(TT["rh"][hs].mean()) if hs.size else None,
            u10_mean=float(u10[hs].mean()) if hs.size else None,
            rose=(rose / N).tolist(), calm=calm / float(N), day=day)
    # v33 (T8): the whole year's window hours on every open receiver, the share with no thermal stress
    Ny = sum(res["seasons"][sd["key"]]["hours"] for sd in SEASONS)
    if Ny:
        def ygrid(v):
            g = np.full(n, np.nan, np.float32)
            g[idx] = v
            return g
        res["year"] = dict(hours=int(Ny), comfort=ygrid(100.0 * CJ.nc.sum(0) / Ny),
                           comfort18=ygrid(100.0 * CJ.nz.sum(0) / Ny), utci=ygrid(CJ.su.sum(0) / Ny),
                           share={sd["key"]: 100.0 * float(CJ.nc[si].mean()) / max(1, res["seasons"][sd["key"]]["hours"])
                                  for si, sd in enumerate(SEASONS)})
    return res


def rad_totals(G, TT, sky, RJ):
    """Mean kWh/m2 per day of each season on every receiver: direct and circumsolar collected through its obstruction
    (RadJob), isotropic sky through its cosine-weighted sky (n . K), the horizon band on tilted surfaces and the
    ground's reflection, from every hour of the typical year."""
    nwx, nwy, nz = G.nwx, G.nwy, G.nz
    sinb = np.sqrt(np.maximum(0.0, 1.0 - nz * nz))
    out = {}
    for si, sd in enumerate(SEASONS):
        up = TT["up"] & (TT["si"] == si)
        V = RJ.V[si]
        tot = nwx * V[0] + nwy * V[1] + nz * V[2]
        for lf in (True, False):
            mm = up & (TT["leaf"] == lf)
            if not mm.any():
                continue
            K, KB, KB0 = sky["K"][lf], sky["KB"][lf], sky["KB0"]
            kiso = np.maximum(0.0, nwx * K[0] + nwy * K[1] + nz * K[2])
            nb = nwx * KB[0] + nwy * KB[1] + nz * KB[2]
            nb0 = nwx * KB0[0] + nwy * KB0[1] + nz * KB0[2]
            khor = np.where(nb0 > 1e-9, sinb * np.clip(nb / np.where(nb0 > 1e-9, nb0, 1.0), 0.0, 1.0), 0.0)
            tot = tot + float(TT["iso"][mm].sum()) * kiso + float(TT["hor"][mm].sum()) * khor
        tot = tot + ALBEDO * float(TT["ghi"][up].sum()) * (1.0 - nz) / 2.0
        out[sd["key"]] = tot / days_in_season(sd["key"]) / 1000.0
    return out


def env16_focus(S, E, solids, F, cell=1.5, log=None):
    """Incident solar radiation on the ground and on every roof of the focus area, mean kWh/m2 per day of each season:
    every hour of the typical year, direct + circumsolar through the obstruction of its sun position, isotropic
    diffuse through the cosine-weighted sky each receiver sees, Perez horizon band and ground reflection on slopes."""
    import time as _t
    log = log if log is not None else []
    t0 = _t.time()
    C = Casters16(S, E, solids, F)
    G = Grid16(S, F, cell, C, roofs=True)
    TT = tmy_table(E)
    t1 = _t.time()
    sky = sky_pass(G, C, want_k=True)
    log.append(("focus sky", SKY_BINS, _t.time() - t1))
    RJ = RadJob(G, TT, C.CP)
    sun_pass(G, C, [RJ], log)
    vals = rad_totals(G, TT, sky, RJ)
    seasons = {}
    yr = np.zeros(G.n)
    for sd in SEASONS:
        nd = days_in_season(sd["key"])
        v = vals[sd["key"]].astype(np.float32)
        yr += vals[sd["key"]] * nd
        up = TT["up"] & (TT["si"] == SEASON_INDEX[sd["key"]])
        seasons[sd["key"]] = dict(kwh=v, ghi=float(TT["ghi"][up].sum()) / nd / 1000.0,
                                  ground_mean=float(np.mean(v[G.open])) if G.open.any() else None,
                                  roof_mean=float(np.mean(v[G.inside])) if G.inside.any() else None)
    yr /= 365.0
    out = dict(cell=cell, nx=G.nx, ny=G.ny, frame=list(F.P), roof=G.inside.copy(), seasons=seasons,
               year=yr.astype(np.float32), ghi_year=float(TT["ghi"][TT["up"]].sum()) / 365.0 / 1000.0,
               svf=sky["svf"][True].astype(np.float32))
    log.append(("focus total", G.nx * G.ny, _t.time() - t0))
    return out


class TerrainRaster(TRCore):
    """The survey terrain sampled every 5 m over a box (numpy, the exact z_at values at the nodes), read
    bilinearly: the ground under a sound path. With a frame F and a reach pad only the nodes within pad of the frame
    (plus two cells, for the bilinear reads at its edge) are computed: a sound path runs from a receiver in the frame
    to a road piece at most R away, so it never leaves the frame grown by R; the corners of a turned frame's box
    lie far from every survey sample and cost most of the time."""

    def __init__(self, S, box, cell=5.0, F=None, pad=None):
        self.x0, self.y0, self.c = box[0], box[1], cell
        self.nx = int(math.ceil((box[2] - box[0]) / cell)) + 1
        self.ny = int(math.ceil((box[3] - box[1]) / cell)) + 1
        X = self.x0 + np.arange(self.nx) * cell
        Y = self.y0 + np.arange(self.ny) * cell
        XX, YY = np.meshgrid(X, Y)
        xs, ys = XX.ravel(), YY.ravel()
        Z = np.zeros(xs.size)
        if F is not None and pad is not None:
            uu, vv = f_local(F, xs, ys)
            g = pad + 2.0 * cell
            need = (uu >= F.u0 - g) & (uu <= F.u1 + g) & (vv >= F.v0 - g) & (vv <= F.v1 + g)
        else:
            need = np.ones(xs.size, bool)
        Z[need] = z_np(S, xs[need], ys[need])
        self.Z = Z.reshape(self.ny, self.nx).tolist()


NOISE_TOUCH = 0.5        # m: v16.4: buildings closer than this (party walls, shared gables) are one block for the sound
#                          that bends around a building's sides: the way round goes round the whole block


def noise_blocks(bl, grid):
    """v16.4: the buildings that touch (within NOISE_TOUCH) joined into blocks, each block's convex hull kept on its
    buildings as b["_hull"] (counter-clockwise): the outline sound has to bend around at the block's ends."""
    par = list(range(len(bl)))

    def root(i):
        while par[i] != i:
            par[i] = par[par[i]]
            i = par[i]
        return i
    idx = dict((id(b), k) for k, b in enumerate(bl))
    t2 = NOISE_TOUCH * NOISE_TOUCH

    def near(P, Q):
        n = len(Q)
        for px, py in P:
            for q in range(n):
                ax, ay = Q[q]
                bx, by = Q[(q + 1) % n]
                dx, dy = bx - ax, by - ay
                L2 = dx * dx + dy * dy
                t = 0.0 if L2 <= 0.0 else max(0.0, min(1.0, ((px - ax) * dx + (py - ay) * dy) / L2))
                ex, ey = ax + dx * t - px, ay + dy * t - py
                if ex * ex + ey * ey <= t2:
                    return True
        return False
    for k, b in enumerate(bl):
        bb = b["bb"]
        for c in grid.query((bb[0] - NOISE_TOUCH, bb[1] - NOISE_TOUCH, bb[2] + NOISE_TOUCH, bb[3] + NOISE_TOUCH)):
            j = idx.get(id(c))
            if j is None or j <= k:
                continue
            cb = c["bb"]
            if cb[0] > bb[2] + NOISE_TOUCH or cb[2] < bb[0] - NOISE_TOUCH or cb[1] > bb[3] + NOISE_TOUCH or \
                    cb[3] < bb[1] - NOISE_TOUCH:
                continue
            if root(k) != root(j) and (near(b["P"], c["P"]) or near(c["P"], b["P"]) or pip(c["P"][0][0], c["P"][0][1], b["P"])):
                par[root(k)] = root(j)
    groups = {}
    for k in range(len(bl)):
        groups.setdefault(root(k), []).append(bl[k])
    for g_ in groups.values():
        H = convex_hull([tuple(p) for b in g_ for p in b["P"]])
        for b in g_:
            b["_hull"] = H
    return len(groups)


class NoiseModel(NoiseCore):
    """Road traffic noise at any receiver: RLS-90 emission per road piece (noise_sources), segment method with
    divergence and air absorption over the 3D distance, ground (Dbm) and building screening (Dz). In each of 36 directions the buildings
    crossed by the ray are taken in order up to the first one whose roof reaches the receiver's height; the most
    effective of them screens each source behind it. The plan map (receivers 4 m above ground) and the sections
    (receivers at every height) use this same model. v16.4: a building block screens by the way over its roof AND the
    two ways round its sides (lateral diffraction, ISO 9613-2 7.4), combined by energy: a detached house no longer
    casts a sharp, deep sound shadow as if it were an endless wall (lateral_db)."""

    def __init__(self, S, solids, R=300.0, h_src=0.5, nbin=36):
        self.S, self.R, self.h_src, self.nbin = S, R, h_src, nbin
        bl = solids[0]
        src = noise_sources(S)
        gS = Grid(50.0)
        for s in src:
            mx, my = (s["a"][0] + s["b"][0]) / 2.0, (s["a"][1] + s["b"][1]) / 2.0
            s["m"] = (mx, my)
            s["lgL"] = 10.0 * math.log10(s["L"])
            s["zs"] = s["z"] + h_src
            gS.add(s, (mx, my, mx, my))
        gR = Grid(15.0)
        for b in bl:
            gR.add(b, b["bb"])
        self.src, self.gS, self.gR = src, gS, gR
        self.n_blocks = noise_blocks(bl, gR)
        self.wbin = 2.0 * math.pi / nbin
        fb = S.F.bb
        self.TR = TerrainRaster(S, (fb[0] - R - 20.0, fb[1] - R - 20.0, fb[2] + R + 20.0, fb[3] + R + 20.0), F=S.F,
                                pad=R + 20.0)


# ------------------------------------------------------------ v17: the sound model on every core
# Rhino's Python runs Python code on one core at a time (its global lock), so threads cannot speed up the sound model,
# which is plain Python. v17 hands the receivers to separate worker processes of Rhino 8's own Python (the python
# executable Rhino installs under .rhinocode, the same version as Rhino's), one per core. Each worker runs the same
# code (NOISE_KERNEL) on the same data, and every receiver is computed whole by one worker, so the levels are the
# same numbers, to the last digit, as computing them one by one in Rhino:
#   * the worker's Python must give exactly the same results as Rhino's on a battery of the maths it uses
#     (_math_probe), and
#   * the first receivers of every worker are also computed in Rhino and must match exactly;
# otherwise, or when no worker Python is found or anything fails, everything is computed in Rhino as in v16.7, and
# the log says why.
PAR_PROCS = 0              # v17: worker processes for the sound model: 0 = one per core, 1 = none (as v16.7)
PY_WORKER = ""             # v17: a python executable to use for them ("" = Rhino 8's own, found by itself)
_NOISE_PY = {}


def _cores():
    return n_cores()


def _py_candidates():
    import sys
    home = os.path.expanduser("~")
    c = []
    if PY_WORKER:
        c.append(PY_WORKER)
    exe = getattr(sys, "executable", "") or ""
    if os.path.basename(exe).lower().startswith("python"):
        c.append(exe)
    base = getattr(sys, "base_prefix", "") or getattr(sys, "prefix", "")
    for b in (base, os.path.join(home, ".rhinocode", "py39-rh8")):
        if b:
            c += [os.path.join(b, "python.exe"), os.path.join(b, "bin", "python3"), os.path.join(b, "bin", "python3.9"),
                  os.path.join(b, "python3"), os.path.join(b, "bin", "python")]
    out = []
    for x in c:
        if x and x not in out and os.path.isfile(x):
            out.append(x)
    return out


def _kernel_file():
    import tempfile, hashlib
    h = hashlib.sha1(NOISE_KERNEL.encode("utf-8")).hexdigest()[:12]
    d = os.path.join(tempfile.gettempdir(), "selinus_workers")
    if not os.path.isdir(d):
        os.makedirs(d)
    f = os.path.join(d, "selinus_noise_kernel_%s.py" % h)
    if not os.path.isfile(f):
        with open(f + ".tmp", "w", encoding="utf-8") as fh:
            fh.write(NOISE_KERNEL + "\n\nif __name__ == '__main__':\n    import sys\n    _noise_worker_main(sys.argv)\n")
        os.replace(f + ".tmp", f)
    return f, d


def _popen_kw():
    kw = {}
    if os.name == "nt":
        kw["creationflags"] = 0x08000000             # no console window per worker
    return kw


def noise_worker_python():
    """The python executable the sound workers use, or None (with the reason in _NOISE_PY["why"])."""
    if "py" in _NOISE_PY:
        return _NOISE_PY["py"]
    import subprocess
    _NOISE_PY["py"], _NOISE_PY["why"] = None, "no python executable found beside Rhino"
    try:
        kf, _ = _kernel_file()
    except Exception as ex:
        _NOISE_PY["why"] = "cannot write to the temp folder ({})".format(ex)
        return None
    want = _math_probe()
    for py in _py_candidates():
        try:
            r = subprocess.run([py, "-I", kf, "--probe"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120,
                               **_popen_kw())
            got = r.stdout.decode("utf-8", "replace").strip()
            if r.returncode == 0 and got == want:
                _NOISE_PY["py"], _NOISE_PY["why"] = py, ""
                return py
            _NOISE_PY["why"] = "{} does not compute exactly like Rhino's Python".format(py)
        except Exception as ex:
            _NOISE_PY["why"] = "{} could not be started ({})".format(py, type(ex).__name__)
    return None


def _noise_model_data(NM):
    """The sound model as plain data (lists, dicts, numbers) for the workers: only what a receiver reads."""
    b_ = {}
    gR = {}
    for k, lst in NM.gR.d.items():
        row = []
        for b in lst:
            sb = b_.get(id(b))
            if sb is None:
                sb = dict(P=b["P"], bb=b["bb"], top=b["top"])
                if b.get("holes") is not None:
                    sb["holes"] = b["holes"]
                if "_hull" in b:
                    sb["_hull"] = b["_hull"]
                sb = b_[id(b)] = sb
            row.append(sb)
        gR[k] = row
    s_ = {}
    gS = {}
    for k, lst in NM.gS.d.items():
        row = []
        for s in lst:
            ss = s_.get(id(s))
            if ss is None:
                ss = s_[id(s)] = dict(m=s["m"], L=s["L"], zs=s["zs"], z=s["z"], em=s["em"], lgL=s["lgL"])
            row.append(ss)
        gS[k] = row
    T = NM.TR
    return dict(R=NM.R, wbin=NM.wbin, TR=(T.x0, T.y0, T.c, T.nx, T.ny, T.Z), gS=(NM.gS.c, gS), gR=(NM.gR.c, gR))


def noise_par_start(NM, tasks, mode, label):
    """Hand the receivers to the worker processes and return at once (they run while Rhino works on other
    analyses); noise_par_collect waits for them. Without workers nothing starts here and collect computes in Rhino."""
    import pickle, subprocess
    import time as _tm
    h = dict(NM=NM, tasks=tasks, mode=mode, label=label, procs=[], files=[], t0=_tm.time(), err=None)
    n = min(_cores() if PAR_PROCS <= 0 else int(PAR_PROCS), len(tasks) // 8)
    py = noise_worker_python() if n >= 2 else None
    if py is None:
        if n >= 2:
            h["err"] = "computed on one core: {}".format(_NOISE_PY.get("why", ""))
        return h
    try:
        kf, d = _kernel_file()
        tag = "%d_%d_%s" % (os.getpid(), int(h["t0"] * 1000) % 100000000, mode)
        mf = os.path.join(d, "model_%s.bin" % tag)
        md = getattr(NM, "_par_data", None)
        if md is None:
            md = NM._par_data = pickle.dumps(_noise_model_data(NM), protocol=4)
        with open(mf, "wb") as fh:
            fh.write(md)
        h["files"].append(mf)
        parts = [list(range(w, len(tasks), n)) for w in range(n)]      # interleaved: every worker gets a fair share
        for w, idx in enumerate(parts):
            tf, of = os.path.join(d, "tasks_%s_%d.bin" % (tag, w)), os.path.join(d, "out_%s_%d.bin" % (tag, w))
            with open(tf, "wb") as fh:
                pickle.dump((mode, [tasks[i] for i in idx]), fh, protocol=4)
            h["files"] += [tf, of]
            h["procs"].append((subprocess.Popen([py, "-I", kf, mf, tf, of], stdout=subprocess.DEVNULL,
                                                stderr=subprocess.PIPE, **_popen_kw()), of, idx))
        h["n"] = n
    except Exception as ex:
        _noise_par_stop(h)
        h["procs"], h["err"] = [], "worker processes not used ({}: {}); computed on one core".format(type(ex).__name__, ex)
    return h


def _noise_par_stop(h):
    for pr, _, _ in h["procs"]:
        try:
            if pr.poll() is None:
                pr.kill()
        except Exception:
            pass
    for f_ in h["files"]:
        try:
            os.remove(f_)
        except Exception:
            pass


def noise_par_collect(h):
    import pickle
    import time as _tm
    NM, tasks, label = h["NM"], h["tasks"], h["label"]
    fn = NM.column_multi if h["mode"] == "multi" else NM.column
    if not h["procs"]:
        if h["err"]:
            LOG.append("Sound {}: {}.".format(label, h["err"]))
        return [fn(*t) for t in tasks]
    try:
        # Rhino computes the first receiver of every worker itself: the check
        check = dict((idx[0], fn(*tasks[idx[0]])) for _, _, idx in h["procs"] if idx)
        out = [None] * len(tasks)
        for pr, of, idx in h["procs"]:
            err = pr.communicate()[1]
            if pr.returncode != 0:
                last = err.decode("utf-8", "replace").strip().splitlines()[-1:] if err else []
                raise RuntimeError("a worker stopped" + (": " + last[0] if last else ""))
            with open(of, "rb") as fh:
                res = pickle.load(fh)
            if len(res) != len(idx):
                raise RuntimeError("a worker returned {} of {} receivers".format(len(res), len(idx)))
            for i, r in zip(idx, res):
                out[i] = r
        bad = [i for i, r in check.items() if r != out[i]]
        if bad:
            raise RuntimeError("{} checked receiver(s) differ from Rhino's own result".format(len(bad)))
        LOG.append("Sound {}: {} receivers on {} worker processes (checked against Rhino).".format(
            label, len(tasks), h["n"]))
        return out
    except Exception as ex:
        LOG.append("Sound {}: worker processes not used ({}: {}); computed on one core.".format(
            label, type(ex).__name__, ex))
        _noise_par_stop(h)
        return [fn(*t) for t in tasks]
    finally:
        _noise_par_stop(h)


def noise_par(NM, tasks, mode, label):
    """NM.column(*t) (mode "col") or NM.column_multi(*t) (mode "multi") for every task, in order, on the worker
    processes when that is possible and checked; in Rhino otherwise. The results are the same either way."""
    return noise_par_collect(noise_par_start(NM, tasks, mode, label))


# ------------------------------------------------------------ v18: worker processes for the one-core stages
# Rhino's Python runs one Python thread at a time, so stages written in plain Python (terrain heights, the section
# drawings) used one core in v17 however many the computer has. v18 hands them to worker processes: Rhino 8's own
# Python running THIS script's own code (everything above the main block, read from the component), so every number
# is made by the same code on the same Python and numpy. Each worker must report the same bytecode for every
# function, the same maths fingerprint and the same numpy as Rhino before it gets any work, and Rhino computes the
# first piece of every job itself and compares it bit for bit with the worker's. On any difference, error or missing
# piece the job is computed in Rhino as in v17 and the workers are not used again in that run (LOG says why).
PAR_POOL = True            # v18: worker processes for the one-core stages (False: in Rhino, as v17)
POOL_MIN_PTS = 60000       # v18: terrain heights of at least this many points go to the workers
POOL_START_S = 120.0       # v18: a worker that has not started within this many seconds: none are used
POOL_KEY = "\nLAYOUT = str(inp(\"layout\""        # the start of the main block: the workers run everything above it
_POOL = {}                 # this run's workers (filled by pool_start, emptied by pool_stop)
_POOL_DATA = {}            # data handed to the workers once per run (pool_share); in Rhino the same objects
_POOL_SHARE = {}           # key -> (version, the message that hands it over)
_NS_MOD = "selinus_ns"     # the module name the script's classes and functions are pickled under
_POOL_LOCK = _threading.Lock()

POOL_LAUNCHER = r'''
import sys, pickle, traceback


def _main():
    inp, out = sys.stdin.buffer, sys.stdout.buffer
    sys.stdout = sys.stderr                                # a print() in the code must not reach Rhino's pipe
    hdr = pickle.load(inp)
    for p in reversed(hdr["path"]):
        if p and p not in sys.path:
            sys.path.insert(0, p)
    try:
        with open(hdr["src"], "r", encoding="utf-8") as fh:
            src = fh.read()
        ns = {"__name__": "selinus_worker"}
        exec(compile(src[:src.index(hdr["key"])], hdr["label"], "exec"), ns)
        b = pickle.dumps(("ok", ns["_pool_hello"]()), 4)
    except BaseException:
        b = pickle.dumps(("err", traceback.format_exc()), 4)
        out.write(b)
        out.flush()
        return
    out.write(b)
    out.flush()
    while True:
        try:
            msg = pickle.load(inp)
        except EOFError:
            return
        if msg[0] == "quit":
            return
        try:
            if msg[0] == "set":
                ns["_POOL_DATA"][msg[1]] = msg[2]
                r = None
            else:
                r = ns[msg[1]](*msg[2])
            b = pickle.dumps(("ok", r), 4)
        except BaseException:
            b = pickle.dumps(("err", traceback.format_exc()), 4)
        out.write(b)
        out.flush()


_main()
'''


def _ns_register(g=None):
    """Make the script's classes and functions picklable by name (module selinus_ns), in Rhino and in a worker alike.
    Only their __module__ label changes; what they do does not."""
    import sys, types
    g = globals() if g is None else g
    m = sys.modules.get(_NS_MOD)
    if m is None:
        m = sys.modules[_NS_MOD] = types.ModuleType(_NS_MOD)
    me = g.get("__name__")
    for k, v in list(g.items()):
        if isinstance(v, type) or type(v).__name__ == "function":
            if getattr(v, "__module__", None) in (me, _NS_MOD):
                try:
                    v.__module__ = _NS_MOD
                except Exception:
                    pass
                setattr(m, k, v)


def _code_print(g=None):
    """name -> fingerprint of the bytecode of every function and method of the script (the workers must match)."""
    import hashlib
    g = globals() if g is None else g
    out = {}

    def const_repr(k_):                                  # sets in sorted order (their order varies per process)
        if isinstance(k_, (frozenset, set)):
            return "{" + ",".join(sorted(const_repr(x) for x in k_)) + "}"
        if isinstance(k_, tuple):
            return "(" + ",".join(const_repr(x) for x in k_) + ")"
        return repr(k_)

    def code_fp(c, h):
        h.update(c.co_code)
        h.update(repr(c.co_names).encode("utf-8"))
        for k_ in c.co_consts:
            if hasattr(k_, "co_code"):
                code_fp(k_, h)
            else:
                h.update(const_repr(k_).encode("utf-8", "replace"))
    for k, v in list(g.items()):
        fs = []
        if type(v).__name__ == "function" and getattr(v, "__module__", None) in (g.get("__name__"), _NS_MOD):
            fs = [(k, v)]
        elif isinstance(v, type) and getattr(v, "__module__", None) in (g.get("__name__"), _NS_MOD):
            fs = [(k + "." + a, f) for a, f in sorted(vars(v).items()) if type(f).__name__ == "function"]
        for nm, f in fs:
            h = hashlib.sha1()
            code_fp(f.__code__, h)
            out[nm] = h.hexdigest()
    return out


def _pool_hello():
    """In a worker, once its code ran: what Rhino checks before handing it any work."""
    import sys
    _ns_register()
    return dict(code=_code_print(), probe=_math_probe(), py=sys.version,
                np=getattr(np, "__version__", None) if HAVE_NP else None)


def _component_text(obj):
    """The script text of a Grasshopper script component (as the render script reads it), or None."""
    f_ = getattr(obj, "TryGetSource", None)
    if callable(f_):
        try:
            r_ = f_()
            if isinstance(r_, tuple) and len(r_) == 2 and r_[0] and isinstance(r_[1], str):
                return r_[1]
            if isinstance(r_, str):
                return r_
        except Exception:
            pass
    for nm in ("Text", "Code", "ScriptSource", "SourceCode", "Script"):
        try:
            v_ = getattr(obj, nm, None)
        except Exception:
            v_ = None
        if isinstance(v_, str) and v_:
            return v_
        if v_ is not None and not isinstance(v_, str):
            for nm2 in ("Text", "Code"):
                t_ = getattr(v_, nm2, None)
                if isinstance(t_, str) and t_:
                    return t_
    for nm in dir(obj):                                  # any other text property that holds this script
        if nm.startswith("_") or not any(w in nm for w in ("Text", "Code", "Script", "Source", "Content")):
            continue
        try:
            v_ = getattr(obj, nm, None)
            if isinstance(v_, str) and POOL_KEY in v_:
                return v_
            for nm2 in dir(v_) if v_ is not None and not isinstance(v_, (str, bytes, int, float)) else ():
                if nm2.startswith("_") or not any(w in nm2 for w in ("Text", "Code", "Source")):
                    continue
                t_ = getattr(v_, nm2, None)
                if isinstance(t_, str) and POOL_KEY in t_:
                    return t_
        except Exception:
            pass
    return None


def _self_source():
    """This script's own text, for the workers: from the component, the file Rhino runs it from or the line cache."""
    cands = []
    s_ = globals().get("_SELINUS_SRC")
    if isinstance(s_, str):
        cands.append(s_)
    try:
        cands.append(_component_text(ghenv.Component))                 # noqa: F821
    except Exception:
        pass
    fn = _self_source.__code__.co_filename
    try:
        if fn and os.path.isfile(fn):
            with open(fn, "r", encoding="utf-8") as fh:
                cands.append(fh.read())
    except Exception:
        pass
    try:
        import linecache
        cands.append("".join(linecache.getlines(fn)))
    except Exception:
        pass
    for t in cands:
        if isinstance(t, str) and POOL_KEY in t and "def _pool_hello" in t:
            return t
    return None


def pool_allow(on=True):
    """Only selinus_board's own pipeline uses the workers (the render script, which runs this code, does not)."""
    _POOL["allow"] = bool(on)


def pool_start():
    """Start the workers (once per run). Returns the list of live workers ([] when they cannot be used)."""
    with _POOL_LOCK:
        if "w" not in _POOL:
            _pool_start()
    return _POOL["w"]


def _pool_start():
    import pickle, subprocess, sys, tempfile, hashlib, threading
    _POOL["w"], _POOL["why"], _POOL["n_jobs"] = [], "", 0
    if not _POOL.get("allow"):
        _POOL["why"] = "not used outside selinus_board's own run"
        return
    if not PAR_POOL:
        _POOL["why"] = "switched off (PAR_POOL = False)"
        return
    n = _cores() if PAR_PROCS <= 0 else int(PAR_PROCS)
    if n < 2:
        _POOL["why"] = "one core only (PAR_PROCS = 1 or a single-core computer)"
        return
    src = _self_source()
    if src is None:
        _POOL["why"] = "this component's code could not be read from Python here"
        return
    py = noise_worker_python()
    if py is None:
        _POOL["why"] = _NOISE_PY.get("why", "") or "no python executable found beside Rhino"
        return
    procs = []
    try:
        d = os.path.join(tempfile.gettempdir(), "selinus_workers")
        if not os.path.isdir(d):
            os.makedirs(d)
        sf = os.path.join(d, "selinus_src_%s.py" % hashlib.sha1(src.encode("utf-8")).hexdigest()[:16])
        lf = os.path.join(d, "selinus_pool_%s.py" % hashlib.sha1(POOL_LAUNCHER.encode("utf-8")).hexdigest()[:12])
        for f_, t_ in ((sf, src), (lf, POOL_LAUNCHER)):
            if not os.path.isfile(f_):
                with open(f_ + ".tmp", "w", encoding="utf-8") as fh:
                    fh.write(t_)
                os.replace(f_ + ".tmp", f_)
        hdr = pickle.dumps(dict(path=[p for p in sys.path if isinstance(p, str)], src=sf, key=POOL_KEY,
                                label="selinus_board"), 4)
        for _ in range(n):
            pr = subprocess.Popen([py, "-I", lf], stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                  stderr=subprocess.DEVNULL, **_popen_kw())
            procs.append(pr)
            pr.stdin.write(hdr)
            pr.stdin.flush()
        _ns_register()
        mine = _code_print()
        want = dict(probe=_math_probe(), np=getattr(np, "__version__", None) if HAVE_NP else None)
        hello = [None] * len(procs)

        def read_hello(k, pr):
            try:
                hello[k] = pickle.load(pr.stdout)
            except Exception as ex_:
                hello[k] = ("err", "{}: {}".format(type(ex_).__name__, ex_))
        rd = [threading.Thread(target=read_hello, args=(k, pr), daemon=True) for k, pr in enumerate(procs)]
        for t_ in rd:
            t_.start()
        import time as _tm
        t_end = _tm.time() + POOL_START_S
        for t_ in rd:
            t_.join(max(0.1, t_end - _tm.time()))
        if any(h_ is None for h_ in hello):
            raise RuntimeError("a worker did not start within {:.0f} s".format(POOL_START_S))
        for st, info in hello:
            if st != "ok":
                raise RuntimeError("a worker could not run the code: " + str(info).strip().splitlines()[-1][:200])
            if info["probe"] != want["probe"] or info["np"] != want["np"]:
                raise RuntimeError("a worker's Python or numpy does not compute exactly like Rhino's")
            bad = [k for k, v in info["code"].items() if mine.get(k) != v]
            if bad or not info["code"]:
                raise RuntimeError("a worker's code differs from this component's ({} functions)".format(len(bad)))
    except Exception as ex:
        for pr in procs:
            try:
                pr.kill()
            except Exception:
                pass
        _POOL["why"] = "{}: {}".format(type(ex).__name__, ex)
        return
    import queue
    _POOL["q"] = queue.PriorityQueue()
    _POOL["seq"] = 0
    _POOL["lock"] = threading.Lock()
    for pr in procs:
        w = dict(proc=pr, sent={}, alive=True)
        w["thread"] = threading.Thread(target=_pool_io, args=(w,), daemon=True)
        w["thread"].start()
        _POOL["w"].append(w)


def _pool_io(w):
    """One thread per worker: takes the next piece of any job, sends it, waits for the result."""
    import pickle
    q = _POOL["q"]
    while True:
        item = q.get()
        if item[2] is None:
            return
        job, i = item[2], item[3]
        if job["dead"]:
            _pool_done(job, i, None)
            continue
        try:
            pr = w["proc"]
            for k in job["share"]:
                ver, msg = _POOL_SHARE[k]
                if w["sent"].get(k) != ver:
                    pr.stdin.write(msg)
                    pr.stdin.flush()
                    st, r = pickle.load(pr.stdout)
                    if st != "ok":
                        raise RuntimeError(str(r).strip().splitlines()[-1][:200])
                    w["sent"][k] = ver
            pr.stdin.write(pickle.dumps(("call", job["fn"], job["args"][i]), 4))
            pr.stdin.flush()
            st, r = pickle.load(pr.stdout)
            if st != "ok":
                raise RuntimeError(str(r).strip().splitlines()[-1][:200])
            _pool_done(job, i, r)
        except Exception as ex:
            job["dead"] = True
            job["err"] = job.get("err") or "{}: {}".format(type(ex).__name__, ex)
            w["alive"] = False
            _pool_done(job, i, None)
            try:
                w["proc"].kill()
            except Exception:
                pass
            return


def _pool_done(job, i, r):
    with job["cv"]:
        job["res"][i] = r
        job["left"] -= 1
        job["cv"].notify_all()


def pool_share(key, obj, ver):
    """Hand obj to every worker once (before the first piece of a job that needs it); ver tells when it changed.
    Rhino keeps the same object under the same key, so its own check computes from the same data."""
    import pickle
    if _POOL_SHARE.get(key, (None,))[0] != ver:
        _POOL_SHARE[key] = (ver, pickle.dumps(("set", key, obj), 4))
        _POOL_DATA[key] = obj
        _POOL_DATA.pop("_obj_" + key, None)


def pool_live():
    """The live workers when this run may use them (started on first use)."""
    if not _POOL.get("allow") or _POOL.get("broken"):
        return []
    return [w for w in pool_start() if w["alive"]]


def pool_submit(fn, args, share=(), prio=5, label=""):
    """Start fn(*a) for every a in args on the workers; returns at once. pool_wait gives the results in order.
    Without workers nothing starts here and pool_wait computes in Rhino."""
    import threading
    job = dict(fn=fn, args=list(args), share=tuple(share), res=[None] * len(args), left=len(args), dead=False,
               err=None, cv=threading.Condition(), label=label, local=True)
    if len(job["args"]) >= 1 and pool_live():
        job["local"] = False
        _POOL.setdefault("jobs", []).append(job)
        with _POOL["lock"]:
            for i in range(len(job["args"])):
                _POOL["seq"] += 1
                _POOL["q"].put((prio, _POOL["seq"], job, i))
    return job


def pool_wait(job):
    f = globals()[job["fn"]]
    if job["local"]:
        return [f(*a) for a in job["args"]]
    first = f(*job["args"][0])                         # Rhino computes the first piece itself: the check
    with job["cv"]:
        while job["left"] > 0:
            job["cv"].wait(1.0)
            if job["left"] > 0 and not any(w["alive"] for w in _POOL.get("w") or []):
                job["err"] = job["err"] or "no worker left running"
                break
    why = job["err"]
    if why is None and not _same(first, job["res"][0]):
        why = "the checked piece differs from Rhino's own result"
    if why is not None:
        _POOL["broken"] = True
        LOG.append("Worker processes ({}): not used from here on ({}); computed in Rhino.".format(job["label"], why))
        return [first] + [f(*a) for a in job["args"][1:]]
    _POOL["n_jobs"] = _POOL.get("n_jobs", 0) + 1
    _POOL.setdefault("labels", [])
    if job["label"] and job["label"] not in _POOL["labels"]:
        _POOL["labels"].append(job["label"])
    return job["res"]


def pool_map(fn, args, share=(), label=""):
    return pool_wait(pool_submit(fn, args, share, label=label))


def pool_result(job):
    """pool_wait once; the same list on every later call (for jobs whose pieces are taken one by one)."""
    if "out" not in job:
        job["out"] = pool_wait(job)
    return job["out"]


def _same(a, b):
    """Bit for bit the same result (numbers, NaN, arrays, bytes, nested lists, tuples and dicts)."""
    import struct
    if type(a) is not type(b):
        return False
    if HAVE_NP and isinstance(a, np.ndarray):
        return a.dtype == b.dtype and a.shape == b.shape and a.tobytes() == b.tobytes()
    if isinstance(a, float):
        return struct.pack("<d", a) == struct.pack("<d", b)
    if isinstance(a, (list, tuple)):
        return len(a) == len(b) and all(_same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict):
        return list(a.keys()) == list(b.keys()) and all(_same(a[k], b[k]) for k in a)
    if HAVE_NP and isinstance(a, np.generic):
        return a.dtype == b.dtype and a.tobytes() == b.tobytes()
    return a == b


def pool_stop():
    """End the workers of this run (also after an error). A job still waited for is then computed in Rhino."""
    for job in _POOL.get("jobs") or []:
        with job["cv"]:
            if job["left"] > 0:
                job["dead"] = True
                job["err"] = job["err"] or "the workers were stopped"
                job["left"] = 0
                job["cv"].notify_all()
    ws = _POOL.get("w") or []
    q = _POOL.get("q")
    for w in ws:
        if q is not None:
            q.put((-1, -1, None, None))
    for w in ws:
        try:
            w["proc"].stdin.close()
        except Exception:
            pass
    for w in ws:
        try:
            w["proc"].wait(timeout=3)
        except Exception:
            try:
                w["proc"].kill()
            except Exception:
                pass
    allow = _POOL.get("allow")
    _POOL.clear()
    _POOL_SHARE.clear()
    _POOL_DATA.clear()
    if allow is not None:
        _POOL["allow"] = allow


def pool_report():
    """One LOG line: how many workers took part, or why none did."""
    if "w" not in _POOL:
        return
    n = len(_POOL["w"])
    if n and _POOL.get("n_jobs"):
        LOG.append("Worker processes: {} for {} ({} jobs, each checked against Rhino).".format(
            n, ", ".join(_POOL.get("labels", [])), _POOL["n_jobs"]))
    elif not n and _POOL.get("why"):
        LOG.append("Worker processes for terrain heights and section drawings: not used ({}); computed in Rhino as "
                   "in v17.".format(_POOL["why"]))


# ---- the pieces of work the workers take (plain data in, plain data out; Rhino runs the same functions to check)
class _TerrainOnly(object):
    """The terrain part of a site (the samples and their z_at), as a worker rebuilds it from the shared samples."""
    _no_pool = True


def _pool_terrain():
    d = _POOL_DATA["terrain"]
    T = _POOL_DATA.get("_obj_terrain")
    if T is None or T._d is not d:
        T = _TerrainOnly()
        T._d = d
        T.terrain_ok, T.terrain_smp = d
        T.z_at = terrain_z_at(T, T.terrain_smp)
        _POOL_DATA["_obj_terrain"] = T
    return T


def pool_terrain(S):
    """Hand the site's terrain samples to the workers (once per site)."""
    pool_share("terrain", (S.terrain_ok, S.terrain_smp), S.terrain_fp)
    return ("terrain",)


def _pool_z_np(X, Y):
    return z_np(_pool_terrain(), X, Y)


def _pool_z_at(pts):
    z = _pool_terrain().z_at
    return [z(x, y) for x, y in pts]


def _pool_chunks(n_items, n_min=1):
    """Contiguous pieces [a, b) for the workers: about three per worker, at least n_min items each."""
    nw = max(1, len(pool_live()))
    k = max(1, min(3 * nw, n_items // max(1, n_min)))
    return [(n_items * j // k, n_items * (j + 1) // k) for j in range(k)]


def z_at_many(S, pts, label="terrain heights"):
    """[S.z_at(x, y) for (x, y) in pts], on the workers when there are many points (the same function there)."""
    pts = list(pts)
    if len(pts) < 2000 or getattr(S, "_no_pool", False) or not pool_live():
        return [S.z_at(x, y) for x, y in pts]
    sh = pool_terrain(S)
    out = []
    for r in pool_map("_pool_z_at", [(pts[a:b],) for a, b in _pool_chunks(len(pts), 500)], sh, label):
        out += r
    return out


def noise_map_start(S, solids, cell=20.0, R=300.0, h_rec=4.0, h_src=0.5, nbin=36, model=None):
    """v17: the map's receivers handed to the worker processes (they run on while Rhino goes on)."""
    F = S.F
    NM = model or NoiseModel(S, solids, R, h_src, nbin)
    nx, ny = int(math.ceil(F.w / cell)) + 1, int(math.ceil(F.h / cell)) + 1
    where, pts = [], []
    for j in range(ny):
        for i in range(nx):
            x, y = F.world(F.u0 + i * cell, F.v0 + j * cell)
            if NM.inside(x, y):
                continue
            where.append((j, i))
            pts.append((x, y))
    tasks = [(x, y, z, (h_rec,)) for (x, y), z in zip(pts, z_at_many(S, pts, "sound receivers"))]   # v18
    return dict(h=noise_par_start(NM, tasks, "col", "map"), where=where, nx=nx, ny=ny, cell=cell, R=R, NM=NM)


def noise_map_collect(m):
    nx, ny, cell, R, NM = m["nx"], m["ny"], m["cell"], m["R"], m["NM"]
    grid = [[None] * nx for _ in range(ny)]
    for (j, i), rr in zip(m["where"], noise_par_collect(m["h"])):     # v17: on every core
        r = rr[0]
        if r is None:                                     # no counted road within R: not computed (not "quiet")
            grid[j][i] = dict(day=None, evening=None, night=None, lden=None, out=True)
            continue
        grid[j][i] = dict(day=r[0], evening=r[1], night=r[2], lden=r[3])
    return dict(grid=grid, cell=cell, nx=nx, ny=ny, n_src=len(NM.src), R=R)


# ------------------------------------------------------------ raster to vector: class regions with holes
def class_regions(cls, nx, ny):
    """Connected patches of equal class as polygons with holes, in cell-corner coordinates."""
    regions = []
    classes = set(v for row in cls for v in row if v is not None)
    for c in classes:
        nxt = {}

        def add(p, q):
            nxt.setdefault(p, []).append(q)
        for j in range(ny):
            row = cls[j]
            for i in range(nx):
                if row[i] != c:
                    continue
                if j == 0 or cls[j - 1][i] != c:
                    add((i, j), (i + 1, j))
                if i == nx - 1 or row[i + 1] != c:
                    add((i + 1, j), (i + 1, j + 1))
                if j == ny - 1 or cls[j + 1][i] != c:
                    add((i + 1, j + 1), (i, j + 1))
                if i == 0 or row[i - 1] != c:
                    add((i, j + 1), (i, j))
        loops = []
        while nxt:
            start = next(iter(nxt))
            loop = [start]
            prev, cur = None, start
            guard = 0
            while guard < 10 ** 6:
                guard += 1
                outs = nxt.get(cur)
                if not outs:
                    break
                if len(outs) == 1 or prev is None:
                    q = outs[0]
                else:
                    din = (cur[0] - prev[0], cur[1] - prev[1])
                    q = min(outs, key=lambda o: (din[0] * (o[1] - cur[1]) - din[1] * (o[0] - cur[0])))
                outs.remove(q)
                if not outs:
                    del nxt[cur]
                prev, cur = cur, q
                if cur == start:
                    break
                loop.append(cur)
            simp = []
            n_ = len(loop)
            for k in range(n_):
                a, b, d = loop[k - 1], loop[k], loop[(k + 1) % n_]
                if (b[0] - a[0]) * (d[1] - b[1]) - (b[1] - a[1]) * (d[0] - b[0]) != 0:
                    simp.append(b)
            if len(simp) >= 3:
                loops.append(simp)
        outers = [L_ for L_ in loops if signed_area(L_) > 0]      # the class on the left: outers anticlockwise
        holes = [L_ for L_ in loops if signed_area(L_) < 0]
        outers.sort(key=lambda L_: shoelace(L_)[0])
        groups = [(o, []) for o in outers]
        for h in holes:
            (x0, y0), (x1, y1) = h[0], h[1]                       # just on the class side of the hole's first edge
            L_ = math.hypot(x1 - x0, y1 - y0) or 1.0
            px, py = (x0 + x1) / 2.0 - (y1 - y0) / L_ * 0.25, (y0 + y1) / 2.0 + (x1 - x0) / L_ * 0.25
            for o, hl in groups:
                if pip(px, py, o):
                    hl.append(h)
                    break
        for o, hl in groups:
            regions.append((c, o, hl))
    return regions

