_PACK = {}


def seam_pack():
    """v33: the plant-analysis data built into this script (SEAM_PACK, from bergama_plant_data_v1.json of
    2026-10-19): canopy-map crowns, site photos, riparian corridor, Landsat heat, section strips."""
    if not _PACK:
        import base64 as _b64
        _PACK.update(json.loads(_zlib.decompress(_b64.b64decode("".join(SEAM_PACK))).decode("utf-8")))
    return _PACK


def context_frame(F, m=CONTEXT_M):
    """The site frame grown by m on every side (a rectangle on the frame's own axes)."""
    return Frame([F.world(u, v) for u, v in ((F.u0 - m, F.v0 - m), (F.u1 + m, F.v0 - m), (F.u1 + m, F.v1 + m),
                                             (F.u0 - m, F.v1 + m))])


def context_lines(RAW, F, m=CONTEXT_M):
    """v33: the survey's buildings, streets and stream banks in the ring of m around the frame (quiet context)."""
    F2 = context_frame(F, m)
    out = {"bld": [], "road": [], "water": []}
    for key, lays in (("bld", list(DWG["bld"]) + [DWG["shed"]]), ("road", DWG["roads"]), ("water", DWG["banks"])):
        for lay in lays:
            for x0, y0, x1, y1 in RAW["lines"].get(lay, []):
                mx, my = 0.5 * (x0 + x1), 0.5 * (y0 + y1)
                if F2.inside(mx, my) and not F.inside(mx, my):
                    out[key].append(((x0, y0), (x1, y1)))
    return out


WHOLE_SKIP = ("NIRENGI", "PINDEX", "NOKTA_", "POLIGON", "SCAN", "MAH_", "YAZI_")   # v36, as fabric_green v10


def whole_frame(RAW, FR, margin=15.0):
    """v36: the whole survey file on the site frame's own axes: every survey layer this board read except the control
    and grid layers, district outlines, labels, layer 0 and the *_alan layers (fabric_green v10's rule)."""
    skip = lambda l: (not l or l.split("::")[-1] == "0" or l.split("::")[-1].upper().startswith(WHOLE_SKIP) or
                      l.lower().endswith("_alan"))
    us, vs = [], []
    for lay, lst in RAW["lines"].items():
        if not skip(lay):
            for s_ in lst:
                for x_, y_ in ((s_[0], s_[1]), (s_[2], s_[3])):
                    u_, v_ = FR.local(x_, y_)
                    us.append(u_)
                    vs.append(v_)
    for lay, lst in (RAW.get("plines") or {}).items():
        if not skip(lay):
            for P in lst:
                for q in P:
                    u_, v_ = FR.local(q[0], q[1])
                    us.append(u_)
                    vs.append(v_)
    if len(us) < 3:
        raise Exception("no survey line work for the whole-file frame")
    u0, u1, v0, v1 = min(us) - margin, max(us) + margin, min(vs) - margin, max(vs) + margin
    return Frame([FR.world(u0, v0), FR.world(u1, v0), FR.world(u1, v1), FR.world(u0, v1)])


def whole_site(RAW, OSM, PLACES, FR, S):
    """v36: the site model over the whole file, for plan 01 only (land use, fabric, land cover, density, stream
    edges); FR, the analysis range, is drawn on it. The tables keep the site frame's model S."""
    FA = whole_frame(RAW, FR)
    SA = build_site(RAW, OSM, PLACES, FA)
    SA.U = S.U                                           # the site's line and text sizes
    load_landcover(SA)
    SA.int_cells, SA.int_breaks, SA.int_cell, SA.int_peak, SA.int_peak_name = [], (0, 0, 0), 50.0, 0.0, ""
    SA.edge_runs, SA.wall_runs, SA.edge_samples = [], [], []
    SA.edge_len = dict((k, 0.0) for k in EDGE_ORDER)
    SA.walled_len, SA.embanked_len, SA.bank_runs = 0.0, 0.0, []
    SA.sections, SA.sec_lines, SA.observations = [], [], []
    for fn in (build_intensity, build_edges):
        try:
            fn(SA)
        except Exception:
            LOG.append("whole-file map: {} failed:\n{}".format(fn.__name__, traceback.format_exc()))
    fabric_types(SA)
    SA.ctx_lines, SA.study_areas, SA.water_pts = {}, list(S.study_areas), []
    SA.frame_src, SA.range_F, SA.rest = "whole file", FR, []
    LOG.append("Plan 01 covers the whole file: {:.0f} x {:.0f} m ({:.0f} ha); farmland {:.1f} ha and orchards {:.1f} "
               "ha in it (satellite / inferred).".format(FA.w, FA.h, FA.area / 1e4,
                                                        SA.lc_area.get("farmland", 0.0) / 1e4,
                                                        SA.lc_area.get("orchard", 0.0) / 1e4))
    return SA


def site_crowns(S, F2):
    """Canopy-map crowns (modelled, Meta/WRI 1 m canopy height map) inside F2: [(x, y, r, h, leaf)]."""
    rows = seam_pack().get("crowns", {}).get("rows", [])
    return [(r[0], r[1], r[2], r[3], r[4]) for r in rows if F2.inside(r[0], r[1])]


def dense_outline(S, cls_min=3, min_cells=20):
    """The outline of the densest grain: groups of at least min_cells touching cells of intensity class >= cls_min
    (10 m cells, so 20 cells = 2,000 m2); single dense cells are left out (they outline one building, not an area)."""
    cells = [P for P, cls, j in getattr(S, "int_cells", []) if cls >= cls_min]
    key = lambda a, b: tuple(sorted(((round(a[0], 2), round(a[1], 2)), (round(b[0], 2), round(b[1], 2)))))
    par = list(range(len(cells)))

    def find(i):
        while par[i] != i:
            par[i] = par[par[i]]
            i = par[i]
        return i
    owner, cnt = {}, {}
    for i, P in enumerate(cells):
        for k in range(len(P)):
            e = key(P[k], P[(k + 1) % len(P)])
            cnt[e] = cnt.get(e, 0) + 1
            if e in owner:
                a, b = find(i), find(owner[e])
                if a != b:
                    par[a] = b
            else:
                owner[e] = i
    size = {}
    for i in range(len(cells)):
        r = find(i)
        size[r] = size.get(r, 0) + 1
    return [list(e) for e, c in cnt.items() if c == 1 and size[find(owner[e])] >= min_cells]


C5_XY = (30359.2, 31631.8)     # v36: centroid of the course survey's K5 working area (begum_alan, 55,525 m2)


def c5_point(S):
    if not getattr(S, "study_areas", None):
        return C5_XY
    best = None
    for a in getattr(S, "study_areas", []) or []:
        if a["name"] == "BEGUM" and (best is None or a["area"] > best["area"]):
            best = a
    if not best:
        return None
    _a, cx, cy = shoelace(best["P"])
    return (cx, cy)


def roundel(B, x, y, r, txt, fill, ink, L, order=62, h=None):
    B.fill([circle_pts(x, y, r, 16)], fill, L, order)
    B.line(circle_pts(x, y, r, 16) + [circle_pts(x, y, r, 16)[0]], ink, L, order + 1, 0.12)
    B.text(txt, x, y, h or 0.95 * r, ink if fill == (255, 255, 255) else (255, 255, 255), L, order=order + 1,
           font=FONT_TITLE, bold=True, align="MC")


def photo_files(folder):
    """The site photos of the data pack as JPEG files in folder (written once); [(path, item)]."""
    import base64 as _b64
    out = []
    if not os.path.isdir(folder):
        os.makedirs(folder)
    for it in seam_pack().get("photos", {}).get("items", []):
        p = os.path.join(folder, os.path.splitext(it["file"])[0].replace(".JPG", "") + ".jpg")
        if not os.path.isfile(p):
            with open(p, "wb") as f_:
                f_.write(_b64.b64decode(it["jpeg_b64"]))
        out.append((p, it))
    return out


def home_col(u):
    """Buildings on the plan: homes in the residential colour by fabric (darker = denser grain), monuments and sacred
    buildings in the fabric's heritage colours, every other use in its land-use colour."""
    fab = u.get("fabric", "regular")
    if fab in ("monument", "sacred"):
        col = FABRIC[fab][2]
    elif u["cat"] == "residential":
        tgt, t = HOME_TONE.get(fab, (None, 0.0))
        col = mix(CAT["residential"][1], tgt, t) if tgt is not None else CAT["residential"][1]
    else:
        col = CAT[u["cat"]][1]
    return mix(col, PAPER, 0.35) if u["annex"] else col


def draw_what_is_there(S, B, x, y, w, U):
    """S1: the site as it is on one plan, the frame and CONTEXT_M of quiet context, at the board scale. Returns the
    y below its legend."""
    L = "LU_BOARD::WhatIsThere"
    F = S.F
    RF = getattr(S, "range_F", None)                      # v36: set on the whole-file model: the analysis range
    F2 = F if RF is not None else context_frame(F)
    r_map = bcite("Plan 01: the map covers the whole survey file; the thin line is the analysis range (site_alan). Crowns "
                  "and photos exist for the site only." if RF is not None else
                  "Plan 01: context beyond the frame: survey line work only.")
    B.text("WHAT IS THERE · GROUND · BUILDINGS · GREEN · STREAM EDGE " + r_map, x, y, 1.05 * U, INK, L,
           font=FONT_TITLE, bold=True)                    # v38: keywords; the coverage note is a key entry
    V, mw, mh = view_fit(F2, x, y - 1.2 * U, w, 10.0 * w)
    s = V.s
    # quiet context: survey line work around the frame, pale
    B.fill([V.P(F2.P)], mix(PAPER, (255, 255, 255), 0.55), L, 1)
    ctx = getattr(S, "ctx_lines", None) or {}
    for key, col, wd in (("water", mix(BLUE_D, PAPER, 0.5), 0.06), ("road", mix(INK2, PAPER, 0.62), 0.04),
                         ("bld", mix(INK2, PAPER, 0.45), 0.04)):
        for a, b in ctx.get(key, []):
            B.line([V.p(*a), V.p(*b)], col, L, 2, wd)
    # the site: land use, land cover, ground, streets, trees, buildings (homes by fabric), walls, bridges
    draw_landuse_map(S, B, V, bcol=home_col)
    # canopy-map crowns (modelled), under the surveyed tree symbols
    crowns = [c for c in site_crowns(S, F) if F.inside(c[0], c[1])]
    for leaf in (0, 1, 2):
        pts = [circle_pts(V.p(cx, cy)[0], V.p(cx, cy)[1], max(0.06 * U, r * s), 10) for cx, cy, r, h, lf in crowns
               if lf == leaf]
        for k in range(0, len(pts), 400):
            B.fill(pts[k:k + 400], mix(LEAF_COL[leaf], PAPER, 0.25), L, 10)
    # footpaths (the open-space network's links)
    path_c = mix(CAT["green"][1], INK, 0.35)
    for p in S.paths:
        for d in dashes(V.P(p["P"]), 0.35 * U, 0.25 * U):
            B.line(d, path_c, L, 19, 0.16)
    # dense fabric (intensity): the outline of the densest floor-area class
    dens = dense_outline(S)
    dc = mix(INTENSITY[3], INK, 0.1)
    for a, b in dens:
        B.line([V.p(*a), V.p(*b)], dc, L, 23, 0.3)
    # stream thresholds, thinner, along the banks
    for typ, pts in getattr(S, "edge_runs", []):
        B.line(V.P(pts), EDGE[typ][1], L, 24, THRESH_W)
    for pts in getattr(S, "wall_runs", []):
        for d in dashes(V.P(pts), 0.16 * U, 0.14 * U):
            B.line(d, PAPER, L, 25, THRESH_W * 0.4)
    # frame, river name, section marks (shared with the section drawings)
    draw_map_annotations(S, B, V, U)
    B.line(V.P(F.P + [F.P[0]]), INK, L, 26, 0.25)
    if RF is not None:                                    # v36: the analysis range (site_alan) on the whole-file map
        B.line(V.P(RF.P + [RF.P[0]]), INK, L, 26, 0.12)
    # bridges, conflicts, photos
    rr = 0.42 * U
    for k, nm, bx, by in BRIDGES_K:
        if F.inside(bx, by):
            px, py = V.p(bx, by)
            roundel(B, px, py + 1.3 * rr, rr, k, (255, 255, 255), INK, L)
    cs = list(CONFLICTS_C)
    c5 = c5_point(S)
    if c5:
        cs.append(("C5", c5[0], c5[1], C5_TEXT))
    for k, cx, cy, t in cs:
        if F.inside(cx, cy):
            px, py = V.p(cx, cy)
            roundel(B, px - 1.3 * rr, py - 1.3 * rr, rr, k, MARK_C, MARK_C, L)
    photos = []
    try:
        photos = photo_files(os.path.join(pdf_folder(), "_site_photos"))
    except Exception:
        LOG.append("WARNING: the site photos could not be written:\n" + traceback.format_exc())
    for i, (p, it) in enumerate(photos):
        px, py = V.p(it["x"], it["y"])
        q = 0.36 * U
        B.fill([rect(px - q, py - q, px + q, py + q)], INK, L, 64)
        B.text(str(i + 1), px, py, 0.5 * q * 2.0 * 0.62, (255, 255, 255), L, order=65, font=FONT_TITLE, bold=True,
               align="MC")
    draw_north_small(B, V, mw, mh, U, L, size=0.7)
    mb = y - 1.2 * U - mh
    draw_scalebar(B, V.X0, mb - 1.4 * U, s, nice_floor(F2.w / 8.0), U, L, h=0.32)
    # photo strip under the map
    yy = mb - 2.6 * U
    if photos:
        n = len(photos)
        g = 0.6 * U
        pw = (mw - (n - 1) * g) / n
        ph = pw * 0.75
        low = yy
        for i, (p, it) in enumerate(photos):
            px = V.X0 + i * (pw + g)
            B.image(p, px, yy - ph, px + pw, yy, L, order=5)
            B.fill([rect(px, yy - 0.9 * U, px + 0.9 * U, yy)], INK, L, 64)
            B.text(str(i + 1), px + 0.45 * U, yy - 0.45 * U, 0.45 * U, (255, 255, 255), L, order=65,
                   font=FONT_TITLE, bold=True, align="MC")
            d = it.get("description", "").split(";")[0].strip().rstrip(".")
            low = min(low, yy - ph - 0.5 * U)
            if d:                                         # v38: the description is a key entry; its [n] under the photo
                B.text(u"{} {}".format(i + 1, bcite(u"Photo {}: {}.".format(i + 1, d))), px, yy - ph - 0.5 * U,
                       0.3 * U, INK, L)
                low = min(low, yy - ph - 0.5 * U - 0.54 * U)
        r_ph = bcite(u"Photos: site visit 2026-10-01 (group photos, GPS within {:.0f} m); the square marks where each "
                     u"was taken. Descriptions: the photo index, a visual reading.".format(
                         max(it.get("gps_err_m", 0.0) for p, it in photos)))
        B.text(u"PHOTOS · site visit 2026-10-01 · GPS within {:.0f} m {}".format(
            max(it.get("gps_err_m", 0.0) for p, it in photos), r_ph), V.X0, low - 0.4 * U, 0.3 * U, INK2, L)
        yy = low - 0.4 * U - 0.54 * U
    # legend (v38: drawn samples with short names; explanations as [n] in the Sources key)
    r_home = bcite("Homes are coloured by their grain.")
    r_crown = bcite("Crowns: modelled heights and leaf types (Meta/WRI 1 m canopy height map, Tolan et al. 2024; CLC+ "
                    "2021 and Sentinel-2).")
    r_edge = bcite("Stream edges: what meets the water along each bank.")
    leg = [("hdr", None, "BUILDINGS · HOMES BY GRAIN " + r_home)]
    for fab in ("traditional", "block", "regular", "selfbuilt"):
        u_ = {"fabric": fab, "cat": "residential", "annex": False}
        leg.append(("box", home_col(u_), "Homes · " + FABRIC_SHORT[fab].lower()))
    for c_ in ("mixed", "commercial", "institutional", "industrial", "transport"):
        leg.append(("box", CAT[c_][1], short(CAT[c_][0])))
    leg += [("box", FABRIC["monument"][2], "Monuments, historic"), ("box", FABRIC["sacred"][2], "Mosques & sacred"),
            ("dense", dc, "Densest grain · floor-area ratio {:.2f}+ {}".format(
                S.int_breaks[2], bcite("Densest grain: floor-area ratio on 10 m cells, areas of 2,000 m2+."))
             if getattr(S, "int_breaks", None) else "Densest grain")]
    leg += [("hdr", None, "GROUND AND GREEN")]
    for k_, lab in (("wood", "Woods"), ("park", "Parks"), ("grass", "Grass & lawns")):
        leg.append(("box", GREEN_SUB[k_], lab))
    leg += [("box", CAT["agri"][1], "Fields & orchards (survey, OSM)"), ("box", CAT["vacant"][1], "Vacant ground"),
            ("box", CAT["water"][1], "The stream")]
    for k_, lab, col in LC_CLASSES:
        if getattr(S, "lc", {}).get(k_):
            leg.append(("box", col, lab))
    for lf in (0, 1, 2):
        if any(c[4] == lf for c in crowns):
            leg.append(("dot", mix(LEAF_COL[lf], PAPER, 0.25), "Crown · " + LEAF_NAME[lf] + " " + r_crown))
    leg += [("dot", TREE_COLS["pine"], "Tree symbols of the survey"), ("dash", path_c, "Footpaths")]
    leg += [("hdr", None, "THE STREAM EDGE " + r_edge)]
    for k_ in EDGE_ORDER:
        if S.edge_len.get(k_, 0) > 0:
            leg.append(("thin", EDGE[k_][1], short(EDGE[k_][0])))
    leg += [("hdr", None, "MARKS")]
    leg += [("kmark", None, "K1-K6 bridges (concept record)")]
    leg += [("cmark", MARK_C, "{} {}".format(k, t)) for k, cx, cy, t in sorted(cs) if F.inside(cx, cy)]
    if photos:
        leg.append(("pmark", INK, "Photo viewpoint (photos under the map)"))
    if RF is not None:
        leg.append(("thin", INK, "Analysis range (site_alan) " + r_map))
    ly = draw_legend_items(B, leg, x, yy - 1.0 * U, mw, U, L, h=0.4)
    tot = sum(S.fabric_area.values()) or 1.0
    # v38: the caption's two figures as tiles (were sentences); its notes are the key entries cited above
    return vis_tiles(B, x, ly - 0.3 * U, min(mw, 44.0 * U), [
        ("build", "OLD TOWN · % OF BUILT FOOTPRINT", "{:.0f}%".format(100.0 * S.fabric_area.get("traditional", 0.0) / tot),
         r_home),
        ("green", "CROWNS IN THE FRAME", "{}".format(len(crowns)), r_crown)], U, L, h=1.3, ink=INK, grey=INK2,
        fill=mix(PAPER, (255, 255, 255), 0.5), rule=FAINT)



# ---- v33 (Q11): satellite strips under every section: land cover (CLC+ Backbone 2021) and greenness (Sentinel-2
# NDVI, January and July), metre by metre along the line, from the plant analysis's section data in SEAM_PACK
CLC_COL = {1: C("A5A097"), 2: LEAF_COL[2], 3: LEAF_COL[0], 4: LEAF_COL[1], 5: C("A9AE7C"), 6: C("C9D1A0"),
           7: C("E0D8A0"), 8: C("D8D2C0"), 9: C("E6DCC8"), 10: C("91ADB4")}
NDVI_STEPS = [(0.15, C("E9E2CF")), (0.25, C("D9D7A8")), (0.35, C("B9C27F")), (0.45, C("93A65E")), (0.55, C("6E8A47")),
              (9.0, C("4E6B37"))]
SAT_ROWS = [("clc", "land cover"), ("jan", "green, Jan"), ("jul", "green, Jul")]


def ndvi_col(v):
    return next(c for t, c in NDVI_STEPS if v < t)


def section_sat(sd_):
    """The pack's satellite rows for this section (or this part of it): {row: [colour per metre]} or None."""
    x0, y0, x1, y1 = sd_["line"][:4]
    L = sd_["L"]
    best = None
    for ps in seam_pack().get("sections", []):
        (ax, ay), (bx, by) = ps["a"], ps["b"]
        dx, dy = bx - ax, by - ay
        n = math.hypot(dx, dy) or 1.0
        off = max(abs(((px - ax) * dy - (py - ay) * dx) / n) for px, py in ((x0, y0), (x1, y1)))
        if off < 2.0 and (best is None or off < best[0]):
            best = (off, ps, dx / n, dy / n)
    if best is None:
        return None
    _, ps, ux, uy = best
    ax, ay = ps["a"]
    clc, nd = ps.get("clc") or [], ps.get("ndvi") or {}
    ex, ey = (x1 - x0) / (L or 1.0), (y1 - y0) / (L or 1.0)
    rows = dict((k, []) for k, _ in SAT_ROWS)
    for s in range(int(L) + 1):
        px, py = x0 + ex * s, y0 + ey * s
        i = int(round((px - ax) * ux + (py - ay) * uy))
        ok = 0 <= i < len(clc)
        rows["clc"].append(CLC_COL.get(int(clc[i])) if ok and clc[i] else None)
        for k in ("jan", "jul"):
            v = nd.get(k) or []
            rows[k].append(ndvi_col(v[i] / 1000.0) if 0 <= i < len(v) and v[i] is not None else None)
    return rows


def draw_sat_strips(B, rows, P, Lm, ytop, x, U, L):
    """The satellite rows under the use ribbon, named at the left; returns the y below them."""
    h, g = 0.24 * U, 0.06 * U
    y = ytop - g
    for k, lab in SAT_ROWS:
        vals = rows[k]
        a = 0
        while a < len(vals):
            b = a
            while b + 1 < len(vals) and vals[b + 1] == vals[a]:
                b += 1
            if vals[a] is not None:
                B.fill([rect(P(a, 0)[0], y - h, P(min(Lm, b + 1), 0)[0], y)], vals[a], L, 20)
            a = b + 1
        B.text(lab, P(0, 0)[0] - 0.25 * U, y - h * 0.85, 0.18 * U, INK2, L, align="R")
        y -= h + g
    return y


# v40 (Aras 25 Oct: "texts and graphics are on top each other ... make the diagram clearer"): the tree-cover chart
# reads at a glance: each bank's four distance bands named beside their rows (0-15 m next to the stream), the stream
# between the banks with its covered reaches drawn on it and the bridges as ticks across it only, a distance axis
# every 500 m, a key of drawn samples. Values as in the pack (no smoothing). Words at RIP_TH page units: the booklet
# crops this panel at 392 mm wide, where they print at 7.5 pt or more.
RIP_TH = 0.6
RIP_RAMP = [(0.0, C("F6F5EF")), (1.0, C("E3E6CF")), (5.0, C("C9D1A4")), (10.0, C("A9B57F")), (20.0, C("8C9969")),
            (40.0, C("6B774A"))]
RIP_COVERED = mix(BLUE_D, INK, 0.35)                   # the stream where it runs under the town
PANEL_RECTS = {}        # v40: a panel's drawing with its in-drawing words (no title, key or notes): (x0, y0, x1, y1)


def rip_colour(v):
    c_ = RIP_RAMP[0][1]
    for t, cc in RIP_RAMP:
        if v >= t:
            c_ = cc
    return c_


def rip_legend():
    """The tree-cover chart's key as drawn samples: [(kind, colour, name)]."""
    out = []
    for k, (t, c_) in enumerate(RIP_RAMP):
        out.append(("box", c_, "tree cover {:g}-{:g} %".format(t, RIP_RAMP[k + 1][0]) if k + 1 < len(RIP_RAMP)
                    else "tree cover {:g} % +".format(t)))
    return out + [("box", CAT["water"][1], "the Selinos stream"), ("box", RIP_COVERED, "covered reach"),
                  ("line", INK, "bridge")]


def draw_riparian(S, B, x, y, w, U):
    """S1 companion (plant analysis panel 3): canopy cover in four bands either side of the Selinos every 25 m of
    chainage; the stream between the banks with its covered reaches and bridges; the section lines by name."""
    L = "LU_BOARD::Riparian"
    cor = seam_pack().get("corridor", {})
    if not cor:
        return y
    B.text("THE STREAM'S TREE COVER · BANK BY BANK, EVERY 25 M", x, y, 1.05 * U, INK, L, font=FONT_TITLE, bold=True)
    n, bm = cor["n_bins"], float(cor["bin_m"])
    th = RIP_TH * U
    rh, hb, gs = 0.95 * U, 1.3 * U, 0.14 * U             # a distance band, the stream, the gap between them
    bands = ["0-15", "15-30", "30-60", "60-100"]
    col_b = tw("RIGHT", th) + 0.5 * U                     # bank names
    lab_w = col_b + tw("60-100 m", th) + 0.5 * U          # + band names
    x0 = x + lab_w
    x1 = x + w - tw("mean", th) - 0.7 * U                 # the reach's mean per band at the right
    cw = (x1 - x0) / float(n)

    def X(ch):
        return x0 + ch / bm * cw
    # ---- distance axis, every 500 m along the stream (downstream to the right)
    ya = y - 2.1 * U
    gtop = ya - 0.5 * U
    B.text("downstream", x0 - 0.5 * U, ya, th, INK2, L, align="R")
    for m in range(0, int(n * bm) + 1, 500):
        B.line([(X(m), gtop + 0.05 * U), (X(m), gtop + 0.3 * U)], INK2, L, 6, 0.08)
        B.text("{:,}".format(m) + (" m" if m == 0 else ""), X(m), ya, th, INK2, L, align="L" if m == 0 else "C")
    B.text("mean", x1 + 0.5 * U, ya, th, INK2, L)

    def row_top(j):                                       # rows 0-3: left bank, far to near; 4-7: right bank, near to far
        return gtop - j * rh - (hb + 2.0 * gs if j >= 4 else 0.0)
    rows = [("left", b_) for b_ in reversed(bands)] + [("right", b_) for b_ in bands]
    for j, (side, b_) in enumerate(rows):
        yy = row_top(j)
        d_ = cor["cover"].get(side + " " + b_, {})
        vals = d_.get("pct") or d_.get("cover") or []
        cells = d_.get("cells", [])
        for i in range(n):
            v = vals[i] if i < len(vals) else None
            if v is None or (i < len(cells) and cells[i] < 20):
                continue
            B.fill([rect(X(i * bm), yy - rh + 0.05 * U, X((i + 1) * bm), yy - 0.05 * U)], rip_colour(v), L, 3)
        ym = yy - 0.5 * rh - 0.5 * th
        B.text(b_ + " m", x0 - 0.5 * U, ym, th, INK, L, align="R")
        if d_.get("total_pct") is not None:
            B.text("{:.1f}%".format(d_["total_pct"]), x1 + 0.5 * U, ym, th, INK, L)
    for side, j0 in (("LEFT", 0), ("RIGHT", 4)):          # the bank's name beside its four rows
        yc = row_top(j0) - 2.0 * rh
        B.text(side, x, yc + 0.15 * U, th, INK, L, font=FONT_TITLE, bold=True)
        B.text("BANK", x, yc - 0.15 * U - th, th, INK, L, font=FONT_TITLE, bold=True)
        B.line(rect(x0, row_top(j0 + 3) - rh, x1, row_top(j0)) + [(x0, row_top(j0 + 3) - rh)], FAINT, L, 4, 0.05)
    # ---- the stream between the banks: covered reaches darker and hatched, bridges as ticks across it
    st, sb = row_top(3) - rh - gs, row_top(3) - rh - gs - hb
    B.fill([rect(x0, sb, x1, st)], CAT["water"][1], L, 3)
    B.text("STREAM", x0 - 0.5 * U, 0.5 * (st + sb) - 0.5 * th, th, BLUE_D, L, font=FONT_TITLE, bold=True, align="R")
    am = 0.5 * (st + sb)                                  # the flow, at the upstream end
    B.line([(X(10.0), am), (X(62.0), am)], BLUE_D, L, 5, 0.25)
    B.fill([[(X(88.0), am), (X(60.0), am + 0.32 * U), (X(60.0), am - 0.32 * U)]], BLUE_D, L, 5)
    for a, b in cor.get("covered_reaches", []):
        cov = rect(X(a), sb, X(b), st)
        B.fill([cov], RIP_COVERED, L, 4)
        B.hatch([cov], CAT["water"][1], L, 5, 0.3 * U, w=0.05)
    ch = cor.get("bridges_ch", [])
    for i in range(0, len(ch) - 1, 2):
        xa, xb = X(ch[i]), X(ch[i + 1])
        if xb - xa < 0.2 * U:
            xa, xb = 0.5 * (xa + xb) - 0.1 * U, 0.5 * (xa + xb) + 0.1 * U
        B.fill([rect(xa, sb - 0.08 * U, xb, st + 0.08 * U)], INK, L, 6)
    # ---- the section lines, by name under the chart
    gb = row_top(7) - rh
    yl = gb - 0.75 * U - th
    secs = cor.get("sections_ch", [])
    if secs:
        B.text("sections", x0 - 0.5 * U, yl, th, INK2, L, align="R")
    for nm, c_ in secs:
        B.line([(X(c_), gb - 0.1 * U), (X(c_), gb - 0.55 * U)], INK, L, 6, 0.12)
        B.text(nm, X(c_), yl, th, INK, L, align="C", font=FONT_TITLE, bold=True)
    PANEL_RECTS["riparian"] = (x, yl - 0.25 * U, x + w, ya + th + 0.25 * U)
    # ---- key: the colour steps, the stream, a covered reach, a bridge
    yk = yl - 1.6 * U
    B.text("TREE COVER · % OF THE GROUND UNDER CROWNS", x, yk, 0.42 * U, INK, L, font=FONT_TITLE, bold=True)
    yb = yk - 1.4 * U
    bw = 2.2 * U
    for k, (t, c_) in enumerate(RIP_RAMP):
        B.fill([rect(x + k * bw, yb, x + (k + 1) * bw, yb + 0.7 * U)], c_, L, 20)
        B.text("{:g}".format(t), x + k * bw, yb - 0.25 * U - 0.42 * U, 0.42 * U, INK2, L, align="C")
    B.line(rect(x, yb, x + len(RIP_RAMP) * bw, yb + 0.7 * U) + [(x, yb)], INK2, L, 21, 0.05)
    B.text("%", x + len(RIP_RAMP) * bw, yb - 0.25 * U - 0.42 * U, 0.42 * U, INK2, L, align="C")
    kx = x + len(RIP_RAMP) * bw + 2.5 * U
    for kind, col, lab in [it for it in rip_legend() if not it[2].startswith("tree cover")]:
        sw = 2.0 * U
        B.fill([rect(kx, yb, kx + sw, yb + 0.7 * U)], CAT["water"][1] if kind == "line" else col, L, 20)
        if col is RIP_COVERED:
            B.hatch([rect(kx, yb, kx + sw, yb + 0.7 * U)], CAT["water"][1], L, 21, 0.3 * U, w=0.05)
        if kind == "line":
            B.fill([rect(kx + 0.5 * sw - 0.1 * U, yb - 0.08 * U, kx + 0.5 * sw + 0.1 * U, yb + 0.78 * U)], col, L, 22)
        B.text(lab, kx + sw + 0.4 * U, yb + 0.15 * U, 0.42 * U, INK, L)
        kx += sw + 0.4 * U + tw(lab, 0.42 * U) + 1.6 * U
    return B.para("cover = share of 1 m cells under crowns · rows by distance from the stream's centre line, left and "
                  "right looking downstream · 25 m bins · mean = the whole reach " + bcite(
        "Stream tree cover: share of the 1 m cells under crown discs (canopy map, modelled), in bands measured from the "
        "OSM centreline (so 0-15 m holds the channel); bins of 25 m of chainage from the upstream frame edge; a bin "
        "under 20 cells is left blank. Covered reaches drawn on the stream, bridges as ticks across it, section lines by name."),
                  x, yb - 1.8 * U, w, 0.32 * U, INK2, L)


# v33: the green table of bergama_fabric_green v10
def green_rows(S):
    """(label, m2) for the green table: land-use areas of selinus_board (S.area) and, for the agricultural ground,
    the farmland / orchard zone outlines (z["A"])."""
    orch = sum(z["A"] for z in S.zones if z["kind"] == "agri" and z.get("sub") == "orchard")
    field = sum(z["A"] for z in S.zones if z["kind"] == "agri" and z.get("sub") != "orchard")
    g, a, w = S.area.get("green", 0.0), S.area.get("agri", 0.0), S.area.get("water", 0.0)
    return [("Green & open ground", g, True), ("Agricultural ground (land-use table)", a, True),
            ("   of which farmland · fields (zone outlines)", field, False),
            ("   of which orchards (zone outlines)", orch, False),
            ("Water · the Selinus", w, True), ("GREEN + AGRICULTURE + WATER", g + a + w, True)] + [
            (lab, getattr(S, "lc_area", {}).get(k, 0.0), True) for k, lab, _c in reversed(LC_CLASSES)
            if getattr(S, "lc", {}).get(k)]


def draw_green_table(S, B, x, y, w, U):
    L = "LU_BOARD::Legend"
    B.text("GREEN, FARMLAND AND ORCHARDS", x, y, 1.05 * U, INK, L, font=FONT_TITLE, bold=True)
    tot = S.frame_area                                   # v35: was the mapped part only (62.59 of 149 ha in the test)
    h = 0.5 * U
    yy = y - 1.6 * U
    B.text("ha", x + w - 6.0 * U, yy, 0.38 * U, INK2, L, align="R")
    B.text("%", x + w, yy, 0.38 * U, INK2, L, align="R")
    B.line([(x, yy - 0.32 * U), (x + w, yy - 0.32 * U)], INK, L, 20, 0.15)
    yy -= 1.2 * U
    for lab, a, main in green_rows(S):
        col = INK if main else INK2
        B.fit(lab, x, yy, h, w - 14.0 * U, col, L, bold=lab.isupper())
        B.text("{:.2f}".format(a / 1e4), x + w - 6.0 * U, yy, h, col, L, align="R", bold=lab.isupper())
        B.text("{:.1f}".format(100.0 * a / tot), x + w, yy, h, col, L, align="R", bold=lab.isupper())
        yy -= 1.25 * U
    SA = getattr(S, "whole", None)
    if SA is not None and getattr(SA, "lc", None):        # v36: farmland and orchards outside the frame, whole file
        la, lb = getattr(SA, "lc_area", {}), getattr(S, "lc_area", {})
        out_f = max(0.0, la.get("farmland", 0.0) - lb.get("farmland", 0.0))
        out_o = max(0.0, la.get("orchard", 0.0) - lb.get("orchard", 0.0))
        lab = u"Outside the frame · farmland {:.1f} + orchards {:.1f} {}".format(                        # v38
            out_f / 1e4, out_o / 1e4, bcite(u"Outside the frame: farmland and orchards in the whole survey file "
                                            u"beyond the site frame, satellite / inferred."))
        B.fit(lab, x, yy, h, w - 14.0 * U, INK2, L)
        B.text("{:.2f}".format((out_f + out_o) / 1e4), x + w - 6.0 * U, yy, h, INK2, L, align="R")
        B.text(u"-", x + w, yy, h, INK2, L, align="R")
        yy -= 1.25 * U
    yy = B.para("% of the site frame · {:.2f} ha {}".format(tot / 1e4, bcite(                           # v38: keywords
        "Green table: farmland and orchard figures are the summed zone outlines of the survey and OSM and need not add "
        "up exactly to the agricultural row. Satellite rows: ESA WorldCover 2021 inside the site, counted under "
        "buildings and streets too (10 m pixels).")), x, yy - 0.2 * U, w, 0.36 * U, INK2, L)
    return yy


# ============================================================ v33 S2 · HOW PEOPLE USE IT
# Movement potential: the engine of bergama_movement v1 (2026-10-22), merged unchanged from 'the route search' to
# '_runs' (its own copies of _py_candidates and _popen_kw dropped: the board's are the same; _kernel_file, ramp and
# PAR renamed _mv_kernel_file, mv_ramp and MV_PAR). Method: bergama_movement v1 header, repeated in the drawing.
import heapq
import hashlib
import tempfile
import time
import pickle

# ============================================================ the route search (run in Rhino AND in the worker processes)
# One text, executed in both places, so both run the same code. Whole numbers only: the sums are exact in any order.
MV_KERNEL = r'''
import heapq, os, pickle, sys


def mv_source(adj, s, ws, dw, limit):
    """Origin node s (ws buildings on it): the shortest-route tree within limit, then every destination's pairs
    carried back towards s. adj[i] = ((j, cost, edge), ...); dw = {node: destinations on it}. Returns {edge: pairs}.
    Ties: the first route found with the smallest cost, nodes taken in (cost, node number) order."""
    dist = {s: 0.0}
    pred = {}
    seen = set()
    order = []
    h = [(0.0, s)]
    while h:
        d, i = heapq.heappop(h)
        if i in seen:
            continue
        seen.add(i)
        order.append(i)
        for j, c, e in adj[i]:
            nd = d + c
            if nd <= limit and (j not in dist or nd < dist[j]):
                dist[j] = nd
                pred[j] = (i, e)
                heapq.heappush(h, (nd, j))
    flow = {}
    out = {}
    for i in reversed(order):
        f = flow.get(i, 0) + dw.get(i, 0)
        if f and i != s:
            p, e = pred[i]
            out[e] = out.get(e, 0) + ws * f
            flow[p] = flow.get(p, 0) + f
    return out


def mv_many(adj, tasks, dw, limit):
    """Every origin of tasks [(node, buildings)]: (sum per edge, the first origin's own result)."""
    tot = {}
    first = None
    for k, (s, ws) in enumerate(tasks):
        r = mv_source(adj, s, ws, dw, limit)
        if k == 0:
            first = r
        for e, v in r.items():
            tot[e] = tot.get(e, 0) + v
    return tot, first


def _mv_worker_main(argv):
    if len(argv) > 1 and argv[1] == "--probe":
        sys.stdout.write("mv-ok")
        return
    mf, tf, of = argv[1], argv[2], argv[3]
    with open(mf, "rb") as fh:
        adj, dw, limit = pickle.load(fh)
    with open(tf, "rb") as fh:
        tasks = pickle.load(fh)
    res = mv_many(adj, tasks, dw, limit)
    with open(of + ".tmp", "wb") as fh:
        pickle.dump(res, fh, protocol=4)
    os.replace(of + ".tmp", of)
'''
_MVK = {"__name__": "mv_kernel"}
exec(compile(MV_KERNEL, "mv_kernel", "exec"), _MVK)

_MV_PY = {}




def _mv_kernel_file():
    h = hashlib.sha1(MV_KERNEL.encode("utf-8")).hexdigest()[:12]
    d = os.path.join(tempfile.gettempdir(), "bergama_movement_workers")
    if not os.path.isdir(d):
        os.makedirs(d)
    f = os.path.join(d, "mv_kernel_%s.py" % h)
    if not os.path.isfile(f):
        with open(f + ".tmp", "w", encoding="utf-8") as fh:
            fh.write(MV_KERNEL + "\n\nif __name__ == '__main__':\n    _mv_worker_main(sys.argv)\n")
        os.replace(f + ".tmp", f)
    return f, d


def worker_python():
    if "py" in _MV_PY:
        return _MV_PY["py"]
    import subprocess
    _MV_PY["py"], _MV_PY["why"] = None, "no python executable found beside Rhino"
    try:
        kf, _ = _mv_kernel_file()
    except Exception as ex:
        _MV_PY["why"] = "cannot write to the temp folder ({})".format(ex)
        return None
    for py in _py_candidates():
        try:
            r = subprocess.run([py, "-I", kf, "--probe"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120,
                               **_popen_kw())
            if r.returncode == 0 and r.stdout.decode("utf-8", "replace").strip() == "mv-ok":
                _MV_PY["py"], _MV_PY["why"] = py, ""
                return py
            _MV_PY["why"] = "{} did not answer the probe".format(py)
        except Exception as ex:
            _MV_PY["why"] = "{} could not be started ({})".format(py, type(ex).__name__)
    return None


def run_routes(adj, tasks, dw, limit, label, log):
    """Sum of mv_source over every origin: on worker processes (one per core) when available, else in Rhino.
    The first origin of every worker is computed in Rhino too and must match exactly."""
    import subprocess
    t0 = time.time()
    n = min(MV_PAR["n"], len(tasks) // 8) if MV_PAR.get("procs", True) else 1
    py = worker_python() if n >= 2 else None
    if py is None:
        if n >= 2:
            log.append("{}: one core ({}).".format(label, _MV_PY.get("why", "")))
        tot = _MVK["mv_many"](adj, tasks, dw, limit)[0]
        log.append("{}: {} origin nodes in {:.1f} s in Rhino.".format(label, len(tasks), time.time() - t0))
        return tot
    files, procs = [], []
    try:
        kf, d = _mv_kernel_file()
        tag = "%d_%d" % (os.getpid(), int(t0 * 1000) % 100000000)
        mf = os.path.join(d, "model_%s.bin" % tag)
        with open(mf, "wb") as fh:
            pickle.dump((adj, dw, limit), fh, protocol=4)
        files.append(mf)
        parts = [tasks[w::n] for w in range(n)]       # interleaved: every worker gets a fair share
        for w, part in enumerate(parts):
            tf, of = os.path.join(d, "tasks_%s_%d.bin" % (tag, w)), os.path.join(d, "out_%s_%d.bin" % (tag, w))
            with open(tf, "wb") as fh:
                pickle.dump(part, fh, protocol=4)
            files += [tf, of]
            procs.append((subprocess.Popen([py, "-I", kf, mf, tf, of], stdout=subprocess.DEVNULL,
                                           stderr=subprocess.PIPE, **_popen_kw()), of, part))
        tot = {}
        bad = 0
        for pr, of, part in procs:
            err = pr.communicate()[1]
            if pr.returncode != 0:
                last = err.decode("utf-8", "replace").strip().splitlines()[-1:] if err else []
                raise RuntimeError("a worker stopped" + (": " + last[0] if last else ""))
            with open(of, "rb") as fh:
                wt, wfirst = pickle.load(fh)
            if part and _MVK["mv_source"](adj, part[0][0], part[0][1], dw, limit) != wfirst:
                bad += 1
            for e, v in wt.items():
                tot[e] = tot.get(e, 0) + v
        if bad:
            raise RuntimeError("{} checked origin(s) differ from Rhino's own result".format(bad))
        log.append("{}: {} origin nodes on {} worker processes in {:.1f} s (checked against Rhino).".format(
            label, len(tasks), n, time.time() - t0))
        return tot
    except Exception as ex:
        for pr, _, _ in procs:
            try:
                if pr.poll() is None:
                    pr.kill()
            except Exception:
                pass
        log.append("{}: worker processes not used ({}: {}); computed in Rhino.".format(label, type(ex).__name__, ex))
        t1 = time.time()
        tot = _MVK["mv_many"](adj, tasks, dw, limit)[0]
        log.append("{}: {} origin nodes in {:.1f} s in Rhino.".format(label, len(tasks), time.time() - t1))
        return tot
    finally:
        for f_ in files:
            try:
                os.remove(f_)
            except Exception:
                pass


# ============================================================ the street network
WALK_NO_HW = {"motorway", "motorway_link"}
CAR_HW = {"trunk", "trunk_link", "primary", "primary_link", "secondary", "secondary_link", "tertiary", "tertiary_link",
          "unclassified", "residential", "living_street", "service", "road"}
NO_VALUES = ("no",)
CLOSE_D = 4.0           # car_closed: a street piece whose middle lies this close to the curve loses its cars


def _walk_ok(t):
    if t.get("highway") in WALK_NO_HW:
        return False
    if t.get("foot") in ("yes", "designated", "permissive"):
        return True
    return t.get("foot") not in NO_VALUES and t.get("access") not in NO_VALUES


def _car_dirs(t):
    """(forward, backward) allowed for cars, as OSM tags them."""
    if t.get("highway") not in CAR_HW:
        return False, False
    for k_ in ("access", "vehicle", "motor_vehicle", "motorcar"):
        if t.get(k_) in NO_VALUES:
            return False, False
    ow = (t.get("oneway") or "").lower()
    if ow in ("yes", "1", "true"):
        return True, False
    if ow == "-1":
        return False, True
    if t.get("junction") in ("roundabout", "circular") and ow != "no":
        return True, False
    return True, True


def _speed(t, urban):
    """km/h: the OSM maxspeed, else the urban limit; (value, source)."""
    v = (t.get("maxspeed") or "").strip().lower()
    if v in ("tr:urban",):
        return urban, "maxspeed TR:urban"
    try:
        num = float(v.replace("km/h", "").replace("kmh", "").strip().split(";")[0])
        if v.endswith("mph"):
            num *= 1.609344
        if 3.0 <= num <= 150.0:
            return num, "OSM maxspeed"
    except Exception:
        pass
    return urban, "urban limit"


class SGrid(object):
    """A plain bucket grid of boxes (x0, y0, x1, y1)."""

    def __init__(self, c):
        self.c, self.d = float(c), {}

    def add(self, k, bb):
        c = self.c
        for i in range(int(math.floor(bb[0] / c)), int(math.floor(bb[2] / c)) + 1):
            for j in range(int(math.floor(bb[1] / c)), int(math.floor(bb[3] / c)) + 1):
                self.d.setdefault((i, j), []).append(k)

    def query(self, bb):
        c, out, seen = self.c, [], set()
        for i in range(int(math.floor(bb[0] / c)), int(math.floor(bb[2] / c)) + 1):
            for j in range(int(math.floor(bb[1] / c)), int(math.floor(bb[3] / c)) + 1):
                for k in self.d.get((i, j), ()):
                    if k not in seen:
                        seen.add(k)
                        out.append(k)
        return out


def _seg_x(p, q, r, s):
    """Proper crossing of segments pq and rs: (t on pq, u on rs, point) or None."""
    d = (q[0] - p[0]) * (s[1] - r[1]) - (q[1] - p[1]) * (s[0] - r[0])
    if abs(d) < 1e-12:
        return None
    t = ((r[0] - p[0]) * (s[1] - r[1]) - (r[1] - p[1]) * (s[0] - r[0])) / d
    u = ((r[0] - p[0]) * (q[1] - p[1]) - (r[1] - p[1]) * (q[0] - p[0])) / d
    if 0.0 <= t <= 1.0 and 0.0 <= u <= 1.0:
        return t, u, (p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1]))
    return None


def _proj(p, a, b):
    """(t, distance, point) of p's nearest point on segment ab."""
    dx, dy = b[0] - a[0], b[1] - a[1]
    L2 = dx * dx + dy * dy
    t = 0.0 if L2 < 1e-18 else max(0.0, min(1.0, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L2))
    q = (a[0] + t * dx, a[1] + t * dy)
    return t, math.hypot(p[0] - q[0], p[1] - q[1]), q


def build_pieces(ns, osm, props, opt, log):
    """Every street piece of the OSM network (split at shared nodes) with the proposal curves joined in.
    props: [(kind, [(x, y) survey], cross)] with kind spine | spine_car | bridge. Returns (pieces, xy) where
    pieces = [dict(a, b, L, walk, cf, cb, v, way, tags, prop)] and xy = {node: (x, y)}; OSM nodes keep their id
    (positive), new nodes get negative ids."""
    urban = float(ns.get("URBAN_LIMIT", 50.0))
    skip = set(ns.get("SKIP_HW", ()))
    xy, segs = {}, []
    n_sp = {}
    for wid in sorted(osm["ways"], key=lambda k: int(k) if str(k).lstrip("-").isdigit() else 0):
        refs, tags = osm["ways"][wid]
        hw = tags.get("highway")
        if not hw or hw in skip or tags.get("area") == "yes" or "building" in tags or len(refs) < 2:
            continue
        walk = _walk_ok(tags)
        cf, cb = _car_dirs(tags)
        if not walk and not cf and not cb:
            continue
        v, vs = _speed(tags, urban)
        n_sp[vs] = n_sp.get(vs, 0) + 1
        prev = None
        for ref in refs:
            p = osm["P"](ref)
            if not p:
                prev = None
                continue
            nid = int(ref)
            xy[nid] = (p[0], p[1])
            if prev is not None and prev != nid:
                segs.append(dict(a=prev, b=nid, walk=walk, cf=cf, cb=cb, v=v, way=str(wid), tags=tags, prop=None))
            prev = nid
    log.append("Network: {} street pieces from OSM; car speeds: {}.".format(
        len(segs), ", ".join("{} ways {}".format(n_, k_) for k_, n_ in sorted(n_sp.items()))))
    # ---- the proposal curves, joined where they cross (and at their ends)
    grid = SGrid(50.0)

    def bb2(a, b):
        pa, pb = xy[a], xy[b]
        return (min(pa[0], pb[0]), min(pa[1], pb[1]), max(pa[0], pb[0]), max(pa[1], pb[1]))
    for i, s in enumerate(segs):
        grid.add(i, bb2(s["a"], s["b"]))
    splits = {}                                       # seg index -> [(t, node)]
    nxt = [-1]

    def new_node(p):
        k = nxt[0]
        nxt[0] -= 1
        xy[k] = (p[0], p[1])
        return k
    n_x = n_end = n_loose = 0
    for ci, (kind, pts, cross) in enumerate(props):
        car = kind == "spine_car"
        ids = [new_node(p) for p in pts]
        mine = []
        for a, b in zip(ids[:-1], ids[1:]):
            mine.append(len(segs))
            segs.append(dict(a=a, b=b, walk=True, cf=car, cb=car, v=urban, way="proposal", tags={"name": kind},
                             prop=kind))
        if cross:
            for si in mine:
                s = segs[si]
                p, q = xy[s["a"]], xy[s["b"]]
                for oi in grid.query(bb2(s["a"], s["b"])):
                    o = segs[oi]
                    hit = _seg_x(p, q, xy[o["a"]], xy[o["b"]])
                    if hit is None:
                        continue
                    t, u, X = hit
                    k = new_node(X)
                    splits.setdefault(si, []).append((t, k))
                    splits.setdefault(oi, []).append((u, k))
                    n_x += 1
        for end, si in ((ids[0], mine[0]), (ids[-1], mine[-1])):
            pe = xy[end]
            if any(math.hypot(xy[k][0] - pe[0], xy[k][1] - pe[1]) < 0.5 for _, k in splits.get(si, [])):
                continue                              # the end already sits on a crossing
            best = None
            for oi in grid.query((pe[0] - opt["snap_end"], pe[1] - opt["snap_end"], pe[0] + opt["snap_end"],
                                  pe[1] + opt["snap_end"])):
                o = segs[oi]
                t, d, q = _proj(pe, xy[o["a"]], xy[o["b"]])
                if d <= opt["snap_end"] and (best is None or d < best[1]):
                    best = (oi, d, t, q)
            if best is None:
                n_loose += 1
                continue
            oi, d, t, q = best
            o = segs[oi]
            if math.hypot(q[0] - xy[o["a"]][0], q[1] - xy[o["a"]][1]) < 0.5:
                k = o["a"]
            elif math.hypot(q[0] - xy[o["b"]][0], q[1] - xy[o["b"]][1]) < 0.5:
                k = o["b"]
            else:
                k = new_node(q)
                splits.setdefault(oi, []).append((t, k))
            if d > 1e-6:
                segs.append(dict(a=end, b=k, walk=True, cf=car, cb=car, v=urban, way="proposal",
                                 tags={"name": kind + " link"}, prop=kind))
            n_end += 1
        for si in mine:
            grid.add(si, bb2(segs[si]["a"], segs[si]["b"]))
    if props:
        log.append("Proposal: {} curves; {} crossings with streets or each other, {} ends joined to the nearest street "
                   "within {:.0f} m{}.".format(len(props), n_x, n_end, opt["snap_end"],
                                              "; WARNING: {} ends join nothing (no street within reach)".format(n_loose)
                                              if n_loose else ""))
    pieces = []
    for i, s in enumerate(segs):
        cuts = sorted(splits.get(i, []))
        chain = [s["a"]] + [k for _, k in cuts] + [s["b"]]
        for a, b in zip(chain[:-1], chain[1:]):
            if a == b:
                continue
            L = math.hypot(xy[b][0] - xy[a][0], xy[b][1] - xy[a][1])
            pieces.append(dict(s, a=a, b=b, L=L, parent=i))
    return pieces, xy


def compress(pieces, use, key_extra, car):
    """The graph of the pieces `use` (indices) as chains between junctions: (adj, chains, kidx).
    A chain runs between key nodes (junctions, dead ends, and key_extra: where origins and destinations attach)
    through nodes of degree 2. car: a chain is passable one way only if every piece on it is. adj[k] = sorted
    ((k2, cost, chain), ...) over key-node numbers 0..K-1 (in node id order)."""
    inc = {}
    for pi in use:
        p = pieces[pi]
        inc.setdefault(p["a"], []).append(pi)
        inc.setdefault(p["b"], []).append(pi)
    keys = set(n for n, l in inc.items() if len(l) != 2) | (set(key_extra) & set(inc))
    for n, l in inc.items():                          # a piece from a node to itself
        if len(l) == 2 and l[0] == l[1]:
            keys.add(n)
    done = set()
    chains = []

    def walk_from(k, pi):
        nodes, seq = [k], []
        cur = k
        while True:
            p = pieces[pi]
            done.add(pi)
            nxt = p["b"] if p["a"] == cur else p["a"]
            seq.append((pi, p["a"] == cur))           # (piece, travelled a -> b)
            nodes.append(nxt)
            cur = nxt
            if cur in keys:
                break
            l = inc[cur]
            pi = l[0] if l[1] == pi else l[1]
            if pi in done:
                break
        return nodes, seq
    for k in sorted(keys):
        for pi in inc[k]:
            if pi not in done:
                chains.append(walk_from(k, pi))
    for pi in use:                                    # rings with no key node
        if pi not in done:
            k = min(pieces[pi]["a"], pieces[pi]["b"])
            keys.add(k)
            chains.append(walk_from(k, pi))
    kl = sorted(keys)
    kidx = dict((n, i) for i, n in enumerate(kl))
    adj = [[] for _ in kl]
    out = []
    zs = {} if car else (getattr(pieces, "z", None) or {})     # v34: node heights for the walking slope
    for ci, (nodes, seq) in enumerate(chains):
        L = sum(pieces[pi]["L"] for pi, _ in seq)
        if car:
            f = all(pieces[pi]["cf"] if fw else pieces[pi]["cb"] for pi, fw in seq)
            b = all(pieces[pi]["cb"] if fw else pieces[pi]["cf"] for pi, fw in seq)
            c = sum(pieces[pi]["L"] / (pieces[pi]["v"] / 3.6) for pi, _ in seq)
        else:
            f = b = True
            c = cb_ = L
            z0, z1 = zs.get(nodes[0]), zs.get(nodes[-1])        # v34: Tobler slope cost, per chain, each way
            if z0 is not None and z1 is not None and L > 1.0:
                c, cb_ = L * tobler_factor((z1 - z0) / L), L * tobler_factor((z0 - z1) / L)
        u, v = kidx[nodes[0]], kidx[nodes[-1]]
        if f:
            adj[u].append((v, c, ci))
        if b:
            adj[v].append((u, c if car else cb_, ci))
        out.append(dict(nodes=nodes, seq=seq, L=L))
    adj = [tuple(sorted(a)) for a in adj]
    return adj, out, kidx


def tobler_factor(g):
    """v34: walking time on grade g (dh/dx) over walking time on flat ground, Tobler (1993): speed = 6 exp(-3.5
    |g + 0.05|) km/h, flat 5.04 km/h. Grades are capped at +-0.5 (steps and survey noise)."""
    g = max(-0.5, min(0.5, g))
    return math.exp(-3.5 * 0.05) / math.exp(-3.5 * abs(g + 0.05))


class _Pieces(list):
    """v34: the street pieces with the terrain height of their nodes (attribute z = {node: height})."""
    z = None


def snap_points(pts, xy, node_ids, dmax):
    """{node: count} of the nearest node (of node_ids) of every point within dmax; and how many were too far."""
    g = SGrid(max(dmax, 25.0))
    for n in node_ids:
        x, y = xy[n]
        g.add(n, (x, y, x, y))
    out, far = {}, 0
    for x, y in pts:
        best, bd = None, dmax
        for n in g.query((x - dmax, y - dmax, x + dmax, y + dmax)):
            d = math.hypot(xy[n][0] - x, xy[n][1] - y)
            if d < bd or (d == bd and best is not None and n < best):
                best, bd = n, d
        if best is None:
            far += 1
        else:
            out[best] = out.get(best, 0) + 1
    return out, far


def potential(pieces, use, origins, dests, opt, car, label, log):
    """Route pairs per piece (whole numbers) for one mode and scenario."""
    adj, chains, kidx = compress(pieces, use, list(origins) + list(dests), car)
    tasks = [(kidx[n], w) for n, w in sorted(origins.items()) if n in kidx]
    dw = dict((kidx[n], w) for n, w in dests.items() if n in kidx)
    lost = sum(w for n, w in origins.items() if n not in kidx)
    if lost:
        log.append("{}: {} buildings sit on nodes this network no longer reaches.".format(label, lost))
    tot = run_routes(adj, tasks, dw, opt["t_car"] if car else opt["r_walk"], label, log)
    val = {}
    for ci, ch in enumerate(chains):
        v = tot.get(ci, 0)
        for pi, _ in ch["seq"]:
            val[pi] = v
    return val, chains


# ============================================================ origins and destinations
def collect_od(ns, S, osm, places_path, opt, log):
    """Buildings (origins) and everyday destinations within `buffer` of the frame, in survey coordinates."""
    F = S.F
    b = opt["buffer"]

    def in_area(x, y):
        u, v = F.local(x, y)
        return F.u0 - b <= u <= F.u1 + b and F.v0 - b <= v <= F.v1 + b
    org = [(u["cx"], u["cy"]) for u in S.bld if not u.get("annex") and u.get("src") != "shed"]
    n_sv = len(org)
    n_osm = 0
    for refs, tags in osm["ways"].values():
        if "building" not in tags or len(refs) < 4 or refs[0] != refs[-1]:
            continue
        P = [p for p in (osm["P"](r) for r in refs[:-1]) if p]
        if len(P) < 3:
            continue
        a_, cx, cy = ns["shoelace"]([(p[0], p[1]) for p in P])
        if a_ <= 0.0 or F.inside(cx, cy) or not in_area(cx, cy):
            continue
        org.append((cx, cy))
        n_osm += 1
    dst, srcs = [], {}
    pl = []
    if places_path:
        for p in ns["parse_places"](places_path):
            if in_area(p["x"], p["y"]):
                pl.append(p)
    g = SGrid(20.0)
    for i, p in enumerate(pl):
        g.add(i, (p["x"], p["y"], p["x"], p["y"]))
        dst.append((p["x"], p["y"], p["cat"]))
        srcs["Overture places"] = srcs.get("Overture places", 0) + 1
    dup = 0
    for ll, tags in osm["pois"]:
        bus = tags.get("highway") == "bus_stop" or tags.get("public_transport") == "platform"
        pc = "bus stop" if bus else ns["poi_class"](tags)
        if not pc:
            continue
        x, y = ns["to_dwg"](*ll)
        if not in_area(x, y):
            continue
        if not bus and any(pl[i]["cat"] == pc and math.hypot(pl[i]["x"] - x, pl[i]["y"] - y) <= 10.0
                           for i in g.query((x - 10, y - 10, x + 10, y + 10))):
            dup += 1
            continue
        dst.append((x, y, pc))
        k_ = "OSM bus stops" if bus else "OSM points"
        srcs[k_] = srcs.get(k_, 0) + 1
    cats = {}
    for _, _, c in dst:
        cats[c] = cats.get(c, 0) + 1
    log.append("Origins: {} buildings ({} surveyed in the frame, {} OSM outlines within {:.0f} m around it).".format(
        len(org), n_sv, n_osm, b))
    log.append("Destinations: {} ({}; {} OSM points dropped as the same place as an Overture place); by class: {}."
               .format(len(dst), ", ".join("{} {}".format(v, k) for k, v in sorted(srcs.items())), dup,
                       ", ".join("{} {}".format(v, k) for k, v in sorted(cats.items()))))
    return org, dst


# ============================================================ statistics
def _ranks(xs):
    o = sorted(range(len(xs)), key=lambda i: xs[i])
    r = [0.0] * len(xs)
    i = 0
    while i < len(o):
        j = i
        while j + 1 < len(o) and xs[o[j + 1]] == xs[o[i]]:
            j += 1
        for k in range(i, j + 1):
            r[o[k]] = (i + j) / 2.0 + 1.0
        i = j + 1
    return r


def spearman(a, b):
    """Spearman rank correlation (average ranks for ties), or None."""
    if len(a) < 3:
        return None
    ra, rb = _ranks(a), _ranks(b)
    ma, mb = sum(ra) / len(ra), sum(rb) / len(rb)
    sab = sum((x - ma) * (y - mb) for x, y in zip(ra, rb))
    saa = math.sqrt(sum((x - ma) ** 2 for x in ra))
    sbb = math.sqrt(sum((y - mb) ** 2 for y in rb))
    return None if saa == 0 or sbb == 0 else sab / (saa * sbb)


# ============================================================ colours
SEQ = ((238, 233, 218), (246, 207, 133), (234, 140, 62), (190, 55, 46), (98, 24, 62))     # low -> high
DIV = ((33, 102, 172), (146, 197, 222), (226, 224, 216), (244, 165, 130), (178, 24, 43))  # less -> more
WATER = (176, 208, 224)
CTX = (200, 196, 188)
PROP_C = (40, 150, 120)
INK_C = (40, 40, 40)


def mv_ramp(stops, t):
    t = max(0.0, min(1.0, t))
    x = t * (len(stops) - 1)
    i = min(len(stops) - 2, int(x))
    f = x - i
    a, b = stops[i], stops[i + 1]
    return tuple(int(round(a[k] + (b[k] - a[k]) * f)) for k in range(3))


def seq_t(v, vmax):
    return 0.0 if vmax <= 0 else math.sqrt(max(0.0, v) / vmax)


def div_t(d, dmax):
    if dmax <= 0:
        return 0.5
    s = math.sqrt(min(1.0, abs(d) / dmax))
    return 0.5 + 0.5 * s if d > 0 else 0.5 - 0.5 * s


# ============================================================ the whole analysis (also used outside Rhino)
def analyse(ns, S, osm, places_path, props, closed, attractors, opt, log):
    """Both scenarios, both modes. Returns R with the pieces, their values and the street table."""
    F = S.F
    pieces, xy = build_pieces(ns, osm, props, opt, log)
    pieces = _Pieces(pieces)
    z_at = getattr(S, "z_at", None) if getattr(S, "terrain_ok", False) else None
    if z_at is not None:                                  # v34: node heights for Tobler's slope cost (walking)
        used = set(n for p in pieces if p["walk"] for n in (p["a"], p["b"]))
        pieces.z = dict((n, z_at(xy[n][0], xy[n][1])) for n in used)
        log.append("Walking cost: Tobler slope on the survey terrain ({} nodes).".format(len(pieces.z)))
    else:
        log.append("Walking cost: flat (no survey terrain), as v33.")
    org, dst = collect_od(ns, S, osm, places_path, opt, log)
    # cars off the streets under car_closed (the proposal only)
    n_cl = 0
    if closed:
        g = SGrid(50.0)
        segs = []
        for P in closed:
            for a, b in zip(P[:-1], P[1:]):
                g.add(len(segs), (min(a[0], b[0]), min(a[1], b[1]), max(a[0], b[0]), max(a[1], b[1])))
                segs.append((a, b))
        for p in pieces:
            if not (p["cf"] or p["cb"]) or p["prop"]:
                continue
            m = ((xy[p["a"]][0] + xy[p["b"]][0]) / 2.0, (xy[p["a"]][1] + xy[p["b"]][1]) / 2.0)
            if any(_proj(m, segs[i][0], segs[i][1])[1] <= CLOSE_D
                   for i in g.query((m[0] - CLOSE_D, m[1] - CLOSE_D, m[0] + CLOSE_D, m[1] + CLOSE_D))):
                p["closed"] = True
                n_cl += 1
        log.append("car_closed: cars taken off {} street pieces (within {:.0f} m of the curves).".format(n_cl, CLOSE_D))
    has_prop = any(p["prop"] for p in pieces)
    car_changes = n_cl > 0 or any(p["prop"] == "spine_car" for p in pieces)
    walk_b = [i for i, p in enumerate(pieces) if p["walk"] and not p["prop"]]
    walk_a = [i for i, p in enumerate(pieces) if p["walk"]]
    car_b = [i for i, p in enumerate(pieces) if (p["cf"] or p["cb"]) and not p["prop"]]
    car_a = []
    for i, p in enumerate(pieces):
        if (p["cf"] or p["cb"]) and not p.get("closed"):
            car_a.append(i)
    # origins and existing destinations attach to EXISTING nodes, the same in both scenarios
    wn = set(n for i in walk_b for n in (pieces[i]["a"], pieces[i]["b"]) if n > 0)
    cn = set(n for i in car_b for n in (pieces[i]["a"], pieces[i]["b"]) if n > 0)
    o_w, far_ow = snap_points(org, xy, wn, opt["snap"])
    d_w, far_dw = snap_points([(x, y) for x, y, _ in dst], xy, wn, opt["snap"])
    o_c, far_oc = snap_points(org, xy, cn, opt["snap"])
    d_c, far_dc = snap_points([(x, y) for x, y, _ in dst], xy, cn, opt["snap"])
    log.append("Attached within {:.0f} m: walking {} buildings / {} destinations ({} / {} too far); driving {} / {} "
               "({} / {} too far).".format(opt["snap"], sum(o_w.values()), sum(d_w.values()), far_ow, far_dw,
                                           sum(o_c.values()), sum(d_c.values()), far_oc, far_dc))
    d_wa, d_ca = dict(d_w), dict(d_c)
    if attractors:
        wn_a = set(n for i in walk_a for n in (pieces[i]["a"], pieces[i]["b"]))
        add_w, far_aw = snap_points(attractors, xy, wn_a, opt["snap"])
        for n, w in add_w.items():
            d_wa[n] = d_wa.get(n, 0) + w * opt["attr_w"]
        cn_a = set(n for i in car_a for n in (pieces[i]["a"], pieces[i]["b"]))
        add_c, _ = snap_points(attractors, xy, cn_a, opt["snap"])
        for n, w in add_c.items():
            d_ca[n] = d_ca.get(n, 0) + w * opt["attr_w"]
        log.append("Attractors: {} new destinations (weight {} each){}.".format(
            sum(add_w.values()), opt["attr_w"], "; WARNING: {} further than {:.0f} m from any street or spine".format(
                far_aw, opt["snap"]) if far_aw else ""))
    V = {}
    V["walk_b"], CH_wb = potential(pieces, walk_b, o_w, d_w, opt, False, "Walking today", log)
    if has_prop or attractors:
        V["walk_a"], CH_wa = potential(pieces, walk_a, o_w, d_wa, opt, False, "Walking with the spine", log)
    else:
        V["walk_a"], CH_wa = V["walk_b"], CH_wb
    V["car_b"], CH_cb = potential(pieces, car_b, o_c, d_c, opt, True, "Driving today", log)
    if car_changes or (attractors and d_ca != d_c):
        V["car_a"], CH_ca = potential(pieces, car_a, o_c, d_ca, opt, True, "Driving with the spine", log)
    else:
        V["car_a"], CH_ca = V["car_b"], CH_cb
        log.append("Driving with the spine: the proposal changes no street for cars, so it equals today.")
    # pieces inside the frame, the indices (100 = busiest piece in the frame today, per mode)
    inside = [i for i, p in enumerate(pieces)
              if F.inside((xy[p["a"]][0] + xy[p["b"]][0]) / 2.0, (xy[p["a"]][1] + xy[p["b"]][1]) / 2.0)]
    mx_w = max([V["walk_b"].get(i, 0) for i in inside] or [0])
    mx_c = max([V["car_b"].get(i, 0) for i in inside] or [0])
    mix = opt["mix"]
    IDX = dict((k, {}) for k in ("walk_b", "walk_a", "car_b", "car_a", "comb_b", "comb_a"))
    for i in inside:
        for k, mx in (("walk_b", mx_w), ("walk_a", mx_w), ("car_b", mx_c), ("car_a", mx_c)):
            IDX[k][i] = 100.0 * V[k].get(i, 0) / mx if mx else 0.0
        IDX["comb_b"][i] = mix * IDX["walk_b"][i] + (1.0 - mix) * IDX["car_b"][i]
        IDX["comb_a"][i] = mix * IDX["walk_a"][i] + (1.0 - mix) * IDX["car_a"][i]
    log.append("Index 100 = walking {} route pairs, driving {} route pairs (the busiest piece inside the frame today)."
               .format(mx_w, mx_c))
    return dict(pieces=pieces, xy=xy, V=V, IDX=IDX, inside=inside, mx_w=mx_w, mx_c=mx_c, has_prop=has_prop,
                car_changes=car_changes, chains=dict(walk_b=CH_wb, walk_a=CH_wa, car_b=CH_cb, car_a=CH_ca))


def street_table(ns, S, R, log):
    """Named streets in the frame: shops (selinus_board build_corridors) and the length-weighted mean index of every
    map. Plus the checks: Spearman of shops against potential, the board's primary spine, the KGM-counted roads."""
    pieces, xy, IDX = R["pieces"], R["xy"], R["IDX"]
    shops = {}
    try:
        ns["build_corridors"](S)
        for r in S.roads + S.paths:
            g = r.get("grp")
            if g and g["label"] != "an unnamed street":
                shops[g["label"]] = g["n"]
        prim = [g["label"] for g in S.corr_primary]
    except Exception as ex:
        prim = []
        log.append("WARNING: selinus_board build_corridors failed ({}): no shop counts.".format(ex))
    acc = {}
    for i in R["inside"]:
        p = pieces[i]
        nm = (p["tags"].get("name") or "").strip()
        if not nm or p["prop"]:
            continue
        a = acc.setdefault(nm, dict(L=0.0, hw={}, s=dict((k, 0.0) for k in IDX)))
        a["L"] += p["L"]
        hw = p["tags"].get("highway", "")
        a["hw"][hw] = a["hw"].get(hw, 0.0) + p["L"]
        for k in IDX:
            a["s"][k] += IDX[k].get(i, 0.0) * p["L"]
    rows = []
    for nm, a in acc.items():
        if a["L"] < 1.0:
            continue
        m = dict((k, a["s"][k] / a["L"]) for k in IDX)
        rows.append(dict(name=nm, L=a["L"], hw=max(a["hw"], key=a["hw"].get), shops=shops.get(nm, 0), **m))
    rows.sort(key=lambda r: -r["comb_b"])
    big = [r for r in rows if r["L"] >= 50.0]
    log.append("")
    log.append("Named streets in the frame: {} ({} at least 50 m long, used for the checks).".format(len(rows), len(big)))
    for k, lab in (("walk_b", "walking"), ("car_b", "driving"), ("comb_b", "combined")):
        rho = spearman([r["shops"] for r in big], [r[k] for r in big])
        log.append("Shops per street vs {} potential today: Spearman {} (n = {}).".format(
            lab, "n/a" if rho is None else "{:.2f}".format(rho), len(big)))
    for nm in prim:
        for k, lab in (("walk_b", "walking"), ("car_b", "driving"), ("comb_b", "combined")):
            order = sorted(big, key=lambda r: -r[k])
            pos = next((j + 1 for j, r in enumerate(order) if r["name"] == nm), None)
            log.append("Board's primary spine {}: rank {} of {} by {} potential today.".format(
                nm, pos if pos else "n/a (under 50 m in the frame)", len(order), lab))
    # KGM-counted roads (selinus_board v18 COUNTED) against driving potential
    rc = ns.get("road_count")
    if rc:
        seen = {}
        for i in R["inside"]:
            p = pieces[i]
            if p["prop"]:
                continue
            c_ = rc(p["tags"])
            if c_:
                s_ = seen.setdefault(c_["src"], [c_["aadt"], 0.0, 0.0])
                s_[1] += IDX["car_b"].get(i, 0.0) * p["L"]
                s_[2] += p["L"]
        if seen:
            for src, (aadt, s_, L_) in sorted(seen.items()):
                log.append("KGM count in the frame: {} | driving index here today {:.2f} (mean over {:.0f} m).".format(
                    src, s_ / L_ if L_ else 0.0, L_))
            if len(seen) < 3:
                log.append("Too few counted roads in the frame to test the driving potential against counts.")
        else:
            log.append("No KGM-counted road runs inside the frame.")
    return rows


# ============================================================ drawing (survey coordinates; baked via selinus_board helpers)
def _runs(chains, pieces, xy, value_of, inside_frame, F):
    """Polylines of equal value along every chain: [(points, value)], clipped to the frame."""
    out = []
    for ch in chains:
        run, cur = [], None
        for (pi, fw), n0, n1 in zip(ch["seq"], ch["nodes"][:-1], ch["nodes"][1:]):
            v = value_of(pi) if pi in inside_frame else None
            if v != cur or not run:
                if run and cur is not None:
                    out.append((run, cur))
                run, cur = [xy[n0]], v
            run.append(xy[n1])
        if run and cur is not None:
            out.append((run, cur))
    clipped = []
    for P, v in out:
        for q in F.clip_line(P):
            if len(q) >= 2:
                clipped.append((q, v))
    return clipped


